CONFIG = dict(DEFAULTS)
CONFIG_NOTES = []
CONFIG_FATAL = []
DEBUG = False
LOG_HANDLE = None
LOG_PATH = None


def token_path():
    return Path(CONFIG.get('token_file') or str(TOKEN_FILE))


def db_path():
    return Path(CONFIG.get('db_file') or str(DB_FILE))


def _whoami():
    try:
        import pwd
        return pwd.getpwuid(os.geteuid()).pw_name
    except Exception:
        return str(os.geteuid())


def _coerce(current, value):
    """Make a config value the same type as its default, where that is sane."""
    if current is None:
        if value in ('', None):
            return None
        try:
            return float(value)
        except (TypeError, ValueError):
            return value
    if isinstance(current, bool):
        if isinstance(value, str):
            return value.strip().lower() in ('1', 'true', 'yes', 'on')
        return bool(value)
    if isinstance(current, int):
        try:
            return int(value)
        except (TypeError, ValueError):
            return current
    if isinstance(current, float):
        try:
            return float(value)
        except (TypeError, ValueError):
            return current
    if isinstance(current, list):
        if isinstance(value, str):
            return [v.strip() for v in value.split(',') if v.strip()]
        return list(value) if isinstance(value, (list, tuple)) else current
    return value if value is not None else current


NOTIFY_CATEGORIES = ('crit', 'warn', 'offline', 'rule', 'switch')


def notify_override_set(value):
    """A per-device override: a preset name, or custom:cat1,cat2 - either of
    which may carry the roads it should take after an @, as in
    'crit@ntfy,telegram' or 'custom:crit,offline@ntfy'."""
    value = str(value or '').split('@')[0] if isinstance(value, str) else value
    if value in NOTIFY_PRESETS:
        return NOTIFY_PRESETS[value]
    if isinstance(value, str) and value.startswith('custom:'):
        return {c for c in value[7:].split(',') if c in NOTIFY_CATEGORIES}
    return None


def notify_override_roads(value):
    """Which roads that device's alerts take, or None to follow the house."""
    if not isinstance(value, str) or '@' not in value:
        return None
    roads = {r for r in value.split('@', 1)[1].split(',') if r in ('ntfy', 'telegram', 'sms')}
    return roads or None


NOTIFY_PRESETS = {
    'mute': set(),
    'crit': {'crit'},
    'crit_offline': {'crit', 'offline'},
    'crit_offline_switch': {'crit', 'offline', 'switch'},
    'all': {'crit', 'warn', 'offline', 'rule', 'switch'},
}

KNOWN_PLUG_KEYS = {'host_state', 'model', 'mac', 'name', 'host', 'password', 'switch_id', 'mqtt_name', 'enabled', 'kind', 'retain_full_days', 'monitor_only'}


def warn_unknown_keys():
    for entry in (CONFIG.get('plugs') or []) + (CONFIG.get('sensors') or []):
        if isinstance(entry, dict):
            for k in entry:
                if k not in KNOWN_PLUG_KEYS:
                    log('config: unknown key %r on device %r - a typo?' % (k, entry.get('name')), 'warn')
    for entry in CONFIG.get('zigbee_gateways') or []:
        if isinstance(entry, dict):
            for k in entry:
                if k not in ('name', 'host', 'target', 'username', 'password', 'model', 'fw', 'kind'):
                    log('config: unknown key %r on zigbee_gateways entry %r - a typo?' % (k, entry.get('name')), 'warn')
    for k in CONFIG:
        if k not in DEFAULTS and not k.startswith('_'):
            log('config: unknown top-level key %r - a typo?' % k, 'warn')


def load_config():
    """File first, then ZIGMON_* environment variables, which win."""
    if CONFIG_FILE.is_file():
        try:
            raw = json.loads(CONFIG_FILE.read_text())
            if not isinstance(raw, dict):
                CONFIG_FATAL.append('%s is not a JSON object' % CONFIG_FILE)
            else:
                for key, value in raw.items():
                    if key not in DEFAULTS:
                        CONFIG_NOTES.append('unknown option "%s" ignored' % key)
                        continue
                    CONFIG[key] = _coerce(DEFAULTS[key], value)
        except PermissionError:
            CONFIG_FATAL.append(
                '%s exists but cannot be read as %s. Fix with:  '
                'sudo chown root:%s %s && sudo chmod 640 %s'
                % (CONFIG_FILE, _whoami(), SERVICE_USER, CONFIG_FILE, CONFIG_FILE))
        except ValueError as e:
            CONFIG_FATAL.append('%s is not valid JSON: %s' % (CONFIG_FILE, e))
        except OSError as e:
            CONFIG_FATAL.append('could not read %s: %s' % (CONFIG_FILE, e))

    for key in DEFAULTS:
        env = os.environ.get('ZIGMON_' + key.upper())
        if env is not None:
            CONFIG[key] = _coerce(DEFAULTS[key], env)
            CONFIG_NOTES.append('%s taken from the environment' % key)
    return CONFIG


# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
# The file and the journal are written by one thread of their own once the
# daemon is running, never by the thread that has something to say. That
# thread is very often the one on its way to a light: a rule writes its line
# and THEN sends the command, a press does the same, and the broker's own
# thread writes a line for what it receives - while it is busy no Zigbee
# command can leave at all. A write to the journal is a write into a pipe
# that journald empties when it gets round to it, and a write to the file
# lands in the page cache only until the disk is busy (a backup, a VACUUM of
# a quarter-gigabyte database) and the kernel makes writers wait. Measured
# with a journal taking 150 ms over a line: a sensor reached its light in
# 154 ms instead of 3.3, every time, for the one line written on the way.
#
# A command-line tool keeps writing where it is - its output and its own
# prints have to come out in the order they were made, and nothing waits on
# it - so the writer is started by the daemon alone.
_LOG_IO = threading.RLock()          # the file and the streams, and reopening them
_LOG_Q = None                         # a deque, once the daemon has a writer
_LOG_WAKE = threading.Event()
_LOG_STATE = {'dropped': 0, 'busy': False}
# A journal that stops taking lines for minutes must not take the memory with
# it: past this many waiting lines the oldest go, and the writer says how many
# when it can write again.
LOG_QUEUE_MAX = 20000


def open_log(path=None):
    """Open the log file for appending. Safe to call again to reopen it."""
    global LOG_HANDLE, LOG_PATH
    with _LOG_IO:
        close_log()
        path = path if path is not None else CONFIG.get('log_file')
        if not path:
            return None
        try:
            target = Path(path)
            target.parent.mkdir(parents=True, exist_ok=True)
            LOG_HANDLE = open(str(target), 'a', encoding='utf-8')
            LOG_PATH = target
        except OSError as e:
            LOG_HANDLE, LOG_PATH = None, None
            sys.stderr.write('cannot write the log file %s: %s\n' % (path, e))
        return LOG_HANDLE


def ensure_log_current():
    """Reopen if the file we hold is no longer the one at the configured path."""
    if not LOG_HANDLE or not LOG_PATH:
        return False
    try:
        same = os.stat(str(LOG_PATH)).st_ino == os.fstat(LOG_HANDLE.fileno()).st_ino
    except OSError:
        same = False
    if same:
        return False
    open_log()
    log('log file reopened - it was rotated without a signal reaching us')
    return True


def close_log():
    global LOG_HANDLE
    with _LOG_IO:
        if LOG_HANDLE:
            try:
                LOG_HANDLE.close()
            except OSError:
                pass
        LOG_HANDLE = None


def _log_write(lines):
    """The lines, written: to the file, then to the journal. One flush for
    the lot rather than one a line."""
    with _LOG_IO:
        if LOG_HANDLE:
            text = ''.join(line + '\n' for line, _level in lines)
            try:
                LOG_HANDLE.write(text)
                LOG_HANDLE.flush()
            except (OSError, ValueError):
                try:
                    open_log()
                    if LOG_HANDLE:
                        LOG_HANDLE.write(text)
                        LOG_HANDLE.flush()
                except Exception:
                    pass
        if CONFIG.get('log_to_journal', True) or not LOG_HANDLE:
            out = [line for line, level in lines if level not in ('error', 'warn')]
            err = [line for line, level in lines if level in ('error', 'warn')]
            for stream, part in ((sys.stdout, out), (sys.stderr, err)):
                if part:
                    try:
                        stream.write(''.join(line + '\n' for line in part))
                        stream.flush()
                    except (OSError, ValueError):
                        pass


def _log_writer():
    while True:
        _LOG_WAKE.wait()
        _LOG_WAKE.clear()
        while _LOG_Q:
            _LOG_STATE['busy'] = True
            try:
                batch = []
                while _LOG_Q and len(batch) < 500:
                    batch.append(_LOG_Q.popleft())
                lost = _LOG_STATE['dropped']
                if lost:
                    _LOG_STATE['dropped'] = 0
                    batch.insert(0, ('%s  warn  %d log line(s) were lost while the journal was not '
                                     'taking any' % (datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                                                     lost), 'warn'))
                _log_write(batch)
            except Exception:
                pass
            finally:
                _LOG_STATE['busy'] = False


def start_log_writer():
    """From now on, lines are handed to a thread of their own to write."""
    global _LOG_Q
    if _LOG_Q is not None:
        return
    _LOG_Q = collections.deque()
    threading.Thread(target=_log_writer, name='log-writer', daemon=True).start()
    import atexit
    atexit.register(log_drain)


def log_drain(timeout=3.0):
    """Wait until every line handed over so far is written. True if it was."""
    if _LOG_Q is None:
        return True
    deadline = time.time() + timeout
    _LOG_WAKE.set()
    while (_LOG_Q or _LOG_STATE['busy']) and time.time() < deadline:
        time.sleep(0.005)
    return not _LOG_Q and not _LOG_STATE['busy']


def apply_gil_switch():
    """Hand Python between threads as often as gil_switch_ms says."""
    try:
        ms = float(numeric(CONFIG.get('gil_switch_ms')) or 0.1)
    except (TypeError, ValueError):
        ms = 0.1
    want = max(0.1, min(5.0, ms)) / 1000.0
    if abs(sys.getswitchinterval() - want) > 1e-7:
        sys.setswitchinterval(want)
    return want


def log(msg, level='info'):
    # The debug switch on the page is meant to turn the trace on; it used to
    # set a flag that this line never looked at, so everything written for it
    # was thrown away unless log_level happened to say debug as well.
    if level == 'debug' and not (DEBUG or CONFIG.get('debug') or CONFIG.get('log_level') == 'debug'):
        return
    # With the trace on, a stamp to the second is useless: the whole point is
    # to see what happened between one millisecond and the next.
    if DEBUG or CONFIG.get('debug') or CONFIG.get('log_level') == 'debug':
        stamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')[:-3]
    else:
        stamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    line = '%s  %-5s %s' % (stamp, level, msg)
    queue = _LOG_Q
    if queue is not None:
        if len(queue) >= LOG_QUEUE_MAX:
            try:
                queue.popleft()
                _LOG_STATE['dropped'] += 1
            except IndexError:
                pass
        queue.append((line, level))
        _LOG_WAKE.set()
        return
    _log_write([(line, level)])


