def _grp(row):
    """The section a Control-tab row sits in - purely for the eye, kept as
    given (up to 40 characters)."""
    g = str((row or {}).get('group') or '').strip()
    return g[:40]


def human_span(seconds):
    """"3 h 20 min", the way the dashboard says it."""
    seconds = int(max(0, seconds))
    if seconds < 90:
        return '%d s' % seconds
    if seconds < 5400:
        return '%d min' % (seconds // 60)
    if seconds < 172800:
        return '%d h %d min' % (seconds // 3600, (seconds % 3600) // 60)
    return '%d days' % (seconds // 86400)

def parse_while(text):
    """'20s', '10m', '2h', or a bare number of minutes, in seconds.

    Not the same as parse_span, which reads a chart's range: this one takes
    what somebody writes into an action - "on for ten minutes" - and refuses
    anything longer than a day. Both were called parse_span for a while, and
    the later one quietly replaced the other, so every chart range longer
    than a day came back as nothing."""
    text = str(text or '').strip().lower().replace(' ', '')
    match = re.match(r'^(\d+(?:[.,]\d+)?)(s|sec|m|min|h|hr)?$', text)
    if not match:
        return None
    value = float(match.group(1).replace(',', '.'))
    unit = match.group(2) or 'm'
    seconds = value * {'s': 1, 'sec': 1, 'm': 60, 'min': 60, 'h': 3600, 'hr': 3600}[unit]
    return seconds if 1 <= seconds <= 86400 else None


def action_words(do):
    """An action in words, for a log line or a text message."""
    do = str(do or '')
    if do.startswith('set:'):
        return 'set to ' + do[4:]
    if do.startswith('for:'):
        return 'on for ' + do[4:]
    if do.startswith('off-for:'):
        return 'off for ' + do[8:]
    if do.startswith('step:'):
        return '%s from where it is' % do[5:]
    return do



# A name is what somebody calls a thing, and in this house things are called
# Ložnice and Světla. The old rule allowed English letters only, so a scene
# could not be named in the language of the people using it. Letters of any
# language, digits, spaces and a little punctuation; no control characters,
# no slashes, nothing that could be mistaken for a path or a topic.
NAME_OK = re.compile(r'^[^\W_][\w .\'()+-]{0,40}$', re.UNICODE)


# A six-digit code from a phone, the ordinary kind - RFC 6238, SHA-1, thirty
# seconds, which is what 2FAS, OTP Auth, Raivo and the rest speak. Fifteen
# lines of the standard library rather than a dependency.
TOTP_STEP = 30
TOTP_DRIFT = 1          # one step either side, for clocks that disagree a little


def totp_secret():
    """A new secret, in the base32 an authenticator app expects."""
    return base64.b32encode(secrets.token_bytes(20)).decode('ascii').rstrip('=')


def totp_at(secret, step):
    """The code this secret shows in that thirty-second step."""
    padded = str(secret or '').strip().replace(' ', '').upper()
    padded += '=' * (-len(padded) % 8)
    try:
        key = base64.b32decode(padded, casefold=True)
    except Exception:
        return None
    mac = hmac.new(key, struct.pack('>Q', int(step)), hashlib.sha1).digest()
    offset = mac[-1] & 0x0F
    number = struct.unpack('>I', mac[offset:offset + 4])[0] & 0x7FFFFFFF
    return '%06d' % (number % 1000000)


def totp_ok(secret, code, when=None):
    """Whether this code is one this secret is showing right now.

    A code stays good while its own window is open and is refused for ever
    after, which is the whole of the replay protection and needs nothing
    remembered. Single use - the usual rule for a login, where a replayed
    code buys a session - would mean the second press of a lamp inside half
    a minute was refused, and somebody standing in a doorway presses twice.
    Here a replayed code buys one press of one thing, inside a minute, which
    the person has just made themselves; a secret read out of a log a week
    later buys nothing at all, which is the case that matters.
    """
    code = re.sub(r'\D', '', str(code or ''))
    if len(code) != 6 or not secret:
        return False
    now = int((time.time() if when is None else when) // TOTP_STEP)
    for step in range(now - TOTP_DRIFT, now + TOTP_DRIFT + 1):
        shown = totp_at(secret, step)
        if shown and secrets.compare_digest(shown, code):
            return True
    return False


def totp_uri(secret, label, issuer='zigmon'):
    """What an authenticator app reads off a QR code."""
    return ('otpauth://totp/%s:%s?secret=%s&issuer=%s&algorithm=SHA1&digits=6&period=%d'
            % (quote(issuer, safe=''), quote(str(label or 'phone'), safe=''),
               secret, quote(issuer, safe=''), TOTP_STEP))


# ---------------------------------------------------------------------------
# Duo, as a second factor
# ---------------------------------------------------------------------------
# The Auth API signs every request with HMAC-SHA512 over a canonical form of
# it - the date, the method, the host, the path, the parameters, the body and
# the X-Duo headers, each on a line of its own. That is the whole of what the
# published client does for this, and it is written out here rather than
# carried as a dependency: the rest of that package is four thousand lines of
# the Admin API, which this has no use for, and the daemon is one file.
# duo_sign is checked against the published client's own signing in
# test/duo.py, so a change on either side shows up rather than failing in the
# field with "invalid signature".
def duo_canon_params(params):
    """The parameters as Duo wants them for signing: sorted, and quoted the
    way OAuth 1.0 quotes them."""
    out = []
    for key in sorted(quote(str(k), '~') for k in params):
        raw = next(v for k, v in params.items() if quote(str(k), '~') == key)
        for value in sorted([quote(str(v), '~') for v in (raw if isinstance(raw, list) else [raw])]):
            out.append('%s=%s' % (key, value))
    return '&'.join(out)


DUO_WAYS = (('2', 'sha512'), ('2', 'sha1'), ('5', 'sha512'), ('1', 'sha1'))


def duo_sign(ikey, skey, method, host, path, when, params=None, version=2, digest='sha512'):
    """The Authorization header for one request.

    Two ways of writing the canonical form are in use. Version 2 is four
    lines and the parameters, whether they travel in the query or in a
    form-encoded body, and is what the Auth API documents. Version 5 adds the
    hash of a JSON body and the hash of the X-Duo headers, and is what the
    published client now defaults to. Which one an account will take is not
    something this can know from here, so it tries the documented one and
    keeps whichever answers - see duo_call.
    """
    params = params or {}
    version = int(version)
    if version == 1:
        # the oldest of them: no date line at all
        canon = [method.upper(), host.lower(), path, duo_canon_params(params)]
    elif version == 5:
        body = duo_body(params) if method.upper() in ('POST', 'PUT', 'PATCH') else ''
        canon = [when, method.upper(), host.lower(), path,
                 duo_canon_params({} if body else params),
                 hashlib.sha512(body.encode('utf-8')).hexdigest(),
                 hashlib.sha512(b'').hexdigest()]
    else:
        canon = [when, method.upper(), host.lower(), path, duo_canon_params(params)]
    sig = hmac.new(str(skey).encode('utf-8'), '\n'.join(canon).encode('utf-8'),
                   hashlib.sha1 if digest == 'sha1' else hashlib.sha512).hexdigest()
    return 'Basic ' + base64.b64encode(('%s:%s' % (ikey, sig)).encode('utf-8')).decode('ascii')


def duo_body(params):
    """The JSON body version 5 signs, written exactly as it is sent."""
    return json.dumps(params, sort_keys=True, separators=(',', ':'))


def tap_post_address():
    """The one address every header link is opened at - no secret in it."""
    where = str(CONFIG.get('public_url') or '').strip() or 'https://your-dashboard/index.php'
    if where.endswith('/index.php'):
        return where[:-len('/index.php')] + '/tap'
    return where + ('&' if '?' in where else '?') + 'api=tap'


def tap_address(token):
    """Where a one-tap link lives.

    Two shapes. The plain one works on any web server: the dashboard's own
    address with ?t= on the end. The tidy one needs a rule in nginx, which
    the shipped configuration has, and is worth having because there is
    nothing in it for a phone to correct - no full stop, no equals sign, no
    ampersand. A phone offered index.php?api=tap&t=... will hand back
    index-php?api-tap&t=... and the request goes nowhere.
    """
    where = str(CONFIG.get('public_url') or '').strip() or 'https://your-dashboard/index.php'
    plain = '%s?t=%s' % (where, token)
    tidy = ''
    if where.endswith('/index.php'):
        tidy = '%s/tap/%s' % (where[:-len('/index.php')], token)
    return tidy or plain, plain


def sensible_name(text):
    """True for a name a person would write."""
    text = str(text or '').strip()
    return bool(text) and bool(NAME_OK.match(text))


# ---------------------------------------------------------------------------
# Turns of phrase for a fact
#
# A fact is a string, and most of the ones worth writing about are lists of
# names with commas between them. What somebody wants in a message is usually
# not that: one per line, or how many there are, or the first three and "and
# four more". These are written once, here, and work anywhere a fact does -
# an alert, a text message, a link that tells you something.

# what this house says when a list has nothing in it
FACT_EMPTY = ('none', 'nobody', 'nothing', 'no one', '-', 'never', 'unknown')


def _fact_items(text):
    """The parts of a fact that is really a list.

    An empty list is a word here rather than an empty string - "nothing",
    "nobody" - so counting one of those as an item would have every message
    saying one socket is on when none is.
    """
    text = str(text or '').strip()
    if not text or text.lower() in FACT_EMPTY:
        return []
    return [p.strip() for p in text.split(',') if p.strip()]


def _fact_join(items, word):
    if not items:
        return ''
    if len(items) == 1:
        return items[0]
    return '%s %s %s' % (', '.join(items[:-1]), word, items[-1])


def _fact_nth(items, n):
    """The n-th of a list, counted from 1; no number is the first. Zero was
    read as no number at all, so {x.nth:0} said the first item, not nothing."""
    n = 1 if n is None else int(n)
    return items[n - 1] if 0 < n <= len(items) else ''


def _fact_round(text, places=0):
    try:
        number = float(str(text).replace(',', '.').split()[0])
    except (ValueError, IndexError):
        return str(text or '')
    # + 0.0 turns the -0.0 a small negative rounds to into 0, not "-0"
    number = round(number, places) + 0.0
    return ('%.*f' % (places, number)).rstrip('0').rstrip('.') if places else '%d' % round(number)


def _fact_ascii(text):
    """The same words without their diacritics.

    Worth more than it looks on a text message: one accented letter anywhere
    turns the whole thing into the wider encoding, where seventy characters
    fill a part instead of a hundred and sixty. A long Czech status reply
    costs twice what the same words plainly spelled would.
    """
    import unicodedata
    flat = unicodedata.normalize('NFKD', str(text or ''))
    return ''.join(c for c in flat if not unicodedata.combining(c))


def _fact_number(text):
    try:
        return float(str(text).replace(',', '.').split()[0])
    except (ValueError, IndexError):
        return None


def _fact_thousands(text):
    """1234567 as "1 234 567" - and 1234.56 as "1 234.56".

    Only the part before the point is grouped; the part after it is kept as
    it was written. Dropping it turned {cost.money} into whole crowns, so a
    message about a few hellers said "0 K\u010d"."""
    number = _fact_number(text)
    if number is None:
        return str(text or '')
    said = str(text or '').strip()
    rest = ''
    # the decimal comma is a decimal point too, as _fact_number reads it
    point = '.' if '.' in said else ','
    if point in said and _fact_number(said.split(point, 1)[0]) is not None:
        rest = point + said.split(point, 1)[1]
    whole = '%d' % abs(int(number)) if not rest else said.split(point, 1)[0].lstrip('-+').strip()
    if not whole.isdigit():
        whole = '%d' % abs(int(number))
        rest = ''
    grouped = ''
    while len(whole) > 3:
        grouped = '\u202f' + whole[-3:] + grouped
        whole = whole[:-3]
    return ('-' if number < 0 else '') + whole + grouped + rest


# Time, in all the shapes a fact may arrive in: seconds since the epoch, an
# ISO stamp, "2026-09-20 18:42:07", "18:42", or a number of seconds that is
# really a length rather than a moment.
def _fact_moment(text):
    """A fact read as a point in time, or None."""
    raw = str(text or '').strip()
    if not raw:
        return None
    number = _fact_number(raw)
    if number is not None and re.match(r'^[-+]?\d+(\.\d+)?$', raw.replace(',', '.')):
        if number > 100000000:                 # seconds since 1970
            return datetime.fromtimestamp(number)
        if 0 <= number < 100000000:
            return None                        # a plain number is a length, not a moment
    for how in ('%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M:%S', '%Y-%m-%dT%H:%M',
                '%Y-%m-%d %H:%M', '%Y-%m-%d', '%d.%m.%Y %H:%M', '%d.%m.%Y', '%H:%M:%S', '%H:%M'):
        try:
            when = datetime.strptime(raw[:19] if 'T' in how or ' ' in how else raw[:len(raw)], how)
        except ValueError:
            continue
        if how in ('%H:%M:%S', '%H:%M'):
            today = datetime.now()
            when = when.replace(year=today.year, month=today.month, day=today.day)
        return when
    return None


def _fact_seconds(text):
    """A fact read as a length of time in seconds: a bare number, or the
    words the house writes lengths in ("2 h 14 min", "45 s", "3 d")."""
    raw = str(text or '').strip().lower()
    if not raw:
        return None
    if re.match(r'^[-+]?\d+(\.\d+)?$', raw.replace(',', '.')):
        return float(raw.replace(',', '.'))
    total, found = 0.0, False
    for number, unit in re.findall(r'(\d+(?:[.,]\d+)?)\s*(d|h|m(?:in)?|s|day|days|hour|hours|minute|minutes|second|seconds)(?![a-z])', raw):
        value = float(number.replace(',', '.'))
        total += value * {'d': 86400, 'day': 86400, 'days': 86400, 'h': 3600, 'hour': 3600,
                          'hours': 3600, 'm': 60, 'min': 60, 'minute': 60, 'minutes': 60,
                          's': 1, 'second': 1, 'seconds': 1}[unit]
        found = True
    return total if found else None


SAFE_CLOCK = re.compile(r'^[%A-Za-z0-9 :.,\-/]*$')
CLOCK_WORDS = ('%Y', '%m', '%d', '%H', '%M', '%S', '%A', '%a', '%B', '%b', '%p', '%I',
               '%j', '%U', '%W', '%y', '%Z', '%%')


def _fact_clock(text, how):
    """A moment written the way somebody asked for, in strftime's letters.
    Only the letters that say a part of a date or a time are allowed."""
    when = _fact_moment(text)
    if when is None:
        return str(text or '')
    if not SAFE_CLOCK.match(how or '') or re.search(r'%(?![YmdHMSAaBbpIjUWyZ%])', how or ''):
        return str(text or '')
    try:
        return when.strftime(how)
    except (ValueError, OverflowError):
        return str(text or '')


def _duration_words(seconds, short=False):
    """A length of time in words, or - short - as a clock.

    Short is hours and minutes, always. It used to write anything under a
    minute as 0:ss, which reads as a number of minutes: 45 seconds and 45
    minutes both came out "0:45", and there was no telling them apart. Under
    a minute is 0:00 now, which is what an hours-and-minutes clock says about
    three quarters of a minute."""
    if seconds is None:
        return ''
    seconds = abs(float(seconds))
    if short:
        return '%d:%02d' % divmod(int(seconds // 60), 60)
    return human_span(seconds)


# Monday first, as tm_wday counts and as a schedule's days are stored. (A
# heating plan counts from Sunday and has its own table; see _plan_days_in.)
DAY_SHORT_LOWER = ('mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun')

# While one action is switching several sockets, the pages are woken at most
# this often: a strip answers one command at a time, so four sockets answered
# 200 ms apart and the page fetched the whole status for each of them. See
# Daemon.wake_together.
WAKE_FOLD_S = 0.25

FACT_TURNS = {
    'nl': lambda t: '\n'.join(_fact_items(t)),
    'lines': lambda t: '\n'.join(_fact_items(t)),
    'bullets': lambda t: '\n'.join('\u2022 ' + x for x in _fact_items(t)),
    'dashes': lambda t: '\n'.join('- ' + x for x in _fact_items(t)),
    'numbered': lambda t: '\n'.join('%d. %s' % (n, x) for n, x in enumerate(_fact_items(t), 1)),
    'count': lambda t: str(len(_fact_items(t))),
    'first': lambda t: (_fact_items(t) or [''])[0],
    'last': lambda t: (_fact_items(t) or [''])[-1],
    'sort': lambda t: ', '.join(sorted(_fact_items(t), key=lambda x: x.lower())),
    'and': lambda t: _fact_join(_fact_items(t), 'and'),
    'or': lambda t: _fact_join(_fact_items(t), 'or'),
    'three': lambda t: (', '.join(_fact_items(t)[:3])
                        + (' and %d more' % (len(_fact_items(t)) - 3) if len(_fact_items(t)) > 3 else '')),
    'upper': lambda t: str(t or '').upper(),
    'lower': lambda t: str(t or '').lower(),
    'title': lambda t: str(t or '').title(),
    'round': lambda t: _fact_round(t),
    'round1': lambda t: _fact_round(t, 1),
    'trim': lambda t: ' '.join(str(t or '').split()),
    'quiet': lambda t: '' if str(t or '').strip().lower() in FACT_EMPTY + ('0',) else str(t or ''),

    # the shape of the words
    'sentence': lambda t: (str(t or '')[:1].upper() + str(t or '')[1:]),
    'ascii': _fact_ascii,
    'plain': _fact_ascii,                 # the name people reach for first
    'oneline': lambda t: ' '.join(str(t or '').split()),
    'nospace': lambda t: ''.join(str(t or '').split()),
    'slug': lambda t: re.sub(r'[^a-z0-9]+', '-', _fact_ascii(t).lower()).strip('-'),
    'short': lambda t: (str(t or '')[:57] + '\u2026') if len(str(t or '')) > 58 else str(t or ''),
    'len': lambda t: str(len(str(t or ''))),
    'sms': lambda t: str(Daemon.sms_parts(t)),
    'url': lambda t: quote(str(t or ''), safe=''),

    # the order and the make-up of a list
    'reverse': lambda t: ', '.join(reversed(_fact_items(t))),
    'unique': lambda t: ', '.join(dict.fromkeys(_fact_items(t))),
    'commas': lambda t: ', '.join(_fact_items(t)),
    'spaces': lambda t: ' '.join(_fact_items(t)),
    'quotes': lambda t: ', '.join('\u201c%s\u201d' % x for x in _fact_items(t)),
    'tags': lambda t: ' '.join('#' + re.sub(r'[^A-Za-z0-9]+', '', _fact_ascii(x)) for x in _fact_items(t)),

    # numbers
    'round2': lambda t: _fact_round(t, 2),
    'abs': lambda t: (lambda n: str(t or '') if n is None else _fact_round(abs(n), 2))(_fact_number(t)),
    'plus': lambda t: (lambda n: str(t or '') if n is None
                       else ('+' if n > 0 else '') + str(t or '').strip())(_fact_number(t)),
    'percent': lambda t: (lambda n: str(t or '') if n is None else '%s%%' % _fact_round(n))(_fact_number(t)),
    'thousands': _fact_thousands,
    'degrees': lambda t: (lambda n: str(t or '') if n is None
                          else '%s\u00b0' % str(t or '').strip())(_fact_number(t)),

    # what a list of numbers adds up to
    'sum': lambda t: _fact_round(sum(_fact_nums(t)), 2) if _fact_nums(t) else '',
    'avg': lambda t: _fact_round(sum(_fact_nums(t)) / len(_fact_nums(t)), 2) if _fact_nums(t) else '',
    'max': lambda t: _fact_round(max(_fact_nums(t)), 2) if _fact_nums(t) else '',
    'min': lambda t: _fact_round(min(_fact_nums(t)), 2) if _fact_nums(t) else '',

    # whole numbers, money and energy
    'int': lambda t: str(int(_fact_number(t))) if _fact_number(t) is not None else str(t or ''),
    'floor': lambda t: str(int(math.floor(_fact_number(t)))) if _fact_number(t) is not None else str(t or ''),
    'ceil': lambda t: str(int(math.ceil(_fact_number(t)))) if _fact_number(t) is not None else str(t or ''),
    'money': lambda t: (_fact_thousands(_fact_round(t, 2)) + ' ' + str(CONFIG.get('currency') or 'K\u010d')) \
        if _fact_number(t) is not None else str(t or ''),
    'kwh': lambda t: (_fact_round(t, 1) + ' kWh') if _fact_number(t) is not None else str(t or ''),
    'watts': lambda t: (_fact_round(t) + ' W') if _fact_number(t) is not None else str(t or ''),
    'kw': lambda t: (_fact_round((_fact_number(t) or 0) / 1000.0, 2) + ' kW') \
        if _fact_number(t) is not None else str(t or ''),

    # time: a moment written differently, or a length said in words
    'time': lambda t: _fact_clock(t, '%H:%M'),
    'time_s': lambda t: _fact_clock(t, '%H:%M:%S'),
    'date': lambda t: _fact_clock(t, '%Y-%m-%d'),
    'date_cz': lambda t: _fact_clock(t, '%d.%m.%Y'),
    'datetime': lambda t: _fact_clock(t, '%Y-%m-%d %H:%M'),
    'day': lambda t: _fact_clock(t, '%d'),
    'dayname': lambda t: _fact_clock(t, '%A'),
    'month': lambda t: _fact_clock(t, '%m'),
    'monthname': lambda t: _fact_clock(t, '%B'),
    'year': lambda t: _fact_clock(t, '%Y'),
    'hour': lambda t: _fact_clock(t, '%H'),
    'minute': lambda t: _fact_clock(t, '%M'),
    'week': lambda t: _fact_clock(t, '%W'),
    'epoch': lambda t: (str(int(_fact_moment(t).timestamp())) if _fact_moment(t) else str(t or '')),
    'iso': lambda t: (_fact_moment(t).strftime('%Y-%m-%dT%H:%M:%S') if _fact_moment(t) else str(t or '')),
    'ago': lambda t: (human_span(max(0.0, time.time() - _fact_moment(t).timestamp())) + ' ago'
                      if _fact_moment(t) else
                      (human_span(_fact_seconds(t)) + ' ago' if _fact_seconds(t) is not None else str(t or ''))),
    'until': lambda t: (('in ' + human_span(max(0.0, _fact_moment(t).timestamp() - time.time())))
                        if _fact_moment(t) else
                        ('in ' + human_span(_fact_seconds(t)) if _fact_seconds(t) is not None else str(t or ''))),
    'duration': lambda t: _duration_words(_fact_seconds(t)),
    'hhmm': lambda t: _duration_words(_fact_seconds(t), short=True),
    'hours': lambda t: (_fact_round((_fact_seconds(t) or 0) / 3600.0, 1) if _fact_seconds(t) is not None else str(t or '')),
    'minutes': lambda t: (str(int((_fact_seconds(t) or 0) // 60)) if _fact_seconds(t) is not None else str(t or '')),
    'seconds': lambda t: (str(int(_fact_seconds(t))) if _fact_seconds(t) is not None else str(t or '')),
    'daypart': lambda t: (lambda w: '' if w is None else
                          ('night' if w.hour < 5 else 'morning' if w.hour < 12
                           else 'afternoon' if w.hour < 18 else 'evening'))(_fact_moment(t)),
    'today': lambda t: (lambda w: '' if w is None else
                        ('yes' if w.date() == datetime.now().date() else ''))(_fact_moment(t)),

    # the other way round: nothing when there is something, and the reverse
    'not': lambda t: '' if fact_truth(t) else 'yes',
    'yes': lambda t: 'yes' if fact_truth(t) else '',

    # a reading that is really a yes or a no
    'yesno': lambda t: ('yes' if str(t or '').strip().lower() in ('1', 'true', 'on', 'yes', 'open')
                        else 'no' if str(t or '').strip() else ''),
    'onoff': lambda t: ('on' if str(t or '').strip().lower() in ('1', 'true', 'on', 'yes', 'open')
                        else 'off' if str(t or '').strip() else ''),
}


# ---------------------------------------------------------------------------
# Saying it only when it is so: conditions, and going round a list.
#
# A message could quote a fact and turn it into other words, but it could not
# ask a question - "say this only if nobody is home", "write a line for each
# socket that is on". Everything below is what answers a question written in
# the same words the rest of the dashboard uses; nothing here runs code that
# anybody typed, and there is no eval anywhere in it: a condition is read into
# a little tree of its own and walked.
# ---------------------------------------------------------------------------
FACT_FALSE = ('', '0', 'no', 'off', 'false', 'nothing', 'nobody', 'none', 'no one',
              '-', 'never', 'unknown', 'closed', 'away', '0.0')


def fact_truth(value):
    """Whether a fact counts as yes. Empty, zero, off, no, nothing: no."""
    if value is True or value is False:
        return bool(value)
    return str(value if value is not None else '').strip().lower() not in FACT_FALSE


COND_OPS = ('>=', '<=', '!=', '==', '>', '<', '=')
COND_WORD_OPS = ('contains', 'starts', 'ends', 'in', 'is')


def _cond_tokens(text):
    """A condition split into its pieces, with quotes and {names} kept whole."""
    out, i, text = [], 0, str(text or '')
    while i < len(text):
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if ch in '()':
            out.append(ch)
            i += 1
            continue
        if ch in '"“”„\'':
            # Czech quotes open low and close high, „like this“; English ones
            # open “ and close ”, and either closing mark is taken for both
            closers = {'"': '"', "'": "'", '“': '“”', '”': '”', '„': '“”'}
            ends = [e for e in (text.find(c, i + 1) for c in closers[ch]) if e >= 0]
            end = min(ends) if ends else len(text)
            out.append(('str', text[i + 1:end]))
            i = end + 1
            continue
        if ch == '{':
            end = text.find('}', i)
            end = len(text) if end < 0 else end
            out.append(('fact', text[i + 1:end].strip()))
            i = end + 1
            continue
        for op in COND_OPS:
            if text.startswith(op, i):
                out.append(('op', op))
                i += len(op)
                break
        else:
            start = i
            while i < len(text) and not text[i].isspace() and text[i] not in '()' \
                    and not any(text.startswith(op, i) for op in COND_OPS):
                i += 1
            word = text[start:i]
            low = word.lower()
            if low in ('and', 'or', 'not', '&&', '||', '!'):
                out.append(('word', {'&&': 'and', '||': 'or', '!': 'not'}.get(low, low)))
            elif low in COND_WORD_OPS:
                out.append(('op', 'contains' if low == 'contains' else low))
            else:
                out.append(('bare', word))
    return out


class _Condition(object):
    """Reads a condition into a tree and answers it. Nothing is executed:
    the pieces are compared, and and/or/not walk the tree."""

    def __init__(self, tokens, resolve):
        self.t = tokens
        self.i = 0
        self.resolve = resolve

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else None

    def take(self):
        one = self.peek()
        self.i += 1
        return one

    def answer(self):
        value = self.or_part()
        return value

    def or_part(self):
        left = self.and_part()
        while self.peek() == ('word', 'or'):
            self.take()
            right = self.and_part()
            left = left or right
        return left

    def and_part(self):
        left = self.not_part()
        while self.peek() == ('word', 'and'):
            self.take()
            right = self.not_part()
            left = left and right
        return left

    def not_part(self):
        if self.peek() == ('word', 'not'):
            self.take()
            return not self.not_part()
        return self.compare()

    def compare(self):
        if self.peek() == '(':
            self.take()
            inside = self.or_part()
            if self.peek() == ')':
                self.take()
            return inside
        was = self.peek()
        left = self.value()
        nxt = self.peek()
        if not (isinstance(nxt, tuple) and nxt[0] == 'op'):
            # A name on its own asks whether that fact says anything: a name
            # nothing is called is a no, not the word itself. (The word only
            # stands for itself where it is being compared with something.)
            if isinstance(was, tuple) and was[0] in ('bare', 'fact'):
                stands = self.resolve(was[1])
                if stands is None and was[0] == 'bare':
                    # a word that is a yes or a no in itself - "while yes",
                    # "if 0" - means what it says; any other unknown name is
                    # a no, because nothing here is called that
                    word = str(was[1]).strip().lower()
                    if word in ('yes', 'true', 'on', 'no', 'false', 'off') or _fact_number(word) is not None:
                        return fact_truth(word)
                return fact_truth(stands)
            return fact_truth(left)
        op = self.take()[1]
        right = self.value()
        return self._holds(left, op, right)

    def value(self):
        one = self.take()
        if one is None:
            return ''
        if one == '(':                      # a bracket where a value was expected
            inside = self.or_part()
            if self.peek() == ')':
                self.take()
            return 'yes' if inside else ''
        kind, text = one if isinstance(one, tuple) else ('bare', str(one))
        if kind == 'str':
            return text
        if kind == 'fact':
            return self.resolve(text)
        if kind == 'word':                  # and/or/not where a value was wanted
            return ''
        # a bare word: a fact if there is one by that name, otherwise the word
        found = self.resolve(text)
        return text if found is None else found

    @staticmethod
    def _holds(left, op, right):
        if op in ('contains', 'starts', 'ends'):
            a, b = str(left or '').lower(), str(right or '').lower()
            return {'contains': b in a, 'starts': a.startswith(b), 'ends': a.endswith(b)}[op]
        if op == 'in':
            return str(left or '').strip().lower() in [x.lower() for x in _fact_items(right)]
        a, b = _fact_number(left), _fact_number(right)
        if a is not None and b is not None:
            return {'>': a > b, '<': a < b, '>=': a >= b, '<=': a <= b,
                    '==': a == b, '=': a == b, '!=': a != b, 'is': a == b}[op]
        a, b = str(left or '').strip().lower(), str(right or '').strip().lower()
        return {'>': a > b, '<': a < b, '>=': a >= b, '<=': a <= b,
                '==': a == b, '=': a == b, '!=': a != b, 'is': a == b}[op]


def condition_holds(text, resolve):
    """True when the condition written in those words holds now."""
    try:
        return bool(_Condition(_cond_tokens(text), resolve).answer())
    except Exception:
        return False


# The head of a block may quote facts of its own - {if {temp} < 5} - so one
# level of braces is allowed inside it.
# The word must stand on its own: a space after it, or the closing brace. A
# word boundary alone let {If-Kitchen.state} count as an {if} - a hyphen ends
# a word - and the block it opened swallowed the rest of the message, which
# then came out empty. A device called If-Kitchen or For-Loznice is an
# ordinary name, and reads as one.
BLOCK_RE = re.compile(r'\{\s*(if|unless|else if|elif|else|end|endif|endfor|for|repeat)'
                      r'(?=\s|\})((?:[^{}]|\{[^{}]*\})*)\}', re.I)


def _block_tree(text):
    """The text cut into plain parts and blocks, blocks inside blocks and all.

    Every piece is either a string or (kind, what, [branches]); a branch is a
    list of pieces. An {if} with no {end} closes itself at the end of the
    text rather than throwing the message away.
    """
    pieces, stack = [], []
    here = pieces
    at = 0
    for found in BLOCK_RE.finditer(text):
        if found.start() > at:
            here.append(text[at:found.start()])
        at = found.end()
        word = found.group(1).lower().replace(' ', '')
        rest = found.group(2).strip()
        if word in ('if', 'unless'):
            node = ('if', ('not (%s)' % rest) if word == 'unless' else rest, [[]])
            here.append(node)
            stack.append(node)
            here = node[2][0]
        elif word in ('for', 'repeat'):
            node = (word, rest, [[]])
            here.append(node)
            stack.append(node)
            here = node[2][0]
        elif word in ('else', 'elif', 'elseif'):
            if not stack or stack[-1][0] != 'if':
                here.append(found.group(0))
                continue
            stack[-1][2].append([])
            stack[-1][2][-1].append(('__cond__', rest, []))   # empty for a plain else
            here = stack[-1][2][-1]
        elif word in ('end', 'endif', 'endfor'):
            if stack:
                stack.pop()
                here = stack[-1][2][-1] if stack else pieces
        else:
            here.append(found.group(0))
    if at < len(text):
        here.append(text[at:])
    return pieces


# One message is one message, however the loops in it are nested. Each loop
# is capped on its own, but nesting multiplies: three {repeat 200} inside one
# another is eight million turns and eight megabytes of text, and four is the
# machine's memory. Nothing anybody writes for a phone comes near either
# number, so a whole rendering is given a budget and stops when it is spent.
BLOCK_TURNS_MOST = 50000       # loop turns in one message, all loops together
BLOCK_TEXT_MOST = 200000       # and how much text they may make between them
BLOCK_CUT = '… (cut: the loops made more text than one message can hold)'


def render_blocks(text, resolve, fill, depth=0):
    """Put the text together, asking each {if} and going round each {for}.

    `resolve` says what a name stands for now; `fill` writes one plain part
    (the ordinary {fact} swapping). A loop hands its own name back through
    `resolve` by way of the facts it was given."""
    if depth > 6 or not BLOCK_RE.search(text or ''):
        return fill(text)

    # what the loops of this one rendering have spent between them
    budget = {'turns': 0, 'chars': 0, 'cut': False}

    def spend(turn_text):
        """Count one loop turn and what it wrote. False when the budget is
        gone and the loops must stop where they are."""
        budget['turns'] += 1
        budget['chars'] += len(turn_text)
        if budget['turns'] > BLOCK_TURNS_MOST or budget['chars'] > BLOCK_TEXT_MOST:
            budget['cut'] = True
            return False
        return True

    def build(pieces, scope):
        out = []
        for piece in pieces:
            if budget['cut']:
                break
            if isinstance(piece, str):
                out.append(fill(piece, scope))
                continue
            kind, what, branches = piece
            if kind == 'if':
                taken = None
                for index, branch in enumerate(branches):
                    if index == 0:
                        holds = condition_holds(what, lambda n: resolve(n, scope))
                        body = branch
                    else:
                        head = branch[0] if branch and isinstance(branch[0], tuple) \
                            and branch[0][0] == '__cond__' else None
                        body = branch[1:] if head else branch
                        holds = True if not (head and head[1]) \
                            else condition_holds(head[1], lambda n: resolve(n, scope))
                    if holds:
                        taken = body
                        break
                if taken is not None:
                    out.append(build(taken, scope))
            elif kind == 'repeat':
                times = _fact_number(fill(what if '{' in what else '{%s}' % what, scope)) \
                    or _fact_number(what)
                # the turns actually gone round, so loop_n and loop_last are
                # about them: past 200 the last turn never said it was last
                times = max(0, min(200, int(times or 0)))
                for number in range(1, times + 1):
                    inner = dict(scope or {})
                    inner['loop_i'] = str(number)
                    inner['loop_n'] = str(times)
                    inner['loop_first'] = 'yes' if number == 1 else ''
                    inner['loop_last'] = 'yes' if number == times else ''
                    turn = build(branches[0], inner)
                    out.append(turn)
                    if not spend(turn):
                        break
            elif kind == 'for':
                found = re.match(r'^\s*(?:each\s+)?([A-Za-z][A-Za-z0-9_]*)\s+(?:in|of)\s+(.+)$', what)
                if not found:
                    continue
                name, over = found.group(1), found.group(2).strip()
                stands = resolve(over.strip('{} '), scope)
                # a list written out on the spot is a list too:
                # {for p in Plug-UPS, Plug-TV}
                items = _fact_items(stands if stands is not None else over)[:200]
                for number, item in enumerate(items, 1):
                    inner = dict(scope or {})
                    inner[name.lower()] = item
                    inner['loop_i'] = str(number)
                    inner['loop_n'] = str(len(items))
                    inner['loop_first'] = 'yes' if number == 1 else ''
                    inner['loop_last'] = 'yes' if number == len(items) else ''
                    turn = build(branches[0], inner)
                    out.append(turn)
                    if not spend(turn):
                        break
        return ''.join(out)

    made = build(_block_tree(text), None)
    if budget['cut']:
        log('a message’s loops were stopped after %d turns and %d characters'
            % (budget['turns'], budget['chars']), 'warn')
        made = made[:BLOCK_TEXT_MOST] + BLOCK_CUT
    return made


# Turns of phrase that carry something of their own, after a colon:
# {who.default:nobody}, {name.left:12}, {plugs_on_list.join: · }. The
# thing after the colon is taken as it stands - spaces and all, so a
# separator can be " and ".
def _with_number(text, arg, how):
    number = _fact_number(text)
    other = _fact_number(arg)
    if number is None or other is None:
        return str(text or '')
    try:
        return _fact_round(how(number, other), 2)
    except ZeroDivisionError:
        return str(text or '')


def _fact_nums(text):
    return [n for n in (_fact_number(x) for x in _fact_items(text)) if n is not None]


FACT_TURNS_WITH = {
    # text
    'default': lambda t, a: (str(t or '') if str(t or '').strip()
                             and str(t or '').strip().lower() not in FACT_EMPTY else a),
    'prefix': lambda t, a: (a + str(t or '')) if str(t or '').strip() else '',
    'suffix': lambda t, a: (str(t or '') + a) if str(t or '').strip() else '',
    'wrap': lambda t, a: (a + str(t or '') + a) if str(t or '').strip() else '',
    'left': lambda t, a: str(t or '')[:max(0, int(_fact_number(a) or 0))],
    'right': lambda t, a: str(t or '')[-max(0, int(_fact_number(a) or 0)):] if _fact_number(a) else '',
    'cut': lambda t, a: (str(t or '')[:max(0, int(_fact_number(a) or 0) - 1)] + '…')
                        if len(str(t or '')) > int(_fact_number(a) or 0) else str(t or ''),
    'pad': lambda t, a: str(t or '').ljust(max(0, int(_fact_number(a) or 0))),
    'padleft': lambda t, a: str(t or '').rjust(max(0, int(_fact_number(a) or 0))),
    'replace': lambda t, a: str(t or '').replace(a.split(':', 1)[0], a.split(':', 1)[1]) if ':' in a else str(t or ''),
    'after': lambda t, a: str(t or '').split(a, 1)[-1] if a and a in str(t or '') else '',
    'before': lambda t, a: str(t or '').split(a, 1)[0] if a and a in str(t or '') else str(t or ''),
    'unit': lambda t, a: ('%s %s' % (str(t or '').strip(), a)) if str(t or '').strip() else '',

    # lists
    'join': lambda t, a: a.join(_fact_items(t)),
    'head': lambda t, a: ', '.join(_fact_items(t)[:max(0, int(_fact_number(a) or 0))]),
    'tail': lambda t, a: ', '.join(_fact_items(t)[-max(0, int(_fact_number(a) or 0)):]) if _fact_number(a) else '',
    'nth': lambda t, a: _fact_nth(_fact_items(t), _fact_number(a)),
    'has': lambda t, a: ('yes' if a.strip().lower() in [x.lower() for x in _fact_items(t)] else 'no'),
    'without': lambda t, a: ', '.join(x for x in _fact_items(t) if x.lower() != a.strip().lower()),

    # numbers
    'add': lambda t, a: _with_number(t, a, lambda x, y: x + y),
    'minus': lambda t, a: _with_number(t, a, lambda x, y: x - y),
    'times': lambda t, a: _with_number(t, a, lambda x, y: x * y),
    'divide': lambda t, a: _with_number(t, a, lambda x, y: x / y),
    'decimals': lambda t, a: _fact_round(t, max(0, min(6, int(_fact_number(a) or 0)))),
    'atleast': lambda t, a: _with_number(t, a, lambda x, y: max(x, y)),
    'atmost': lambda t, a: _with_number(t, a, lambda x, y: min(x, y)),

    # time, written the way you ask
    'clock': _fact_clock,
    'plusdays': lambda t, a: (lambda w: str(t or '') if w is None
                              else (w + timedelta(days=int(_fact_number(a) or 0))).strftime('%Y-%m-%d'))(_fact_moment(t)),
    'plushours': lambda t, a: (lambda w: str(t or '') if w is None
                               else (w + timedelta(hours=float(_fact_number(a) or 0))).strftime('%H:%M'))(_fact_moment(t)),
    'plusmins': lambda t, a: (lambda w: str(t or '') if w is None
                              else (w + timedelta(minutes=float(_fact_number(a) or 0))).strftime('%H:%M'))(_fact_moment(t)),

    # a yes or a no of one's own words: {anyone_home.say:everyone is out}
    'say': lambda t, a: (a if fact_truth(t) else ''),
    'saynot': lambda t, a: ('' if fact_truth(t) else a),
    'ifempty': lambda t, a: (str(t or '') if str(t or '').strip() else a),
}


def apply_turn(text, turn):
    """One turn of phrase, with or without something of its own after a colon."""
    name, _, arg = str(turn).partition(':')
    name = name.lower()
    try:
        if name in FACT_TURNS_WITH:
            return FACT_TURNS_WITH[name](text, arg)
        if name in FACT_TURNS:
            return FACT_TURNS[name](text)
    except Exception:
        return str(text or '')
    return str(text or '')


def cpu_temperature():
    """The processor's own temperature in degrees, or None.

    thermal_zone0 alone is right on a Pi, where it IS the processor, and
    wrong on most else: on x86 zone0 is commonly an ACPI or a battery zone
    and the package temperature lives under coretemp in hwmon. Read from one
    place only, this said nothing at all on those machines - and the alert on
    a hot processor had the same blind spot, because it read the same path.
    So: the zones that call themselves the processor first, then hwmon, then
    whatever zone0 says as a last resort.
    """
    def degrees(path):
        raw = _read_first_line(path)
        try:
            value = int(str(raw).strip())
        except (TypeError, ValueError):
            return None
        value = value / 1000.0 if abs(value) > 200 else float(value)
        return round(value, 1) if -40.0 < value < 150.0 else None

    want = ('cpu_thermal', 'cpu-thermal', 'x86_pkg_temp', 'soc_thermal', 'coretemp', 'k10temp')
    try:
        zones = sorted(os.listdir('/sys/class/thermal'))
    except OSError:
        zones = []
    for zone in zones:
        if not zone.startswith('thermal_zone'):
            continue
        kind = str(_read_first_line('/sys/class/thermal/%s/type' % zone) or '').strip().lower()
        if kind in want:
            found = degrees('/sys/class/thermal/%s/temp' % zone)
            if found is not None:
                return found
    try:
        boxes = sorted(os.listdir('/sys/class/hwmon'))
    except OSError:
        boxes = []
    for box in boxes:
        name = str(_read_first_line('/sys/class/hwmon/%s/name' % box) or '').strip().lower()
        if name in ('coretemp', 'k10temp', 'zenpower', 'cpu_thermal'):
            found = degrees('/sys/class/hwmon/%s/temp1_input' % box)
            if found is not None:
                return found
    return degrees('/sys/class/thermal/thermal_zone0/temp')


def _read_first_line(where):
    """The first line of a file that may not be there: /sys is like that."""
    try:
        with open(where) as fh:
            return fh.readline().strip()
    except (OSError, ValueError):
        return ''


def _memory_free_pct():
    try:
        info = {}
        with open('/proc/meminfo') as fh:
            for line in fh:
                key, _, value = line.partition(':')
                bits = value.split()
                if bits:
                    info[key] = int(bits[0])
        if info.get('MemTotal'):
            return round(info.get('MemAvailable', info['MemTotal']) * 100.0 / info['MemTotal'], 1)
    except (OSError, ValueError):
        pass
    return ''


def untouched_row(item, keys):
    """A row just added and not yet filled in.

    Pressing Add leaves one of these in every editor, and refusing the whole
    list for it meant that from that moment nothing could be saved at all -
    which reads as "saving is broken" rather than "finish this row". An
    unfinished thought is passed over; a half-filled one is still refused,
    because that is a mistake rather than a blank.
    """
    if not isinstance(item, dict):
        return False
    # The section a row is filed under is not something somebody typed: the
    # "+" on a section stamps its name onto the new blank row, and counting
    # that as filled in made the whole list refuse to save ("binding 4 needs
    # a device, an action and a plug") until the blank row was removed by
    # hand. It is passed over wherever it is named.
    return not any(str(item.get(k) or '').strip() for k in keys if k != 'group')


def valid_action(do):
    """'on', 'off', 'toggle', 'pulse', 'set:<value>' (a number, or a mode a
    device names), 'for:<time>' (on now, off again after) and 'step:<+/-n>'
    (a nudge from wherever it is now)."""
    do = str(do or '').strip()
    if do.lower() in BINDING_ACTIONS or do.lower() in PLUG_EXTRA_ACTIONS:
        return do.lower()
    if do.lower().startswith('set:') and 1 <= len(do[4:].strip()) <= 40:
        return 'set:' + do[4:].strip()
    for word in ('for:', 'off-for:'):
        if do.lower().startswith(word) and parse_while(do[len(word):]) is not None:
            return word + do[len(word):].strip().lower()
    if do.lower().startswith('step:'):
        rest = do[5:].strip().replace(',', '.')
        if re.match(r'^[+-]?\d+(\.\d+)?$', rest):
            return 'step:' + rest
    return None
RULE_OPS = ['>=', '<=', '>', '<', '==', '!=']
_UNKNOWN_OPS_SAID = set()           # a comparison nobody knows is complained about once
RULE_COOLDOWN_DEFAULT = 300
PULSE_MS_DEFAULT = 5000
SELFTEST_NAME = 'zigmon-selftest'   # the probe uses a real /set topic, on a device that does not exist
PULSE_MS_MIN, PULSE_MS_MAX = 100, 3600000
PLUG_HEADLINE = ['switch.apower', 'switch.aenergy.total', 'switch.output', 'switch.voltage']


# ---------------------------------------------------------------------------
# Wi-Fi presence: who is at home
# ---------------------------------------------------------------------------
# A phone on the house Wi-Fi is a good enough answer to "is anyone in". It is
# not a perfect one: a phone sleeps its radio, so it drops off the controller
# for a minute or two while its owner is asleep in the next room. Arriving is
# therefore believed at once and leaving only after a grace period.

UNIFI_PREFIXES = ['/proxy/network/integration/v1', '/proxy/network/integrations/v1']
PRESENCE_GRACE_S = 600          # gone this long before we call it "out"
WIFI_POLL_S = 30


def _unifi_opener(verify_ssl):
    import urllib.request
    if verify_ssl:
        return urllib.request.build_opener()
    context = ssl.create_default_context()
    context.check_hostname = False
    context.verify_mode = ssl.CERT_NONE
    return urllib.request.build_opener(urllib.request.HTTPSHandler(context=context))


UNIFI_QUICK = threading.local()      # .timeout set by a thread that cannot wait the full 15 s
REQUEST_CALLER = threading.local()   # .who: the address an API request is counted against;
                                     # .path: the road asked for; .cli: the root command line


# ---- accounts of the dashboard (5.19) ----------------------------------------------
# A name and a password, as otp has them, in place of the one PIN everybody
# shared. Three roles: somebody who only looks, somebody who uses the house
# (switches, scenes, heating, the alerts), and somebody who looks after it
# (every setting, the accounts, the machine itself). What the PIN stood in
# front of is the administrator's; the few things a person does every day
# are the operator's as well.
ROLES = ('viewer', 'operator', 'admin')
ROLE_RANK = {'viewer': 1, 'operator': 2, 'admin': 3}
ROLE_NAMES = {'viewer': 'Read only', 'operator': 'Operator', 'admin': 'Administrator'}
ROLE_WORDS = {'viewer': 'sees the house - also when the view is not public - and changes nothing',
              'operator': 'uses the house: switches the sockets and lights, runs scenes and '
                          'sequences, sets the heating of the rooms, clears the alerts; no settings, '
                          'no switching rules off',
              'admin': 'everything: the settings, the security, the accounts, the machine'}
# What an operator may do: what a person living in the house does every day.
# Everything else that changes something is an administrator's.
OPERATOR_ROADS = frozenset((
    '/api/plug/switch', '/api/scene/run', '/api/sequence/advance', '/api/sequence/reset',
    '/api/target/set', '/api/hold/release', '/api/alerts/clear', '/api/rule/dryrun',
    '/api/what-if', '/api/plug/diagnose', '/api/energy/monthly'))
# What somebody who still has to change their first password may do.
MUST_CHANGE_ROADS = ('/api/auth/password', '/api/auth/logout', '/api/auth/whoami')
ACCOUNT_NAME = re.compile(r'^[A-Za-z0-9][A-Za-z0-9._@-]{0,63}$')


def password_hash(password, salt=None, rounds=310000):
    """PBKDF2-SHA256, as otp keeps its own: nothing outside the standard library."""
    salt = salt or secrets.token_bytes(16)
    got = hashlib.pbkdf2_hmac('sha256', str(password).encode('utf-8'), salt, rounds)
    return 'pbkdf2_sha256$%d$%s$%s' % (rounds, base64.b64encode(salt).decode('ascii'),
                                       base64.b64encode(got).decode('ascii'))


def password_ok(password, stored):
    try:
        kind, rounds, salt, want = str(stored or '').split('$')
        if kind != 'pbkdf2_sha256':
            return False
        got = hashlib.pbkdf2_hmac('sha256', str(password).encode('utf-8'),
                                  base64.b64decode(salt), int(rounds))
        return hmac.compare_digest(got, base64.b64decode(want))
    except (ValueError, TypeError):
        return False


def password_problem(password):
    """Why a password for an account here will not do, or ''."""
    p = str(password or '')
    if len(p) < 8:
        return 'a password needs at least eight characters'
    if len(p) > 200:
        return 'that password is longer than anybody types'
    return ''


DUMMY_PW_HASH = None          # made on first use: a sign-in for nobody takes as long
# A PIN account (5.19.1): somebody - or a tablet, or the whole household as
# before - signs in with a PIN alone, and holds the role its account has. A
# PIN is short by nature, so it is guarded by how few tries are allowed, not
# by its length; and no two accounts may share one, or a PIN would not say
# who it is.
PIN_RE = re.compile(r'^[0-9A-Za-z]{4,12}$')
PIN_ROUNDS = 60000


def pin_problem(pin):
    if not PIN_RE.match(str(pin or '')):
        return 'a PIN is 4 to 12 digits (or letters), with nothing else in it'
    return ''


def cli_key_path():
    """The command line's key: beside the API token, readable by the daemon's
    own account and root only. The web server reads the token (it relays every
    request), so the token alone proves nothing about who is asking; this
    file it cannot read."""
    return token_path().parent / 'cli-key'


def read_cli_key():
    try:
        return cli_key_path().read_text().strip()
    except OSError:
        return ''


def _unifi_get(opener, url, headers, timeout=15, data=None, method=None):
    import urllib.error
    import urllib.request
    timeout = min(timeout, getattr(UNIFI_QUICK, 'timeout', timeout) or timeout)
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with opener.open(request, timeout=timeout) as response:
            body = response.read().decode('utf-8', 'replace')
            return response.status, dict(response.headers), (json.loads(body) if body.strip() else {})
    except urllib.error.HTTPError as e:
        body = e.read().decode('utf-8', 'replace')
        try:
            parsed = json.loads(body) if body.strip() else {}
        except ValueError:
            parsed = {'error': body[:200]}
        return e.code, dict(e.headers or {}), parsed
    except urllib.error.URLError as e:
        raise RuntimeError('cannot reach %s: %s' % (url.split('/')[2], e.reason))
    except socket.timeout:
        raise RuntimeError('%s did not answer in time' % url.split('/')[2])


# Signing in is not free: the controller counts attempts and answers 429 once
# there have been too many. Asking who is at home every thirty seconds and
# logging in each time is exactly the pattern it guards against, so a session
# is opened once and kept - and deliberately not logged out afterwards, since
# logging out is what forces the next request to sign in again.
_UNIFI_SESSIONS = {}
_UNIFI_SESSION_LOCK = threading.Lock()
UNIFI_SESSION_MAX_AGE = 1800
UNIFI_LOCKOUT_S = 600


def _creds_fingerprint(cfg):
    """Enough to tell one set of credentials from another, without keeping
    them: only whether what is stored has changed since it was refused."""
    import hashlib
    raw = '%s|%s' % (cfg.get('username') or '', cfg.get('password') or '')
    return hashlib.sha256(raw.encode('utf-8')).hexdigest()[:16]


def _unifi_session(cfg, force=False):
    """A signed-in opener for this controller, made once and reused."""
    import urllib.request
    key = (str(cfg.get('host')), int(cfg.get('port') or 443), str(cfg.get('username') or ''))
    now = time.time()
    with _UNIFI_SESSION_LOCK:
        entry = _UNIFI_SESSIONS.get(key)
        # a password that was rejected gets one more chance the moment it is
        # changed, and not before
        if entry and entry.get('rejected') and entry['rejected'] != _creds_fingerprint(cfg):
            entry = None
            _UNIFI_SESSIONS.pop(key, None)
        if entry and entry.get('blocked_until', 0) > now:
            if entry.get('rejected'):
                raise RuntimeError('the controller rejected this username and password (HTTP %s). '
                                   'Nothing more will be tried until they are changed, because '
                                   'repeating a wrong password is what locks the account out.'
                                   % entry.get('last_status'))
            raise RuntimeError('the controller asked for a pause after %d refusal(s) in a row; '
                               '%s left of it'
                               % (entry.get('strikes') or 1, human_age(entry['blocked_until'] - now)))
        # a record of a lockout carries no opener; once it lapses a real
        # sign-in has to happen rather than the note being handed back
        if entry and entry.get('opener') and not force:
            age = now - entry['at']
            if age < UNIFI_SESSION_MAX_AGE:
                return entry
            # past its age, ask the controller to extend it instead of signing
            # in again - a refusal here simply falls through to a fresh sign-in
            status, headers, _ = _unifi_get(entry['opener'], entry['base'] + '/api/auth/refresh',
                                            dict(entry['head'], **{'Content-Type': 'application/json'}),
                                            data=b'', method='POST')
            if status < 400:
                fresh = _unifi_csrf(headers)
                if fresh:
                    entry['head']['X-CSRF-Token'] = fresh
                entry['at'] = now
                return entry
        opener = _unifi_opener(bool(cfg.get('verify_ssl')))
        opener.add_handler(urllib.request.HTTPCookieProcessor())
        base = 'https://%s:%d' % (cfg.get('host'), int(cfg.get('port') or 443))
        payload = json.dumps({'username': cfg.get('username') or '',
                              'password': cfg.get('password') or '',
                              'token': '', 'rememberMe': True}).encode()
        # Two doors: UniFi OS answers on /api/auth/login, the classic
        # controller on /api/login. A self-hosted server may rate-limit one
        # and let the other through, so both are tried before giving up.
        status, headers, answer = None, {}, {}
        for path in ('/api/auth/login', '/api/login'):
            status, headers, answer = _unifi_get(opener, base + path,
                                                 {'Content-Type': 'application/json'}, data=payload)
            if status < 400:
                break
            if status not in (404, 429):
                break
        # "You've reached the login attempt limit" counts FAILED sign-ins: the
        # password is wrong, and trying again is what keeps the account locked.
        code = str((answer or {}).get('code') or '')
        if status == 429 and 'AUTHENTICATION_FAILED' in code.upper():
            status = 401
        if status in (400, 401, 403):
            # Repeating a rejected password is how an account gets locked out
            # of its own controller. It is not tried again until somebody
            # changes what is stored.
            _UNIFI_SESSIONS[key] = {'blocked_until': now + 86400, 'at': now, 'last_status': status,
                                    'rejected': _creds_fingerprint(cfg)}
            raise RuntimeError('the controller rejected the sign-in (HTTP %s%s). It will not be tried '
                               'again until the username or password is changed - repeating a wrong '
                               'password is what locks the account out.'
                               % (status, ', ' + code if code else ''))
        if status == 429:
            # Trying again the moment the wait lapses is how a lockout renews
            # itself forever: the controller's own window is longer than the
            # one it hands out. Each refusal in a row doubles the wait.
            strikes = int((entry or {}).get('strikes') or 0) + 1
            asked = numeric(headers.get('Retry-After'))
            wait = min(3600, int(asked or UNIFI_LOCKOUT_S) * (2 ** (strikes - 1)))
            _UNIFI_SESSIONS[key] = {'blocked_until': now + wait, 'at': now, 'strikes': strikes,
                                    'last_status': 429}
            raise RuntimeError('the controller answered 429 to the sign-in (%d in a row); '
                               'waiting %s before trying again' % (strikes, human_age(wait)))
        if status >= 400:
            raise RuntimeError('signing in failed with HTTP %s' % status)
        head = {'Accept': 'application/json'}
        token = _unifi_csrf(headers)
        if not token:
            # UniFi OS hands the cross-site token back on the first read rather
            # than with the sign-in; its own pages fetch this very endpoint for
            # it, and every read after that carries it.
            st, who, _ = _unifi_get(opener, base + '/api/users/self', head)
            token = _unifi_csrf(who)
        if token:
            head['X-CSRF-Token'] = token
        entry = {'opener': opener, 'head': head, 'at': now, 'base': base, 'strikes': 0}
        _UNIFI_SESSIONS[key] = entry
        return entry


def _unifi_csrf(headers):
    """The cross-site token from a reply. It rotates, and a fresh one comes
    back under x-updated-csrf-token rather than the name it was first sent
    under, so both are looked at."""
    for name in ('x-updated-csrf-token', 'X-Updated-Csrf-Token',
                 'x-csrf-token', 'X-CSRF-Token', 'X-Csrf-Token'):
        if headers.get(name):
            return headers[name]
    return None


def _unifi_signed_get(cfg, path):
    """One signed-in read, renewing the session if it has been dropped."""
    entry = _unifi_session(cfg)
    status, headers, body = _unifi_get(entry['opener'], entry['base'] + path, entry['head'])
    fresh = _unifi_csrf(headers)
    if fresh:
        entry['head']['X-CSRF-Token'] = fresh      # it rotates; keep up with it
    if status in (401, 403):
        entry = _unifi_session(cfg, force=True)
        status, headers, body = _unifi_get(entry['opener'], entry['base'] + path, entry['head'])
        fresh = _unifi_csrf(headers)
        if fresh:
            entry['head']['X-CSRF-Token'] = fresh
    return status, body


def _probe_access_points(d, cfg):
    """What each access point says when asked - the diagnostic that matters
    now that they are the source of the detail."""
    out = {}
    for ap in (d.wifi.get('detail') or {}).get('aps') or []:
        host = ap.get('ip')
        if not host:
            out[ap.get('name') or '?'] = {'error': 'the controller gave no address for it'}
            continue
        try:
            info = parse_ap_info(ap_run(cfg, host, 'info'))
            seen = parse_mca_dump(ap_run(cfg, host, 'dump'))
            out[ap.get('name') or host] = {
                'ok': True, 'address': host, 'model': info.get('model') or seen.get('model'),
                'version': info.get('version') or seen.get('version'),
                'clients': len(seen.get('clients') or []),
                'radios': len(seen.get('radios') or []),
                'networks': len(seen.get('networks') or []),
                'temperature': seen.get('temperature'),
            }
        except Exception as e:
            out[ap.get('name') or host] = {'ok': False, 'address': host, 'error': str(e)[:140]}
    return out or {'note': 'no access point with an address is known yet - ask the controller first'}


def unifi_signin_probe(cfg):
    """Sign in once, on purpose, and report exactly what came back. A 429 says
    the account is being rate-limited; a 401 says the credentials are wrong;
    they are not the same problem and the difference matters."""
    import urllib.request
    host = str(cfg.get('host') or '')
    base = 'https://%s:%d' % (host, int(cfg.get('port') or 443))
    out = {'host': host, 'username': cfg.get('username') or '(none)',
           'has_password': bool(cfg.get('password'))}
    key = (host, int(cfg.get('port') or 443), str(cfg.get('username') or ''))
    entry = _UNIFI_SESSIONS.get(key) or {}
    if entry.get('blocked_until', 0) > time.time():
        out['waiting_for'] = int(entry['blocked_until'] - time.time())
        out['refusals_in_a_row'] = entry.get('strikes')
    opener = _unifi_opener(bool(cfg.get('verify_ssl')))
    opener.add_handler(urllib.request.HTTPCookieProcessor())
    payload = json.dumps({'username': cfg.get('username') or '',
                          'password': cfg.get('password') or ''}).encode()
    for path in ('/api/auth/login', '/api/login'):
        status, headers, body = _unifi_get(opener, base + path,
                                           {'Content-Type': 'application/json'}, data=payload)
        entry_out = {'status': status}
        for name in ('Retry-After', 'X-Ratelimit-Limit', 'X-Ratelimit-Remaining', 'X-Ratelimit-Reset'):
            if headers.get(name):
                entry_out[name] = headers[name]
        if isinstance(body, dict):
            entry_out['answer'] = {k: str(v)[:80] for k, v in list(body.items())[:6]}
        out[path] = entry_out
        if status < 400:
            out[path]['csrf_from_signin'] = bool(headers.get('x-csrf-token') or headers.get('X-CSRF-Token'))
            site = cfg.get('site') or 'default'
            # exactly what the reader asks, with the same session and token
            for label, where in (('clients (v2)', '/proxy/network/v2/api/site/%s/clients/active' % site),
                                 ('clients (older)', '/proxy/network/api/s/%s/stat/sta' % site),
                                 ('access points', '/proxy/network/api/s/%s/stat/device' % site)):
                try:
                    st, sample = _unifi_signed_get(cfg, where)
                except Exception as e:
                    out[label] = {'error': str(e)[:90]}
                    continue
                rows = sample if isinstance(sample, list) else ((sample or {}).get('data') or [])
                out[label] = {'status': st, 'rows': len(rows)}
                if rows and label.startswith('clients'):
                    out[label]['fields'] = sorted(rows[0].keys())[:18]
            break
    return out


def unifi_wants_legacy(cfg):
    """Whether to sign in at all.

    Signing in is the older way to a client's network, signal and channel.
    Asking the access points over SSH answers the same questions without a
    sign-in for the controller to count, so once that is on, this is left
    alone: a controller that locks an account out after a few failures is not
    worth troubling for something already in hand."""
    method = str(cfg.get('method') or 'official')
    if method == 'official':
        return False
    if cfg.get('ssh_enabled') and method == 'both':
        return False
    if method == 'legacy':
        return True
    return bool(cfg.get('username')) and bool(cfg.get('password'))


def unifi_clients(cfg):
    """Everything the controller currently sees, normalised. Wired clients are
    kept: a desktop is as good a sign of someone being in as a phone."""
    host = str(cfg.get('host') or '').strip()
    if not host:
        raise ValueError('the controller needs an address')
    port = int(cfg.get('port') or 443)
    base = 'https://%s:%d' % (host, port)
    opener = _unifi_opener(bool(cfg.get('verify_ssl')))
    if not unifi_wants_legacy(cfg):
        return _unifi_official(cfg, base, opener)
    try:
        return _unifi_legacy(cfg, base, opener)
    except Exception as e:
        if str(cfg.get('method')) != 'both' or not cfg.get('api_key'):
            raise
        log('wifi: signing in failed (%s), falling back to the API key' % e, 'warn')
        return _unifi_official(cfg, base, _unifi_opener(bool(cfg.get('verify_ssl'))))


UNIFI_BANDS = {'ng': '2.4', 'na': '5', '6e': '6', 'ax': '6'}
UNIFI_GENERATIONS = {'a': 'WiFi 2', 'b': 'WiFi 1', 'g': 'WiFi 3', 'n': 'WiFi 4', 'ng': 'WiFi 4',
                     'na': 'WiFi 4', 'ac': 'WiFi 5', 'ax': 'WiFi 6', 'be': 'WiFi 7'}


def unifi_band(radio, channel=None):
    """Which band a radio is on. The controller names them ng, na and 6e; a
    channel above 100 with a 6 GHz radio is not the same as one on 5 GHz, so
    the radio name is trusted first and the channel is only a fallback."""
    name = str(radio or '').lower()
    if name in UNIFI_BANDS:
        return UNIFI_BANDS[name]
    if isinstance(channel, int):
        if channel <= 14:
            return '2.4'
        return '5'
    return None


def unifi_generation(proto):
    name = str(proto or '').lower()
    if name in UNIFI_GENERATIONS:
        return UNIFI_GENERATIONS[name]          # "na" is 802.11n on 5 GHz, not "a"
    for key in ('be', 'ax', 'ac', 'ng', 'na', 'n', 'g', 'b', 'a'):
        if name.endswith(key) or name == key:
            return UNIFI_GENERATIONS[key]
    return ''


def unifi_probe(cfg):
    """What the controller actually answers, in outline. Field names differ
    between firmware revisions, and guessing at them from the outside is how
    an empty tab happens; this shows the shape so it can be read rather than
    assumed. Values are shortened and anything that looks like a secret is
    left out."""
    def outline(value, depth=0):
        if isinstance(value, dict):
            if depth >= 3:
                return '{%d keys}' % len(value)
            return {k: outline(v, depth + 1) for k, v in list(value.items())[:40]
                    if not re.search(r'key|pass|secret|token', str(k), re.I)}
        if isinstance(value, list):
            return [outline(v, depth + 1) for v in value[:2]] if value else []
        if isinstance(value, str):
            return value[:60]
        return value

    host = str(cfg.get('host') or '').strip()
    base = 'https://%s:%d' % (host, int(cfg.get('port') or 443))
    opener = _unifi_opener(bool(cfg.get('verify_ssl')))
    out = {'method': cfg.get('method')}
    if not cfg.get('api_key'):
        out['note'] = 'No API key is stored, so there is nothing to ask this way.'
        return out
    headers = {'X-API-KEY': str(cfg.get('api_key') or ''), 'Accept': 'application/json'}
    prefix = site_id = None
    for candidate in UNIFI_PREFIXES:
        status, _, body = _unifi_get(opener, base + candidate + '/sites', headers)
        out.setdefault('sites', {})[candidate] = status
        if status < 400 and (body.get('data') or []):
            prefix, site_id = candidate, body['data'][0]['id']
            break
    if not prefix:
        out['error'] = 'no site could be read'
        return out
    out['prefix'], out['site'] = prefix, site_id
    for name, path in (('info', '/info'),
                       ('devices', '/sites/%s/devices?limit=3' % site_id),
                       ('clients', '/sites/%s/clients?limit=3' % site_id)):
        status, _, body = _unifi_get(opener, base + prefix + path, headers)
        rows = body.get('data') if isinstance(body, dict) else None
        entry = {'status': status}
        if isinstance(rows, list):
            entry['count'] = body.get('totalCount', len(rows))
            entry['first'] = outline(rows[0]) if rows else None
        else:
            entry['body'] = outline(body)
        out[name] = entry
    first = ((out.get('devices') or {}).get('first')) or {}
    if first:
        out['reads_as_access_point'] = _is_access_point(first)
        status, _, stats = _unifi_get(
            opener, '%s%s/sites/%s/devices/%s/statistics/latest' % (base, prefix, site_id, first.get('id')), headers)
        out['statistics'] = {'status': status, 'shape': outline(stats)}
    return out


# ---------------------------------------------------------------------------
# Asking the access points themselves
# ---------------------------------------------------------------------------
# The controller's key interface will not say which network a client is on,
# nor its signal. The points know both, and answer over SSH. Nothing here
# writes: the commands are a fixed list in this file, none of them changes
# anything, and no part of it is built from what somebody typed.

# `info` is a shell function from the interactive profile, not a program, so a
# non-interactive session cannot find it by that name. Each entry is therefore
# a list of ways to ask, tried in turn until one works.
AP_COMMANDS = {
    # the whole picture: radios, networks and every station on them
    'dump': ['mca-dump', '/usr/bin/mca-dump'],
    # what it is and how long it has been up; the dump carries all of this too,
    # so this is only a lighter way of asking
    'info': ['mca-cli-op info', '/usr/bin/mca-cli-op info',
             '. /etc/profile >/dev/null 2>&1; info', 'info'],
}
SSH_CONNECT_TIMEOUT = 8
SSH_RUN_TIMEOUT = 25


_SSH_THERE = None


def ssh_available():
    """Whether ssh is on the machine.

    This walks the whole of PATH, and the answer was being asked for on every
    status - which is many times a second with two tabs open. It does not
    change while the daemon runs.
    """
    global _SSH_THERE
    if _SSH_THERE is None:
        _SSH_THERE = bool(shutil.which('ssh'))
    return _SSH_THERE


def ssh_keygen_available():
    return bool(shutil.which('ssh-keygen'))


def generate_ssh_key(comment='zigmon'):
    """A fresh ed25519 pair. The private half is what gets stored; the public
    half is what goes into the controller."""
    if not ssh_keygen_available():
        raise RuntimeError('ssh-keygen is not installed (dnf install openssh-clients)')
    folder = tempfile.mkdtemp(prefix='zigmon-key-')
    path = os.path.join(folder, 'id')
    try:
        run = subprocess.run(['ssh-keygen', '-t', 'ed25519', '-N', '', '-C', comment, '-f', path],
                             capture_output=True, timeout=30)
        if run.returncode != 0:
            raise RuntimeError('ssh-keygen failed: %s' % (run.stderr or b'').decode('utf-8', 'replace')[:200])
        with open(path, encoding='utf-8') as f:
            private = f.read()
        with open(path + '.pub', encoding='utf-8') as f:
            public = f.read().strip()
        return private, public
    finally:
        shutil.rmtree(folder, ignore_errors=True)


def ssh_public_from_private(private):
    """The public half of a key somebody uploaded, so it can be shown to them
    without asking for it twice."""
    if not ssh_keygen_available() or not private:
        return ''
    folder = tempfile.mkdtemp(prefix='zigmon-key-')
    path = os.path.join(folder, 'id')
    try:
        with open(path, 'w', encoding='utf-8') as f:
            f.write(private if private.endswith('\n') else private + '\n')
        os.chmod(path, 0o600)
        run = subprocess.run(['ssh-keygen', '-y', '-P', '', '-f', path], capture_output=True, timeout=20)
        if run.returncode != 0:
            return ''
        return run.stdout.decode('utf-8', 'replace').strip()
    except Exception:
        return ''
    finally:
        shutil.rmtree(folder, ignore_errors=True)


def _ssh_argv(cfg, host, key_path=None):
    port = int(numeric(cfg.get('ssh_port')) or 22)
    argv = ['ssh', '-p', str(port),
            '-o', 'ConnectTimeout=%d' % SSH_CONNECT_TIMEOUT,
            '-o', 'StrictHostKeyChecking=accept-new',
            '-o', 'UserKnownHostsFile=%s' % str(RUN_DIR / 'known_hosts'),
            '-o', 'LogLevel=ERROR',
            '-o', 'PreferredAuthentications=' + ('publickey' if key_path else 'password,keyboard-interactive'),
            '-o', 'NumberOfPasswordPrompts=1']
    if key_path:
        argv += ['-i', key_path, '-o', 'IdentitiesOnly=yes', '-o', 'BatchMode=yes']
    argv.append('%s@%s' % (str(cfg.get('ssh_user') or 'admin'), host))
    return argv


def ap_run(cfg, host, what):
    """One read-only command on one access point.

    `what` names an entry in AP_COMMANDS; nothing else can be run, so no
    caller - and nothing arriving over the network - can turn this into a way
    of changing a device."""
    if what not in AP_COMMANDS:
        raise ValueError('%r is not one of the commands this can run' % what)
    if not ssh_available():
        raise RuntimeError('the ssh client is not installed (dnf install openssh-clients)')
    trouble = None
    for command in AP_COMMANDS[what]:
        try:
            return _ap_run_one(cfg, host, command)
        except RuntimeError as e:
            # "not found" means this firmware spells it differently; anything
            # else is a real problem and there is no point trying the rest
            if 'not found' not in str(e).lower():
                raise
            trouble = e
    raise trouble or RuntimeError('none of the ways of asking worked')


def _ap_run_one(cfg, host, command):
    key_path = None
    folder = None
    try:
        if str(cfg.get('ssh_auth') or 'key') == 'key':
            private = cfg.get('ssh_key') or ''
            if not private:
                raise RuntimeError('no private key is stored yet')
            folder = tempfile.mkdtemp(prefix='zigmon-ssh-')
            key_path = os.path.join(folder, 'id')
            with open(key_path, 'w', encoding='utf-8') as f:
                f.write(private if private.endswith('\n') else private + '\n')
            os.chmod(key_path, 0o600)
            argv = _ssh_argv(cfg, host, key_path) + [command]
            run = subprocess.run(argv, capture_output=True, timeout=SSH_RUN_TIMEOUT)
            out, err, code = run.stdout, run.stderr, run.returncode
        else:
            out, err, code = _ssh_with_password(cfg, host, command)
        text = out.decode('utf-8', 'replace')
        if code != 0:
            why = err.decode('utf-8', 'replace').strip().splitlines()
            raise RuntimeError(why[-1][:160] if why else 'ssh exited %s' % code)
        return text
    except subprocess.TimeoutExpired:
        raise RuntimeError('%s did not answer within %d s' % (host, SSH_RUN_TIMEOUT))
    finally:
        if folder:
            shutil.rmtree(folder, ignore_errors=True)


def _ssh_with_password(cfg, host, command):
    """Password authentication without another package: ssh insists on a
    terminal for the prompt, so it is given one and answered."""
    import pty
    argv = _ssh_argv(cfg, host) + [command]
    password = (str(cfg.get('ssh_password') or '') + '\n').encode()
    pid, fd = pty.fork()
    if pid == 0:                                  # the child becomes ssh
        try:
            os.execvp(argv[0], argv)
        finally:
            os._exit(127)
    out = b''
    sent = False
    finished = False
    deadline = time.time() + SSH_RUN_TIMEOUT
    try:
        while time.time() < deadline and not finished:
            ready, _, _ = select.select([fd], [], [], 0.4)
            if ready:
                try:
                    chunk = os.read(fd, 65536)
                except OSError:
                    finished = True          # the far end closed: it is done
                    break
                if not chunk:
                    finished = True
                    break
                out += chunk
                if not sent and b'assword' in out[-200:]:
                    os.write(fd, password)
                    sent = True
                    out = b''                # the prompt itself is not output
            else:
                done, status = os.waitpid(pid, os.WNOHANG)
                if done:
                    finished = True
                    break
        if not finished:
            os.kill(pid, signal.SIGKILL)
            raise subprocess.TimeoutExpired(argv, SSH_RUN_TIMEOUT)
        try:
            _, status = os.waitpid(pid, 0)
            code = os.WEXITSTATUS(status)
        except OSError:
            code = 0
        text = out.decode('utf-8', 'replace')
        if code != 0 or 'denied' in text.lower():
            return b'', out or b'the access point refused those details', code or 255
        return out, b'', 0
    finally:
        try:
            os.close(fd)
        except OSError:
            pass
        try:
            os.waitpid(pid, os.WNOHANG)
        except OSError:
            pass


def parse_ap_info(text):
    """The `info` command's few lines."""
    out = {}
    for line in (text or '').splitlines():
        if ':' not in line:
            continue
        name, _, value = line.partition(':')
        key = name.strip().lower().replace(' ', '_')
        if key in ('model', 'version', 'mac_address', 'ip_address', 'hostname', 'uptime', 'status', 'ntp'):
            out[key] = value.strip()
    if out.get('uptime'):
        out['uptime'] = numeric(out['uptime'].split()[0])
    return out


def is_dfs_channel(band, channel):
    """Radar-shared channels. An access point told to leave one by a radar
    detection takes its network with it, which looks like a fault and is not."""
    if str(band) != '5' or not isinstance(channel, int):
        return False
    return 52 <= channel <= 144


def _sta_generation(sta):
    """A station's Wi-Fi generation. The dump flags what it can do rather than
    naming a protocol, so the best flag set wins."""
    for flag, name in (('is_11be', 'WiFi 7'), ('is_11ax', 'WiFi 6'), ('is_11ac', 'WiFi 5'),
                       ('is_11n', 'WiFi 4'), ('is_11g', 'WiFi 3'), ('is_11a', 'WiFi 2'),
                       ('is_11b', 'WiFi 1')):
        if sta.get(flag):
            return name
    return ''


def parse_mca_dump(text):
    """What an access point knows about itself and everyone on it.

    Field names here follow a real dump from a U7-Pro rather than what looks
    likely: the channel and its width sit on each wireless network, not on the
    radio; a station carries `signal` in dBm while `rssi` is its
    signal-to-noise margin; and the rates are in kilobits."""
    start = (text or '').find('{')
    if start < 0:
        raise ValueError('no JSON in the answer')
    try:
        data = json.loads(text[start:text.rfind('}') + 1])
    except ValueError as e:
        raise ValueError('the answer was not JSON: %s' % e)

    heat = {t.get('name'): numeric(t.get('value')) for t in (data.get('temperatures') or [])
            if numeric(t.get('value')) is not None}
    radios, neighbours, spectrum = {}, [], []
    for radio in data.get('radio_table') or []:
        name = radio.get('name')
        band = unifi_band(radio.get('radio'))
        # What the radio itself has measured, which is the answer to "why is
        # it slow": how much of the air is in use, how much of that is us,
        # and how much is somebody else. A radio 80% busy of which 10% is
        # ours is a neighbour problem; one with a high retry rate is a link
        # problem. Neither can be guessed from a signal strength.
        stats = radio.get('athstats') or {}
        sent = numeric(stats.get('n_tx_pkts')) or 0
        retries = numeric(stats.get('n_tx_retries')) or 0
        radios[name] = {'band': band, 'name': name,
                        'chains': radio.get('nss'), 'max_power': radio.get('max_txpower'),
                        'min_power': radio.get('min_txpower'),
                        'dfs_capable': bool(radio.get('has_dfs')),
                        'temperature': heat.get(name),
                        'busy': numeric(stats.get('cu_total')),
                        'busy_us_tx': numeric(stats.get('cu_self_tx')),
                        'busy_us_rx': numeric(stats.get('cu_self_rx')),
                        'busy_others': numeric(stats.get('cu_interf')),
                        'noise': numeric(stats.get('noise_floor')),
                        'sent': sent, 'retries': retries,
                        'retry_pct': round(100.0 * retries / sent, 1) if sent else None,
                        'given_up': numeric(stats.get('n_tx_xretries')),
                        'modern': ('11be' if radio.get('is_11be') else '11ax' if radio.get('is_11ax')
                                   else '11ac' if radio.get('is_11ac') else ''),
                        'clients': 0, 'networks': 0}
        # what else is on the air around this point, and how busy each channel is
        for other in radio.get('scan_table') or []:
            neighbours.append({'ssid': other.get('essid') or '', 'bssid': other.get('bssid'),
                               'band': unifi_band(other.get('band'), other.get('channel')),
                               'channel': other.get('channel'), 'width': other.get('bw'),
                               'signal': numeric(other.get('signal')),
                               'security': other.get('security') or '',
                               'ubiquiti': bool(other.get('is_ubnt')),
                               'seen': numeric(other.get('age'))})
        for slot in radio.get('spectrum_table') or []:
            busy = numeric(slot.get('utilization'))
            if busy is None:
                continue
            spectrum.append({'band': band, 'channel': slot.get('channel'),
                             'width': slot.get('width'), 'busy': busy,
                             'interference': numeric(slot.get('interference')),
                             'others': slot.get('other_bss_count')})

    clients, networks = [], []
    for vap in data.get('vap_table') or []:
        radio = radios.get(vap.get('radio_name'))
        band = (radio or {}).get('band') or unifi_band(vap.get('radio'), vap.get('channel'))
        if radio is not None:
            # the channel and its width live on the networks, not the radio
            if vap.get('channel') is not None:
                radio['channel'] = vap['channel']
            if vap.get('bw') is not None:
                radio['width'] = vap['bw']
            if vap.get('tx_power') is not None:
                radio['power'] = vap['tx_power']
            radio['clients'] += int(vap.get('num_sta') or 0)
            if vap.get('up'):
                radio['networks'] += 1
        if vap.get('essid'):
            attempts = numeric(vap.get('tx_total'))
            networks.append({'name': vap['essid'], 'band': band, 'channel': vap.get('channel'),
                             'width': vap.get('bw'), 'clients': vap.get('num_sta'),
                             'retry_pct': (round(100.0 * (numeric(vap.get('tx_retries')) or 0) / attempts, 1)
                                           if attempts else None),
                             'rx_errors': numeric(vap.get('rx_errors')),
                             'dropped': (numeric(vap.get('tx_dropped')) or 0) + (numeric(vap.get('rx_dropped')) or 0),
                             'power': vap.get('tx_power'),
                             'guest': str(vap.get('usage') or '') == 'guest',
                             'experience': vap.get('satisfaction'),
                             'avg_signal': vap.get('avg_client_signal'),
                             'up': bool(vap.get('up'))})
        for sta in vap.get('sta_table') or []:
            rates = (numeric(sta.get('tx_rate')), numeric(sta.get('rx_rate')))
            clients.append({
                'mac': str(sta.get('mac') or '').lower(),
                'name': sta.get('hostname') or sta.get('1x_identity') or '',
                'ip': sta.get('ip') or '',
                'wired': False, 'kind': 'WIRELESS',
                'ssid': vap.get('essid'),
                'guest': str(vap.get('usage') or '') == 'guest',
                # signal is dBm; rssi is the margin above the noise floor
                'signal': numeric(sta.get('signal')),
                'noise': numeric(sta.get('noise')),
                'snr': numeric(sta.get('rssi')),
                'channel': vap.get('channel'), 'band': band, 'width': vap.get('bw'),
                'technology': _sta_generation(sta),
                'chains': ('%sx%s' % (sta.get('nss'), sta.get('nss'))) if sta.get('nss') else '',
                'experience': sta.get('satisfaction'),
                'vlan': sta.get('vlan_id'),
                # the dump counts in kilobits a second
                'tx_rate': rates[0] * 1000 if rates[0] else None,
                'rx_rate': rates[1] * 1000 if rates[1] else None,
                'tx_bytes': numeric(sta.get('tx_bytes')), 'rx_bytes': numeric(sta.get('rx_bytes')),
                'usage': (numeric(sta.get('tx_bytes')) or 0) + (numeric(sta.get('rx_bytes')) or 0),
                'retries': numeric(sta.get('tx_retries')),
                'retry_pct': (round(100.0 * (numeric(sta.get('tx_retries')) or 0)
                                    / numeric(sta.get('tx_total')), 1)
                              if numeric(sta.get('tx_total')) else None),
                'ccq': numeric(sta.get('ccq')),
                'tx_power': numeric(sta.get('tx_power')),
                'ipv6': [a for a in (sta.get('ipv6_addresses') or []) if not str(a).startswith('fe80')],
                'uptime': numeric(sta.get('uptime')),
                'idle': numeric(sta.get('idletime')),
                'power_save': bool(sta.get('state_pwrmgt')),
                'authorized': bool(sta.get('authorized', True)),
                'mlo': bool(sta.get('is_mlo')),
                'from_ap': True,
            })

    # What the point measures on its own way out: latency, jitter and loss to
    # the gateway and to whatever carries it. An access point that is fine in
    # itself but sits behind a bad wire looks the same from the controller.
    paths = []
    for target in ((data.get('pathmon') or {}).get('targets') or []):
        latency = numeric(target.get('latency_us_ema'))
        paths.append({
            'to': target.get('type'), 'address': target.get('resolved'),
            'family': target.get('family'),
            'reachable': str(target.get('state') or '') == 'reachable',
            'latency_ms': round(latency / 1000.0, 2) if latency is not None else None,
            'jitter_ms': round(numeric(target.get('jitter_us_ema')) / 1000.0, 2)
                         if numeric(target.get('jitter_us_ema')) is not None else None,
            # loss arrives per million
            'loss_pct': round((numeric(target.get('loss_pcm_ema')) or 0) / 10000.0, 3),
        })

    # what it is plugged into, as the switch on the other end introduces itself
    wired_to = []
    for seen_on in data.get('lldp_table') or []:
        addresses = [a for a in (seen_on.get('mgmt_ips') or []) if ':' not in a] or seen_on.get('mgmt_ips') or []
        entry = {'mac': seen_on.get('chassis_id'), 'address': addresses[0] if addresses else None,
                 'port': seen_on.get('port_id'), 'our_port': seen_on.get('local_port_name')}
        if entry not in wired_to:
            wired_to.append(entry)

    uplink = next((i for i in (data.get('if_table') or []) if i.get('name') == data.get('uplink')),
                  (data.get('if_table') or [{}])[0])
    stats = data.get('system-stats') or {}
    detail_stats = data.get('sys_stats') or {}
    load = detail_stats.get('loadavg_1')
    # how busy the channel each radio sits on is, and whether a quieter one is
    # going spare - the whole point of the spectrum scan
    for radio in radios.values():
        here = [x for x in spectrum if x['band'] == radio.get('band') and x['channel'] == radio.get('channel')]
        if here:
            radio['utilization'] = here[0]['busy']
            radio['interference'] = here[0]['interference']
            radio['neighbours'] = here[0].get('others')
        # The radio's own count of the air beats the scan's: the scan is a
        # moment from some minutes ago, this is what it is measuring now.
        if radio.get('busy') is not None:
            radio['utilization'] = radio['busy']
        if radio.get('retry_pct') is not None:
            radio['tx_retries'] = radio['retry_pct']
        radio['dfs'] = is_dfs_channel(radio.get('band'), radio.get('channel'))
        options = sorted((x for x in spectrum if x['band'] == radio.get('band')),
                         key=lambda x: (x['busy'], x.get('others') or 0))
        quieter = [x for x in options
                   if x['channel'] != radio.get('channel')
                   and radio.get('utilization') is not None
                   and x['busy'] + 8 < radio['utilization']]
        radio['quieter'] = [{'channel': x['channel'], 'busy': x['busy'],
                             'dfs': is_dfs_channel(radio.get('band'), x['channel'])}
                            for x in quieter[:3]]
    return {
        'clients': clients,
        'radios': [r for r in radios.values() if r.get('band')],
        'networks': networks,
        'neighbours': sorted(neighbours, key=lambda n: -(n['signal'] or -999)),
        'spectrum': spectrum,
        'uptime': numeric(data.get('uptime')),
        'uptime_text': data.get('uptime_str'),
        'load': numeric(load),
        'cpu': numeric(stats.get('cpu')),
        'memory': numeric(stats.get('mem')),
        'load_5': numeric(detail_stats.get('loadavg_5')),
        'load_15': numeric(detail_stats.get('loadavg_15')),
        'memory_used': numeric(detail_stats.get('mem_used')),
        'memory_total': numeric(detail_stats.get('mem_total')),
        'temperature': max(heat.values()) if heat else None,
        'experience': data.get('satisfaction'),
        'version': data.get('version'),
        'model': data.get('model_display') or data.get('model'),
        'name': data.get('hostname'),
        'serial': data.get('serial'),
        'kernel': data.get('kernel_version'),
        'internet': data.get('internet'),
        'wired': {'name': uplink.get('name'), 'speed': uplink.get('speed'),
                  'duplex': uplink.get('full_duplex'), 'up': uplink.get('up'),
                  'rx_bytes': uplink.get('rx_bytes'), 'tx_bytes': uplink.get('tx_bytes'),
                  'rx_errors': uplink.get('rx_errors'), 'tx_errors': uplink.get('tx_errors'),
                  'rx_dropped': uplink.get('rx_dropped'), 'tx_dropped': uplink.get('tx_dropped')},
        'paths': paths,
        'wired_to': wired_to,
        # where it sends its reports, and what went wrong last time it could not
        'inform_url': data.get('inform_url'),
        'adopted': data.get('state') == 2,
        'last_trouble': next((e.get('last_error_str') for e in (data.get('last_error_conns') or [])
                              if e.get('last_error_str')), None),
        # the health of the thing itself
        'boot_reason': (data.get('boot') or {}).get('reason'),
        'ever_crashed': data.get('ever_crash'),
        'flash_wear': data.get('emmc_wear_level'),
        'architecture': data.get('architecture'),
        'board': data.get('bomrev'),
        'gateway': data.get('gateway_ip'),
        'netmask': data.get('netmask'),
        'ipv6': [a for a in (data.get('ipv6') or []) if not str(a).startswith('fe80')],
        'six_ghz': data.get('support_wifi6e'),
        'guest_kicks': data.get('guest_kicks'),
        'antenna': next((a.get('name') for a in (data.get('antenna_table') or []) if a.get('default')), None),
    }


def unifi_detail(cfg):
    """What the controller knows about itself, its access points and its SSIDs.

    The official Integration API grew: 10.6 lists the wifi broadcasts and the
    networks behind them as well as the devices and clients, and its device
    statistics live under /statistics/latest. Older revisions have neither, so
    the SSIDs fall back to whatever the clients are joined to. Signing in with
    a password reaches the older API, which is still the only one reporting a
    client's signal and channel."""
    host = str(cfg.get('host') or '').strip()
    if not host:
        raise ValueError('the controller needs an address')
    base = 'https://%s:%d' % (host, int(cfg.get('port') or 443))
    opener = _unifi_opener(bool(cfg.get('verify_ssl')))
    if not unifi_wants_legacy(cfg):
        out = _unifi_detail_official(cfg, base, opener)
        out['read_with'] = 'key'
        return out
    try:
        out = _unifi_detail_legacy(cfg, base, opener)
        out['read_with'] = 'signin'
        return out
    except Exception as e:
        if str(cfg.get('method')) != 'both' or not cfg.get('api_key'):
            raise
        log('wifi detail: signing in failed (%s), falling back to the API key' % e, 'warn')
        out = _unifi_detail_official(cfg, base, _unifi_opener(bool(cfg.get('verify_ssl'))))
        out['read_with'] = 'key'
        out['fell_back'] = str(e)
        return out


def _port_summary(device):
    """How many wired ports there are and how many are up, when the device
    itself was read; the device list only says the word "ports"."""
    interfaces = device.get('interfaces')
    if not isinstance(interfaces, dict):
        return None
    ports = [p for p in (interfaces.get('ports') or []) if isinstance(p, dict)]
    if not ports:
        return None
    states = [str(p.get('state') or '').upper() for p in ports]
    up = [x for x in states if x == 'UP']
    live = max((numeric(p.get('speedMbps')) or 0) for p in ports)
    most = max((numeric(p.get('maxSpeedMbps')) or 0) for p in ports)
    return {'count': len(ports),
            'up': len(up) if any(states) else None,   # None: it did not say
            'speed': int(live) if live else None,
            'max_speed': int(most) if most else None,
            'connector': next((p.get('connector') for p in ports if p.get('connector')), None),
            'poe': any((p.get('poe') or {}).get('enabled') for p in ports if isinstance(p.get('poe'), dict))}


def _wifi_standard(name):
    """802.11ax and the like, as the generation people actually say."""
    return {'802.11a': 'WiFi 2', '802.11b': 'WiFi 1', '802.11g': 'WiFi 3', '802.11n': 'WiFi 4',
            '802.11ac': 'WiFi 5', '802.11ax': 'WiFi 6', '802.11be': 'WiFi 7'}.get(str(name or ''), '')


def _is_access_point(device):
    """Whether the controller is describing a wireless access point.

    The feature list has been spelled several ways across firmware -
    ACCESS_POINT, accessPoint, sometimes an object keyed by feature - so the
    comparison ignores case and punctuation instead of matching one spelling.
    A device with no feature list at all is not ruled out."""
    features = device.get('features')
    if isinstance(features, dict):
        names = list(features.keys())
    elif isinstance(features, (list, tuple)):
        names = list(features)
    else:
        names = []
    flat = {re.sub(r'[^a-z0-9]', '', str(f).lower()) for f in names}
    if flat:
        return 'accesspoint' in flat or 'wireless' in flat or 'wifi' in flat
    kind = re.sub(r'[^a-z0-9]', '', str(device.get('type') or device.get('deviceType') or '').lower())
    if kind:
        return kind in ('uap', 'accesspoint', 'wireless')
    return True                          # nothing said otherwise


def _client_ssid(client):
    """The network a client is joined to, when the controller says.

    The official API's access object holds an authorisation type - GUEST or
    DEFAULT - and no network name, on any version. A key that looks like an
    SSID is still accepted in case a later release adds one, but the honest
    answer there is usually None, and None is shown as unknown rather than
    quietly counted as nothing."""
    access = client.get('access')
    if not isinstance(access, dict):
        return None
    for key, value in access.items():
        if 'ssid' in str(key).lower() and value:
            return str(value)
    return None


def _ap_from_official(device, stats):
    # Two places describe the radios: the device says which channel and how
    # wide, the statistics say how busy. They are joined on the frequency.
    configured = {}
    for radio in ((device.get('interfaces') or {}).get('radios') or []) \
            if isinstance(device.get('interfaces'), dict) else []:
        band = radio.get('frequencyGHz')
        configured[str(band)] = {
            'band': str(band) if band is not None else None,
            'channel': radio.get('channel'),
            'width': radio.get('channelWidthMHz'),
            'standard': _wifi_standard(radio.get('wlanStandard')),
        }
    measured = (stats.get('interfaces') or {}).get('radios') if isinstance(stats, dict) else None
    for radio in measured or (stats.get('radios') if isinstance(stats, dict) else None) or []:
        band = str(radio.get('frequencyGHz'))
        entry = configured.setdefault(band, {'band': band})
        entry['tx_retries'] = radio.get('txRetriesPct')
        if radio.get('numberOfConnectedClients') is not None:
            entry['clients'] = radio['numberOfConnectedClients']
    radios = [r for r in configured.values() if r.get('band')]
    uplink = (stats or {}).get('uplink') or {}
    return {
        'mac': str(device.get('macAddress') or '').lower(),
        'name': device.get('name') or device.get('model') or 'access point',
        'model': device.get('model') or '',
        'state': str(device.get('state') or '').lower(),
        'ip': device.get('ipAddress') or '',
        'version': device.get('firmwareVersion') or '',
        'uptime': (stats or {}).get('uptimeSec'),
        'cpu': ((stats or {}).get('cpuUtilizationPct')),
        'memory': ((stats or {}).get('memoryUtilizationPct')),
        'updatable': bool(device.get('firmwareUpdatable')),
        'ports': _port_summary(device),
        'clients': sum(r['clients'] for r in radios if isinstance(r.get('clients'), int)) or None,
        'tx_bytes': uplink.get('txRateBps'), 'rx_bytes': uplink.get('rxRateBps'),
        'uplink': _uplink_text(uplink),
        'load': (stats or {}).get('loadAverage1Min'),
        'heartbeat': (stats or {}).get('lastHeartbeatAt'),
        'supported': device.get('supported'),
        'radios': radios,
    }


def _uplink_text(uplink):
    """What is flowing through the wire behind the access point."""
    def rate(bps):
        bps = numeric(bps)
        if not bps:
            return None
        if bps >= 1000000:
            return ('%.1f' % (bps / 1000000.0)).rstrip('0').rstrip('.') + ' Mbps'
        return ('%.1f' % (bps / 1000.0)).rstrip('0').rstrip('.') + ' Kbps'
    down, up = rate(uplink.get('rxRateBps')), rate(uplink.get('txRateBps'))
    if not down and not up:
        return ''
    return '\u2193 %s  \u2191 %s' % (down or '0', up or '0')


def _unifi_detail_official(cfg, base, opener):
    headers = {'X-API-KEY': str(cfg.get('api_key') or ''), 'Accept': 'application/json'}
    prefix = site_id = None
    for candidate in UNIFI_PREFIXES:
        status, _, body = _unifi_get(opener, base + candidate + '/sites', headers)
        if status >= 400:
            continue
        sites = body.get('data') or []
        if sites:
            prefix, site_id = candidate, sites[0]['id']
        break
    if not prefix:
        raise RuntimeError('the integration API is not answering')
    out = {'controller': {}, 'aps': [], 'ssids': [], 'source': 'official'}
    status, _, body = _unifi_get(opener, base + prefix + '/info', headers)
    if status < 400 and isinstance(body, dict):
        out['controller'] = {'version': body.get('applicationVersion') or body.get('version') or '',
                             'name': body.get('name') or ''}
    status, _, body = _unifi_get(opener, '%s%s/sites/%s/devices?limit=200' % (base, prefix, site_id), headers)
    devices = (body.get('data') or []) if status < 400 else []
    if status >= 400:
        out['error'] = 'listing devices failed with HTTP %s' % status
    out['seen_devices'] = len(devices)
    wireless = [d for d in devices if _is_access_point(d)]
    # Rather than show nothing at all, fall back to everything the controller
    # listed: a name and an address still beat an empty tab.
    out['filtered'] = bool(devices) and not wireless
    for device in (wireless or devices):
        stats = {}
        did = device.get('id')
        if did:
            # the list is a summary: interfaces come back as the words "ports"
            # and "radios", and the real ones are on the device itself
            st, _, full = _unifi_get(opener, '%s%s/sites/%s/devices/%s' % (base, prefix, site_id, did), headers)
            if st < 400 and isinstance(full, dict):
                device = dict(device, **full)
            for suffix in ('/statistics/latest', '/statistics'):
                st, _, sb = _unifi_get(opener, '%s%s/sites/%s/devices/%s%s'
                                       % (base, prefix, site_id, did, suffix), headers)
                if st < 400 and isinstance(sb, dict):
                    stats = sb
                    break
        ap = _ap_from_official(device, stats)
        ap['id'] = device.get('id')
        out['aps'].append(ap)
    # Newer firmware does list the networks after all - 10.6 has both the
    # broadcasts and the VLANs behind them, which earlier revisions did not.
    status, _, body = _unifi_get(opener, '%s%s/sites/%s/networks?limit=100' % (base, prefix, site_id), headers)
    networks = {}
    for net in (body.get('data') or []) if status < 400 else []:
        networks[net.get('id')] = {'name': net.get('name') or '', 'vlan': net.get('vlanId'),
                                   'default': bool(net.get('default')), 'enabled': net.get('enabled')}
    out['networks'] = sorted(({k: v for k, v in n.items() if k != 'default'} for n in networks.values()),
                             key=lambda x: str(x['name']).lower())
    ap_names = {ap.get('id'): ap.get('name') for ap in out['aps']}
    status, _, body = _unifi_get(opener, '%s%s/sites/%s/wifi/broadcasts?limit=100' % (base, prefix, site_id), headers)
    default_net = next((v for v in networks.values() if v.get('default')), {})
    for wlan in (body.get('data') or []) if status < 400 else []:
        ref = wlan.get('network') or {}
        if str(ref.get('type') or '').upper() == 'NATIVE':
            net = default_net                # the site's own network, not named again
        else:
            net = networks.get(ref.get('networkId') or ref.get('id')) or {}
        bands = sorted((str(b) for b in (wlan.get('broadcastingFrequenciesGHz') or [])),
                       key=lambda b: numeric(b) or 0)
        out['ssids'].append({
            'name': wlan.get('name') or '',
            'enabled': bool(wlan.get('enabled', True)),
            'security': _wifi_security((wlan.get('securityConfiguration') or {}).get('type')),
            'band': '/'.join(bands),
            'network': net.get('name') or ref.get('name') or '',
            'vlan': net.get('vlan'),
            'guest': str((wlan.get('hotspotConfiguration') or {}).get('type') or '').upper() == 'GUEST'
                     or bool(wlan.get('hotspotConfiguration')),
            'hidden': bool(wlan.get('hideSsid')),
            'on_aps': _broadcasting_on(wlan.get('broadcastingDeviceFilter'), ap_names),
        })
    return out


def _broadcasting_on(filt, ap_names):
    """Which access points carry a network. A filter naming devices lists
    them; anything else means every point on the site."""
    if not isinstance(filt, dict):
        return ''
    if str(filt.get('type') or '').upper() != 'DEVICES':
        return 'all'
    ids = filt.get('deviceIds') or filt.get('devices') or []
    named = [ap_names.get(i) or str(i)[:8] for i in ids]
    return ', '.join(named) if named else 'all'


def _wifi_security(kind):
    """WPA2_WPA3_PERSONAL and friends, said the way the controller says them."""
    name = str(kind or '').upper()
    if not name:
        return ''
    text = name.replace('_PERSONAL', '').replace('_', '/')
    if name.endswith('_ENTERPRISE'):
        text = text.replace('/ENTERPRISE', '') + ' Enterprise'
    return 'Open' if text == 'OPEN' else text


def _unifi_detail_legacy(cfg, base, opener):
    site = str(cfg.get('site') or 'default')
    out = {'controller': {}, 'aps': [], 'ssids': [], 'source': 'legacy'}
    st, body = _unifi_signed_get(cfg, '/proxy/network/api/s/%s/stat/device' % site)
    for device in (body.get('data') or []) if st < 400 else []:
        if str(device.get('type') or '') != 'uap':
            continue
        widths = {}
        for radio in device.get('radio_table') or []:
            widths[radio.get('name')] = {'width': radio.get('ht'), 'power': radio.get('tx_power'),
                                         'radio': radio.get('radio')}
        radios = []
        for radio in device.get('radio_table_stats') or []:
            extra = widths.get(radio.get('name')) or {}
            radios.append({'band': unifi_band(radio.get('radio') or extra.get('radio'), radio.get('channel')),
                           'channel': radio.get('channel'),
                           'width': int(numeric(extra.get('width'))) if numeric(extra.get('width')) is not None else None,
                           'power': extra.get('power'),
                           'clients': radio.get('user-num_sta'),
                           'guests': radio.get('guest-num_sta'),
                           'tx_retries': radio.get('tx_retries_pct'),
                           'utilization': radio.get('cu_total'),
                           'interference': radio.get('cu_self_rx')})
        sysstats = device.get('system-stats') or {}
        uplink = device.get('uplink') or {}
        out['aps'].append({
            'mac': str(device.get('mac') or '').lower(),
            'name': device.get('name') or device.get('model') or 'access point',
            'model': device.get('model') or '', 'ip': device.get('ip') or '',
            'state': 'online' if device.get('state') == 1 else 'offline',
            'version': device.get('version') or '',
            'uptime': device.get('uptime'),
            'cpu': numeric(sysstats.get('cpu')), 'memory': numeric(sysstats.get('mem')),
            'clients': device.get('num_sta'), 'guests': device.get('guest-num_sta'),
            'tx_bytes': device.get('tx_bytes'), 'rx_bytes': device.get('rx_bytes'),
            'experience': device.get('satisfaction'),
            'uplink': (uplink.get('type') or '') + (
                ' %s Mbps' % uplink.get('speed') if uplink.get('speed') else ''),
            'radios': radios,
        })
    networks = {}
    st, body = _unifi_signed_get(cfg, '/proxy/network/api/s/%s/list/networkconf' % site)
    for net in (body.get('data') or []) if st < 400 else []:
        networks[net.get('_id')] = {'name': net.get('name') or '', 'vlan': net.get('vlan')}
    out['networks'] = sorted(({k: v for k, v in n.items() if k != 'default'} for n in networks.values()),
                         key=lambda x: str(x['name']).lower())
    st, body = _unifi_signed_get(cfg, '/proxy/network/api/s/%s/list/wlanconf' % site)
    for wlan in (body.get('data') or []) if st < 400 else []:
        net = networks.get(wlan.get('networkconf_id')) or {}
        raw = str(wlan.get('security') or '').lower()
        security = {'wpapsk': 'WPA2', 'wpaeap': 'WPA2 Enterprise', 'wep': 'WEP',
                    'open': 'Open', 'none': 'Open'}.get(raw, raw.upper())
        if wlan.get('wpa3_support') or str(wlan.get('wpa_mode') or '').lower() == 'wpa3':
            security = security.replace('WPA2', 'WPA2/WPA3')
        if str(wlan.get('wpa_mode') or '').lower() == 'wpa3' and 'WPA2' not in security:
            security = 'WPA3'
        bands = []
        for key, label in (('wlan_band_2g', '2.4'), ('wlan_band_5g', '5'), ('wlan_band_6g', '6')):
            if wlan.get(key):
                bands.append(label)
        if not bands:
            band = str(wlan.get('wlan_band') or 'both')
            bands = ['2.4', '5'] if band == 'both' else [band.replace('g', '')]
        out['ssids'].append({'name': wlan.get('name') or '', 'enabled': bool(wlan.get('enabled', True)),
                             'security': security, 'hidden': bool(wlan.get('hide_ssid')),
                             'guest': bool(wlan.get('is_guest')), 'band': '/'.join(bands),
                             'network': net.get('name') or '', 'vlan': net.get('vlan')})
    st, body = _unifi_signed_get(cfg, '/proxy/network/api/s/%s/stat/health' % site)
    for sub in (body.get('data') or []) if st < 400 else []:
        if sub.get('subsystem') == 'wlan':
            out['controller']['wlan_status'] = sub.get('status')
            out['controller']['wlan_users'] = sub.get('num_user')
            out['controller']['wlan_guests'] = sub.get('num_guest')
    return out


def _unifi_official(cfg, base, opener):
    key = str(cfg.get('api_key') or '')
    if not key:
        raise ValueError('the official API needs an API key')
    headers = {'X-API-KEY': key, 'Accept': 'application/json'}
    prefix = sites = None
    last = ''
    for candidate in UNIFI_PREFIXES:      # the path changed between firmware revisions
        status, _, body = _unifi_get(opener, base + candidate + '/sites', headers)
        if status == 404:
            last = 'HTTP 404'
            continue
        if status in (401, 403):
            raise RuntimeError('the controller refused the API key')
        if status >= 400:
            last = 'HTTP %s' % status
            continue
        prefix, sites = candidate, body.get('data') or []
        break
    if prefix is None:
        raise RuntimeError('the integration API is not answering (%s). On a UniFi OS Server the '
                           'port is usually 11443, on a console 443.' % (last or 'no reply'))
    if not sites:
        raise RuntimeError('the controller returned no site')
    site_id = sites[0]['id']
    out, offset = [], 0
    while True:
        status, _, body = _unifi_get(
            opener, '%s%s/sites/%s/clients?limit=200&offset=%d' % (base, prefix, site_id, offset), headers)
        if status >= 400:
            raise RuntimeError('reading clients failed with HTTP %s' % status)
        page = body.get('data') or []
        out.extend(page)
        offset += len(page)
        if not page or offset >= int(body.get('totalCount') or offset):
            break
    return [{
        'name': c.get('name') or c.get('hostname') or '',
        'mac': str(c.get('macAddress') or '').lower(),
        'ip': c.get('ipAddress') or '',
        'wired': str(c.get('type') or '').upper() == 'WIRED',
        'kind': str(c.get('type') or '').upper(),          # WIRED, WIRELESS, VPN, TELEPORT
        'ssid': _client_ssid(c),
        'guest': str((c.get('access') or {}).get('type') or '').upper() == 'GUEST'
                 if isinstance(c.get('access'), dict) else False,
        'since': c.get('connectedAt'),
        # the newer firmware names the access point by id rather than by MAC
        'uplink_id': c.get('uplinkDeviceId'),
        'signal': None, 'ap': None,
    } for c in out if c.get('macAddress')]


def _unifi_legacy(cfg, base, opener):
    """The clients, as the controller's own pages see them.

    Its interface asks v2 for `clients/active`, which carries the signal, the
    channel, the rates and the name of the access point already resolved. The
    older `stat/sta` is the fallback for controllers without it - the fields
    overlap enough that one mapping reads both."""
    site = str(cfg.get('site') or 'default')
    raw, status = [], None
    for path in ('/proxy/network/v2/api/site/%s/clients/active?includeTrafficUsage=true&includeUnifiDevices=true' % site,
                 '/proxy/network/api/s/%s/stat/sta' % site):
        status, body = _unifi_signed_get(cfg, path)
        if status >= 400:
            continue
        rows = body if isinstance(body, list) else (body.get('data') or [])
        if rows or status < 400:
            raw = rows
            break
    if status is not None and status >= 400 and not raw:
        raise RuntimeError('reading clients failed with HTTP %s' % status)
    return [{
        'name': c.get('display_name') or c.get('name') or c.get('hostname') or c.get('oui') or '',
        'mac': str(c.get('mac') or '').lower(),
        'ip': c.get('ip') or '',
        'wired': bool(c.get('is_wired')),
        'kind': 'WIRED' if c.get('is_wired') else 'WIRELESS',
        'ssid': c.get('essid'),
        'guest': bool(c.get('is_guest')),
        'signal': c.get('signal'), 'noise': c.get('noise'),
        'ap': str(c.get('ap_mac') or c.get('uplink_mac') or c.get('last_uplink_mac') or '').lower(),
        'ap_name': c.get('last_uplink_name') or None,
        'vlan': c.get('vlan'),
        'channel': c.get('channel'),
        'band': unifi_band(c.get('radio'), c.get('channel')),
        'width': int(numeric(c.get('channel_width'))) if numeric(c.get('channel_width')) is not None else None,
        'technology': unifi_generation(c.get('radio_proto')),
        'chains': ('%sx%s' % (c.get('nss'), c.get('nss'))) if c.get('nss') else '',
        'experience': c.get('satisfaction') if c.get('satisfaction') is not None
                      else c.get('wifi_experience_score'),
        'retries': c.get('wifi_tx_retries_percentage'),
        'mimo': c.get('mimo'),
        'status': c.get('status'),
        'tx_rate': c.get('tx_rate'), 'rx_rate': c.get('rx_rate'),
        'down_bps': numeric(c.get('rx_bytes-r')), 'up_bps': numeric(c.get('tx_bytes-r')),
        'tx_bytes': c.get('tx_bytes'), 'rx_bytes': c.get('rx_bytes'),
        'usage': numeric(c.get('usage_bytes')) if c.get('usage_bytes') is not None
                 else (numeric(c.get('tx_bytes')) or 0) + (numeric(c.get('rx_bytes')) or 0),
        'uptime': c.get('uptime'), 'since': c.get('assoc_time'),
        'satisfaction': c.get('satisfaction'),
        'vendor': c.get('oui'), 'network': c.get('network'),
        'powersave': c.get('powersave_enabled'),
    } for c in raw if c.get('mac')]


# Readings worth no history: the hardware's own identity and sizes, counters'
# reset stamps, per-minute arrays, clocks and revision numbers. A gateway
# hands all of it over on every poll, and stored every thirty seconds it is
# what fills a database - without ever telling anyone anything.
NOISE_KEY = re.compile(
    r'(^|\.)('
    r'id|source|tag|mac|uptime_ts|unixtime|time|last_sync_ts|'
    r'hw_version|zb_version|fw_id|u_device|coord_mode|wifi_mode|zb_type|zb_channel|'
    r'fs_size|fs_total|ram_size|ram_total|psram_total|psram_size|zb_flash_size|zb_ram_size|'
    r'cfg_rev|kvs_rev|schedule_rev|webhook_rev|slot|gen'
    r')$'
    r'|_rst_ts$|\.minute_ts$|\.by_minute|(^|\.)ble\.[a-z_]*enabled$')

GATEWAY_ANCHOR_S = 900          # a flat reading still gets a point this often
SAMPLE_ANCHOR_S = 900           # ...and one that has not changed is not written until then


# ---------------------------------------------------------------------------
# Storage
# ---------------------------------------------------------------------------
# Readings are stored as (device, key, value) rows rather than in fixed
# columns, because what one sensor reports is not what the next one does.
# Full resolution is kept for a fortnight, hourly averages for two years; the
# latest complete payload of every device sits in `snapshots`.
SCHEMA = """
CREATE TABLE IF NOT EXISTS devices (
    id          TEXT PRIMARY KEY,       -- IEEE address, or shelly:<name>
    name        TEXT NOT NULL,          -- friendly name (the MQTT topic)
    source      TEXT NOT NULL,          -- zigbee | shelly | mqtt
    kind        TEXT,                   -- EndDevice | Router | Coordinator | wifi
    model       TEXT,
    vendor      TEXT,
    description TEXT,
    exposes     TEXT,                   -- JSON: key -> {label, unit, description}
    first_seen  INTEGER,
    last_seen   INTEGER,
    removed     INTEGER NOT NULL DEFAULT 0,
    alias       TEXT                    -- a display name set on the dashboard
);

-- WITHOUT ROWID: the table IS the index that enforces its key, rather than
-- SQLite keeping the whole of it a second time. On a real house that is 268 MB
-- against 147 MB, for the same queries at the same speed.
CREATE TABLE IF NOT EXISTS samples (
    ts      INTEGER NOT NULL,
    device  TEXT    NOT NULL,
    key     TEXT    NOT NULL,
    value   REAL,
    PRIMARY KEY (device, key, ts)
) WITHOUT ROWID;
-- No index on ts alone. It cost 29 MB on a real house and saved 6 ms on one
-- query a night; the fold walks the whole table either way.

CREATE TABLE IF NOT EXISTS samples_hourly (
    ts      INTEGER NOT NULL,
    device  TEXT    NOT NULL,
    key     TEXT    NOT NULL,
    n       INTEGER,
    avg     REAL,
    min     REAL,
    max     REAL,
    PRIMARY KEY (device, key, ts)
);
CREATE INDEX IF NOT EXISTS samples_hourly_ts ON samples_hourly (ts);
-- the peaks are asked for one key across a window ("the most the house drew
-- this week"): with ts alone that walked every device's every key for the
-- whole window and looked each row up to test the key
CREATE INDEX IF NOT EXISTS samples_hourly_key_ts ON samples_hourly (key, ts);

CREATE TABLE IF NOT EXISTS snapshots (
    device  TEXT PRIMARY KEY,
    ts      INTEGER NOT NULL,
    payload TEXT NOT NULL,
    availability TEXT
);

CREATE TABLE IF NOT EXISTS events (
    id      INTEGER PRIMARY KEY AUTOINCREMENT,
    ts      INTEGER NOT NULL,
    device  TEXT,
    kind    TEXT NOT NULL,
    level   TEXT,
    detail  TEXT
);
CREATE TABLE IF NOT EXISTS taps_log (
    ts      REAL NOT NULL,
    ended   REAL,
    ticket  TEXT,
    link    TEXT,
    what    TEXT,
    who     TEXT,
    way     TEXT,
    factor  TEXT,
    state   TEXT,
    message TEXT,
    device  TEXT,
    times   INTEGER DEFAULT 1,   -- the same refusal, repeated, folded into one line
    mark    TEXT                 -- what was tried, as a fingerprint; never the thing itself
);
CREATE INDEX IF NOT EXISTS taps_log_ts ON taps_log (ts);
-- a press's own line found again by its ticket when it ends, rather than by
-- reading the whole log for it
CREATE INDEX IF NOT EXISTS taps_log_ticket ON taps_log (ticket);
-- and a refusal folded into the last one like it, found without reading every
-- press there ever was (refusals are what somebody guessing makes plenty of)
CREATE INDEX IF NOT EXISTS taps_log_refused ON taps_log (state, who, ts);

-- Every line read out of a log on the server in front, kept as rows rather
-- than weighed once and thrown away. Streaming past a line can only ever ask
-- "what is this one worth"; a table can ask the questions that actually catch
-- somebody - how many different paths in an hour, how long between tries,
-- whether this address has ever been seen before, what it did across all four
-- logs in order. It also means a rule changed today can be tried against
-- yesterday, instead of only ever seeing what comes next.
CREATE TABLE IF NOT EXISTS proxy_lines (
    ts     REAL NOT NULL,
    src    TEXT NOT NULL,           -- which log it came out of
    ip     TEXT NOT NULL,
    method TEXT,
    path   TEXT,
    status INTEGER,
    kind   TEXT                     -- what the weighing made of it, if anything
);
CREATE INDEX IF NOT EXISTS proxy_lines_ip ON proxy_lines (ip, ts);
CREATE INDEX IF NOT EXISTS proxy_lines_ts ON proxy_lines (ts);

-- Lists somebody else keeps: ranges known for scanning, for botnets, for
-- being somewhere nothing of this house should ever hear from. Fetched whole,
-- kept as rows, and asked one question - is this address in one of them.
CREATE TABLE IF NOT EXISTS feed_ranges (
    feed   TEXT NOT NULL,
    lo     BLOB NOT NULL,           -- packed, so a comparison is a comparison
    hi     BLOB NOT NULL,
    family INTEGER NOT NULL         -- 4 or 6
);
CREATE INDEX IF NOT EXISTS feed_ranges_lo ON feed_ranges (family, lo);

-- Which country an address belongs to, from a free list fetched monthly. Only
-- ever used to say so beside an address - nothing is judged by it, because a
-- country is not a thing an address chooses and a scanner in Rotterdam looks
-- exactly like a phone in Rotterdam.
CREATE TABLE IF NOT EXISTS geo_ranges (
    lo     BLOB NOT NULL,
    hi     BLOB NOT NULL,
    family INTEGER NOT NULL,
    cc     TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS geo_ranges_lo ON geo_ranges (family, lo);

-- The Suricata rules that have actually fired here, fetched with the logs
-- rather than one at a time when somebody looks. A rule does not change
-- between fetches, so once it is here nothing asks the proxy about it again.
CREATE TABLE IF NOT EXISTS ids_rules (
    sid       INTEGER PRIMARY KEY,
    rev       INTEGER,
    msg       TEXT,
    classtype TEXT,
    looks_for TEXT,
    refs      TEXT,
    got_at    REAL NOT NULL
);

CREATE TABLE IF NOT EXISTS block_events (
    ts     REAL NOT NULL,
    ip     TEXT NOT NULL,
    what   TEXT NOT NULL,        -- 'blocked' or 'let back in'
    why    TEXT,
    auto   INTEGER DEFAULT 1,
    by     TEXT
);
CREATE INDEX IF NOT EXISTS block_events_ts ON block_events (ts);
-- "how many times has this one been kept out before" is asked for every row
-- of the blocked list and for every decision: by address, not by reading the
-- whole story each time
CREATE INDEX IF NOT EXISTS block_events_ip ON block_events (ip, what, ts);

CREATE TABLE IF NOT EXISTS blocked_log (
    ts     REAL NOT NULL,
    ended  REAL,
    ip     TEXT NOT NULL,
    why    TEXT,
    how    TEXT,               -- how it ended: ran out, taken off, still on
    auto   INTEGER DEFAULT 1,
    hits   INTEGER DEFAULT 0,
    by     TEXT
);
CREATE INDEX IF NOT EXISTS blocked_log_ts ON blocked_log (ts);

-- Each folding of addresses into subnets, as it was done, so any one of the
-- last few can be undone on its own: which subnets it made, which addresses
-- went into each and how each stood before. Kept to the number set in
-- Settings; the oldest go first.
CREATE TABLE IF NOT EXISTS fold_versions (
    id      INTEGER PRIMARY KEY AUTOINCREMENT,
    ts      REAL NOT NULL,
    by      TEXT,
    widest  INTEGER,
    before  INTEGER,
    after   INTEGER,
    groups  TEXT,               -- JSON: [{net, existing, lists, members: [row, ...]}]
    undone  REAL,               -- when it was undone, if it was
    undone_by TEXT
);

CREATE TABLE IF NOT EXISTS blocked (
    ip     TEXT PRIMARY KEY,
    since  REAL NOT NULL,
    until  REAL,              -- null means until somebody takes it off
    why    TEXT,
    hits   INTEGER DEFAULT 0,
    auto   INTEGER DEFAULT 1,
    by     TEXT
);

CREATE INDEX IF NOT EXISTS events_ts ON events (ts);
CREATE INDEX IF NOT EXISTS events_device_kind_ts ON events (device, kind, ts);

CREATE TABLE IF NOT EXISTS meta (
    key     TEXT PRIMARY KEY,
    value   TEXT
);
"""

# the accounts of the dashboard, apart so a restore can make them again
SCHEMA_ACCOUNTS = """
-- The accounts of the dashboard (5.19) and who is signed in with them. A
-- sign-in is kept by the hash of its token, never the token, and survives a
-- restart of the daemon - a restore or an upgrade no longer signs anybody out.
CREATE TABLE IF NOT EXISTS accounts (
    name        TEXT PRIMARY KEY COLLATE NOCASE,
    role        TEXT NOT NULL,
    pw          TEXT NOT NULL,
    disabled    INTEGER DEFAULT 0,
    must_change INTEGER DEFAULT 0,
    note        TEXT DEFAULT '',
    created     INTEGER,
    last_in     INTEGER,
    last_from   TEXT DEFAULT '',
    kind        TEXT DEFAULT 'password',
    pin_len     INTEGER DEFAULT 0
);
CREATE TABLE IF NOT EXISTS signins (
    token_hash  TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    created     INTEGER,
    last        INTEGER,
    expires     INTEGER,
    ip          TEXT DEFAULT '',
    agent       TEXT DEFAULT ''
);

-- Every other network the access points have ever heard, one row each, with
-- when it was first and last heard and the best it was ever received. The
-- card shows what is on the air this minute; this is what has been.
CREATE TABLE IF NOT EXISTS wifi_seen (
    bssid    TEXT PRIMARY KEY,
    ssid     TEXT,
    band     TEXT,
    channel  INTEGER,
    width    TEXT,
    security TEXT,
    ubiquiti INTEGER DEFAULT 0,
    best     INTEGER,
    last     INTEGER,
    first    INTEGER,
    times    INTEGER DEFAULT 0
);
CREATE INDEX IF NOT EXISTS wifi_seen_last ON wifi_seen (last);
"""
SCHEMA += SCHEMA_ACCOUNTS



class StorageError(Exception):
    pass


class Storage(object):
    def __init__(self, path=None):
        self.path = Path(path) if path else db_path()
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
        except OSError:
            pass
        try:
            self.db = sqlite3.connect(str(self.path), check_same_thread=False,
                                      timeout=15, isolation_level=None)
        except sqlite3.OperationalError as e:
            raise StorageError('cannot open %s: %s' % (self.path, e))
        self.db.row_factory = sqlite3.Row
        self.lock = threading.RLock()
        self._meta_cache = {}
        # Recording must never make a person wait. Writes from the message
        # path are queued and drained by one background thread, so a VACUUM
        # or an online backup - which hold the database for as long as they
        # take - can never stall a button press or the MQTT client thread.
        self._snap_cache = {}     # device -> (payload, availability), the merge source of truth
        # the blocked addresses, kept in hand: this is read on every request
        self._block_cache = {}
        self._block_nets = []
        self._block_cache_at = 0
        self._block_gen = 0
        self._block_loaded = False
        self._block_guard = threading.Lock()
        self._block_delta = []    # (gen, ip, until, gone) since the list was last read whole
        self._dev_cache = {}      # device id -> row (or None when there is no such device)
        self._dev_list = None     # the whole list, rebuilt after any change
        self._actions_cache = {}  # device id -> the actions it has reported
        self._last_action = {}    # device id -> its most recent action
        self._meta_raw = {}       # meta key -> its stored text
        self._stats_cache = None  # (when, row counts) for the header
        self._geo_count = None    # how many country ranges; counted once, see geo_size
        self._feed_counts = None  # list -> how many ranges; the same, see feed_sizes
        self._wq = collections.deque()
        self._wq_wake = threading.Event()
        self._wq_idle = threading.Event()
        self._wq_idle.set()
        self._wq_thread = threading.Thread(target=self._writer_loop, name='db-writer', daemon=True)
        self._wq_thread.start()
        self.db.execute('PRAGMA journal_mode=WAL')
        self.db.execute('PRAGMA synchronous=NORMAL')
        self.db.executescript(SCHEMA)
        self.accounts_mend()
        try:
            self.db.execute('ALTER TABLE devices ADD COLUMN alias TEXT')
        except sqlite3.OperationalError:
            pass                        # already there
        try:
            # how many times the same refusal arrived; a table written before
            # this has none, and every row in it stands for one
            self.db.execute('ALTER TABLE taps_log ADD COLUMN times INTEGER DEFAULT 1')
        except sqlite3.OperationalError:
            pass                        # already there
        try:
            self.db.execute('ALTER TABLE taps_log ADD COLUMN mark TEXT')
        except sqlite3.OperationalError:
            pass                        # already there
        self.slim_samples()
        self.last_sample = {}     # (device, key) -> ts of the last row written
        self.last_written = {}    # (device, key) -> (value, ts) actually stored
        # Every setting row, read once, here. This was only ever done before a
        # VACUUM - so after a restart each key went to the database the first
        # time anything asked for it, under the one lock, and the FIRST motion
        # of the evening took that lock three times on its way to the light.
        # Measured on this house's own database: 3 lock acquisitions on the
        # first firing, 0 on the second and every one after.
        self._warm_meta()

    def slim_samples(self):
        """Store the readings once instead of twice.

        `samples` is keyed on (device, key, ts) and was an ordinary table, so
        SQLite kept the whole of it a second time in the index that enforces
        that key - on a real house, 94 MB of readings and 88 MB of index
        saying the same thing. WITHOUT ROWID makes the table BE the index:
        one copy, same queries, same speed for everything a chart or the
        newest-reading lookup does.

        Done once, on the first start after an upgrade, and only when it is
        worth doing. The rebuild is a few seconds for two million rows and it
        happens before anything else runs.
        """
        try:
            sql = self.db.execute(
                "SELECT sql FROM sqlite_master WHERE type='table' AND name='samples'").fetchone()
            half = self.db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='samples_slim'").fetchone()
            if half:
                # Killed part way through a rebuild. The schema above has
                # already made an empty `samples` again, so the readings are
                # sitting in samples_slim with nothing reading them: they are
                # moved across and the half-built table goes. Rows already in
                # both are left as they are.
                moved = self.db.execute(
                    'INSERT OR IGNORE INTO samples SELECT ts, device, key, value '
                    'FROM samples_slim').rowcount
                self.db.execute('DROP TABLE samples_slim')
                self.db.commit()
                if moved:
                    log('a rebuild of the readings table had been left half done; %s row(s) '
                        'brought back' % format(moved, ','), 'warn')
            if not sql:
                return
            if 'WITHOUT ROWID' in (sql[0] or '').upper():
                return
            rows = self.db.execute('SELECT COUNT(*) FROM samples').fetchone()[0]
        except Exception:
            return
        # VACUUM writes a whole second copy before it puts the first away, so
        # a disk with less than that free ends the day with neither. The
        # rebuild itself is worth doing either way; the tidying can wait.
        room = 0
        try:
            where = str(self.path.parent) or '.'
            spare = os.statvfs(where)
            room = spare.f_bavail * spare.f_frsize
        except Exception:
            room = 0
        size = 0
        try:
            size = self.path.stat().st_size
        except Exception:
            size = 0
        log('making the readings table its own index (%s row(s)); this takes a moment once'
            % format(rows, ','), 'info')
        began = time.time()
        try:
            self.db.executescript("""
                DROP INDEX IF EXISTS samples_ts;
                CREATE TABLE IF NOT EXISTS samples_slim (
                    ts      INTEGER NOT NULL,
                    device  TEXT    NOT NULL,
                    key     TEXT    NOT NULL,
                    value   REAL,
                    PRIMARY KEY (device, key, ts)
                ) WITHOUT ROWID;
                INSERT OR IGNORE INTO samples_slim SELECT ts, device, key, value FROM samples;
                DROP TABLE samples;
                ALTER TABLE samples_slim RENAME TO samples;
            """)
            self.db.commit()
            if room and size and room > size * 2.2:
                self.db.execute('VACUUM')
            elif size:
                log('the readings table was rebuilt, but there is not room to tidy the file '
                    'afterwards (%d MB free, %d MB wanted); it will shrink at the next backup'
                    % (room // 1048576, int(size * 2.2) // 1048576), 'warn')
            log('the readings table is its own index now, in %.0f s' % (time.time() - began), 'info')
        except Exception as e:
            log('the readings table could not be rebuilt: %s' % e, 'warn')

    # -- devices --------------------------------------------------------------
    def upsert_device(self, dev):
        now = int(time.time())
        # Nothing new is the usual answer - a poll re-states the same
        # description every round, and a sensor group re-states its own every
        # time it moves - and it is answered from the row already in memory.
        # It used to be a SELECT under the database lock every time: on the
        # rule worker, for a group of PIRs, that is the one place between a
        # movement and the light that a backup could stand in front of.
        cached = self._dev_cache.get(dev['id'])
        if cached is not None and not cached.get('removed') and self._same_cached(cached, dev):
            return 'known'
        with self.lock:
            row = self.db.execute('SELECT * FROM devices WHERE id=?', (dev['id'],)).fetchone()
            if row is not None and not row['removed'] and self._same_device(row, dev):
                return 'known'               # nothing to write, nothing to forget
            self._forget_device(dev['id'])   # every path below changes the row
            if row is None:
                self.db.execute(
                    'INSERT INTO devices (id,name,source,kind,model,vendor,description,'
                    'exposes,first_seen,last_seen,removed) VALUES (?,?,?,?,?,?,?,?,?,?,0)',
                    (dev['id'], dev['name'], dev['source'], dev.get('kind'), dev.get('model'),
                     dev.get('vendor'), dev.get('description'),
                     json.dumps(dev.get('exposes') or {}), now, dev.get('last_seen')))
                # a name given by hand on the old machine, waiting in a
                # restored export for this device to turn up here
                pending = self.get_meta('pending_aliases')
                if pending:
                    try:
                        waiting = json.loads(pending)
                    except ValueError:
                        waiting = {}
                    if isinstance(waiting, dict) and dev['id'] in waiting:
                        self.db.execute('UPDATE devices SET alias=? WHERE id=?',
                                        (str(waiting.pop(dev['id']))[:80] or None, dev['id']))
                        self.set_meta('pending_aliases', json.dumps(waiting))
                return 'new'
            changed = 'renamed' if row['name'] != dev['name'] else None
            self.db.execute(
                'UPDATE devices SET name=?,source=?,kind=COALESCE(?,kind),model=COALESCE(?,model),'
                'vendor=COALESCE(?,vendor),description=COALESCE(?,description),'
                'exposes=CASE WHEN ? THEN ? ELSE exposes END,removed=0 WHERE id=?',
                (dev['name'], dev['source'], dev.get('kind'), dev.get('model'), dev.get('vendor'),
                 dev.get('description'), 1 if dev.get('exposes') else 0,
                 json.dumps(dev.get('exposes') or {}), dev['id']))
            if changed:
                return changed
            return 'known'

    def mark_removed(self, device_id):
        with self.lock:
            self.db.execute('UPDATE devices SET removed=1 WHERE id=?', (device_id,))
        self._forget_device(device_id)

    def touch_device(self, device_id, ts):
        self._defer(self._write_touch, device_id, ts)

    def _write_touch(self, device_id, ts):
        with self.lock:
            self.db.execute('UPDATE devices SET last_seen=? WHERE id=?', (ts, device_id))
        row = self._dev_cache.get(device_id)
        if row is not None:
            row['last_seen'] = ts        # keep it current without another read
        for d in (self._dev_list or []):
            if d['id'] == device_id:
                d['last_seen'] = ts
                break

    def devices(self, include_removed=False):
        """The whole list, in memory. The dashboard rebuilds its status from
        this on every refresh, so it must not queue behind a long write."""
        if self._dev_list is None:
            with self.lock:
                rows = self.db.execute(
                    'SELECT * FROM devices ORDER BY name COLLATE NOCASE').fetchall()
            listed = []
            for r in rows:
                d = dict(r)
                try:
                    d['exposes'] = json.loads(d.get('exposes') or '{}')
                except ValueError:
                    d['exposes'] = {}
                listed.append(d)
                self._dev_cache[d['id']] = d
            self._dev_list = listed
        return [dict(d) for d in self._dev_list
                if include_removed or not d.get('removed')]

    def device(self, device_id):
        """Kept in memory: this is read on the path a person is waiting on
        (a switch resolves its target here), and the row changes rarely."""
        if device_id in self._dev_cache:
            row = self._dev_cache[device_id]
            return dict(row) if row is not None else None
        with self.lock:
            r = self.db.execute('SELECT * FROM devices WHERE id=?', (device_id,)).fetchone()
        if r is None:
            self._dev_cache[device_id] = None
            return None
        d = dict(r)
        try:
            d['exposes'] = json.loads(d.get('exposes') or '{}')
        except ValueError:
            d['exposes'] = {}
        self._dev_cache[device_id] = d
        return dict(d)

    @staticmethod
    def _same_device(row, dev):
        """Would the update write anything new? A poll re-states the same
        description every round; rewriting it would cost a lock and throw the
        cached list away for nothing."""
        if row['name'] != dev['name'] or row['source'] != dev['source']:
            return False
        for field in ('kind', 'model', 'vendor', 'description'):
            value = dev.get(field)
            if value is not None and row[field] != value:
                return False
        exposes = dev.get('exposes')
        if exposes and json.dumps(exposes) != (row['exposes'] or ''):
            return False
        return True

    @staticmethod
    def _same_cached(row, dev):
        """_same_device, for a row as it is held in memory (exposes parsed)."""
        if row.get('name') != dev['name'] or row.get('source') != dev['source']:
            return False
        for field in ('kind', 'model', 'vendor', 'description'):
            value = dev.get(field)
            if value is not None and row.get(field) != value:
                return False
        exposes = dev.get('exposes')
        if exposes and exposes != (row.get('exposes') or {}):
            return False
        return True

    def trim_wal(self):
        """Fold the write-ahead log back into the file. SQLite reuses it in
        place, so after a VACUUM it can sit at the size of the whole database
        for good - and it counts towards what the disk, and the dashboard,
        report."""
        if not self.lock.acquire(timeout=0.05):
            return False
        try:
            self.db.execute('PRAGMA wal_checkpoint(TRUNCATE)')
        except sqlite3.OperationalError:
            return False
        finally:
            self.lock.release()
        self._stats_cache = None
        return True

    def _warm_actions(self):
        """Which actions each device has sent, for every device at once."""
        try:
            with self.lock:
                rows = self.db.execute(
                    "SELECT device, detail, MAX(ts) AS ts FROM events WHERE kind='action' "
                    "AND device IS NOT NULL GROUP BY device, detail ORDER BY ts DESC").fetchall()
        except Exception:
            return
        # every known device gets an entry, including the ones with nothing to
        # show: a missing entry means "go and look", which is the whole point
        seen = {d['id']: [] for d in (self._dev_list or [])}
        latest = {d['id']: None for d in (self._dev_list or [])}
        for r in rows:
            if not r['detail']:
                continue
            seen.setdefault(r['device'], []).append(r['detail'])
            if not latest.get(r['device']):
                latest[r['device']] = {'action': r['detail'], 'ts': r['ts']}
        self._actions_cache = seen
        self._last_action = latest

    def _warm_meta(self):
        """Read every setting row in one go, so nothing has to fetch one later
        at a bad moment."""
        try:
            with self.lock:
                rows = self.db.execute('SELECT key, value FROM meta').fetchall()
            # update, never replace: keys we already know are absent stay
            # remembered as absent, so nothing goes back to the database for them
            self._meta_raw.update({r['key']: r['value'] for r in rows})
            # ...and now every key the table holds is in memory, so a key that
            # is NOT in memory is a key the table does not have. That is what
            # the first firing after a restart was waiting on: three settings
            # nobody had ever written. The two places that write a meta row
            # without going through set_meta keep this true by hand.
            self._meta_complete = True
        except Exception:
            self._meta_complete = False
        self._warm_devices()

    def _warm_devices(self):
        """Every device row read into memory in one go.

        A row was fetched under the database lock the first time anything
        asked for it after a start, a rename or a restore - and two of the
        things that ask are on the way to a light: a Zigbee command reads its
        target's row before it is published, and a sensor group reads its own
        before it is recorded. A backup holds that lock for a second and a
        half. Read here, while nothing is waiting on it."""
        # Anything forgotten while the rows were being read may have been
        # changed in the meantime, and putting back what was read before that
        # would put back the old row: in that case nothing is filled in, and
        # the next asking reads the row as it is now.
        before = self.__dict__.get('_dev_forgets', 0)
        try:
            with self.lock:
                rows = self.db.execute('SELECT * FROM devices').fetchall()
        except Exception:
            return
        if self.__dict__.get('_dev_forgets', 0) != before:
            return
        for r in rows:
            if r['id'] in self._dev_cache:
                continue
            row = dict(r)
            try:
                row['exposes'] = json.loads(row.get('exposes') or '{}')
            except ValueError:
                row['exposes'] = {}
            self._dev_cache[r['id']] = row

    def _forget_device(self, device_id=None):
        self._dev_list = None
        self._dev_forgets = self.__dict__.get('_dev_forgets', 0) + 1
        if device_id is None:
            self._dev_cache.clear()
            # ...and read back at once, on a thread of its own, rather than one
            # row at a time by whatever asks next - which after a restore or a
            # sweep of stale devices was a sensor on its way to a light
            threading.Thread(target=self._warm_devices, name='warm-devices', daemon=True).start()
        else:
            self._dev_cache.pop(device_id, None)

    def resolve(self, name_or_id):
        """Accept an IEEE address, an id, a friendly name or a dashboard alias.
        Answered from the device list already in memory: this sits on the
        dashboard path, where waiting on the database is what a long write
        turns into a stall."""
        key = str(name_or_id or '')
        if not key:
            return None
        if self._dev_list is None:
            self.devices(include_removed=True)      # fills the list once
        listed = self._dev_list or []
        for d in listed:
            if d['id'] == key:
                return d['id']
        low = key.lower()
        for d in listed:
            if (d['name'] or '').lower() == low or (d['alias'] or '').lower() == low:
                return d['id']
        return None

    def set_alias(self, device_id, alias):
        with self.lock:
            self.db.execute('UPDATE devices SET alias=? WHERE id=?', (alias or None, device_id))
        self._forget_device(device_id)

    # -- readings -------------------------------------------------------------
    def store_sample(self, device_id, ts, values):
        self._defer(self._write_sample, device_id, ts, dict(values or {}))

    def _write_sample(self, device_id, ts, values):
        """values: {key: float}. Honour sample_interval by replacing the row,
        and don't write down the same number twice in a row.

        A house writes down what it is told, and most of what it is told is
        what it was told a moment ago: an IMEI fifteen thousand times, a SIM
        slot count fourteen thousand, a plug's returned-energy total the same.
        On a real house two weeks old that was sixty-two per cent of every row
        in the database.

        A reading equal to the last one written for that series is skipped
        until the anchor time has passed, so a flat line still gets a point
        every quarter of an hour and every hour still has rows to be folded
        into. Nothing else changes: the live reading, the rules, the alerts
        and the switches all work from what arrived, not from what was
        written down, and a value that differs by any amount at all is written
        at once.
        """
        gap = int(CONFIG.get('sample_interval') or 0)
        anchor = max(0, int(CONFIG.get('sample_anchor_s', SAMPLE_ANCHOR_S) or 0))
        with self.lock:
            for key, value in values.items():
                prev = self.last_sample.get((device_id, key))
                if prev is None:
                    r = self.db.execute('SELECT MAX(ts) AS ts FROM samples WHERE device=? AND key=?',
                                        (device_id, key)).fetchone()
                    prev = r['ts'] if r and r['ts'] is not None else 0
                # 0 <= ... : a reading that is OLDER than the last one written
                # is not "inside the gap", it is late - and treating it as
                # inside meant it overwrote the newest row with an older
                # value. Anything from before the last row is simply written
                # where it belongs.
                if gap and prev and 0 <= ts - prev < gap and prev != ts:
                    self.db.execute('UPDATE samples SET value=? WHERE device=? AND key=? AND ts=?',
                                    (value, device_id, key, prev))
                    # what is stored for that series has just changed, so the
                    # memory of it must change too - or a later reading equal
                    # to the value this one replaced would be skipped as a
                    # repeat of something no longer there
                    self.last_written[(device_id, key)] = (value, prev)
                    continue
                if anchor:
                    same = self.last_written.get((device_id, key))
                    if same is not None and same[0] == value and ts - same[1] < anchor:
                        continue                  # the same number, and the anchor is not due
                self.db.execute('INSERT OR REPLACE INTO samples (ts,device,key,value) VALUES (?,?,?,?)',
                                (ts, device_id, key, value))
                self.last_sample[(device_id, key)] = ts
                self.last_written[(device_id, key)] = (value, ts)

    def store_snapshot(self, device_id, ts, payload, availability=None):
        """Merge in memory and hand the result straight back - the dashboard
        shows this immediately - then write the row on the writer thread."""
        cached = self._snap_cache.get(device_id)
        if cached is None:
            cached = self._read_snapshot(device_id)
        merged = dict(cached[0])
        merged.update(payload or {})
        if availability is None:
            availability = cached[1]
        self._snap_cache[device_id] = (merged, availability)
        self._defer(self._write_snapshot, device_id, ts, merged, availability)
        return merged

    def replace_snapshot(self, device_id, payload, availability=None):
        """The whole payload, not merged into what was there - for taking a
        reading away rather than adding one."""
        cached = self._snap_cache.get(device_id) or self._read_snapshot(device_id)
        if availability is None:
            availability = cached[1]
        self._snap_cache[device_id] = (dict(payload or {}), availability)
        self._defer(self._write_snapshot, device_id, int(time.time()), dict(payload or {}), availability)
        return dict(payload or {})

    def _read_snapshot(self, device_id):
        with self.lock:
            row = self.db.execute('SELECT payload, availability FROM snapshots WHERE device=?',
                                  (device_id,)).fetchone()
        payload, availability = {}, None
        if row:
            try:
                payload = json.loads(row['payload'])
            except ValueError:
                payload = {}
            availability = row['availability']
        self._snap_cache[device_id] = (payload, availability)
        return self._snap_cache[device_id]

    def _write_snapshot(self, device_id, ts, merged, availability=None):
        with self.lock:
            self.db.execute('INSERT OR REPLACE INTO snapshots (device,ts,payload,availability) '
                            'VALUES (?,?,?,?)', (device_id, ts, json.dumps(merged), availability))
        return merged

    def snapshots(self):
        with self.lock:
            rows = self.db.execute('SELECT * FROM snapshots').fetchall()
        out = {}
        for r in rows:
            try:
                payload = json.loads(r['payload'])
            except ValueError:
                payload = {}
            out[r['device']] = {'ts': r['ts'], 'payload': payload,
                                'availability': r['availability']}
            self._snap_cache[r['device']] = (payload, r['availability'])
        return out

    def keys_for(self, device_id):
        with self.lock:
            a = self.db.execute('SELECT DISTINCT key FROM samples WHERE device=?', (device_id,)).fetchall()
            b = self.db.execute('SELECT DISTINCT key FROM samples_hourly WHERE device=?',
                                (device_id,)).fetchall()
        return sorted({r['key'] for r in a} | {r['key'] for r in b})

    def counter_span(self, device_id, key, since, until):
        """The first and last reading of a rising counter in a window - what a
        meter counted between two moments, whether or not anyone was watching
        at the time."""
        with self.lock:
            row = self.db.execute(
                'SELECT (SELECT value FROM samples WHERE device=? AND key=? AND ts>=? AND ts<? ORDER BY ts LIMIT 1),'
                '       (SELECT value FROM samples WHERE device=? AND key=? AND ts>=? AND ts<? ORDER BY ts DESC LIMIT 1)',
                (device_id, key, int(since), int(until), device_id, key, int(since), int(until))).fetchone()
        if not row or row[0] is None or row[1] is None:
            return None
        return (float(row[0]), float(row[1]))

    def counter_span_many(self, wanted, since, until):
        """counter_span for a whole list of (device, key) pairs, under one
        turn of the lock instead of one each.

        The month's money asked this once per socket, twice for the window,
        so twice a second the page took and let go of the only lock this
        database has forty-six times over. Each of those was a fresh chance to
        be queued behind a busy background thread, and the page saw it as a
        stall of a sixth of a second.
        """
        out = {}
        if not wanted:
            return out
        sql = ('SELECT (SELECT value FROM samples WHERE device=? AND key=? AND ts>=? AND ts<? ORDER BY ts LIMIT 1),'
               '       (SELECT value FROM samples WHERE device=? AND key=? AND ts>=? AND ts<? ORDER BY ts DESC LIMIT 1)')
        since, until = int(since), int(until)
        with self.lock:
            for device_id, key in wanted:
                row = self.db.execute(
                    sql, (device_id, key, since, until, device_id, key, since, until)).fetchone()
                if row and row[0] is not None and row[1] is not None:
                    out[(device_id, key)] = (float(row[0]), float(row[1]))
        return out

    def history(self, device_id, keys, seconds, points=600):
        """Rows of {ts, key1, key2, ...} mixing hourly data for the old part."""
        now = int(time.time())
        since = now - seconds
        full_from = now - int(CONFIG.get('retain_full_days', 14)) * 86400
        # Thin inside SQLite, not in Python: a 7-day chart used to pull every
        # 30 s row (20k per key) through Python just to keep 400 of them, which
        # held the store lock for ~40 ms per device - and the Overview reloads
        # every chart on every live update. One real row per time bucket
        # (the last one in it, so the newest point is always kept) is the
        # same picture for a fraction of the work.
        bucket = max(1, seconds // max(1, int(points or 600)))
        rows = {}
        # the lock is taken a key at a time: held round all of them, one
        # question for many keys held every writer, the rules' reads and the
        # door's list for as long as the whole lot took
        for key in keys:
            with self.lock:
                if since < full_from:
                    for r in self.db.execute(
                            'SELECT MAX(ts) AS ts, avg AS value, min, max FROM samples_hourly '
                            'WHERE device=? AND key=? AND ts>=? AND ts<? GROUP BY ts/? ORDER BY ts',
                            (device_id, key, since, full_from, max(3600, bucket))):
                        rows.setdefault(r['ts'], {'ts': r['ts']})[key] = r['value']
                        rows[r['ts']][key + '_min'] = r['min']
                        rows[r['ts']][key + '_max'] = r['max']
                for r in self.db.execute(
                        'SELECT MAX(ts) AS ts, value FROM samples WHERE device=? AND key=? AND ts>=? '
                        'GROUP BY ts/? ORDER BY ts',
                        (device_id, key, max(since, full_from), bucket)):
                    rows.setdefault(r['ts'], {'ts': r['ts']})[key] = r['value']
        ordered = [rows[t] for t in sorted(rows)]
        return thin(ordered, points)

    def reading_over(self, device, key, since):
        """min, max, average, count, first and last of one reading since a
        moment - from the raw samples, and from the hourly ones where the raw
        have already been folded away."""
        with self.lock:
            row = self.db.execute('SELECT MIN(value) AS lo, MAX(value) AS hi, AVG(value) AS av, COUNT(*) AS n '
                                  'FROM samples WHERE device=? AND key=? AND ts>=?',
                                  (str(device), str(key), int(since))).fetchone()
            ends = self.db.execute('SELECT (SELECT value FROM samples WHERE device=? AND key=? AND ts>=? '
                                   'ORDER BY ts LIMIT 1) AS first, (SELECT value FROM samples WHERE device=? '
                                   'AND key=? AND ts>=? ORDER BY ts DESC LIMIT 1) AS last',
                                   (str(device), str(key), int(since)) * 2).fetchone()
            out = {'min': row['lo'], 'max': row['hi'], 'avg': row['av'], 'count': int(row['n'] or 0),
                   'first': ends['first'], 'last': ends['last']}
            if not out['count']:
                row = self.db.execute('SELECT MIN(min) AS lo, MAX(max) AS hi, SUM(avg*n)/SUM(n) AS av, '
                                      'SUM(n) AS n FROM samples_hourly WHERE device=? AND key=? AND ts>=?',
                                      (str(device), str(key), int(since))).fetchone()
                if row and row['n']:
                    out.update(min=row['lo'], max=row['hi'], avg=row['av'], count=int(row['n'] or 0))
        return out

    def history_many(self, wanted, seconds, points=400):
        """[(device_id, [keys]), ...] -> {device_id: rows}. One call, one
        lock, one round trip for the Overview charts instead of one request
        per device."""
        return {device_id: self.history(device_id, keys, seconds, points) for device_id, keys in wanted}

    # -- events ---------------------------------------------------------------
    on_event = None

    def note_networks(self, neighbours):
        """Write down what the air holds, so it can be looked at afterwards.

        One row per network rather than one per sighting: a neighbour heard
        every twenty seconds for a year would be a million rows saying the
        same thing. What is worth keeping is that it was there, when it was
        first and last heard, and the best it ever came in."""
        now = int(time.time())
        rows = []
        for n in neighbours or []:
            bssid = str(n.get('bssid') or '').strip().lower()
            if not bssid:
                continue
            rows.append((bssid, str(n.get('ssid') or ''), str(n.get('band') or ''),
                         int(n.get('channel') or 0), str(n.get('width') or ''),
                         str(n.get('security') or ''), 1 if n.get('ubiquiti') else 0,
                         int(n.get('signal') or -999), now))
        if not rows:
            return 0
        self._defer(self._write_networks, rows)
        return len(rows)

    def _write_networks(self, rows):
        with self.lock:
            self._bulk(
                'INSERT INTO wifi_seen (bssid, ssid, band, channel, width, security, ubiquiti, '
                'best, last, first, times) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1) '
                'ON CONFLICT(bssid) DO UPDATE SET ssid = excluded.ssid, band = excluded.band, '
                'channel = excluded.channel, width = excluded.width, security = excluded.security, '
                'ubiquiti = excluded.ubiquiti, best = MAX(wifi_seen.best, excluded.best), '
                'last = excluded.last, times = wifi_seen.times + 1',
                [r + (r[8],) for r in rows])

    def networks_seen(self, limit=500):
        with self.lock:
            rows = self.db.execute(
                'SELECT bssid, ssid, band, channel, width, security, ubiquiti, best, last, first, times '
                'FROM wifi_seen ORDER BY last DESC, best DESC LIMIT ?', (int(limit),)).fetchall()
        return [{'bssid': r[0], 'ssid': r[1], 'band': r[2], 'channel': r[3], 'width': r[4],
                 'security': r[5], 'ubiquiti': bool(r[6]), 'best': r[7], 'last': r[8],
                 'first': r[9], 'times': r[10]} for r in rows]

    def forget_networks(self):
        with self.lock:
            gone = self.db.execute('SELECT COUNT(*) FROM wifi_seen').fetchone()[0]
            self.db.execute('DELETE FROM wifi_seen')
            self.db.commit()
        return gone

    # -- every press of a one-tap link, whichever road and whatever it asked --
    def log_tap(self, row):
        """Write down a press. On the writer thread: a link must not wait for
        a disk to answer before the light comes on."""
        self._defer(self._write_tap, dict(row))
        return row.get('ticket') or ''

    # The same refusal over and over is one thing that happened, not many. A
    # browser asked once will often ask again by itself - a retry, a reload, a
    # second connection - and each of those arrived as a line of its own, so
    # opening one bad address twice filled the log with ten. They are folded
    # into one line carrying how many times, which is what a reader wants and
    # what the counting should weigh.
    SAME_PRESS_WITHIN = 5.0

    def _write_tap(self, row):
        # under the lock, as every other write to the shared connection: an
        # insert landing inside another thread's open transaction went with it
        # when that one rolled back
        with self.lock:
            self._write_tap_locked(row)

    def _write_tap_locked(self, row):
        when = row.get('ts') or time.time()
        # a refusal carries a ticket of its own, so folding cannot be made to
        # depend on there being none
        if row.get('state') == 'refused':
            same = self.db.execute(
                'SELECT rowid, ts, times FROM taps_log WHERE state=? AND who=? AND way=? '
                'AND message=? AND IFNULL(link,\'\')=? AND IFNULL(mark,\'\')=? '
                'ORDER BY ts DESC LIMIT 1',
                ('refused', row.get('who'), row.get('way'), row.get('message'),
                 row.get('link') or '', row.get('mark') or '')).fetchone()
            if same and when - (same['ts'] or 0) <= self.SAME_PRESS_WITHIN:
                self.db.execute('UPDATE taps_log SET ts=?, times=IFNULL(times,1)+1 WHERE rowid=?',
                                (when, same['rowid']))
                return
        self.db.execute(
            'INSERT INTO taps_log (ts,ended,ticket,link,what,who,way,factor,state,message,device,times,mark) '
            'VALUES (?,?,?,?,?,?,?,?,?,?,?,1,?)',
            (when, row.get('ended'), row.get('ticket'), row.get('link'),
             row.get('what'), row.get('who'), row.get('way'), row.get('factor'),
             row.get('state'), row.get('message'), row.get('device'), row.get('mark')))

    def finish_tap(self, ticket, state, message=''):
        if ticket:
            self._defer(self._write_tap_end, ticket, state, message)

    def _write_tap_end(self, ticket, state, message):
        with self.lock:
            self.db.execute('UPDATE taps_log SET state=?, message=?, ended=? WHERE ticket=?',
                            (state, message, time.time(), ticket))

    def tap_counts(self, since):
        """How many presses, and how many refused, since a moment - counted by
        the database rather than by pulling the rows out and counting them
        here, which every message preview was doing."""
        with self.lock:
            row = self.db.execute(
                'SELECT COUNT(*) AS n, SUM(CASE WHEN state=? THEN 1 ELSE 0 END) AS bad '
                'FROM taps_log WHERE ts > ?', ('refused', float(since))).fetchone()
        return int(row['n'] or 0), int(row['bad'] or 0)

    def blocked_summary(self):
        """How many are blocked, and the newest of them."""
        with self.lock:
            row = self.db.execute('SELECT COUNT(*) AS n FROM blocked').fetchone()
            newest = self.db.execute('SELECT ip, why, since AS at FROM blocked '
                                     'ORDER BY since DESC LIMIT 1').fetchone()
        return int(row['n'] or 0), (dict(newest) if newest else {})

    def blocked_since(self, when):
        """How many addresses have been kept out since a moment.

        The list as it stands and the history together, each address counted
        once. Counting only the list said "kept out and still kept out": with
        the usual hour-long ban, everything from before the last hour had
        already been swept into the history, so {blocked_today} read nearly
        nothing on a day that had kept out dozens."""
        with self.lock:
            row = self.db.execute(
                'SELECT COUNT(*) AS n FROM ('
                '  SELECT ip FROM blocked WHERE since >= ?'
                '  UNION SELECT ip FROM blocked_log WHERE ts >= ?)',
                (float(when), float(when))).fetchone()
        return int((row or {'n': 0})['n'] or 0)

    def blocked_names(self, limit=12):
        with self.lock:
            rows = self.db.execute('SELECT ip FROM blocked ORDER BY since DESC LIMIT ?',
                                   (int(limit),)).fetchall()
        return [r['ip'] for r in rows]

    def tap_log(self, limit=200, text='', state=''):
        """The newest presses, and how many there are in all.

        Searched in the database rather than on the page: a house that has
        been running a year has more of these than a browser wants to be
        handed, and the answer to "when did that address last try" is in the
        old ones, not the new.
        """
        where, args = [], []
        for word in [w for w in str(text or '').split() if w][:6]:
            where.append('(link LIKE ? OR what LIKE ? OR who LIKE ? OR factor LIKE ? '
                         'OR way LIKE ? OR message LIKE ? OR state LIKE ?)')
            args.extend(['%%%s%%' % word] * 7)
        if state:
            where.append('state = ?')
            args.append(str(state))
        clause = (' WHERE ' + ' AND '.join(where)) if where else ''
        with self.lock:
            total = self.db.execute('SELECT COUNT(*) AS n FROM taps_log').fetchone()['n']
            matched = self.db.execute('SELECT COUNT(*) AS n FROM taps_log' + clause, args).fetchone()['n']
            rows = self.db.execute('SELECT * FROM taps_log' + clause + ' ORDER BY ts DESC LIMIT ?',
                                   args + [max(1, min(int(limit or 200), 2000))]).fetchall()
        return [dict(r) for r in rows], int(matched or 0), int(total or 0)

    def forget_tap_log(self):
        with self.lock:
            gone = self.db.execute('DELETE FROM taps_log').rowcount
            self.db.commit()
        return gone or 0

    # -- addresses that may not talk to the API -------------------------------
    def blocked_all(self):
        with self.lock:
            rows = self.db.execute('SELECT * FROM blocked ORDER BY since DESC').fetchall()
        return [dict(r) for r in rows]

    def blocked_until(self, ip, networks=True, wait=True):
        """None when the address is free; otherwise when it comes free again
        (0 for never). Read on every request, so it is answered from a small
        map rather than from the disk. An entry may be a whole range - one
        line keeping out a street rather than thirty keeping out its houses.

        wait=False is the door of the API: every click, every press of a link
        and every text from the gateway is asked about here before anything
        else happens to it. The map was read again from the table whenever it
        was two seconds old - the whole list, 27,000 rows on this house, under
        the database lock that a backup holds for a second and a half - and
        it was whichever request came first that paid. At the door the map in
        hand answers, and a fresh one is read behind it."""
        now = time.time()
        if not wait and self._block_cache_at and self._block_cache_at >= now - 60:
            pass                              # fresh enough for the door
        elif not wait and self._block_loaded:
            self._block_reload_later()
        elif self._block_cache_at < now - 2:
            self._block_reload(now)
        return self._block_answer(ip, networks, now)

    def _block_reload_later(self):
        """Read the list again on a thread of its own, once at a time."""
        with self._block_guard:
            if self.__dict__.get('_block_reloading'):
                return
            self._block_reloading = True

        def again():
            try:
                self._block_reload(time.time())
            except Exception as e:
                log('reading the blocked list again: %s' % e, 'debug')
            finally:
                self._block_reloading = False
        threading.Thread(target=again, name='blocked-list', daemon=True).start()

    def _block_changed(self):
        """The list changed: whatever is held must be read again.

        A number that moves with every change, as well as the stamp: a reading
        of the list that started before a block and finished after it used to
        write its own stamp over the block's "read me again", and the door then
        trusted the list from before the block for its full minute - the
        address just blocked walked in 293 times in that minute."""
        with self._block_guard:
            self._block_gen = getattr(self, '_block_gen', 0) + 1
            self._block_delta.append((self._block_gen, '*', None, False))
            del self._block_delta[:-4000]
            self._block_cache_at = 0

    @staticmethod
    def _block_apply(cache, nets, ip, until, gone):
        ip = str(ip)
        if gone:
            cache.pop(ip, None)
        else:
            cache[ip] = until
        if '/' in ip:
            try:
                net = ipaddress.ip_network(ip, strict=False)
            except ValueError:
                return
            nets[:] = [x for x in nets if x[0] != net]
            if not gone:
                nets.append((net, until))

    def _block_patch(self, ip, until=None, gone=False):
        """One address on or off the list, put into the list in hand at once.

        A block used to throw the whole list away: the door kept answering
        from the old one until a fresh read of all of it - 27,000 rows under
        the database lock - came back, and an address blocked a moment before
        got in 1,302 times meanwhile while a backup held the lock. And the log
        sweep, blocking 292 addresses, read the whole list again 293 times:
        17 s, 15.8 of them that. The change is also written down, so a read
        of the whole list that began before it cannot put the old list back."""
        with self._block_guard:
            self._block_gen = getattr(self, '_block_gen', 0) + 1
            self._block_delta.append((self._block_gen, str(ip), until, bool(gone)))
            del self._block_delta[:-4000]
            cache, nets = dict(self._block_cache), list(self._block_nets)
            self._block_apply(cache, nets, ip, until, gone)
            self._block_cache, self._block_nets = cache, nets

    def _block_reload(self, now):
        with self._block_guard:
            gen = getattr(self, '_block_gen', 0)
        with self.lock:
            rows = self.db.execute('SELECT ip, until FROM blocked').fetchall()
        # built aside and put in place whole: filled in place, a request on
        # another thread read a half-built list of ranges and an address
        # inside a blocked range walked in
        cache = {r['ip']: r['until'] for r in rows}
        nets = []
        for r in rows:
            if '/' in str(r['ip']):
                try:
                    nets.append((ipaddress.ip_network(r['ip'], strict=False), r['until']))
                except ValueError:
                    continue
        with self._block_guard:
            # what changed while it was being read is put into it, so a block
            # made meanwhile is never lost; a change of the whole list (an
            # import, a fold undone) leaves it to be read again
            whole = False
            for g, ip, until, gone in self._block_delta:
                if g <= gen:
                    continue
                if ip == '*':
                    whole = True
                else:
                    self._block_apply(cache, nets, ip, until, gone)
            self._block_delta = [x for x in self._block_delta if x[0] > gen]
            self._block_cache, self._block_nets = cache, nets
            self._block_cache_at = 0 if whole else now
            self._block_loaded = True

    def _block_answer(self, ip, networks, now):
        cache, nets = self._block_cache, self._block_nets
        found = ip if ip in cache else None
        until = cache.get(ip)
        if found is None and networks and nets:
            try:
                one = ipaddress.ip_address(ip)
            except ValueError:
                return None
            for net, ends in nets:
                if one in net:
                    found, until = str(net), ends
                    break
        if found is None:
            return None
        if until and until < now:
            self.unblock(found, how='ran out')
            return None
        return until or 0

    def note_block_event(self, ip, what, why='', auto=True, by=''):
        """One line in the story of an address, as it happened.

        A block and the letting go of it are two things at two times, and were
        being kept as one row with two dates in it - which reads as a summary
        and not as a log. Each is written as it happens.
        """
        self._defer(self._write_block_event, time.time(), str(ip), str(what),
                    str(why or '')[:200], 1 if auto else 0, str(by or '')[:60])

    def _write_block_event(self, ts, ip, what, why, auto, by):
        with self.lock:
            self.db.execute('INSERT INTO block_events (ts, ip, what, why, auto, by) VALUES (?,?,?,?,?,?)',
                            (ts, ip, what, why, auto, by))

    def block_events(self, limit=200, text=''):
        where, args = [], []
        for word in [w for w in str(text or '').split() if w][:6]:
            where.append('(ip LIKE ? OR what LIKE ? OR why LIKE ? OR by LIKE ?)')
            args.extend(['%%%s%%' % word] * 4)
        clause = (' WHERE ' + ' AND '.join(where)) if where else ''
        with self.lock:
            total = self.db.execute('SELECT COUNT(*) AS n FROM block_events').fetchone()['n']
            matched = self.db.execute('SELECT COUNT(*) AS n FROM block_events' + clause,
                                      args).fetchone()['n']
            rows = self.db.execute('SELECT * FROM block_events' + clause + ' ORDER BY ts DESC LIMIT ?',
                                   args + [max(1, min(int(limit or 200), 2000))]).fetchall()
        return [dict(r) for r in rows], int(matched or 0), int(total or 0)

    def block(self, ip, until=None, why='', auto=True, by=''):
        self.note_block_event(ip, 'blocked', why, auto, by)
        with self.lock:
            self.db.execute(
                'INSERT INTO blocked (ip, since, until, why, hits, auto, by) VALUES (?,?,?,?,1,?,?) '
                'ON CONFLICT(ip) DO UPDATE SET until=excluded.until, why=excluded.why, '
                'hits=blocked.hits+1, auto=excluded.auto, by=excluded.by',
                (str(ip), time.time(), until, str(why)[:200], 1 if auto else 0, str(by)[:60]))
            self.db.commit()
        self._block_patch(ip, until)
        return True

    def unblock(self, ip=None, how='taken off'):
        """Off the list, and into the history: an address that was kept out
        once is worth knowing about long after it is let back in."""
        with self.lock:
            rows = (self.db.execute('SELECT * FROM blocked').fetchall() if ip is None
                    else self.db.execute('SELECT * FROM blocked WHERE ip=?', (str(ip),)).fetchall())
            for r in rows:
                self.db.execute(
                    'INSERT INTO blocked_log (ts, ended, ip, why, how, auto, hits, by) '
                    'VALUES (?,?,?,?,?,?,?,?)',
                    (r['since'], time.time(), r['ip'], r['why'], how, r['auto'], r['hits'], r['by']))
                self.db.execute(
                    'INSERT INTO block_events (ts, ip, what, why, auto, by) VALUES (?,?,?,?,?,?)',
                    (time.time(), r['ip'], 'let back in', how,
                     1 if how == 'ran out' else 0, r['by'] or ''))
            gone = (self.db.execute('DELETE FROM blocked').rowcount if ip is None
                    else self.db.execute('DELETE FROM blocked WHERE ip=?', (str(ip),)).rowcount)
            self.db.commit()
        if how == 'ran out':
            # The store cannot say anything itself, so it leaves the names and
            # the daemon says them on its next round. Without this, "let back
            # in when its time ran out" was a kind of message the card offered
            # a road for and nothing ever sent.
            if not hasattr(self, 'ran_out'):
                self.ran_out = []
            self.ran_out.extend(str(r['ip']) for r in rows)
            del self.ran_out[:-50]
        if ip is None:
            self._block_changed()
        else:
            self._block_patch(ip, gone=True)
        return gone or 0

    def fold_into(self, ip, net, by='folded'):
        """Take one address off the list because a whole subnet now covers it.

        Not "let back in": nothing gets in, the subnet is keeping it out. So
        the history says "folded into" rather than "let back in", the ladder
        (which counts blocks) is not touched, and everything that was kept
        about the address - its reason, the lines that earned it, what
        Suricata said - stays exactly where it was, under its own name.
        Returns the row as it stood, or None if it was not on the list.
        """
        now = time.time()
        with self.lock:
            r = self.db.execute('SELECT * FROM blocked WHERE ip=?', (str(ip),)).fetchone()
            if not r:
                return None
            self.db.execute(
                'INSERT INTO blocked_log (ts, ended, ip, why, how, auto, hits, by) '
                'VALUES (?,?,?,?,?,?,?,?)',
                (r['since'], now, r['ip'], r['why'], 'folded into %s' % net, r['auto'],
                 r['hits'], r['by']))
            self.db.execute(
                'INSERT INTO block_events (ts, ip, what, why, auto, by) VALUES (?,?,?,?,?,?)',
                (now, r['ip'], 'folded', 'into %s' % net, 1, str(by or '')[:60]))
            self.db.execute('DELETE FROM blocked WHERE ip=?', (str(ip),))
            self.db.commit()
        self._block_patch(ip, gone=True)
        return dict(r)

    def unfold(self, row, net):
        """Put one address back on the list exactly as it was before it was
        folded: its own reason, its own start, its own end."""
        now = time.time()
        until = row.get('until')
        if until and until < now:
            return False                  # its own time ran out while it was folded
        with self.lock:
            self.db.execute(
                'INSERT OR REPLACE INTO blocked (ip, since, until, why, hits, auto, by) '
                'VALUES (?,?,?,?,?,?,?)',
                (str(row['ip']), float(row.get('since') or now), until, str(row.get('why') or '')[:200],
                 int(row.get('hits') or 0), 1 if row.get('auto', True) else 0,
                 str(row.get('by') or '')[:60]))
            self.db.execute(
                'INSERT INTO block_events (ts, ip, what, why, auto, by) VALUES (?,?,?,?,?,?)',
                (now, str(row['ip']), 'unfolded', 'out of %s' % net, 0, ''))
            self.db.commit()
        self._block_patch(row['ip'], until)
        return True

    def add_fold_version(self, by, widest, before, after, groups, keep=10):
        with self.lock:
            cur = self.db.execute(
                'INSERT INTO fold_versions (ts, by, widest, before, after, groups) VALUES (?,?,?,?,?,?)',
                (time.time(), str(by or '')[:60], int(widest or 0), int(before or 0), int(after or 0),
                 json.dumps(groups)))
            self.db.commit()
            new = cur.lastrowid
        self.prune_fold_versions(keep)
        return new

    def prune_fold_versions(self, keep):
        keep = max(1, int(keep or 10))
        with self.lock:
            self.db.execute('DELETE FROM fold_versions WHERE id NOT IN '
                            '(SELECT id FROM fold_versions ORDER BY id DESC LIMIT ?)', (keep,))
            self.db.commit()

    def fold_versions(self, limit=50):
        with self.lock:
            rows = self.db.execute('SELECT * FROM fold_versions ORDER BY id DESC LIMIT ?',
                                   (max(1, int(limit or 50)),)).fetchall()
        out = []
        for r in rows:
            one = dict(r)
            try:
                one['groups'] = json.loads(one.get('groups') or '[]')
            except (ValueError, TypeError):
                one['groups'] = []
            out.append(one)
        return out

    def fold_version(self, vid):
        return next((v for v in self.fold_versions(1000) if v['id'] == int(vid)), None)

    # The list of addresses kept out, and everything written about them, in
    # a settings export. A house rebuilt from its export used to come up with
    # the list empty: every attacker let back in, the router emptied on its
    # first sync, and the story of each one gone.
    BAN_META = ('blocked_', 'ids_about_')

    def ban_export(self):
        # the story of a block is written a moment after it happens; an
        # export taken in that moment would leave the last line out
        self.flush(3.0)
        with self.lock:
            rows = [dict(r) for r in self.db.execute('SELECT * FROM blocked ORDER BY since')]
            ended = [dict(r) for r in self.db.execute('SELECT * FROM blocked_log ORDER BY ts')]
            events = [dict(r) for r in self.db.execute('SELECT * FROM block_events ORDER BY ts')]
            folds = [dict(r) for r in self.db.execute('SELECT * FROM fold_versions ORDER BY id')]
            notes = {r['key']: r['value'] for r in self.db.execute(
                "SELECT key, value FROM meta WHERE substr(key, 1, 8) = 'blocked_' "
                "OR substr(key, 1, 10) = 'ids_about_'")}
        return {'blocked': rows, 'ended': ended, 'events': events, 'folds': folds, 'notes': notes}

    def ban_import(self, data):
        """Put an exported list back, added to what is here rather than over
        it: an address kept out on this machine since the file was written
        stays kept out, and a line of history already here is not written
        twice. Returns how many of each were added."""
        if not isinstance(data, dict):
            return {}
        added = {'blocked': 0, 'ended': 0, 'events': 0, 'folds': 0, 'notes': 0}
        now = time.time()

        def num(x, default=None):
            try:
                return float(x)
            except (TypeError, ValueError):
                return default
        with self.lock:
            for r in data.get('blocked') or []:
                if not isinstance(r, dict) or not r.get('ip'):
                    continue
                until = num(r.get('until'))
                if until and until < now:
                    continue                 # its time ran out while the server was gone
                cur = self.db.execute(
                    'INSERT OR IGNORE INTO blocked (ip, since, until, why, hits, auto, by) '
                    'VALUES (?,?,?,?,?,?,?)',
                    (str(r['ip'])[:64], num(r.get('since'), now), until, str(r.get('why') or '')[:200],
                     int(num(r.get('hits'), 0)), 1 if r.get('auto', 1) else 0, str(r.get('by') or '')[:60]))
                added['blocked'] += cur.rowcount or 0
            for key, table, cols in (
                    ('ended', 'blocked_log', ('ts', 'ended', 'ip', 'why', 'how', 'auto', 'hits', 'by')),
                    ('events', 'block_events', ('ts', 'ip', 'what', 'why', 'auto', 'by'))):
                # one line of history is the moment, the address and what
                # happened (how it ended, for the log)
                third = 'how' if table == 'blocked_log' else 'what'
                have = {(round(float(x['ts']), 3), x['ip'], x[third] or '') for x in
                        self.db.execute('SELECT ts, ip, %s FROM %s' % (third, table))}
                for r in data.get(key) or []:
                    if not isinstance(r, dict) or not r.get('ip') or num(r.get('ts')) is None:
                        continue
                    mark = (round(float(r['ts']), 3), str(r['ip']), str(r.get(third) or ''))
                    if mark in have:
                        continue
                    have.add(mark)
                    self.db.execute('INSERT INTO %s (%s) VALUES (%s)' % (table, ', '.join(cols),
                                                                     ', '.join('?' * len(cols))),
                                    tuple(r.get(c) for c in cols))
                    added[key] += 1
            stamps = {round(float(x['ts']), 3) for x in self.db.execute('SELECT ts FROM fold_versions')}
            for r in data.get('folds') or []:
                if not isinstance(r, dict) or num(r.get('ts')) is None or round(float(r['ts']), 3) in stamps:
                    continue
                groups = r.get('groups')
                self.db.execute(
                    'INSERT INTO fold_versions (ts, by, widest, before, after, groups, undone, undone_by) '
                    'VALUES (?,?,?,?,?,?,?,?)',
                    (float(r['ts']), r.get('by'), r.get('widest'), r.get('before'), r.get('after'),
                     groups if isinstance(groups, str) else json.dumps(groups or []),
                     r.get('undone'), r.get('undone_by')))
                added['folds'] += 1
            self.db.commit()
        for key, value in (data.get('notes') or {}).items():
            key = str(key)
            if not key.startswith(self.BAN_META) or self.get_meta(key) is not None:
                continue
            self.set_meta(key, str(value))
            added['notes'] += 1
        self._block_changed()
        return added

    def drop_fold_version(self, vid):
        """One record of a fold taken out of the undo history. Only the
        record: the subnets it made stay kept out, and what each was folded
        from stays under it (that is kept per subnet, not here)."""
        with self.lock:
            gone = self.db.execute('DELETE FROM fold_versions WHERE id=?', (int(vid),)).rowcount
            self.db.commit()
        return gone or 0

    def fold_version_undone(self, vid, by=''):
        with self.lock:
            self.db.execute('UPDATE fold_versions SET undone=?, undone_by=? WHERE id=?',
                            (time.time(), str(by or '')[:60], int(vid)))
            self.db.commit()

    def feed_ranges_holding(self, ip, feeds=None):
        """Every list range this address is in, as (list, lo, hi) - the ranges
        themselves, not just the names, so the width of each can be judged."""
        packed, family = pack_address(ip)
        if packed is None:
            return []
        with self.lock:
            rows = self.db.execute(
                'SELECT feed, lo, hi FROM feed_ranges '
                'WHERE family=? AND lo BETWEEN ? AND ? AND hi>=?',
                (family, self._floor_of(packed, family), packed, packed)).fetchall()
        return [(r['feed'], bytes(r['lo']), bytes(r['hi'])) for r in rows
                if feeds is None or r['feed'] in feeds]

    def sweep_expired(self):
        """Every block whose time has run out, taken off and written down.

        It used to happen only when that one address asked for something
        again: nobody asking meant the line sat there for ever saying "0 min",
        while the router had already dropped its own rule by timeout. Swept
        here, so the list says what is true and the history says when it
        stopped being true.
        """
        now = time.time()
        with self.lock:
            gone = [r['ip'] for r in self.db.execute(
                'SELECT ip FROM blocked WHERE until IS NOT NULL AND until < ?', (now,)).fetchall()]
        for ip in gone:
            self.unblock(ip, how='ran out')
        return gone

    def _bulk(self, sql, rows):
        """Many rows written as ONE transaction, under the caller's lock.

        This connection is in autocommit (isolation_level=None), which is what
        lets every small write elsewhere land without a transaction of its
        own - and in autocommit `executemany` commits EVERY ROW separately.
        The house's largest block list is 27,452 ranges, so replacing it was
        27,452 transactions and 27,452 appends to the journal: 709 ms of the
        only lock this database has, while the page waited 940 ms for a
        status it usually gets in 18, and the writer thread sat on a reading
        it had been handed. As one transaction the same rows take 50 ms.

        And the promise the callers make - all of it or none of it - was not
        kept either: a daemon stopped in the middle left half a list, which
        matches half of what it should and tells nobody.
        """
        mine = not self.db.in_transaction
        if mine:
            self.db.execute('BEGIN IMMEDIATE')
        try:
            self.db.executemany(sql, rows)
        except BaseException:
            if mine:
                try:
                    self.db.execute('ROLLBACK')
                except sqlite3.Error:
                    pass
            raise
        if mine:
            self.db.execute('COMMIT')

    def put_feed(self, feed, ranges):
        """Replace one list's ranges with what was just fetched. All or
        nothing: a half-written list quietly stops matching the half that is
        missing, and nobody finds out until somebody gets through."""
        with self.lock:
            mine = not self.db.in_transaction
            if mine:
                self.db.execute('BEGIN IMMEDIATE')   # the delete and the rows together, or not at all
            try:
                self.db.execute('DELETE FROM feed_ranges WHERE feed=?', (feed,))
                self.db.executemany(
                    'INSERT INTO feed_ranges (feed, lo, hi, family) VALUES (?,?,?,?)',
                    [(feed, lo, hi, fam) for lo, hi, fam in ranges])
            except BaseException:
                if mine:
                    try:
                        self.db.execute('ROLLBACK')
                    except sqlite3.Error:
                        pass
                raise
            if mine:
                self.db.execute('COMMIT')
            self._feed_counts = None
        return len(ranges)

    def put_geo(self, rows):
        """Replace the country list with what was just fetched.

        Seven hundred thousand rows in one transaction holds the only lock
        this database has for as long as it takes to write them, and
        everything else - the status the page asks for twice a second, the
        charts, the writing down of readings - waits behind it. So it goes in
        in thousands, and the lock is let go between them: a little slower in
        all, and nothing else notices it happening.
        """
        step = 5000
        with self.lock:
            self.db.execute('DELETE FROM geo_ranges')
            self.db.commit()
            self._geo_count = 0
        for at in range(0, len(rows), step):
            with self.lock:
                self._bulk('INSERT INTO geo_ranges (lo, hi, family, cc) VALUES (?,?,?,?)',
                           rows[at:at + step])
                self._geo_count = None
            # A breath that is actually a breath. sleep(0) yields nothing a
            # waiting thread can use: a lock just released is handed to
            # whichever thread the system wakes, and this one - already
            # running, already holding the interpreter - took it again and
            # again. Through seven hundred thousand rows the lock was held
            # 85% of eighteen seconds, and the page asking twice a second
            # saw it.
            time.sleep(0.005)
        with self.lock:
            self._geo_count = len(rows)
        return len(rows)

    def geo_size(self):
        """How many country ranges are held.

        Counted once and remembered. Nothing but put_geo changes this table,
        and put_geo forgets the count, so the remembered number is the true
        one. It matters because the page asks for the status twice a second
        and this count was a walk of seven hundred thousand rows each time,
        holding the one lock the whole database has while it walked.
        """
        got = self._geo_count
        if got is not None:
            return got
        with self.lock:
            if self._geo_count is None:
                row = self.db.execute('SELECT COUNT(*) AS n FROM geo_ranges').fetchone()
                self._geo_count = int(row['n'] or 0) if row else 0
            return self._geo_count

    def country_of(self, ip):
        packed, family = pack_address(ip)
        if packed is None:
            return None
        with self.lock:
            row = self.db.execute(
                'SELECT cc FROM geo_ranges WHERE family=? AND lo BETWEEN ? AND ? AND hi>=? '
                'ORDER BY lo DESC LIMIT 1',
                (family, self._floor_of(packed, family), packed, packed)).fetchone()
        return row['cc'] if row else None

    def feed_sizes(self):
        """How many ranges each list holds. Remembered, for the same reason
        geo_size is: only put_feed changes the table, and it forgets this."""
        got = self._feed_counts
        if got is not None:
            return dict(got)
        with self.lock:
            if self._feed_counts is None:
                rows = self.db.execute(
                    'SELECT feed, COUNT(*) AS n FROM feed_ranges GROUP BY feed').fetchall()
                self._feed_counts = {r['feed']: int(r['n']) for r in rows}
            return dict(self._feed_counts)

    @staticmethod
    def _floor_of(packed, family):
        """The lowest start a range containing this address could have.

        Nothing wider than a /8 (or a /16 in IPv6) is ever taken from a list,
        so a range that contains this address must start within that much of
        it. Without this the lookup walked every range below the address -
        1.5 ms with five lists in, for every line of every log.
        """
        spare = 24 if family == 4 else 112
        value = int.from_bytes(packed, 'big')
        floor = (value >> spare) << spare
        return floor.to_bytes(len(packed), 'big')

    def feeds_with(self, ip, remembered=None):
        """Every list this address is on, not just the first one found. Two
        lists agreeing about an address says more than one does.

        The answer is worth remembering where the caller can: the blocked card
        asks it for every row, twice a second, and a hundred rows is a hundred
        queries for something that changes when a list is fetched and not
        otherwise. Pass a dict and it is kept there.
        """
        if remembered is not None:
            key = str(ip)
            if key not in remembered:
                remembered[key] = self.feeds_with(ip)
            return remembered[key]
        packed, family = pack_address(ip)
        if packed is None:
            return []
        with self.lock:
            rows = self.db.execute(
                'SELECT DISTINCT feed FROM feed_ranges '
                'WHERE family=? AND lo BETWEEN ? AND ? AND hi>=?',
                (family, self._floor_of(packed, family), packed, packed)).fetchall()
        return sorted(r['feed'] for r in rows)

    def in_any_feed(self, ip):
        packed, family = pack_address(ip)
        if packed is None:
            return None
        with self.lock:
            row = self.db.execute(
                'SELECT feed FROM feed_ranges '
                'WHERE family=? AND lo BETWEEN ? AND ? AND hi>=? LIMIT 1',
                (family, self._floor_of(packed, family), packed, packed)).fetchone()
        return row['feed'] if row else None

    def in_feed(self, feed, ip):
        """Whether one named list holds this address - any list may, and the
        first one found is not always the one asked about."""
        packed, family = pack_address(ip)
        if packed is None:
            return False
        with self.lock:
            row = self.db.execute(
                'SELECT 1 FROM feed_ranges WHERE feed=? AND '
                'family=? AND lo BETWEEN ? AND ? AND hi>=? LIMIT 1',
                (str(feed), family, self._floor_of(packed, family), packed, packed)).fetchone()
        return bool(row)

    def keep_proxy_lines(self, rows):
        """Write down what was read, so it can be asked about afterwards.

        In thousands, letting the lock go between them, for the reason put_geo
        gives: a busy hour on the proxy hands this tens of thousands of lines
        at once, and written in one go it held the only lock this database has
        for a fifth of a second - which the page, asking twice a second, sees
        as a stall.
        """
        if not rows:
            return 0
        step = 1000
        for at in range(0, len(rows), step):
            with self.lock:
                self._bulk('INSERT INTO proxy_lines (ts, src, ip, method, path, status, kind) '
                           'VALUES (?,?,?,?,?,?,?)', rows[at:at + step])
            if at + step < len(rows):
                time.sleep(0.005)      # a breath another thread can use; see put_geo
        return len(rows)

    def proxy_lines_forget(self, days):
        """Old lines go. A month is plenty to answer any question worth
        asking about somebody who came knocking."""
        if not days:
            return 0
        with self.lock:
            done = self.db.execute('DELETE FROM proxy_lines WHERE ts < ?',
                                   (time.time() - days * 86400,))
            self.db.commit()
        return done.rowcount or 0

    def paths_in(self, ip, seconds):
        """How many different paths this address has asked for lately, and how
        many lines in all. One address asking for one path a hundred times is
        a watch with a stale shortcut; one asking for a hundred different ones
        is somebody looking for a way in, and no single line says so."""
        with self.lock:
            row = self.db.execute(
                'SELECT COUNT(*) AS n, COUNT(DISTINCT path) AS spread FROM proxy_lines '
                'WHERE ip=? AND ts > ?', (str(ip), time.time() - seconds)).fetchone()
        return (int(row['n'] or 0), int(row['spread'] or 0)) if row else (0, 0)

    def blocked_before(self, ip, within_days=0):
        """How many times this address has been kept out before, from the
        story rather than from a counter - so it survives a restart and can be
        wiped by erasing the history, which is what somebody expects."""
        since = (time.time() - within_days * 86400) if within_days else 0
        with self.lock:
            row = self.db.execute(
                "SELECT COUNT(*) AS n FROM block_events WHERE ip=? AND what='blocked' AND ts>?",
                (str(ip), since)).fetchone()
        return int(row['n'] or 0) if row else 0

    def blocked_history(self, limit=200):
        with self.lock:
            rows = self.db.execute('SELECT * FROM blocked_log ORDER BY ended DESC LIMIT ?',
                                   (max(1, min(int(limit or 200), 2000)),)).fetchall()
        return [dict(r) for r in rows]

    def forget_blocked_history(self):
        with self.lock:
            gone = self.db.execute('DELETE FROM blocked_log').rowcount
            gone += self.db.execute('DELETE FROM block_events').rowcount
            self.db.commit()
        return gone or 0

    def mend_block_story(self):
        """The rows kept before this was a log, read as the two events they
        each stand for, so nothing of what happened is lost."""
        if self.get_meta('block_events_from_log'):
            return 0
        self.set_meta('block_events_from_log', '1')
        with self.lock:
            rows = self.db.execute('SELECT * FROM blocked_log').fetchall()
            for r in rows:
                self.db.execute(
                    'INSERT INTO block_events (ts, ip, what, why, auto, by) VALUES (?,?,?,?,?,?)',
                    (r['ts'], r['ip'], 'blocked', r['why'], r['auto'], r['by'] or ''))
                if r['ended']:
                    self.db.execute(
                        'INSERT INTO block_events (ts, ip, what, why, auto, by) VALUES (?,?,?,?,?,?)',
                        (r['ended'], r['ip'], 'let back in', r['how'],
                         1 if r['how'] == 'ran out' else 0, r['by'] or ''))
            self.db.commit()
        return len(rows)

    def note_block_hit(self, ip):
        self._defer(self._write_block_hit, str(ip))

    def _write_block_hit(self, ip):
        with self.lock:
            self.db.execute('UPDATE blocked SET hits = hits + 1 WHERE ip=?', (ip,))

    def add_event(self, kind, detail='', level='info', device=None, ts=None):
        if callable(self.on_event):
            try:
                self.on_event(kind, detail, level, device)
            except Exception:
                pass
        if kind == 'action' and device and detail:
            known = self._actions_cache.get(device)
            if known is not None and detail not in known:
                self._actions_cache[device] = [detail] + known    # most recent first
            self._last_action[device] = {'action': detail, 'ts': ts or int(time.time())}
        self._defer(self._write_event, kind, detail, level, device, ts or int(time.time()))

    def _write_event(self, kind, detail, level, device, ts):
        with self.lock:
            self.db.execute('INSERT INTO events (ts,device,kind,level,detail) VALUES (?,?,?,?,?)',
                            (ts, device, kind, level, detail))

    def count_events(self, kind, since, starts=''):
        """How many of one kind of the house's own events since a moment,
        counted in the table rather than in the newest page of it."""
        with self.lock:
            row = self.db.execute(
                "SELECT COUNT(*) AS n FROM events WHERE device IS NULL AND kind=? AND ts>=? AND detail LIKE ?",
                (kind, since, str(starts).replace('%', '').replace('_', '') + '%')).fetchone()
        return int(row['n'] or 0) if row else 0

    def events(self, limit=100, device=None, text=None, kind=None, level=None):
        """The newest events, and - when text is given - the newest ones that
        contain it, searched over the whole table rather than over whatever
        was on the page. Case does not matter, as in grep -i, and the words
        may sit in the detail, the device or the kind."""
        where, args = [], []
        if device:
            where.append('device=?')
            args.append(device)
        if kind:
            where.append('kind=?')
            args.append(kind)
        if level:
            where.append("COALESCE(level,'info')=?")
            args.append(level)
        for word in [w for w in str(text or '').split() if w][:4]:
            # every word must appear somewhere in the row, in any order
            where.append('(detail LIKE ? ESCAPE \'\\\' OR device LIKE ? ESCAPE \'\\\' OR kind LIKE ? ESCAPE \'\\\')')
            like = '%' + word.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_') + '%'
            args += [like, like, like]
        sql = 'SELECT * FROM events'
        if where:
            sql += ' WHERE ' + ' AND '.join(where)
        sql += ' ORDER BY ts DESC, id DESC LIMIT ?'
        args.append(int(limit))
        with self.lock:
            rows = self.db.execute(sql, args).fetchall()
        return [dict(r) for r in rows]

    def events_count(self, text=None, kind=None, level=None):
        """How many rows a search matches in the whole table - so the page can
        say "852 of 8 956" rather than "852 of what happened to be loaded".
        Counted in the database rather than by fetching the rows."""
        where, args = [], []
        if kind:
            where.append('kind=?')
            args.append(kind)
        if level:
            where.append("COALESCE(level,'info')=?")
            args.append(level)
        for word in [w for w in str(text or '').split() if w][:4]:
            where.append('(detail LIKE ? ESCAPE \'\\\' OR device LIKE ? ESCAPE \'\\\' OR kind LIKE ? ESCAPE \'\\\')')
            like = '%' + word.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_') + '%'
            args += [like, like, like]
        sql = 'SELECT COUNT(*) FROM events' + (' WHERE ' + ' AND '.join(where) if where else '')
        if not where:
            # "of how many altogether" is asked again on every keystroke of a
            # search, and counting a table kept for two years is a full scan
            # under the one lock every reader needs. It changes by a handful a
            # minute; half a minute old is close enough to say "of 8 956".
            got = getattr(self, '_events_total', None)
            if got and time.time() - got[0] < 30:
                return got[1]
        with self.lock:
            n = int(self.db.execute(sql, args).fetchone()[0])
        if not where:
            self._events_total = (time.time(), n)
        return n

    def events_since(self, when):
        """How many events there have been since a moment.

        Counted in the database. {events_today} once counted how many of the
        newest four hundred rows were inside the day, so a busy day - a
        thunderstorm, a device flapping - reported four hundred and stopped,
        and it cost half a millisecond of fetching every time a message was
        previewed."""
        with self.lock:
            row = self.db.execute('SELECT COUNT(*) AS n FROM events WHERE ts >= ?',
                                  (float(when),)).fetchone()
        return int((row or {'n': 0})['n'] or 0)

    # -- maintenance: check, optimise, back up, restore -------------------------
    _latency_cache = (0.0, None)

    def latency(self):
        """Round-trip of a trivial read and a trivial write, in milliseconds.
        Measured at most every 15 s: the probe is a real commit under the
        store lock, and /api/health is polled on every refresh of the
        Control tab - nothing that automations should ever queue behind."""
        at, cached = self._latency_cache
        if cached is not None and time.time() - at < 15:
            return cached
        if not self.lock.acquire(timeout=0.05):
            # busy with something long: the last figures are far better than
            # holding up the page that asked for them
            return cached if cached is not None else {'read_ms': None, 'write_ms': None}
        try:
            t0 = time.perf_counter()
            self.db.execute('SELECT value FROM meta WHERE key=?', ('schema',)).fetchone()
            read_ms = (time.perf_counter() - t0) * 1000
            t0 = time.perf_counter()
            stamp = str(int(time.time()))
            self.db.execute('INSERT OR REPLACE INTO meta (key, value) VALUES (?, ?)', ('_latency_probe', stamp))
            self.db.commit()
            self._meta_raw['_latency_probe'] = stamp     # see _warm_meta: memory holds every row
            write_ms = (time.perf_counter() - t0) * 1000
        finally:
            self.lock.release()
        result = {'read_ms': round(read_ms, 2), 'write_ms': round(write_ms, 2)}
        self._latency_cache = (time.time(), result)
        return result

    def integrity_check(self):
        with self.lock:
            rows = self.db.execute('PRAGMA integrity_check').fetchall()
            fk = self.db.execute('PRAGMA foreign_key_check').fetchall()
        lines = [r[0] for r in rows]
        ok = lines == ['ok'] and not fk
        return {'ok': ok, 'lines': lines[:20], 'foreign_key_problems': len(fk)}

    def stale_data(self):
        """What is recorded for devices the dashboard no longer shows: ones
        marked removed, and any left behind with no device row at all. A
        rename leaves the old name's history here, and it adds up."""
        with self.lock:
            known = {r['id']: dict(r) for r in
                     self.db.execute('SELECT id, name, alias, removed, last_seen FROM devices')}
            counts = {}
            for table in ('samples', 'samples_hourly', 'events', 'snapshots'):
                for r in self.db.execute(
                        'SELECT device, COUNT(*) n FROM %s WHERE device IS NOT NULL GROUP BY device' % table):
                    if r['device'] in known and not known[r['device']]['removed']:
                        continue
                    entry = counts.setdefault(r['device'], {'device': r['device'], 'rows': 0})
                    entry[table] = r['n']
                    entry['rows'] += r['n']
        out = []
        for device_id, entry in counts.items():
            row = known.get(device_id)
            entry['name'] = (row.get('alias') or row.get('name')) if row else device_id
            entry['reason'] = 'removed' if row else 'no device record'
            entry['last_seen'] = row.get('last_seen') if row else None
            out.append(entry)
        out.sort(key=lambda x: -x['rows'])
        return {'devices': out, 'rows': sum(x['rows'] for x in out)}

    def drop_stale(self, only=None):
        """Erase what stale_data() found, or one device from it."""
        found = self.stale_data()['devices']
        wanted = [x for x in found if only is None or x['device'] == only]
        removed = 0
        with self.lock:
            for entry in wanted:
                for table in ('samples', 'samples_hourly', 'events', 'snapshots'):
                    cur = self.db.execute('DELETE FROM %s WHERE device=?' % table, (entry['device'],))
                    removed += cur.rowcount if cur.rowcount and cur.rowcount > 0 else 0
                self.db.execute('DELETE FROM devices WHERE id=? AND removed=1', (entry['device'],))
            self.db.commit()
        self._forget_device()
        self._snap_cache.clear()
        self._actions_cache.clear()
        self._last_action.clear()
        self.last_sample.clear()
        self.last_written.clear()
        self._meta_raw.clear()
        self._meta_complete = False
        self.devices(include_removed=True)
        self._warm_meta()
        self._warm_actions()
        self._stats_cache = None
        before = self.stats().get('bytes') or 0
        try:
            # under the lock, as every use of the shared connection: run bare,
            # it ran beside the writer thread's own statements on it
            with self.lock:
                self.db.execute('VACUUM')
                self.db.execute('PRAGMA wal_checkpoint(TRUNCATE)')
        except sqlite3.OperationalError:
            pass
        self._stats_cache = None
        return {'devices': len(wanted), 'rows': removed, 'ids': [x['device'] for x in wanted],
                'before_bytes': before, 'after_bytes': self.stats().get('bytes') or 0}

    def prune(self, apply=False):
        """Throw away readings that were never worth keeping: the hardware's
        bookkeeping keys, and gateway values written again unchanged. Counts
        what it would remove unless asked to actually do it."""
        noise = flat = 0
        with self.lock:
            for table in ('samples', 'samples_hourly'):
                for row in self.db.execute('SELECT DISTINCT key FROM %s' % table).fetchall():
                    key = row[0] or ''
                    if not NOISE_KEY.search(key):
                        continue
                    noise += self.db.execute('SELECT COUNT(*) FROM %s WHERE key=?' % table,
                                             (key,)).fetchone()[0]
                    if apply:
                        self.db.execute('DELETE FROM %s WHERE key=?' % table, (key,))
            # The same value stored over and over - by a gateway poll, by a
            # plug's own counters, by a modem reporting its IMEI every few
            # seconds. On a real house a fortnight old this was eighteen per
            # cent of the whole database: seven hundred thousand rows saying
            # what the row before them said. Every series is looked at now,
            # not only the gateway's, and a run of identical values keeps its
            # first and its last - which is what a flat line on a chart is
            # made of - plus one anchor every so often so a long flat stretch
            # still has points in it.
            pairs = self.db.execute(
                "SELECT DISTINCT device, key FROM samples").fetchall()
            for device, key in [(r[0], r[1]) for r in pairs]:
                if NOISE_KEY.search(key):
                    continue
                drop, last = [], None
                for r in self.db.execute(
                        'SELECT ts, value FROM samples WHERE device=? AND key=? ORDER BY ts',
                        (device, key)):
                    if last is not None and r[1] == last[0] and r[0] - last[1] < GATEWAY_ANCHOR_S:
                        drop.append(r[0])
                    else:
                        last = (r[1], r[0])
                flat += len(drop)
                if apply and drop:
                    for i in range(0, len(drop), 400):
                        chunk = drop[i:i + 400]
                        self.db.execute(
                            'DELETE FROM samples WHERE device=? AND key=? AND ts IN (%s)'
                            % ','.join('?' * len(chunk)), [device, key] + chunk)
            if apply:
                self.db.commit()
        before = self.stats().get('bytes') or 0
        if apply:
            self._stats_cache = None
            try:
                with self.lock:            # the shared connection, as everywhere
                    self.db.execute('VACUUM')
                    # fold the write-ahead log back in, or the file still looks
                    # every bit as big as it was
                    self.db.execute('PRAGMA wal_checkpoint(TRUNCATE)')
            except sqlite3.OperationalError:
                pass
        after = (self.stats().get('bytes') or 0) if apply else before
        return {'bookkeeping_rows': noise, 'repeated_rows': flat, 'applied': bool(apply),
                'before_bytes': before, 'after_bytes': after}

    def optimize(self):
        self.flush()
        before = db_path().stat().st_size if db_path().exists() else 0
        t0 = time.time()
        with self.lock:
            self.db.execute('PRAGMA optimize')
            self.db.execute('ANALYZE')
            self.db.commit()
            self.db.execute('VACUUM')
            self.db.execute('PRAGMA wal_checkpoint(TRUNCATE)')
        self._stats_cache = None
        after = db_path().stat().st_size if db_path().exists() else 0
        return {'before_bytes': before, 'after_bytes': after, 'seconds': round(time.time() - t0, 2)}

    def backup_to(self, target):
        """A consistent copy through SQLite's online backup API - safe while
        the daemon keeps writing."""
        import sqlite3
        self.flush()
        with self.lock:
            dest = sqlite3.connect(str(target))
            try:
                self.db.backup(dest)
            finally:
                dest.close()
        return target.stat().st_size

    def restore_from(self, source):
        """Replace the live database's contents with a backup's, in place:
        the file stays open, callers keep their connection, the daemon's
        in-memory state re-syncs from the next poll and report."""
        import sqlite3
        self.flush(5.0)
        self._wq.clear()                     # anything still queued belongs to the replaced contents
        # The copies in memory stay in force while the pages are copied, and
        # are swapped for the restored ones after (below). Cleared here, every
        # reader - the broker thread recording a report, the rule workers
        # reading the rules - missed them and queued on the lock for the
        # whole copy: a light five seconds late for every restore.
        self.last_sample.clear()             # what was written last belongs to the old contents
        self.last_written.clear()
        self._dev_list = None
        self._stats_cache = None
        # read-only, by URI: a file that is not there is an error, never a
        # new empty database copied over the live one
        # The accounts and who is signed in stay as they are (5.19): putting
        # the house back is not putting back who may sign in to it - a backup
        # from before 5.19 has none at all, one from last month an old
        # password - and whoever is restoring stays signed in.
        try:
            keep_accounts, keep_signins = self.accounts_all(), self.signins_all()
        except sqlite3.Error as e:
            keep_accounts, keep_signins = None, None
            log('the accounts could not be read before the database was put back (%s): it brings '
                'its own' % e, 'warn')
        src = sqlite3.connect('file:%s?mode=ro' % quote(str(source)), uri=True)
        try:
            with self.lock:
                src.backup(self.db)
                self.db.commit()
                # read while the lock is still held (the first read after the
                # copy builds the WAL index - a second on a big database) and
                # put in place in one go
                # (a backup from an older version may lack a table: then
                # nothing of it in memory, and nothing taken as complete)
                meta_ok = True
                try:
                    meta = {r['key']: r['value'] for r in self.db.execute('SELECT key, value FROM meta')}
                except sqlite3.Error:
                    meta, meta_ok = {}, False
                snaps = {}
                try:
                    snap_rows = self.db.execute('SELECT device, payload, availability FROM snapshots').fetchall()
                except sqlite3.Error:
                    snap_rows = []
                for r in snap_rows:
                    try:
                        snaps[r['device']] = (json.loads(r['payload'] or '{}'), r['availability'])
                    except ValueError:
                        snaps[r['device']] = ({}, r['availability'])
                self._meta_raw, self._meta_cache, self._meta_complete = meta, {}, meta_ok
                self._snap_cache = snaps
                self._actions_cache, self._last_action = {}, {}
                self._dev_cache, self._dev_list = {}, None
                self._warm_devices()
        finally:
            src.close()
        if keep_accounts is not None:
            with self.lock:
                self.db.executescript(SCHEMA_ACCOUNTS)
            self.accounts_mend()
            with self.lock:
                self.db.execute('DELETE FROM accounts')
                self.db.execute('DELETE FROM signins')
            for row in keep_accounts:
                self.account_put(row)
            for row in keep_signins:
                self.signin_put(row)
        # the restored contents, read into memory in one go - the settings in
        # them are in force from this moment, not from the next restart.
        # The parsed lists are dropped AGAIN here, after the copy: they were
        # dropped only before it, and a reader in between (a report reading
        # the rules) put the old list straight back, where it stayed - the
        # raw settings said the restored rules and the rules in force were
        # the ones from before the restore.
        self._meta_cache.clear()

    def counter_delta(self, device_id, key, t0, t1):
        """How much a monotonic counter grew between two times: the sum of its
        positive steps, so a counter reset in between does not go negative."""
        with self.lock:
            rows = self.db.execute('SELECT ts, value FROM samples WHERE device=? AND key=? AND ts BETWEEN ? AND ? '
                                   'ORDER BY ts', (device_id, key, int(t0), int(t1))).fetchall()
            if len(rows) < 2:
                rows = self.db.execute('SELECT ts, avg AS value FROM samples_hourly WHERE device=? AND key=? '
                                       'AND ts BETWEEN ? AND ? ORDER BY ts',
                                       (device_id, key, int(t0), int(t1))).fetchall()
        total = 0.0
        previous = None
        for row in rows:
            value = row['value']
            if value is None:
                continue
            if previous is not None and value > previous:
                total += value - previous
            previous = value
        return round(total, 2)

    def last_action(self, device_id):
        """The most recent action this device sent, with when. Read for every
        button on every refresh, and we are the ones who record it, so the
        answer is kept in memory and updated as the actions come in."""
        if device_id in self._last_action:
            return dict(self._last_action[device_id]) if self._last_action[device_id] else None
        with self.lock:
            r = self.db.execute("SELECT detail, ts FROM events WHERE device=? AND kind='action' "
                                "ORDER BY ts DESC LIMIT 1", (device_id,)).fetchone()
        found = {'action': r['detail'], 'ts': r['ts']} if r else None
        self._last_action[device_id] = found
        return dict(found) if found else None

    def actions_seen(self, device_id):
        """Every distinct action this device has ever reported, most recent
        first. Asked for every button on every dashboard refresh, and it only
        changes when a button reports something it never reported before."""
        cached = self._actions_cache.get(device_id)
        if cached is not None:
            return list(cached)
        with self.lock:
            rows = self.db.execute("SELECT detail, MAX(ts) AS ts FROM events WHERE device=? AND kind='action' "
                                   "GROUP BY detail ORDER BY ts DESC", (device_id,)).fetchall()
        seen = [r['detail'] for r in rows if r['detail']]
        self._actions_cache[device_id] = seen
        return list(seen)

    # -- meta -----------------------------------------------------------------
    # -- the accounts of the dashboard and their sign-ins (5.19) --------------
    # Read once into the daemon's memory and written through here: a request
    # is answered from memory, never from under the database lock.
    def accounts_all(self):
        with self.lock:
            return [dict(r) for r in self.db.execute('SELECT * FROM accounts ORDER BY name')]

    def accounts_mend(self):
        """The two columns 5.19.1 added (a PIN account and the length of its
        PIN), on a table 5.19.0 made."""
        with self.lock:
            for col in ("kind TEXT DEFAULT 'password'", 'pin_len INTEGER DEFAULT 0'):
                try:
                    self.db.execute('ALTER TABLE accounts ADD COLUMN ' + col)
                except sqlite3.OperationalError:
                    pass                    # already there

    def account_put(self, row):
        with self.lock:
            self.db.execute(
                'INSERT OR REPLACE INTO accounts (name, role, pw, disabled, must_change, note, '
                'created, last_in, last_from, kind, pin_len) VALUES (?,?,?,?,?,?,?,?,?,?,?)',
                (row['name'], row['role'], row['pw'], int(bool(row.get('disabled'))),
                 int(bool(row.get('must_change'))), str(row.get('note') or '')[:300],
                 row.get('created'), row.get('last_in'), str(row.get('last_from') or '')[:60],
                 row.get('kind') or 'password', int(row.get('pin_len') or 0)))

    def account_delete(self, name):
        with self.lock:
            self.db.execute('DELETE FROM accounts WHERE name = ?', (name,))
            self.db.execute('DELETE FROM signins WHERE name = ?', (name,))

    def signins_all(self):
        with self.lock:
            return [dict(r) for r in self.db.execute('SELECT * FROM signins')]

    def signin_put(self, row):
        with self.lock:
            self.db.execute('INSERT OR REPLACE INTO signins (token_hash, name, created, last, expires, '
                            'ip, agent) VALUES (?,?,?,?,?,?,?)',
                            (row['token_hash'], row['name'], row['created'], row['last'],
                             row['expires'], str(row.get('ip') or '')[:60],
                             str(row.get('agent') or '')[:120]))

    def signin_drop(self, token_hash):
        with self.lock:
            self.db.execute('DELETE FROM signins WHERE token_hash = ?', (token_hash,))

    def signin_touch(self, token_hash, last):
        with self.lock:
            self.db.execute('UPDATE signins SET last = ? WHERE token_hash = ?', (int(last), token_hash))

    def get_meta(self, key, default=None):
        """Small settings read on the dashboard path (a plug's counter reset
        stamp, for one), so the value is kept rather than fetched each time."""
        if key in self._meta_raw:
            value = self._meta_raw[key]
            return value if value is not None else default
        if getattr(self, '_meta_complete', False):
            self._meta_raw[key] = None       # the warm read every row; this one is not there
            return default
        with self.lock:
            r = self.db.execute('SELECT value FROM meta WHERE key=?', (key,)).fetchone()
        value = r['value'] if r else None
        self._meta_raw[key] = value
        return value if value is not None else default

    def _defer(self, fn, *args):
        """Run a write later, in order, on the writer thread."""
        # a pathological backlog: keep the newest. 20,000 was half a minute of
        # a busy house's readings - less than the nightly VACUUM holds the
        # database for, and the readings of that half minute were dropped
        if len(self._wq) > 200000:
            try:
                self._wq.popleft()
            except IndexError:
                pass
        self._wq_idle.clear()
        self._wq.append((fn, args))
        self._wq_wake.set()

    def _writer_loop(self):
        while True:
            self._wq_wake.wait(0.5)
            self._wq_wake.clear()
            drained = False
            while True:
                try:
                    fn, args = self._wq.popleft()
                except IndexError:
                    break
                drained = True
                try:
                    fn(*args)
                except Exception as e:
                    try:
                        log('deferred write failed: %s' % e, 'error')
                    except Exception:
                        pass
            if drained or not self._wq:
                self._wq_idle.set()

    def flush(self, timeout=30.0):
        """Wait for the queued writes to land - before a backup or a VACUUM,
        so what they capture is everything that has happened."""
        self._wq_wake.set()
        deadline = time.time() + timeout
        while self._wq and time.time() < deadline:
            self._wq_idle.wait(0.05)
        return not self._wq

    def set_meta(self, key, value, deferred=False):
        """The in-memory copy is updated at once and every reader sees it; the
        row itself lands under the lock. Callers on the message path pass
        deferred=True and the write joins the queue instead, because a
        critical alert or a hand-taking-over must not stand behind a VACUUM
        for the best part of a second."""
        self._meta_raw[key] = str(value)
        if deferred:
            self._defer(self._write_meta, key, str(value))
        else:
            self._write_meta(key, str(value))
        # refresh rather than drop: a dropped cache means the next button press
        # goes to the database, and that press may land during a VACUUM
        try:
            data = json.loads(value) if isinstance(value, str) and value[:1] in '[{' else None
        except ValueError:
            data = None
        if isinstance(data, list):
            self._meta_cache[key] = [x for x in data if isinstance(x, dict)]
        else:
            self._meta_cache.pop(key, None)

    def _write_meta(self, key, value):
        with self.lock:
            self.db.execute('INSERT OR REPLACE INTO meta (key,value) VALUES (?,?)', (key, value))

    def forget_meta(self, key):
        """A note that no longer applies: gone from memory, out of the queue,
        and out of the table.

        Deleting the row alone left the in-memory copy standing, and every
        reader goes to that first. Worse, a write of that very key could be
        sitting in the deferred queue - Suricata writes its note that way -
        and it landed AFTER the delete, so the old note came back and the
        next restart showed September's rule against December's block. The
        delete joins the same queue, in order, so whatever was already in it
        for this key is overtaken rather than racing.

        And it is remembered as gone rather than simply dropped from memory.
        Dropping it sent the next reader to the table - where the row is still
        standing, because the delete is in the queue behind it - and the old
        note was read from there and cached again. September's list name came
        back against December's block that way, for as long as the queue took
        to drain, and a page or a text asked for in that moment carried it.
        `None` is what get_meta already reads as "there is nothing here".
        """
        self._meta_raw[key] = None
        self._meta_cache.pop(key, None)
        self._defer(self._delete_meta, key)

    def _delete_meta(self, key):
        with self.lock:
            self.db.execute('DELETE FROM meta WHERE key=?', (key,))

    def meta_json(self, key):
        """A config list (bindings, rules, scenes...) parsed once and kept in
        memory. These are read on EVERY incoming message to decide what to
        fire; going to the database each time put the automation path behind
        the same lock a VACUUM or an online backup holds for seconds."""
        cached = self._meta_cache.get(key)
        if cached is not None:
            return cached
        raw = self.get_meta(key)
        try:
            data = json.loads(raw) if raw else []
        except ValueError:
            data = []
        data = [x for x in data if isinstance(x, dict)]
        self._meta_cache[key] = data
        return data

    # -- housekeeping ---------------------------------------------------------
    def aggregate(self):
        """Roll full-resolution rows older than two hours into hourly buckets."""
        now = int(time.time())
        cutoff = (now // 3600) * 3600 - 7200
        done = 0
        with self.lock:
            r = self.db.execute("SELECT value FROM meta WHERE key='aggregated_to'").fetchone()
            start = int(r['value']) if r else 0
            if start >= cutoff:
                return 0
            self.db.execute('BEGIN')
            try:
                cur = self.db.execute(
                    'INSERT OR REPLACE INTO samples_hourly (ts,device,key,n,avg,min,max) '
                    'SELECT (ts/3600)*3600, device, key, COUNT(*), AVG(value), MIN(value), MAX(value) '
                    'FROM samples WHERE ts>=? AND ts<? GROUP BY device, key, ts/3600',
                    (start, cutoff))
                done = cur.rowcount if cur.rowcount is not None else 0
                self.db.execute("INSERT OR REPLACE INTO meta (key,value) VALUES ('aggregated_to',?)",
                                (str(cutoff),))
                self._meta_raw['aggregated_to'] = str(cutoff)   # see _warm_meta
                full_days = int(CONFIG.get('retain_full_days', 14))
                hourly_days = int(CONFIG.get('retain_hourly_days', 730))
                event_days = int(CONFIG.get('retain_events_days', 730))
                self.db.execute('DELETE FROM samples WHERE ts<?', (now - full_days * 86400,))
                self.db.execute('DELETE FROM samples_hourly WHERE ts<?', (now - hourly_days * 86400,))
                self.db.execute('DELETE FROM events WHERE ts<?', (now - event_days * 86400,))
                # The two that came with the one-tap roads. Nothing trimmed
                # them: a link open to the internet writes a line for every
                # press and every refusal, and a year of that is a table
                # nobody asked for and a database that only grows.
                press_days = int(CONFIG.get('retain_presses_days', 180))
                self.db.execute('DELETE FROM taps_log WHERE ts<?', (now - press_days * 86400,))
                self.db.execute('DELETE FROM block_events WHERE ts<?', (now - press_days * 86400,))
                # What was kept ABOUT an address - which list knew it, what
                # Suricata said - is two rows apiece, written for every alert
                # and not only for a block, and nothing ever took them away.
                # Three hundred addresses is six hundred rows; a busy week is
                # thousands, every one of them held in memory as well. They go
                # when the address is neither on the list nor anywhere in the
                # history, which is exactly when nothing can ask about it.
                still = set()
                for row in self.db.execute('SELECT ip FROM blocked'):
                    still.add(str(row[0]))
                for row in self.db.execute('SELECT DISTINCT ip FROM block_events'):
                    still.add(str(row[0]))
                stale = []
                for row in self.db.execute(
                        "SELECT key FROM meta WHERE key LIKE 'blocked!_%' ESCAPE '!' "
                        "OR key LIKE 'ids!_about!_%' ESCAPE '!'"):
                    key = str(row[0])
                    who = key.split('_', 2)[-1]
                    if who and who not in still:
                        stale.append((key,))
                if stale:
                    self.db.executemany('DELETE FROM meta WHERE key=?', stale)
                    for key, in stale:
                        self._meta_raw[key] = None      # gone, and known to be gone: see _warm_meta
                    log('%d thing(s) kept about addresses nobody remembers, forgotten' % len(stale),
                        'debug')
                self.db.execute('DELETE FROM blocked_log WHERE ts<?', (now - press_days * 86400,))
                self.db.execute('COMMIT')
            except Exception:
                self.db.execute('ROLLBACK')
                raise
        return done

    def forget_devices(self, ids):
        """Take a handful of devices out in one go. reset('device') is the
        thorough version, with a vacuum behind it; this is for housekeeping,
        where a hundred of them at once must not stop the world."""
        ids = [str(i) for i in ids]
        if not ids:
            return 0
        marks = ','.join('?' for _ in ids)
        with self.lock:
            for table in ('samples', 'samples_hourly', 'events', 'snapshots'):
                self.db.execute('DELETE FROM %s WHERE device IN (%s)' % (table, marks), ids)
            self.db.execute('DELETE FROM devices WHERE id IN (%s)' % marks, ids)
            self.db.commit()
        gone = set(ids)
        for device_id in ids:
            self._snap_cache.pop(device_id, None)
        # kept by (device, key): popped by the device alone, nothing went, and
        # a device back within the sample interval had its next reading
        # "updated" into a row that no longer existed - and lost
        for memo in (self.last_sample, self.last_written):
            for k in [k for k in list(memo) if isinstance(k, tuple) and k and k[0] in gone]:
                memo.pop(k, None)
        self._forget_device()          # the device list is read fresh anyway
        return len(ids)

    def reset(self, scope, device_id=None):
        """Erase recorded data. scope: all, history, events, device."""
        with self.lock:
            if scope == 'all':
                for table in ('samples', 'samples_hourly', 'events', 'snapshots'):
                    self.db.execute('DELETE FROM %s' % table)
                self.db.execute("DELETE FROM meta WHERE key NOT IN ('bindings', 'pin_account_made')")
                self.db.execute('DELETE FROM devices')
            elif scope == 'history':
                for table in ('samples', 'samples_hourly'):
                    self.db.execute('DELETE FROM %s' % table)
                self.db.execute("DELETE FROM meta WHERE key='aggregated_to'")
            elif scope == 'events':
                self.db.execute('DELETE FROM events')
            elif scope == 'device' and device_id:
                for table in ('samples', 'samples_hourly', 'events', 'snapshots'):
                    self.db.execute('DELETE FROM %s WHERE device=?' % table, (device_id,))
                self.db.execute('DELETE FROM devices WHERE id=?', (device_id,))
            else:
                raise ValueError('unknown scope %r' % scope)
            self.last_sample.clear()
            self.last_written.clear()      # or a flat series is not written again for a quarter of an hour
        self._forget_device()            # rows and whole tables just went away
        self._stats_cache = None         # the counts changed; refreshed below, before the VACUUM
        if scope == 'device' and device_id:
            for cache in (self._snap_cache, self._actions_cache, self._last_action):
                cache.pop(device_id, None)   # only this one went away
        else:
            self._snap_cache.clear()
            self._actions_cache.clear()
            self._last_action.clear()
        if scope in ('all', 'history'):
            self._meta_cache.clear()         # only those scopes touch meta rows
            self._meta_raw.clear()
            self._meta_complete = False      # the table was emptied under us; see _warm_meta
        # Everything the dashboard reads must be back in memory BEFORE the
        # VACUUM starts: behind it, a first read waits for the whole thing.
        self.devices(include_removed=True)   # also fills the list the warm below needs
        self._warm_meta()
        if scope != 'device':
            self._warm_actions()
        self.stats(wait=True)            # the header's counts, while the file is still free
        try:
            self.db.execute('VACUUM')
            self.db.execute('PRAGMA wal_checkpoint(TRUNCATE)')   # or the file still looks as big
        except sqlite3.OperationalError:
            pass
        self._stats_cache = None

    def _count_rows(self):
        """The row counts for stats(), read on a connection that only reads.
        Where one cannot be opened, counted as before, under the lock."""
        sql = [('devices', 'SELECT COUNT(*) FROM devices'), ('samples', 'SELECT COUNT(*) FROM samples'),
               ('samples_hourly', 'SELECT COUNT(*) FROM samples_hourly'),
               ('events', 'SELECT COUNT(*) FROM events'), ('snapshots', 'SELECT COUNT(*) FROM snapshots')]
        # opened for the counting and closed straight after, so nothing is
        # left holding the file while a VACUUM, a restore or a checkpoint
        # wants it to itself; once every thirty seconds costs a millisecond
        out = {}

        def oldest_of(ask):
            """How far back the readings go, without reading the lot.

            `samples` has no index on ts of its own - its key is
            (device, key, ts) - so MIN(ts) over it is a walk of the whole
            table: 83 ms warm, 102 ms cold here, 270 MB off the disk on the
            house itself. The hourly table carries the same history folded up
            and is indexed on ts, so its oldest row is the answer in a
            microsecond. Only a house that has never folded has none, and
            there `samples` is small enough to walk."""
            a = ask('SELECT MIN(ts) FROM samples_hourly').fetchone()[0]
            if a:
                return a
            return ask('SELECT MIN(ts) FROM samples').fetchone()[0]

        try:
            from urllib.parse import quote as _q
            reader = sqlite3.connect('file:%s?mode=ro' % _q(str(self.path)), uri=True, timeout=5)
            try:
                for name, q in sql:
                    out[name] = reader.execute(q).fetchone()[0]
                out['oldest'] = oldest_of(reader.execute)
            finally:
                reader.close()
            return out
        except sqlite3.Error:
            out = {}
        with self.lock:
            for name, q in sql:
                out[name] = self.db.execute(q).fetchone()[0]
            out['oldest'] = oldest_of(self.db.execute)
        return out

    def _stats_sizes(self, out):
        """The file's size, which is three stat() calls and no reading."""
        try:
            size = self.path.stat().st_size
            wal = self.path.with_name(self.path.name + '-wal')
            wal_size = wal.stat().st_size if wal.exists() else 0
            out['bytes'] = size + wal_size
            out['file_bytes'] = size
            out['wal_bytes'] = wal_size
        except OSError:
            out['bytes'] = out['file_bytes'] = out['wal_bytes'] = None
        out['path'] = str(self.path)
        return out

    def _stats_count_now(self):
        """Count, remember, and write the figures down for the next restart."""
        out = self._stats_sizes(self._count_rows())
        self._stats_cache = (time.time(), out)
        if time.time() - getattr(self, '_stats_written', 0) > 300:
            self._stats_written = time.time()
            try:
                self.set_meta('row_counts', json.dumps(
                    {k: out.get(k) for k in ('devices', 'samples', 'samples_hourly',
                                             'events', 'snapshots', 'oldest')}))
            except Exception:
                pass                          # a figure on a card is not worth an exception
        return out

    def stats(self, wait=False):
        """Row counts for the dashboard header, never counted on the thread
        that asks.

        `samples` is WITHOUT ROWID and keyed (device, key, ts), so counting it
        is a walk of the whole table - 270 MB on the house, which off a cold
        disk is a second and a half. /api/health carries these figures and is
        asked for on every refresh, so that second and a half was the first
        thing the dashboard did after a restart, and `zigmon check` reported
        the daemon as answering in 1592 ms because of it.

        So: the figures are counted on a thread of their own and kept for half
        a minute; whoever asks gets what is in hand - the last count, or the
        one this daemon wrote down before it was restarted - and the fresh
        count lands a moment later. `wait=True` is for the one caller that
        needs them now (before a VACUUM, while the file is still free)."""
        cached = self._stats_cache
        if cached and time.time() - cached[0] < 30:
            return dict(cached[1])
        guard = getattr(self, '_stats_guard', None)
        if guard is None:
            guard = self._stats_guard = threading.Lock()
        if wait:
            with guard:
                return dict(self._stats_count_now())
        if guard.acquire(blocking=False):
            def work():
                try:
                    self._stats_count_now()
                except Exception as e:
                    log('counting the rows for the header: %s' % e, 'debug')
                finally:
                    guard.release()
            threading.Thread(target=work, name='row-counts', daemon=True).start()
        if cached:
            return dict(cached[1])            # being counted; the last figures will do
        return self._stats_sizes(dict(self._stats_seed(), counting=True))

    def _stats_seed(self):
        """The figures this daemon wrote down before it was last restarted, so
        the first card drawn after a restart has numbers on it rather than a
        dash. Empty on a house that has never counted."""
        try:
            saved = json.loads(self.get_meta('row_counts') or '{}')
        except ValueError:
            saved = {}
        return {k: v for k, v in saved.items() if isinstance(v, (int, float))} if isinstance(saved, dict) else {}


# ---------------------------------------------------------------------------
# MQTT
# ---------------------------------------------------------------------------
def make_mqtt_client(client_id, clean=True):
    """A paho client that works with both the 1.x and the 2.x API."""
    if mqtt is None:
        raise RuntimeError('python3-paho-mqtt is not installed')
    if hasattr(mqtt, 'CallbackAPIVersion'):
        client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2, client_id=client_id,
                             clean_session=clean)
    else:
        client = mqtt.Client(client_id=client_id, clean_session=clean)
    if CONFIG.get('mqtt_username'):
        client.username_pw_set(CONFIG['mqtt_username'], CONFIG.get('mqtt_password') or None)
    if CONFIG.get('mqtt_tls'):
        ca = CONFIG.get('mqtt_ca') or None
        if ca:
            client.tls_set(ca_certs=ca, cert_reqs=ssl.CERT_REQUIRED, tls_version=ssl.PROTOCOL_TLS_CLIENT)
        else:
            client.tls_set(cert_reqs=ssl.CERT_NONE, tls_version=ssl.PROTOCOL_TLS_CLIENT)
            client.tls_insecure_set(True)
    client.reconnect_delay_set(min_delay=1, max_delay=30)
    # A scene that switches twenty things publishes twenty messages at once.
    # Paho lets twenty be in flight by default and then waits for each PUBACK
    # before the next goes out - so the far end of a big scene waited on the
    # broker's acknowledgements. There is nothing to protect here: it is a
    # broker on the same machine.
    try:
        client.max_inflight_messages_set(200)
        client.max_queued_messages_set(0)         # 0 = as many as it takes
    except Exception:
        pass
    return client


def reason_text(rc):
    """paho 1.x gives an int, 2.x a ReasonCode; both print sensibly."""
    try:
        if hasattr(rc, 'is_failure'):
            return str(rc)
        return mqtt.connack_string(rc) if mqtt else str(rc)
    except Exception:
        return str(rc)


def rc_failed(rc):
    if hasattr(rc, 'is_failure'):
        return rc.is_failure
    return int(rc) != 0


def exposes_map(definition):
    """Zigbee2MQTT's exposes tree -> {property: {label, unit, description, type}}."""
    out = {}

    def walk(items, prefix=''):
        for item in items or []:
            if not isinstance(item, dict):
                continue
            prop = item.get('property')
            if prop:
                name = (prefix + prop) if prefix else prop
                out[name] = {
                    'access': item.get('access'),
                    'label': item.get('label') or key_label(name),
                    'unit': item.get('unit') or key_unit(name),
                    'description': item.get('description') or '',
                    'type': item.get('type') or '',
                    'category': item.get('category') or '',
                    'values': item.get('values') or None,
                    'min': item.get('value_min'),
                    'max': item.get('value_max'),
                }
            if item.get('features'):
                sub = (prefix + prop + '.') if prop else prefix
                walk(item['features'], sub)

    if isinstance(definition, dict):
        walk(definition.get('exposes'))
    return out


class PlugState(object):
    """Everything the daemon remembers about one configured plug."""

    def __init__(self, name, cfg):
        self.name = name
        self.cfg = cfg
        self.device_id = 'plug:' + name
        self.info = None
        self.device_status = None
        self.last_device_status = 0.0
        self.last_poll = 0.0
        self.last_sample = 0.0
        self.backoff_until = 0.0
        self.failures = 0
        self.error = None
        self.output = None
        self.flat = {}
        self.generated = None
        self.pulsing = False
        self.pulse_lock = threading.Lock()
        # One command at a time to one socket, in the order they were
        # given, and what the last of them asked for while it is on its way
        self.cmd_lock = threading.Lock()
        self.inflight = 0
        self.wanted = None
        self.cmd_seq = 0

    @property
    def optional(self):
        return bool(self.cfg.get('optional')) or str(self.cfg.get('host_state') or '') == 'optional'

    @property
    def unplugged(self):
        """An optional box that is not answering right now: expected, not a fault."""
        return self.optional and self.failures >= 3

    @property
    def known_down(self):
        """It has failed its last three readings, so it is not there.

        This house's own month: 393 commands that timed out or found no route,
        and on 97% of them the box was still unreachable two minutes later -
        so these are boxes that are really gone, not lost packets. Each of
        those commands spent the full five-second timeout first, and 164 of
        them went to one light. A person pressing a button on a light that is
        not there should be told in a moment, not in five seconds, and the
        reading that comes round every fifteen seconds is what notices it
        coming back."""
        return self.failures >= 3

    def rpc(self):
        rpc = ShellyRPC(self.cfg.get('host'), self.cfg.get('password') or '',
                        self.cfg.get('switch_id') or 0, label='plug %s' % self.name)
        if self.unplugged or self.known_down:
            # do not spend the full timeout on a box that is known to be
            # off: a quick probe is enough to notice it coming back, and a
            # command aimed at it fails fast instead of holding a thread
            rpc.timeout = min(rpc.timeout, 2.0)
            rpc.known_down = True
        return rpc


def local_moment(year, month, day, minutes):
    """The moment a local clock says HH:MM on a given day, as a timestamp.

    "Midnight plus N minutes" and "plus 86,400 seconds for tomorrow" are both
    wrong twice a year: on the night the clocks go back a day is 25 hours long
    and on the night they go forward 23. Quiet hours ending at 07:00 ended at
    06:00 on 25 October, and a text sent at 06:30 that morning was held until
    the next day. mktime is asked for the wall-clock time itself (with the day
    allowed to run past the end of the month) and works out which offset
    applies; a time that does not exist on a spring-forward night comes out
    as the moment after the gap.
    """
    return time.mktime((year, month, day, minutes // 60, minutes % 60, 0, 0, 0, -1))


# ---------------------------------------------------------------------------
# PHP, and the two holes in it
# ---------------------------------------------------------------------------
# php2shell, published 21 October 2026. Two holes in PHP's own handling of a
# request, both 9.2:
#
#   CVE-2026-109618  running out of memory interrupts PHP while the data for
#                    a request is only half set up, and the tidying up
#                    afterwards treats what is left as though it were whole
#   CVE-2026-109619  state belonging to one request outlives the memory it
#                    was in, and the NEXT request on the same worker reads it
#                    before anything resets it
#
# Why this program cares at all, being Python: the dashboard is PHP, and both
# of these are reached before any page of this house runs. The PIN, the allow
# rules, the API token, every check written in index.php - all of them are
# behind the point where this happens. A request that arrives at php-fpm is
# the whole exposure, and the only thing that mends it is the version.
#
# The versions that carry the fix, by branch. Anything on 8.1 or older gets
# nothing from upstream (the PHP security team published source backports for
# 7.4, 8.0 and 8.1, and some distributions carry them) - which is why a
# branch missing from this table is reported as "no fix upstream" rather than
# as "fine".
PHP_FIXED = {'8.5': (8, 5, 12), '8.4': (8, 4, 27), '8.3': (8, 3, 36), '8.2': (8, 2, 35)}
PHP2SHELL = ('CVE-2026-109618', 'CVE-2026-109619')
# A distribution that backports a fix does not change the version number, so
# the number alone would call a patched machine broken. The package's own
# changelog is asked as well, and it has the last word.
PHP_PACKAGES = ('php-fpm', 'php8.3-fpm', 'php8.2-fpm', 'php8.4-fpm', 'php')
_PHP_SAID = {}


def php_version_now():
    """The version of the PHP that serves pages here, and how it was asked.

    php-fpm first, because that is the one serving the dashboard; the command
    line second, because a machine may have one and not the other. Never
    guessed from a package name - the number is read from the thing itself.
    """
    for argv, how in ((['php-fpm', '-v'], 'php-fpm'), (['php-fpm8.3', '-v'], 'php-fpm'),
                      (['php', '-v'], 'the php command line')):
        if not shutil.which(argv[0]):
            continue
        try:
            out = subprocess.run(argv, capture_output=True, text=True, timeout=10)
        except (OSError, subprocess.SubprocessError):
            continue
        found = re.search(r'\bPHP\s+(\d+)\.(\d+)\.(\d+)', (out.stdout or '') + (out.stderr or ''))
        if found:
            return tuple(int(g) for g in found.groups()), how
    return None, ''


def php_changelog_mentions(names=PHP2SHELL):
    """Does the installed package's own changelog name these?

    rpm and dpkg both keep one. A distribution that backports a fix says so
    there and nowhere else, so this is the only honest way to tell a patched
    8.3.6 from an unpatched one.
    """
    for package in PHP_PACKAGES:
        for argv in (['rpm', '-q', '--changelog', package],
                     ['dpkg-query', '-W', '-f=${Version}\\n', package]):
            if not shutil.which(argv[0]):
                continue
            try:
                out = subprocess.run(argv, capture_output=True, text=True, timeout=15)
            except (OSError, subprocess.SubprocessError):
                continue
            if out.returncode != 0:
                continue
            text = (out.stdout or '')
            if any(name.lower() in text.lower() for name in names):
                return package
            # dpkg's changelog is a file rather than a query
            if argv[0] == 'dpkg-query':
                for where in ('/usr/share/doc/%s/changelog.Debian.gz' % package,
                              '/usr/share/doc/%s/changelog.gz' % package):
                    try:
                        import gzip
                        with gzip.open(where, 'rt', errors='replace') as fh:
                            body = fh.read(400000)
                        if any(name.lower() in body.lower() for name in names):
                            return package
                    except Exception:
                        pass
    return ''


NGINX_CONFS = ('/etc/nginx/conf.d/zigmon.conf', '/etc/nginx/sites-enabled/zigmon.conf',
               '/etc/nginx/conf.d/zigmon-tap-front.conf')


def nginx_refuses_multipart(where=NGINX_CONFS):
    """Does the web server in front of PHP turn a multipart body away?

    None when there is no nginx file here to read - this machine may not be
    the one serving the dashboard, and a check cannot report on a file it
    cannot see. True or False when there is one.
    """
    seen = False
    for path in where:
        try:
            text = Path(path).read_text(errors='replace')
        except OSError:
            continue
        seen = True
        if re.search(r'content_type\s*~\*?\s*"?\^?multipart', text):
            return True
    return False if seen else None


def php_now(force=False):
    """What there is to say about the PHP on this machine, or nothing at all.

    Held for a quarter of an hour: the check command, the dashboard and the
    loop above all ask, and the answer only changes when somebody runs an
    update.
    """
    if not force and _PHP_SAID.get('at', 0) > time.time() - 900:
        return _PHP_SAID.get('said') or {}
    version, how = php_version_now()
    said = {'found': bool(version), 'how': how,
            'version': '.'.join(str(n) for n in version) if version else '',
            'vulnerable': False, 'branch': '', 'wanted': '', 'patched_by': '', 'fix': ''}
    if version:
        branch = '%d.%d' % (version[0], version[1])
        said['branch'] = branch
        wanted = PHP_FIXED.get(branch)
        said['wanted'] = '.'.join(str(n) for n in wanted) if wanted else ''
        if wanted:
            said['vulnerable'] = version < wanted
            said['fix'] = ('Update PHP to %s or newer and restart php-fpm.'
                           % said['wanted']) if said['vulnerable'] else ''
        else:
            # a branch upstream does not publish for: 8.1 and older, or one
            # newer than this program knows about
            newer = version >= max(PHP_FIXED.values())
            said['vulnerable'] = not newer
            said['fix'] = '' if newer else (
                'PHP %s gets no fix from upstream. Move to a branch that does (8.2.35, '
                '8.3.36, 8.4.27 or 8.5.12 and newer), or make sure the distribution '
                'carries the backport.' % branch)
        if said['vulnerable']:
            # ...unless the distribution has already put it right without
            # moving the number, which its own changelog is the proof of
            package = php_changelog_mentions()
            if package:
                said['vulnerable'] = False
                said['patched_by'] = package
                said['fix'] = ''
    _PHP_SAID['at'], _PHP_SAID['said'] = time.time(), said
    return said


# ---------------------------------------------------------------------------
# New versions from the web (5.21)
#
# Settings - Upgrades - upgrade_url is asked once a day (upgrade_check) and
# whenever Look now is pressed, for zigmon-X.Y.Z.tar.gz: a GitHub folder
# through GitHub's API, any other page by the links in it, or one package's
# own address. The newest one newer than what runs here is offered on the
# dashboard; one click fetches it, and from then on it is a package exactly as
# though it had been sent by hand - the same zigmon_upgrade.py --inspect, the
# same signature, the same Upgrade button, root checking it all again from
# scratch. Nothing is put in by itself, and nothing is trusted because of
# where it came from: HTTPS only keeps the look honest, the release key is
# what the package is believed on.
# ---------------------------------------------------------------------------
ONLINE_PKG_RE = re.compile(r'(?:^|/)(zigmon-(\d+)\.(\d+)\.(\d+)\.tar\.gz)(?:\?|#|$)')
ONLINE_EVERY_S = 86400
# One look and one fetch at a time, whichever of the chores, the page or the
# command line asked for it.
ONLINE_WORK = {'busy': False, 'fetching': False, 'at': 0.0}
ONLINE_LOCK = threading.Lock()
# A folder listing is a page or two of JSON; a package is the program, the
# page and the helpers. Both are bounded, so an address that answers with an
# endless stream fills neither memory nor the disk.
ONLINE_PAGE_MOST = 4 * 1024 * 1024
UPGRADE_MOST = 64 * 1024 * 1024


def _online_get(url, limit=ONLINE_PAGE_MOST, accept='*/*', timeout=30, into=None):
    """(bytes, content type, final address) of an https:// address.

    With `into`, the answer is written to that file a piece at a time and
    the bytes come back as None: the service runs with MemoryMax=300M, and a
    package read whole into memory is a fifth of that before anything else
    has happened. The address it ends at after redirects is checked as well
    as the one asked - a redirect to plain http would otherwise undo the
    whole point of asking over https."""
    import urllib.request
    if not str(url).startswith('https://'):
        raise ValueError('only https:// addresses are asked: %s' % str(url)[:200])
    req = urllib.request.Request(url, headers={
        'User-Agent': 'zigmon/%s (+upgrade check)' % __version__, 'Accept': accept})
    with urllib.request.urlopen(req, timeout=timeout, context=ssl.create_default_context()) as r:
        final = r.geturl()
        if not str(final).startswith('https://'):
            raise ValueError('it was sent on to an address that is not https: %s' % str(final)[:200])
        ct = r.headers.get('Content-Type') or ''
        if into is None:
            data = r.read(limit + 1)
            if len(data) > limit:
                raise ValueError('the answer from %s is bigger than %d MB' % (url, limit >> 20))
            return data, ct, final
        got = 0
        with open(str(into), 'wb') as fh:
            while True:
                piece = r.read(256 * 1024)
                if not piece:
                    break
                got += len(piece)
                if got > limit:
                    raise ValueError('the answer from %s is bigger than %d MB' % (url, limit >> 20))
                fh.write(piece)
        return None, ct, final


def _online_ver(text):
    try:
        return tuple(int(x) for x in str(text).split('.')[:3])
    except ValueError:
        return (0, 0, 0)


def online_list(url):
    """The packages at `url`: [{'name', 'version', 'url', 'bytes'}], newest first.

    Three kinds of address are understood. One package's own (a GitHub page
    of a file is read as the file itself, from raw.githubusercontent.com); a
    GitHub folder, asked through GitHub's contents API and, when that
    refuses - sixty questions an hour without an account - through the
    folder's own page, read for the names; and any other page, as a JSON
    list or as the links in it, which is what nginx's and Apache's folder
    listings are. A link that is not https is never offered."""
    import html
    import urllib.parse
    url = str(url or '').strip()
    if not url:
        raise ValueError('there is no address to look at (Settings - Upgrades)')
    if not url.startswith('https://'):
        raise ValueError('only https:// addresses are asked: %s' % url[:200])
    found = {}

    def add(name, link, size=None):
        m = ONLINE_PKG_RE.search('/' + str(name))
        if not m or not str(link).startswith('https://'):
            return
        version = '%d.%d.%d' % tuple(int(x) for x in m.group(2, 3, 4))
        found[m.group(1)] = {'name': m.group(1), 'version': version, 'url': str(link),
                             'bytes': size if isinstance(size, int) else None}

    gh = re.match(r'^https://github\.com/([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+)'
                  r'(?:/tree/([^/?#]+)(?:/([^?#]*?))?)?/?$', url)
    one = ONLINE_PKG_RE.search(urllib.parse.urlparse(url).path)
    if one:
        link = url
        b = re.match(r'^https://github\.com/([^/]+)/([^/]+)/blob/([^?#]+)', url)
        if b:
            link = 'https://raw.githubusercontent.com/%s/%s/%s' % b.groups()
        add(one.group(1), link)
    elif gh:
        owner, repo, ref, folder = gh.group(1), gh.group(2), gh.group(3), (gh.group(4) or '').strip('/')
        api = 'https://api.github.com/repos/%s/%s/contents/%s' % (owner, repo, urllib.parse.quote(folder))
        if ref:
            api += '?ref=' + urllib.parse.quote(ref)
        try:
            data, _ct, _final = _online_get(api, accept='application/vnd.github+json')
            items = json.loads(data.decode('utf-8'))
        except Exception as e:                          # noqa: BLE001 - the page is asked instead
            try:
                data, _ct, _final = _online_get(url)
            except Exception:                           # noqa: BLE001
                raise ValueError('GitHub did not answer: %s' % (getattr(e, 'reason', None) or e))
            base = 'https://raw.githubusercontent.com/%s/%s/%s/%s' % (
                owner, repo, ref or 'HEAD', (folder + '/') if folder else '')
            items = [{'type': 'file', 'name': n, 'download_url': base + n}
                     for n in sorted(set(re.findall(r'zigmon-\d+\.\d+\.\d+\.tar\.gz',
                                                    data.decode('utf-8', 'replace'))))]
        if isinstance(items, dict):
            items = [items]
        for it in items if isinstance(items, list) else []:
            if isinstance(it, dict) and it.get('type') == 'file' and it.get('download_url'):
                add(str(it.get('name') or ''), str(it['download_url']), it.get('size'))
    else:
        data, ct, final = _online_get(url)
        text = data.decode('utf-8', 'replace')
        try:
            items = json.loads(text) if 'json' in ct or text.lstrip()[:1] in ('[', '{') else None
        except ValueError:
            items = None
        if isinstance(items, list):
            for it in items:
                if isinstance(it, dict):
                    link = str(it.get('download_url') or it.get('url') or '')
                    add(str(it.get('name') or link), urllib.parse.urljoin(final, link), it.get('size'))
        else:
            for href in re.findall(r'''href\s*=\s*["']([^"']+)["']''', text, re.I):
                link = urllib.parse.urljoin(final, html.unescape(href))
                m = ONLINE_PKG_RE.search(urllib.parse.urlparse(link).path)
                if m:
                    add(m.group(1), link)
    return sorted(found.values(), key=lambda x: _online_ver(x['version']), reverse=True)


# ---------------------------------------------------------------------------
# The daemon
# ---------------------------------------------------------------------------
def _one_writer(fn):
    """A method that reads a whole list from the database, changes it and
    writes it back: one at a time."""
    @functools.wraps(fn)
    def held(self, *a, **k):
        with self._lists_lock:
            return fn(self, *a, **k)
    return held


class Daemon(object):
    def __init__(self, storage=None):
        open_log()
        # every line from here on is written by a thread of its own, so that
        # nothing on its way to a light waits on the journal or the disk
        start_log_writer()
        self.store = storage or Storage()
        self.lock = threading.Lock()
        self.token = self._ensure_token()
        self.started = time.time()
        self.connected = False
        self.last_connect = None
        self.last_disconnect = None
        self.connect_failures = 0
        self.last_error = None
        self.messages = 0
        self.last_message_at = None
        self.last_aggregate_at = 0.0
        self.bridge = {'state': None, 'version': None, 'coordinator': None,
                       'permit_join': None, 'permit_join_end': None, 'channel': None,
                       'pan_id': None, 'log_level': None, 'updated': None,
                       'devices_at': None}
        self._stale_topics = {}  # topic -> when we last complained about it
        self._empty_seen = {}    # topic -> when we last saw it cleared
        self.names = {}          # friendly name -> device id (zigbee)
        self.live = {}           # device id -> {'payload', 'ts', 'availability'}
        self._gw_answered = {}   # device id -> when its own gateway API last answered
        self._rule_queue = collections.deque()
        self._rule_kick = threading.Event()
        self._report_hits = {}   # caller -> when it last reported, for the rate limit
        self._heat_last = {}     # valve target -> the last temperature we asked it for
        self._heat_drift = {}
        self._switch_times = []    # (when, socket, ms) for the last few commands
        self._power_minutes = []   # [minute, the house total] for the last hour
        self._money_cache = None   # (when, price, the month's money), see money()
        # The gateway takes one at a time, so only one thread may be talking
        # to it. Reentrant, because one thread legitimately does two things in
        # a row: reading the inbox and then answering what it found. That is
        # sequential and the box is never asked two things at once; a plain
        # lock would have deadlocked the polling way of working on the first
        # message from a number that is not allowed to give commands.
        self._sms_send_lock = threading.RLock()
        self._secrets = {}         # what is shortened on the way out, kept whole
        self._bindings = {}        # what each device was configured with
        self._binding_said = {}    # when we last mentioned one
        self._binding_waiting = {}  # devices to configure the moment they speak
        self._confirm_due = {}     # host -> when the next confirming read may go
        self._confirm_guard = threading.Lock()
        self._heat_told = {}       # (when, how many times) we have told a head to go back    # valve target -> when we first saw it wander off
        self._heat_state_cache = None   # (seq, state): dropped whenever anything changes
        self._sms_tok = None            # (token, good until) for the device's own API
        self._sms_modem_id = None       # which modem to send from, asked once
        # the ones already dealt with, oldest first, so trimming drops the
        # oldest rather than whichever sorts lowest
        self._sms_seen = collections.OrderedDict()
        self._sms_last_poll = 0.0
        self._sms_first_look = True
        try:                            # so a restart does not act on the inbox all over again
            kept = json.loads(self.store.get_meta('sms_seen') or '[]')
            self._sms_seen = collections.OrderedDict(
                (k, 0) for k in (kept if kept and isinstance(kept[0], str) else [x[0] for x in kept]))
        except (ValueError, IndexError, TypeError):
            pass
        try:                            # the ones thrown away on purpose, so they stay thrown away
            self._sms_binned = set(json.loads(self.store.get_meta('sms_binned') or '[]'))
        except ValueError:
            self._sms_binned = set()
        self._described = {}     # one device as the API says it, until it speaks again
        self._sms_busy = False   # a poll already in flight; the gateway can be slow
        self._ubus_session = None  # the gateway's own bus session, while it lasts
        self.started_at = time.time()   # so a message can say how long it has been running
        self._weather_cache = None # (when, forecast)
        self._modem_bands = []     # the per-band table, as the device last gave it
        self._sms_today = None     # (day, count, when counted)
        self._battery_cache = None # (when, rows): a month of history per cell is not free
        self._box_status = {}      # host -> (when, one reading of the whole box)
        self._box_status_guard = threading.Lock()
        self._warm_rate = {}       # room -> how fast it heats, degrees an hour
        self._lat = {'broker_rtt_ms': None, 'broker_at': 0, 'timer_jitter_ms': 0.0, 'set_rtt_ms': None}
        self._bump_timer = None  # a pending "numbers changed" wake-up, if one is scheduled
        self._numbers_pending = False   # ...and whether it still owes the pages anything
        self._rpc_lock = threading.Lock()
        self._rpc_waiting = {}   # our RPC id -> the thread waiting for the box's answer
        self._mqtt_quiet = {}    # plug -> when we last said its MQTT went unanswered
        self._mqtt_road_off = {}  # plug -> until when its commands go straight over HTTP
        self._silent_since = {}  # device -> when we first said it had gone quiet
        self._group_last = {}    # sensor group -> the value it last read
        self._group_trigger = {} # sensor group -> which member last moved it
        self._group_skipped = {} # sensor group -> members left out this time
        self._left_network = []  # when devices left the mesh, for the last hour
        self._mesh_said = 0.0    # when we last said the mesh was unsettled
        self._set_sent = {}      # (device, key) -> when a set went out, until its echo comes back
        self._pending_set = {}   # (device, key) -> what a knob last asked for, and the timer that sends it
        self._valve_mode = {}    # device -> when we last told a head to use manual mode
        self._month_done = ''    # which month's summary has already gone out
        self._rule_queue_gated = collections.deque()
        self._rule_kick_gated = threading.Event()
        # whether a "finish the rules that must hold" tick is already waiting
        # on that queue: asked four times a second, and a deque cannot be
        # walked while two other threads are appending to it
        self._for_queued = False
        self.rule_runtime = {}   # rule id -> {'holds', 'fired', 'reading'}
        self.schedule_runtime = {}   # schedule id -> {'last_day'}
        # rule id -> an action put off for a while: {'due', 'origin', 'facts', 'do'}
        self.rule_waiting = {}
        # one writer at a time of the lists kept whole in the database: a
        # scene switching three rules off from three threads lost one of them
        self._lists_lock = threading.RLock()
        self.file_config = dict(CONFIG)      # what config.json says, before overrides
        # ...and which keys it really names, rather than leaving to the default:
        # the page says which of the three a running value came from
        try:
            _raw = json.loads(CONFIG_FILE.read_text()) if CONFIG_FILE.is_file() else {}
            self.file_keys = set(_raw) if isinstance(_raw, dict) else set()
        except (OSError, ValueError):
            self.file_keys = set()
        self.file_keys |= {k for k in DEFAULTS if os.environ.get('ZIGMON_' + k.upper()) is not None}
        self.apply_config_overrides()
        apply_gil_switch()
        # the machine itself (5.21): its network, a restart, the firewall on
        # trial, the clock - each asked of root on a road of its own
        self._net_kick = threading.Event()
        self._root_call_locks = {}
        self._net_work = {'read_at': 0.0}
        try:
            self.note_version_high()
        except Exception as e:                          # noqa: BLE001
            log('the highest version run on the database could not be written: %s' % e, 'warn')
        self._ntp_work = {'read_at': 0.0}
        threading.Thread(target=self.backup_loop, name='backup', daemon=True).start()
        # ...and the version of PHP the dashboard is served by, which is the
        # only thing standing between a caller and the two holes of 21
        # October 2026. Nothing in this program can mend it; saying so until
        # somebody does is the whole job.
        threading.Thread(target=self.php_loop, name='php', daemon=True).start()
        threading.Thread(target=self.system_loop, name='system', daemon=True).start()
        # always on: gateway_configs() covers both config.json and dashboard
        # entries, and simply does nothing on an empty list either way
        threading.Thread(target=self.gateway_loop, name='gateway', daemon=True).start()
        warn_unknown_keys()
        self.notify_queue = []
        self.notify_sent = {}    # dedup key -> last ts
        self._notify_kick = threading.Event()
        threading.Thread(target=self.notify_loop, name='notify', daemon=True).start()
        self.store.on_event = self.consider_notifying
        try:
            self.parents = json.loads(self.store.get_meta('parents') or '{}')
        except ValueError:
            self.parents = {}
        self.seq = 0             # bumped on every visible change; /api/wait hangs on it
        # presses waiting for somebody to approve them, and the one lock the
        # watch waits on rather than asking again every second
        self._waiting = {}
        self._waiting_cond = threading.Condition()
        self._anomaly = {}                # address -> what it has been doing
        self._anomaly_from = {}           # address -> where it was last seen doing it
        self._strong_seen = {}            # address -> the unmistakable things it did, over a week
        self._strong_near = {}            # neighbourhood -> the unmistakable things done from it lately
        self._slow_seen = {}              # address -> the light things it did, over a day
        self._said_at = {}                # what was said and when, so it is not said again at once
        self._blocked_times = {}          # address -> how often it has been kept out
        self._mikrotik_lock = threading.Lock()   # one talk to the router at a time
        # one fold, undo or unfold at a time: two at once each wrote the list
        # of what a subnet was folded from, the second over the first, and a
        # double click left subnets that no longer knew what they stood for
        self._fold_lock = threading.RLock()
        self._trial_lock = threading.RLock()
        self._trial_index = None
        self._proxy_reading = threading.Lock()   # and one reading of the proxy log
        self._anomaly_lock = threading.Lock()
        # addresses waiting to be asked about, and the one worker that does
        self._intel_queue = []
        self._intel_lock = threading.Lock()
        self._intel_kick = threading.Event()
        self._intel_worker = None
        self._change = threading.Condition()
        self.client = None
        self._stop = threading.Event()
        # Friendly name -> id, prefilled from the database so a report or a
        # retained availability message arriving before bridge/devices after a
        # restart does not spawn a duplicate "name:" placeholder.
        for known in self.store.devices(include_removed=True):
            if known['source'] == 'zigbee' and not known['id'].startswith('name:'):
                self.names.setdefault(known['name'], known['id'])
        self.plugs = {}          # name -> PlugState
        self.sensors = {}        # name -> PlugState, for Shelly sensors polled over RPC
        self.pushes_received = 0
        self.pushes_rejected = 0
        self.last_push_at = None
        self._plug_lock = threading.Lock()
        self._zb_echo = {}       # Zigbee2MQTT name -> when we last saw our own /set echoed back
        self._gw_last = {}       # device -> {key: (value, when)} last written from a gateway poll
        self.presence = {}       # person id -> {home, last_seen, since, device, on_wifi}
        self.presence_restore()
        self.wifi = {'ok': None, 'error': None, 'checked': None, 'count': None,
                     'wifi_count': None, 'clients_list': [], 'names': {}}
        try:
            remembered = json.loads(self.store.get_meta('wifi_names') or '{}')
            if isinstance(remembered, dict):
                self.wifi['names'] = remembered
        except ValueError:
            pass
        self._wifi_kick = threading.Event()
        # re-entrant: whatever runs under it and comes back in by another
        # road (a presence trigger marking somebody home) must not wait for
        # itself
        self._wifi_lock = threading.RLock()
        self._wifi_fetch_lock = threading.Lock()
        self._wifi_detail_lock = threading.Lock()
        self._wifi_detail_at = 0.0
        self._anyone_home_before = False
        self._presence_cache = None
        self._msg_last = {}      # message id + text -> when it last went out
        threading.Thread(target=self.wifi_loop, name='wifi', daemon=True).start()
        threading.Thread(target=self.presence_ntfy_loop, name='presence-ntfy', daemon=True).start()
        # The first time these are worked out they walk a year of meter
        # readings and a month of battery history. Somebody's page used to pay
        # for that, whoever happened to ask first after a restart; now the
        # daemon pays it in its own time, a moment after it comes up.
        threading.Thread(target=self._warm_caches, name='warm', daemon=True).start()
        self.zigbee_seen = {}    # device id -> when it last reported over Zigbee itself
        self._energy_closed = {}  # (plug, from, to) -> the reading of a period that has ended
        self._energy_summary = None
        self._mqtt_selftest_seen = None
        self._map_stamp = 0.0        # bumped whenever a network map lands
        self.setup_plugs()
        self.setup_sensors()
        # What was recorded before the restart is the starting point, so the
        # dashboard is never blank while waiting for sleepy devices to report.
        for dev in self.store.devices():
            if dev['source'] == 'zigbee':
                self.names[dev['name']] = dev['id']
        for device_id, snap in self.store.snapshots().items():
            self.live[device_id] = snap
        # the accounts of the dashboard and who is signed in (5.19)
        self.auth_start()

    # -- API token ----------------------------------------------------------
    def _ensure_token(self):
        token = None
        try:
            token = TOKEN_FILE.read_text().strip() or None
        except OSError:
            pass
        token = token or secrets.token_urlsafe(32)
        path = token_path()
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(token)
            path.chmod(0o640)
            import grp
            import pwd
            info = path.stat()
            log('API token at %s (owner %s, group %s, mode %o)'
                % (path, pwd.getpwuid(info.st_uid).pw_name,
                   grp.getgrgid(info.st_gid).gr_name, info.st_mode & 0o777))
        except OSError as e:
            log('cannot write the API token to %s: %s - the privileged '
                'endpoints will refuse every request' % (path, e), 'error')
        return token

    # -- MQTT plumbing ------------------------------------------------------
    def connect(self):
        self.client = make_mqtt_client(CONFIG.get('mqtt_client_id') or 'zigmon')
        self.client.on_connect = self._on_connect
        self.client.on_disconnect = self._on_disconnect
        self.client.on_message = self._on_message
        if hasattr(self.client, 'on_connect_fail'):
            self.client.on_connect_fail = self._on_connect_fail
        host, port = CONFIG['mqtt_host'], int(CONFIG['mqtt_port'])
        log('connecting to mqtt://%s:%d as %s' % (host, port, CONFIG.get('mqtt_username') or 'anonymous'))
        try:
            self.client.connect_async(host, port, int(CONFIG.get('mqtt_keepalive') or 60))
        except (OSError, ValueError) as e:
            self.last_error = str(e)
            log('connect: %s' % e, 'error')
        self.client.loop_start()

    def topics(self):
        base = CONFIG['base_topic'].rstrip('/')
        wanted = [(base + '/#', 0)]
        for extra in CONFIG.get('extra_topics') or []:
            if extra and extra.rstrip('/') != base:
                wanted.append((extra, 0))
        seen = {t for t, _ in wanted}
        for prefix in self.plug_prefix_map():
            t = prefix + '/#'
            if t not in seen and not any(t.startswith(e.rstrip('#')) for e in seen):
                wanted.append((t, 0))
        return wanted

    def _device_gen(self):
        """A number that changes when the device list does.

        reload_devices puts a new dict in place of the old one, so the two
        identities say "something changed" by themselves; what a box says its
        own name is arrives later, and bumps this by hand.
        """
        return (id(self.plugs), id(self.sensors), getattr(self, '_info_gen', 0))

    def plug_prefix_map(self):
        """MQTT prefix -> the plug rows behind it (several for a multi-relay device).

        Worked out once per device list rather than once per message: this was
        rebuilt - under the plug lock - for every message that is not Zigbee,
        which on a house with a few Shellys pushing their state is several
        times a second, on the broker thread, behind a lock a device list
        being saved holds across a dozen database writes.
        """
        gen = self._device_gen()
        got = getattr(self, '_prefix_cache', None)
        if got and got[0] == gen:
            return got[1]
        out = {}
        with self._plug_lock:
            for p in list(self.plugs.values()) + list(self.sensors.values()):
                prefix = str(p.cfg.get('mqtt_name') or '').strip().strip('/')
                if prefix:
                    out.setdefault(prefix, []).append(p)
        self._prefix_cache = (gen, out)
        return out

    def _on_connect(self, client, userdata, flags, rc, *rest):
        if rc_failed(rc):
            self.connect_failures += 1
            self.last_error = 'connect refused: %s' % reason_text(rc)
            log(self.last_error, 'error')
            return
        self.connected = True
        self.last_connect = time.time()
        self.last_error = None
        if getattr(self, '_broker_lost_told', False):
            # said when it went, so said when it is back
            self._broker_lost_told = False
            self.notify('The broker connection is back.', 'info', dedup='broker-back', about='broker')
        client.subscribe(self.topics() + [('zigmon/ping', 0), ('zigmon/rpc', 0)])
        log('connected; subscribed to %s' % ', '.join(t for t, _ in self.topics()))
        self.store.add_event('broker', 'connected to %s:%s' % (CONFIG['mqtt_host'], CONFIG['mqtt_port']))

    def _on_connect_fail(self, client, userdata, *rest):
        self.connect_failures += 1
        self.last_error = 'cannot reach the broker at %s:%s' % (CONFIG['mqtt_host'], CONFIG['mqtt_port'])
        # paho retries by itself; one line per minute is enough noise.
        if self.connect_failures in (1, 2) or self.connect_failures % 30 == 0:
            log(self.last_error + ' (attempt %d)' % self.connect_failures, 'warn')

    def _on_disconnect(self, client, userdata, *rest):
        # paho 2.x: (client, userdata, flags, reason_code, properties); 1.x: (client, userdata, rc)
        rc = rest[1] if len(rest) >= 2 else (rest[0] if rest else 0)
        was = self.connected
        self.connected = False
        self.last_disconnect = time.time()
        if was and not self._stop.is_set():
            self.last_error = 'broker connection lost (%s)' % reason_text(rc)
            log(self.last_error, 'warn')
            self.store.add_event('broker', 'connection lost', 'warn')
            self._broker_lost_told = True
            self.notify('The broker connection was lost. Nothing is being heard or switched until '
                        'it comes back.', 'warn', dedup='broker-lost', about='broker')

    def say(self, topic, payload, qos=0, retain=False):
        """Everything this daemon publishes goes through here, so the trace
        has both halves of every conversation and not just what came in."""
        if CONFIG.get('debug'):
            body = payload if isinstance(payload, str) else (
                '<none>' if payload is None else str(payload))
            log('mqtt -> %s qos%d%s %s' % (topic, qos, ' retain' if retain else '',
                                           debug_cut(body)), 'debug')
        return self.client.publish(topic, payload, qos=qos, retain=retain)

    def _on_message(self, client, userdata, msg):
        self.messages += 1
        self.last_message_at = time.time()
        self._msg_t0 = time.perf_counter()
        if CONFIG.get('debug'):
            try:
                body = msg.payload.decode()[:300]
            except UnicodeDecodeError:
                body = '<%d bytes>' % len(msg.payload)
            self.debug('MQTT in  %s' % msg.topic, body)
        if msg.topic == 'zigmon/rpc':
            try:
                reply = json.loads(msg.payload.decode())
            except (ValueError, UnicodeDecodeError):
                return
            with self._rpc_lock:
                entry = self._rpc_waiting.get(reply.get('id'))
                if entry:
                    entry['reply'] = reply
            if entry:
                entry['event'].set()
            elif reply.get('error'):
                log('a box answered an MQTT command with an error: %s' % reply['error'], 'warn')
            return
        if msg.topic == 'zigmon/ping':
            try:
                self._lat['broker_rtt_ms'] = round((time.time() - float(msg.payload.decode())) * 1000, 1)
            except (ValueError, UnicodeDecodeError):
                pass
            return
        # A retained message is the broker telling us what was said last,
        # at a reconnect or a restart of either side - not something that
        # happened now. A button whose Zigbee2MQTT topic is retained replayed
        # its last "single" at every reconnect, and a toggle bound to it
        # flipped the light. Its readings are still taken; its presses not.
        self._retained_msg = bool(getattr(msg, 'retain', False))
        try:
            self.handle(msg.topic, msg.payload)
        except Exception as e:      # one bad payload must never stop the feed
            log('handling %s: %s' % (msg.topic, e), 'error')
        finally:
            self._retained_msg = False

    # -- message routing ----------------------------------------------------
    def handle(self, topic, raw):
        base = CONFIG['base_topic'].rstrip('/')
        if topic == base or topic.startswith(base + '/'):
            rest = topic[len(base) + 1:] if topic != base else ''
            self.handle_zigbee(rest, raw)
            return
        parts = topic.split('/')
        prefixes = self.plug_prefix_map()
        for depth in range(min(3, len(parts) - 1), 0, -1):
            prefix = '/'.join(parts[:depth])
            if prefix in prefixes:
                self.handle_plug_push(prefixes[prefix], parts[depth:], raw)
                return
        if len(parts) >= 2:
            self.handle_generic(parts, raw)

    @staticmethod
    def decode(raw):
        text = raw.decode('utf-8', 'replace').strip() if isinstance(raw, bytes) else str(raw)
        if not text:
            return None
        if text[0] in '{[':
            try:
                return json.loads(text)
            except ValueError:
                return text
        return text

    def handle_zigbee(self, rest, raw):
        parts = rest.split('/')
        if not parts or not parts[0]:
            return
        if parts[0] == 'bridge':
            self.handle_bridge(parts[1:], raw)
            return
        name = parts[0]
        sub = parts[1] if len(parts) > 1 else ''
        if not raw:
            # an empty retained message: someone cleared this topic, possibly us
            self._empty_seen['%s/%s' % (CONFIG['base_topic'].rstrip('/'), rest)] = time.time()
            self._stale_topics.pop('%s/%s' % (CONFIG['base_topic'].rstrip('/'), rest), None)
            return
        if sub in ('set', 'get'):
            # our own command coming back to us: proof the broker accepted it
            if sub == 'set':
                self._zb_echo[name] = time.time()
                if name == SELFTEST_NAME:
                    payload = self.decode(raw)
                    self._mqtt_selftest_seen = payload if isinstance(payload, dict) else {}
            return

        payload = self.decode(raw)
        device_id = self.names.get(name)
        if sub == 'availability':
            state = payload.get('state') if isinstance(payload, dict) else payload
            if isinstance(state, str):
                target = device_id or self.adopt_unknown(name, 'availability')
                if target:
                    self.set_availability(target, state.lower(), name)
            return
        if sub:
            return          # some other sub-topic we do not care about
        if not isinstance(payload, dict):
            return
        if device_id is None:
            # A name the house does not know yet, while the bridge's new list
            # of devices is still being taken in behind this thread: it is
            # very likely ON that list - a device just paired or renamed
            # reports at once, a few hundred milliseconds before the list has
            # been walked - and refusing it now threw its first readings away
            # and called a real device a ghost (whose topic the "clear ghosts"
            # button would then have wiped). It waits for the list instead.
            if self._devices_in_hand():
                parked = self.__dict__.setdefault('_parked_reports', collections.deque(maxlen=200))
                parked.append((rest, raw))
                return
            device_id = self.adopt_unknown(name)
            if device_id is None:
                return
        self.record(device_id, name, payload)

    def _devices_in_hand(self):
        """Is a new device list from the bridge being taken in right now?"""
        idle = self.__dict__.get('_devices_idle')
        return idle is not None and not idle.is_set()

    def _replay_parked(self):
        """The reports that waited for the device list, now that it is in."""
        parked = self.__dict__.get('_parked_reports')
        while parked:
            try:
                rest, raw = parked.popleft()
            except IndexError:
                break
            try:
                self.handle_zigbee(rest, raw)
            except Exception as e:
                log('a report that waited for the device list: %s' % e, 'warn')

    def ghost_topics(self):
        """Topics the broker keeps replaying for devices Zigbee2MQTT no longer
        has. We only know about one once its retained message has arrived,
        which it does the moment we subscribe."""
        return sorted(self._stale_topics)

    def clear_ghost_topics(self):
        """Publish an empty retained message to each, which is how a retained
        message is deleted, and see which ones the broker actually took."""
        topics = self.ghost_topics()
        if not topics:
            return {'ok': True, 'cleared': [], 'refused': [], 'message': 'nothing left to clear'}
        if not self.connected or not self.client:
            return {'ok': False, 'error': 'not connected to the broker'}
        sent_at = time.time()
        for topic in topics:
            try:
                info = self.say(topic, None, qos=1, retain=True)
                info.wait_for_publish(3)
            except Exception as e:
                log('clearing %s: %s' % (topic, e), 'debug')
        deadline = time.time() + 5
        while time.time() < deadline:
            if all(self._empty_seen.get(t, 0) >= sent_at for t in topics):
                break
            if self._stop.wait(0.2):
                break
        cleared = [t for t in topics if self._empty_seen.get(t, 0) >= sent_at]
        refused = [t for t in topics if t not in cleared]
        for topic in cleared:
            self._stale_topics.pop(topic, None)
        out = {'ok': not refused, 'cleared': cleared, 'refused': refused}
        if refused:
            out['message'] = ('the broker would not let the daemon write to %s. Its MQTT user needs '
                              '"topic write %s/#" for this, or clear them by hand with mosquitto_pub -r -n'
                              % (refused[0], CONFIG['base_topic'].rstrip('/')))
        else:
            out['message'] = 'cleared %d topic(s)' % len(cleared)
        return out

    def adopt_unknown(self, name, sub=''):
        """A device the bridge list has not told us about yet.

        Once Zigbee2MQTT has told us what it has, a message under a name that
        is not on that list is not a new device - it is the broker replaying a
        retained message for one that was deleted. Adopting it puts a ghost
        back on the dashboard every restart, so it is refused. The warning
        names the exact topic holding the message, sub-topic and all: a device
        usually has more than one, and clearing the wrong one changes
        nothing."""
        if self.bridge.get('devices_at'):
            topic = '%s/%s%s' % (CONFIG['base_topic'].rstrip('/'), name, ('/' + sub) if sub else '')
            last = self._stale_topics.get(topic, 0)
            if time.time() - last > 3600:
                self._stale_topics[topic] = time.time()
                log('ignoring %s: Zigbee2MQTT does not have that device, so this is a message the '
                    'broker kept. Clear it with: mosquitto_pub -r -n -t \'%s\'' % (topic, topic), 'warn')
            return None
        device_id = 'name:' + name
        self.names[name] = device_id
        if self.store.device(device_id) is None:
            self.store.upsert_device({'id': device_id, 'name': name, 'source': 'zigbee',
                                      'kind': None, 'exposes': {}})
            log('device "%s" seen before the bridge listed it' % name)
        return device_id

    # What the bridge says that nothing here reads. All of them are retained,
    # so every one arrives again on every reconnect - and bridge/definitions
    # on Zigbee2MQTT 1.x is several megabytes: parsed on the broker's own
    # thread and thrown away, it held that thread 137 ms (4.7 MB) on every
    # connect, with no report heard and no command sent meanwhile.
    BRIDGE_IGNORED = ('definitions', 'groups', 'extensions', 'request', 'converters',
                      'options', 'health')

    def handle_bridge(self, parts, raw):
        what = parts[0] if parts else ''
        if what in self.BRIDGE_IGNORED:
            return
        # The big ones and the ones that write to the database or the disk are
        # handed over before anything is parsed: the device list (hundreds of
        # kilobytes), the network map (whose answer is written into the
        # settings table under the database lock - 1,436 ms on this thread
        # while a backup held it), and the coordinator's own backup (megabytes
        # of base64, decoded and written to disk). On this thread none of it
        # may happen: while it does, the house is not heard and no Zigbee
        # command can leave.
        if what == 'devices':
            self._sync_devices_later(raw)
            return
        if what == 'response' and len(parts) > 1 and parts[1] in ('networkmap', 'backup'):
            self._bridge_later(self.handle_networkmap if parts[1] == 'networkmap'
                               else self.handle_zigbee_backup, raw)
            return
        payload = self.decode(raw)
        now = int(time.time())
        if what == 'state':
            state = payload.get('state') if isinstance(payload, dict) else payload
            state = str(state).lower() if state is not None else None
            old = self.bridge['state']
            self.bridge['state'] = state
            self.bridge['updated'] = now
            if old != state:
                log('bridge is %s' % state)
                if old is not None or state != 'online':
                    self.store.add_event('bridge', 'Zigbee2MQTT is %s' % state,
                                         'info' if state == 'online' else 'crit')
                # The events had it and nobody was told: with the bridge
                # down, no button, sensor or valve is heard, and the page's
                # own banner is only seen by somebody already looking.
                if state == 'offline' and old is not None:
                    self._bridge_down_told = True
                    self.notify('Zigbee2MQTT is offline: no button, sensor or valve is heard until it is back.',
                                'crit', dedup='bridge-offline', title='The Zigbee bridge is down', about='bridge')
                elif state == 'online' and getattr(self, '_bridge_down_told', False):
                    self._bridge_down_told = False
                    self.notify('Zigbee2MQTT is back online.', 'info', dedup='bridge-online',
                                title='The Zigbee bridge is back', about='bridge')
        elif (what == 'response' and len(parts) > 2 and parts[1] == 'device'
              and parts[2] == 'configure'):
            self.configure_answer(payload if isinstance(payload, dict) else {})
        elif what == 'info' and isinstance(payload, dict):
            coord = payload.get('coordinator') or {}
            meta = coord.get('meta') or {}
            net = payload.get('network') or {}
            self.bridge.update({
                'version': payload.get('version'),
                'coordinator': ('%s %s' % (coord.get('type') or '', meta.get('revision') or '')).strip() or None,
                'coordinator_ieee': coord.get('ieee_address'),
                'permit_join': payload.get('permit_join'),
                'permit_join_end': payload.get('permit_join_end'),
                'channel': net.get('channel'),
                'pan_id': net.get('pan_id'),
                'log_level': payload.get('log_level'),
                'updated': now,
            })
        elif what == 'event' and isinstance(payload, dict):
            self.bridge_event(payload)
        elif what == 'logging' and isinstance(payload, dict):
            level = str(payload.get('level') or '').lower()
            message = str(payload.get('message') or '')
            # Zigbee2MQTT rightly complains that it does not know the name our
            # publish test uses; that complaint is ours, not a fault worth
            # putting in front of anyone.
            if level == 'error' and SELFTEST_NAME not in message:
                self.say_event('bridge', message[:300], 'warn', about='bridge_errors',
                               title='Zigbee2MQTT reports an error')
        # request/response/definitions/groups/extensions: nothing to record

    # Bindings and reporting: what a sensor was told to send, and when it
    # stops having been told
    # ---------------------------------------------------------------------
    #
    # A battery sensor is configured once, when it joins: the bindings say
    # which clusters report to the coordinator and the reporting configuration
    # says how often. Both live in the sensor's own memory. A rejoin, a
    # firmware update or a Zigbee2MQTT that was killed rather than stopped can
    # leave that configuration gone - and nothing says so. The device is still
    # in the network, still in the list, and simply never speaks again. At
    # thirty devices that can go unnoticed for weeks.
    #
    # There is no way to ask what a device *should* have without repeating the
    # converter library's work. But there is a way to notice: six of seven of
    # the same model have three bindings and the seventh has none.

    SILENT_MODELS = ('TS0601',)          # Tuya EF00: they send datapoints unasked

    def _bridge_later(self, handler, raw):
        """A heavy answer from the bridge, parsed and acted on behind the
        broker's thread, in the order they came."""
        queue = self.__dict__.get('_bridge_queue')
        if queue is None:
            queue = self._bridge_queue = collections.deque()
            self._bridge_wake = threading.Event()
            self._bridge_idle = threading.Event()
            self._bridge_idle.set()
            threading.Thread(target=self._bridge_worker, name='bridge-work', daemon=True).start()
        self._bridge_idle.clear()
        queue.append((handler, raw))
        self._bridge_wake.set()

    def _bridge_worker(self):
        while not self._stop.is_set():
            self._bridge_wake.wait(1.0)
            self._bridge_wake.clear()
            while self._bridge_queue:
                handler, raw = self._bridge_queue.popleft()
                try:
                    handler(self.decode(raw))
                except Exception as e:
                    log('an answer from the bridge (%s): %s'
                        % (getattr(handler, '__name__', '?'), e), 'error')
            if not self._bridge_queue:
                self._bridge_idle.set()

    def bridge_settled(self, timeout=5.0):
        """Wait until every heavy answer from the bridge has been acted on."""
        idle = self.__dict__.get('_bridge_idle')
        return True if idle is None else idle.wait(timeout)

    def _sync_devices_later(self, devices):
        """The bridge's whole device list, taken off the broker's own thread.

        Zigbee2MQTT publishes it retained, so a copy arrives on every connect
        and again on every rename, pairing or restart of the bridge. Walking
        it cost that thread 226 ms cold, and as much as 443 ms while the
        writer had a restart's worth of readings queued - and for that whole
        time the house is not heard and nothing can be published, which is
        the one thing that thread must never do. Nothing in the list is
        urgent, and only the newest copy of it means anything, so one worker
        takes the newest and the thread that hears the house goes straight
        back to hearing it.
        """
        self._devices_pending = devices
        if not hasattr(self, '_devices_wake'):
            self._devices_wake = threading.Event()
            self._devices_idle = threading.Event()
            self._devices_idle.set()
            threading.Thread(target=self._devices_worker, name='devices', daemon=True).start()
        self._devices_idle.clear()
        self._devices_wake.set()

    def _devices_worker(self):
        while not self._stop.is_set():
            self._devices_wake.wait(1.0)
            self._devices_wake.clear()
            devices, self._devices_pending = self._devices_pending, None
            if devices is None:
                self._devices_idle.set()
                continue
            try:
                # handed over as it arrived, so the parsing is done here too:
                # hundreds of kilobytes of JSON are not the broker's to read
                if isinstance(devices, (bytes, bytearray, str)):
                    devices = self.decode(devices)
                if not isinstance(devices, list):
                    if self._devices_pending is None:
                        self._devices_idle.set()
                        self._replay_parked()
                    continue
                self.sync_devices(devices)
                self.bridge['devices_at'] = int(time.time())
                self.note_bindings(devices)
            except Exception as e:
                log('the bridge\'s device list: %s' % e, 'error')
            if self._devices_pending is None:
                self._devices_idle.set()
                self._replay_parked()

    def devices_settled(self, timeout=5.0):
        """Wait until the bridge's device list has been taken in. For the
        checks, and for anything that must not read the list while it is
        being replaced. True when there is nothing left to take in."""
        idle = getattr(self, '_devices_idle', None)
        if idle is None:
            return True
        return idle.wait(timeout)

    def note_bindings(self, devices):
        """Keep what the bridge says each device was configured with."""
        kept = {}
        for d in devices:
            if not isinstance(d, dict) or d.get('type') in ('Coordinator', 'GreenPower'):
                continue
            ieee = d.get('ieee_address')
            if not ieee:
                continue
            binds, reports, clusters = [], [], set()
            for epid, ep in (d.get('endpoints') or {}).items():
                if not isinstance(ep, dict):
                    continue
                for b in ep.get('bindings') or []:
                    name = ((b.get('cluster') or {}).get('name') if isinstance(b.get('cluster'), dict)
                            else b.get('cluster'))
                    binds.append('%s:%s' % (epid, name))
                for r in ep.get('configured_reportings') or []:
                    cluster = ((r.get('cluster') or {}).get('name') if isinstance(r.get('cluster'), dict)
                               else r.get('cluster'))
                    reports.append({'at': '%s:%s:%s' % (epid, cluster, r.get('attribute')),
                                    'every': numeric(r.get('maximum_report_interval'))})
                for kind in ('input', 'output'):
                    for c in ((ep.get('clusters') or {}).get(kind) or []):
                        clusters.add(str(c))
            kept[ieee] = {
                'name': d.get('friendly_name') or ieee,
                'model': (d.get('definition') or {}).get('model') or d.get('model_id') or '',
                'model_id': d.get('model_id') or '',
                'maker': d.get('manufacturer') or '',
                'kind': d.get('type') or '',
                'powered': str((d.get('power_source') or '')).lower(),
                'firmware': str(d.get('software_build_id') or d.get('date_code') or ''),
                'binds': sorted(binds),
                'reports': sorted(reports, key=lambda r: r['at']),
                'clusters': sorted(clusters),
                'at': int(time.time()),
            }
        self._bindings = kept
        self.store.set_meta('device_bindings', json.dumps(kept))

    # A remembered shape, for when there is nothing left to compare with
    # ---------------------------------------------------------------------
    #
    # Comparing a device with the others of its model is the best evidence
    # there is, and it needs no knowledge of any model. But it needs others:
    # replace six of seven sensors and the seventh has nobody to be compared
    # with, and a house that grows one device at a time never has anybody at
    # all.
    #
    # So a shape can be remembered. Not learned - remembered, on the word of
    # whoever is looking at the screen and can see that the house is working.
    # Learning it by itself would mean that a model whose every copy is broken
    # teaches that broken is correct, and the check would then certify the
    # fault for ever. That is the one mistake this must not make.

    def baselines(self):
        try:
            return json.loads(self.store.get_meta('binding_baselines') or '{}')
        except ValueError:
            return {}

    @staticmethod
    def _shape_of(entry):
        return {'binds': list(entry.get('binds') or []),
                'reports': [r['at'] for r in (entry.get('reports') or [])]}

    @staticmethod
    def _model_key(entry):
        return '%s|%s' % (entry.get('maker') or '?', entry.get('model_id') or entry.get('model') or '?')

    def commit_baselines(self, only=None, force=False, origin='the dashboard'):
        """Remember the shape of every model that is plainly in order.

        Refused, unless forced: a model whose devices disagree with each other
        (which of them would be the truth?), and a shape with nothing in it at
        all (that is the fault itself, and remembering it would bless it for
        ever).
        """
        known, out = self.bindings_known(), {'kept': [], 'refused': []}
        saved = self.baselines()
        groups = {}
        for ieee, entry in known.items():
            if self._configured_by_other_means(entry):
                continue
            groups.setdefault(self._model_key(entry), []).append(entry)
        for key, group in sorted(groups.items()):
            if only and key != only:
                continue
            shapes = {}
            for entry in group:
                shape = self._shape_of(entry)
                shapes.setdefault(json.dumps(shape, sort_keys=True), []).append(entry)
            if len(shapes) > 1 and not force:
                out['refused'].append({'model': key, 'why': 'its %d devices are not configured alike, so '
                                                            'there is no telling which is right' % len(group)})
                continue
            text, agreed = max(shapes.items(), key=lambda kv: len(kv[1]))
            shape = json.loads(text)
            if not shape['binds'] and not shape['reports'] and not force:
                out['refused'].append({'model': key, 'why': 'nothing is configured on any of them, and that '
                                                            'is the fault this looks for'})
                continue
            saved[key] = {'shape': shape, 'from': len(agreed), 'at': int(time.time()), 'by': origin,
                          'firmware': sorted({e.get('firmware') or '' for e in agreed if e.get('firmware')}),
                          'names': sorted(e.get('name') or '' for e in agreed)[:12]}
            out['kept'].append({'model': key, 'from': len(agreed),
                                'binds': len(shape['binds']), 'reports': len(shape['reports'])})
        self.store.set_meta('binding_baselines', json.dumps(saved))
        if out['kept']:
            self.store.add_event('audit', 'remembered the right shape for %d Zigbee model(s) (%s)'
                                 % (len(out['kept']), origin), 'info')
            log('remembered the right shape for %d model(s)' % len(out['kept']))
        return out

    def forget_baseline(self, key):
        saved = self.baselines()
        if key in saved:
            del saved[key]
            self.store.set_meta('binding_baselines', json.dumps(saved))
            self.store.add_event('audit', 'forgot the remembered shape for %s' % key, 'info')
            return True
        return False

    def bindings_forget(self, ieee):
        """Drop what we remember about one device.

        What is kept here is a copy of what the bridge said; forgetting it
        costs nothing, and is the way out when a row is stale - a device
        renamed, re-paired, or replaced by another of the same name.
        """
        known = dict(self.bindings_known())
        gone = known.pop(ieee, None)
        if gone is None:
            for key, entry in list(known.items()):
                if entry.get('name') == ieee:
                    gone = known.pop(key)
                    ieee = key
                    break
        if gone is None:
            return False, 'nothing is remembered about %s' % ieee
        self._bindings = known
        self.store.set_meta('device_bindings', json.dumps(known))
        self.store.add_event('device', 'what was remembered about its bindings was forgotten', 'warn', ieee)
        self.bump()
        return True, 'forgotten. It comes back the next time the bridge sends its list.'

    def bindings_reload(self):
        """Ask the broker for the bridge's device list again.

        Zigbee2MQTT publishes it retained, so subscribing afresh brings the
        whole of it back at once - there is no request to make and nothing to
        wait for.
        """
        if not self.connected:
            return False, 'not connected to the broker'
        topic = CONFIG['base_topic'].rstrip('/') + '/bridge/devices'
        try:
            self.client.unsubscribe(topic)
            self.client.subscribe(topic, 0)
        except Exception as e:
            self._sms_sending = 0
            return False, str(e)
        return True, 'asked the broker for the list again; it arrives in a moment'

    def bindings_known(self):
        if getattr(self, '_bindings', None):
            return self._bindings
        try:
            self._bindings = json.loads(self.store.get_meta('device_bindings') or '{}')
        except ValueError:
            self._bindings = {}
        return self._bindings

    @staticmethod
    def _configured_by_other_means(entry):
        """Devices for which nothing configured is the right answer.

        Tuya's EF00 sends its datapoints unasked; an alarm contact or a PIR
        enrols with the coordinator instead and reports nothing; Green Power
        has no binding table at all. Saying these are broken would be a lie
        told often enough to teach somebody to ignore the honest ones.
        """
        model = str(entry.get('model_id') or '')
        maker = str(entry.get('maker') or '')
        if model in Daemon.SILENT_MODELS or maker.startswith(('_TZE200_', '_TZE204_', '_TZ3000_')):
            return 'Tuya, which sends its readings unasked'
        clusters = entry.get('clusters') or []
        if any(str(c).startswith('ssIasZone') for c in clusters):
            return 'an alarm device, which reports by enrolling rather than by binding'
        if entry.get('kind') == 'GreenPower':
            return 'Green Power, which has no binding table'
        return ''

    def binding_check(self):
        """The three checks, and what to do about each device.

        A: the odd one out. Group by model, take the commonest shape of
           bindings and reporting, and mark whatever differs from it. It is
           the only check that needs no knowledge of what a model ought to
           have - the other copies of it are the knowledge.
        B: nothing configured at all, on a model where others have something.
        C: silence longer than twice what the device said it would report in.
        """
        known = self.bindings_known()
        remembered = self.baselines()
        by_model, out = {}, []
        for ieee, entry in known.items():
            by_model.setdefault(self._model_key(entry), []).append((ieee, entry))
        now = time.time()
        for key, group in by_model.items():
            shapes = {}
            for ieee, entry in group:
                shape = (tuple(entry.get('binds') or []),
                         tuple(r['at'] for r in (entry.get('reports') or [])))
                shapes.setdefault(shape, []).append(ieee)
            common = max(shapes.values(), key=len) if shapes else []
            usual = None
            for shape, who in shapes.items():
                if who is common:
                    usual = shape
            for ieee, entry in group:
                why, how = [], 'watch'
                excused = self._configured_by_other_means(entry)
                shape = (tuple(entry.get('binds') or []),
                         tuple(r['at'] for r in (entry.get('reports') or [])))
                others = len(group) - 1
                if others and usual is not None and shape != usual and len(common) > others / 2.0:
                    why.append('%d of the %d %s here are configured differently'
                               % (len(common), len(group), entry.get('model') or 'devices of this model'))
                # Nobody of its own kind to compare with, but its shape was
                # remembered once when the house was working. That is somebody's
                # word rather than evidence, so it is said as such.
                mine = remembered.get(self._model_key(entry)) if not others else None
                if mine and not excused:
                    want = mine.get('shape') or {}
                    same = (sorted(want.get('binds') or []) == sorted(entry.get('binds') or [])
                            and sorted(want.get('reports') or [])
                            == sorted(r['at'] for r in (entry.get('reports') or [])))
                    if not same:
                        newer = (entry.get('firmware') and mine.get('firmware')
                                 and entry['firmware'] not in mine['firmware'])
                        why.append('it does not match the shape remembered for this model on %s '
                                   '(%d binding(s) then, %d now)%s'
                                   % (time.strftime('%d.%m.%Y', time.localtime(mine.get('at') or 0)),
                                      len(want.get('binds') or []), len(entry.get('binds') or []),
                                      ' - though its firmware has changed since, which can move these '
                                      'about on its own' if newer else ''))
                device = self.store.device(ieee)
                seen = (device or {}).get('last_seen') or 0
                quiet = self.watch_patience(self.device_kind(device or {})) if device else 0
                gone_quiet = bool(seen and quiet and now - seen > quiet)
                if not excused and not entry.get('binds') and not entry.get('reports'):
                    if others and len(common) > 0 and usual and (usual[0] or usual[1]):
                        why.append('nothing at all is configured on it, while the others have %d binding(s)'
                                   % len(usual[0]))
                    elif not others and gone_quiet:
                        # The only one of its kind, so there is nothing to compare it with. A button
                        # that sends its presses unasked is right to have nothing configured, and
                        # saying otherwise about every such device would teach anybody to ignore all
                        # of this. So: only if it has also stopped speaking.
                        why.append('nothing is configured on it, there is no other of its kind to '
                                   'compare with, and it has gone quiet')
                # C: silent for longer than it said it would be
                every = [r['every'] for r in (entry.get('reports') or [])
                         if r.get('every') and r['every'] < 60000]
                if every and seen and now - seen > 2 * min(every):
                    why.append('it said it would speak every %s and has not for %s - it may have '
                               'lost its configuration, or its battery may be flat'
                               % (human_span(min(every)), human_span(now - seen)))
                if why:
                    out.append({'ieee': ieee, 'name': entry.get('name'), 'model': entry.get('model'),
                                'why': why, 'excused': excused, 'binds': len(entry.get('binds') or []),
                                'reports': len(entry.get('reports') or []),
                                'last_seen': seen, 'do': how,
                                'battery': 'battery' in (entry.get('powered') or '')})
        return sorted(out, key=lambda x: (not x['excused'], x['name'] or ''))

    def check_bindings(self):
        """Say once about each device that has lost its configuration."""
        if not CONFIG.get('binding_watch', True):
            return
        for item in self.binding_check():
            if item['excused']:
                continue
            key = 'binding|' + item['ieee']
            if time.time() - self._binding_said.get(key, 0) < 86400:
                continue
            self._binding_said[key] = time.time()
            detail = '%s: %s' % (item['name'], '; '.join(item['why']))
            self.store.add_event('device', detail[:300], 'warn', item['ieee'])
            if self.telling_about('offline'):
                self.notify('%s may have lost its Zigbee configuration: %s. Wake it - press its '
                            'button, or take the battery out and back - and it will be set up again.'
                            % (item['name'], '; '.join(item['why'])), 'warn', dedup=key, about='bindings')
            # told about either way; set up again by itself only while that is
            # switched on - it was done whatever the switch said
            if not CONFIG.get('binding_mend', True):
                continue
            if item['battery']:
                self._binding_waiting[item['ieee']] = 0     # tries so far
                log('%s: waiting for it to speak, then it will be configured again' % item['name'])
            else:
                self.reconfigure(item['ieee'], item['name'],
                                 'by itself, it is mains powered so it is listening')

    def configure_answer(self, payload):
        """What Zigbee2MQTT made of being asked to configure something.

        Asking is not mending: the bridge has to reach the device, and for a
        sleeping one that is a matter of a second or two. Without this, the
        events said what was asked for and never what came of it.
        """
        who = str((payload.get('data') or {}).get('id') or '')
        # the answer names the device the way the asking did, which may be its
        # friendly name; the waiting list is keyed by address
        device = self.store.device(who) or self.store.device(self.names.get(who) or '')
        if device is None:
            device = next((x for x in self.store.devices() if x.get('name') == who), None)
        ieee = (device or {}).get('id') or who
        name = (device or {}).get('name') or who
        if str(payload.get('status') or '').lower() == 'ok':
            self._binding_waiting.pop(ieee, None)
            self._binding_said.pop('binding|' + ieee, None)
            self.store.add_event('device', 'set up again: Zigbee2MQTT says it took', 'info', ieee)
            log('%s: set up again, and it took' % name)
            if self.telling_about('offline'):
                self.notify('%s has been set up again and is reporting as it should' % name,
                            'info', dedup='binding-ok|' + ieee, about='bindings')
        else:
            why = str(payload.get('error') or 'no reason given')[:160]
            self.store.add_event('device', 'would not be set up again: %s' % why, 'warn', ieee)
            log('%s: would not be set up again (%s)' % (name, why), 'warn')

    def reconfigure(self, ieee, name='', why='by hand'):
        """Ask Zigbee2MQTT to configure a device again.

        The bridge does the work; this only asks. For a battery device the
        asking has to land while it is awake, which is why it is sent the
        moment one speaks rather than on a timer.
        """
        if not self.connected:
            return False
        topic = CONFIG['base_topic'].rstrip('/') + '/bridge/request/device/configure'
        self.say(topic, json.dumps({'id': name or ieee}), qos=1)
        self.store.add_event('device', 'asked Zigbee2MQTT to set it up again (%s)' % why, 'info', ieee)
        log('%s: asked for it to be set up again (%s)' % (name or ieee, why))
        return True

    def maybe_reconfigure(self, device_id):
        """A device we are waiting for has spoken: this is the moment.

        A sleeping sensor is awake for a second or two after it reports and
        deaf the rest of the time, so a configure sent on a timer is a
        configure sent into the dark.
        """
        # A burst of three reports started three of these at once, each read
        # the same count and each sent a configure. Taken one at a time per
        # device, and a second within the minute is the same wake.
        guard = self.__dict__.setdefault('_reconfigure_guard', threading.Lock())
        with guard:
            tries = self._binding_waiting.get(device_id)
            if tries is None:
                return
            busy = self.__dict__.setdefault('_reconfigure_at', {})
            if time.time() - busy.get(device_id, 0) < 60:
                return
            busy[device_id] = time.time()
            limit = max(1, int(CONFIG.get('binding_tries') or 3))
            if tries < limit:
                self._binding_waiting[device_id] = tries + 1
        name = (self.store.device(device_id) or {}).get('name') or device_id
        # binding_tries decides, as the message always said it did
        if tries >= limit:
            self._binding_waiting.pop(device_id, None)
            self.store.add_event('device', 'could not be configured again after %d tries - it may '
                                           'need pairing afresh'
                                 % max(1, int(CONFIG.get('binding_tries') or 3)), 'warn', device_id)
            if self.telling_about('offline'):
                self.notify('%s would not take its configuration. %d tries while it was awake: '
                            'its battery may be flat, or it may be out of reach.' % (name, limit),
                            'warn', dedup='binding-give-up|' + device_id, about='bindings')
            return
        self.reconfigure(device_id, name, 'by itself, it just woke - try %d of %d'
                         % (tries + 1, max(1, int(CONFIG.get('binding_tries') or 3))))

    def sync_devices(self, devices):
        seen = set()
        for d in devices:
            if not isinstance(d, dict):
                continue
            ieee = d.get('ieee_address')
            name = d.get('friendly_name') or ieee
            if not ieee or not name:
                continue
            if d.get('type') == 'Coordinator':
                self.bridge['coordinator_name'] = name
                self.bridge['coordinator_ieee'] = ieee
                # The coordinator is not a device of its own here - a gateway
                # entry can stand in for it. Point its name at that one record
                # so its own reports do not create a second, silent copy.
                self.names[name] = 'gw:coordinator'
                stray = self.store.device('name:' + name)
                if stray is not None and not stray.get('removed'):
                    self.store.mark_removed('name:' + name)
                    self.live.pop('name:' + name, None)
                    log('folded the stray "%s" record into the coordinator' % name)
                continue
            definition = d.get('definition') or {}
            dev = {
                'id': ieee, 'name': name, 'source': 'zigbee',
                'kind': d.get('type'),
                'model': definition.get('model') or d.get('model_id'),
                'vendor': definition.get('vendor') or d.get('manufacturer'),
                'description': definition.get('description'),
                'exposes': exposes_map(definition),
                'power_source': d.get('power_source'),
            }
            seen.add(ieee)
            # A device that reported before the list arrived was filed under
            # its name; move that history across now that we know its address.
            placeholder = 'name:' + name
            if self.store.device(placeholder):
                self.migrate(placeholder, ieee)
            old_name = None
            for n, i in list(self.names.items()):
                if i == ieee and n != name:
                    old_name = n
                    del self.names[n]
            self.names[name] = ieee
            outcome = self.store.upsert_device(dev)
            if outcome == 'new':
                log('new device: %s (%s %s)' % (name, dev['vendor'] or '', dev['model'] or ''))
                self.store.add_event('device', 'added: %s %s' % (dev['vendor'] or '', dev['model'] or ''),
                                     'info', ieee)
            elif outcome == 'renamed':
                log('device renamed: %s -> %s' % (old_name or '?', name))
                self.store.add_event('device', 'renamed from "%s" to "%s"' % (old_name or '?', name),
                                     'info', ieee)
        for dev in self.store.devices():
            if dev['source'] != 'zigbee':
                continue
            if dev['id'].startswith('name:'):
                # A leftover placeholder from an earlier version or a race:
                # if the bridge list names that device, fold it in now.
                real = self.names.get(dev['name'])
                if real and real != dev['id'] and not real.startswith('name:'):
                    self.migrate(dev['id'], real)
                continue
            if dev['id'] not in seen:
                self.store.mark_removed(dev['id'])
                self.names.pop(dev['name'], None)
                log('device left: %s' % dev['name'])
                self.say_event('device', 'removed from the network', 'warn', dev['id'], about='zigbee_left',
                               title='A device left the Zigbee network')
                self._left_network.append(time.time())

    def migrate(self, old_id, new_id):
        """Fold one device row into another: rename when the target does not
        exist yet, merge and delete the leftover when it does."""
        with self.store.lock:
            for table in ('samples', 'samples_hourly', 'events', 'snapshots'):
                self.store.db.execute('UPDATE OR REPLACE %s SET device=? WHERE device=?' % table,
                                      (new_id, old_id))
            target = self.store.db.execute('SELECT first_seen FROM devices WHERE id=?', (new_id,)).fetchone()
            if target is None:
                self.store.db.execute('UPDATE OR REPLACE devices SET id=? WHERE id=?', (new_id, old_id))
            else:
                old_row = self.store.db.execute('SELECT first_seen, alias FROM devices WHERE id=?',
                                                (old_id,)).fetchone()
                if old_row:
                    if old_row['first_seen'] and (not target['first_seen']
                                                  or old_row['first_seen'] < target['first_seen']):
                        self.store.db.execute('UPDATE devices SET first_seen=? WHERE id=?',
                                              (old_row['first_seen'], new_id))
                    if old_row['alias']:
                        self.store.db.execute('UPDATE devices SET alias=COALESCE(alias,?) WHERE id=?',
                                              (old_row['alias'], new_id))
                self.store.db.execute('DELETE FROM devices WHERE id=?', (old_id,))
            self.store.last_sample.clear()
            self.store.last_written.clear()
        self.store._forget_device(old_id)
        self.store._forget_device(new_id)
        self.store._snap_cache.pop(old_id, None)
        if old_id in self.live:
            merged = self.live.pop(old_id)
            self.live.setdefault(new_id, merged)
        log('history recorded under "%s" now belongs to %s' % (old_id[5:], new_id))
        self.bump()

    def bridge_event(self, payload):
        kind = payload.get('type') or ''
        data = payload.get('data') or {}
        name = data.get('friendly_name') or data.get('ieee_address')
        ieee = data.get('ieee_address')
        if kind == 'device_joined':
            self.say_event('device', 'joined the network', 'info', ieee, about='zigbee_joined',
                           message='%s joined the Zigbee network' % (name or ieee),
                           title='A new device joined')
            log('device joined: %s' % name)
        elif kind == 'device_leave':
            self.say_event('device', 'left the network', 'warn', ieee, about='zigbee_left',
                           title='A device left the Zigbee network')
            self._left_network.append(time.time())
            log('device left: %s' % name)
        elif kind == 'device_interview':
            status = data.get('status')
            if status == 'successful':
                d = data.get('definition') or {}
                self.store.add_event('device', 'interviewed: %s %s' % (d.get('vendor') or '',
                                     d.get('model') or ''), 'info', ieee)
            elif status == 'failed':
                self.say_event('device', 'interview failed', 'warn', ieee, about='zigbee_left',
                               title='A device could not be paired')
        elif kind == 'device_announce':
            self.store.add_event('device', 'announced itself', 'info', ieee)

    def _sleeps(self, device_id):
        """Whether a Wi-Fi device runs on a battery and so sleeps between
        reports: it has told us about its battery."""
        payload = (self.live.get(device_id) or {}).get('payload') or {}
        keys = list(payload)
        if not keys:
            try:
                keys = self.store.keys_for(device_id)     # after a restart, from what it has recorded
            except Exception:
                keys = []
        return any(str(k).split('.')[0] in ('battery', 'bat', 'devicepower') for k in keys)

    def set_availability(self, device_id, state, name):
        if state == 'offline' and time.time() - self._gw_answered.get(device_id, 0) < 300:
            log('%s: the bridge says offline, but its own API answered a moment ago - keeping it online' % name, 'debug')
            return
        prev = (self.live.get(device_id) or {}).get('availability')
        entry = self.live.setdefault(device_id, {'payload': {}, 'ts': None, 'availability': None})
        entry['availability'] = state
        self.store.store_snapshot(device_id, entry['ts'] or int(time.time()), {}, state)
        if prev != state and prev is not None:
            level = 'warn' if state == 'offline' else 'info'
            self.store.add_event('availability', state, level, device_id)
            log('%s is %s' % (name, state))

    HEAT_KEYS = ('current_heating_setpoint', 'occupied_heating_setpoint', 'system_mode')

    def _heat_watch(self, device_id, payload):
        """A head has just said what it is set to. If the house is told to put
        its setting back at once, this is the moment - waiting for the next
        half-minute round would leave a hand-turned knob in charge for as long
        as thirty seconds, which is not what "at once" means to anybody."""
        if not any(k in payload for k in self.HEAT_KEYS):
            return
        _, at_once = self.heating_enforce()
        if not at_once:
            return
        for room in (self.heating_state().get('rooms') or []):
            if room.get('mode') == 'manual':
                continue
            if any(device_id in str(v.get('target') or '') for v in (room.get('valves') or [])):
                # one at a time: most reports of a head carry its setpoint, and
                # each started a run of its own - several racing over what was
                # last told to which head, and telling it twice
                if getattr(self, '_heat_now_running', False):
                    return
                self._heat_now_running = True

                def apply_now():
                    try:
                        self.heating_apply()
                    finally:
                        self._heat_now_running = False
                threading.Thread(target=apply_now, name='heating-now', daemon=True).start()
                return

    # What a device says that needs nobody to have written a rule for it:
    # water on the floor, smoke, a case prised open. Only rules could tell
    # anybody about a leak sensor getting wet, and a house without that rule
    # had a sensor that turned red on a page nobody was looking at.
    # key -> (kind of message, level, what it means, what its end means)
    DANGER_KEYS = {
        'water_leak': ('leak', 'crit', 'water leak', 'dry again'),
        'smoke': ('smoke', 'crit', 'smoke', 'no smoke any more'),
        'gas': ('smoke', 'crit', 'gas', 'no gas any more'),
        'carbon_monoxide': ('smoke', 'crit', 'carbon monoxide', 'no carbon monoxide any more'),
        'tamper': ('tamper', 'warn', 'opened or tampered with', 'closed again'),
    }
    DANGER_TITLES = {'leak': 'Water leak', 'smoke': 'Smoke or gas', 'tamper': 'A device was tampered with'}

    # What a report has to say for the pages to be woken together rather than
    # at once. These are the slow numbers - a temperature, a link quality, a
    # battery - which move all the time and are never what somebody is
    # watching for. EVERYTHING else is a state: a light's state, a PIR's
    # occupancy, a door's contact, a leak, a thermostat's running_state, a
    # relay's output. A state has to be on the screen the moment it happens,
    # which is the whole point of the dashboard.
    SLOW_KEYS = re.compile(
        r'^(temperature|humidity|pressure|linkquality|link_quality|lqi|rssi|signal|battery|battery_v|'
        r'voltage|current|power|apower|aenergy|ret_aenergy|energy|illuminance(_lux)?|co2|pm\d*|voc|uptime|'
        r'device_temperature|elapsed|duration|position_pct|update_available_pct|'
        r'freq|pf|power_factor|ram_free|ram_size|fs_free|fs_size|total|by_minute|minute_ts|'
        r'tc|tf|percent|ts|elapsed_s|last_seen|generated|'
        r'.*_temperature|.*_humidity|.*_voltage|.*_power|.*_energy|.*_current|.*_battery|.*_lux)$', re.I)

    @classmethod
    def _is_state_key(cls, key, value):
        """Is this worth waking every page for on its own?

        Anything that is not one of the slow numbers is. A boolean and a word
        are always a state - on/off, open/closed, idle/heat - and a number is
        one unless its name says it is a reading. A name may be a path, and
        then its last part decides: aenergy.total is a reading, switch.output
        is not."""
        if key in cls.DANGER_KEYS:
            return True
        key = str(key)
        last = key.rsplit('.', 1)[-1]
        # The name decides first. Asked the other way round - is it a word? -
        # a slow number written as a word was a state: last_seen as an ISO
        # date, which Zigbee2MQTT can be told to send, or a voltage in
        # quotes, and every report from every sensor woke every page again.
        if cls.SLOW_KEYS.match(key) or cls.SLOW_KEYS.match(last):
            return False
        return True

    @staticmethod
    def _truthy(value):
        return value in (True, 1) or str(value).strip().lower() in ('true', 'on', '1', 'yes')

    def watch_states(self, device_id, name, before, said):
        """Tell the edges of what a device reports - a leak starting and
        ending, a battery going under a line, a room leaving its range - once
        each, never every report that repeats them."""
        label = self.device_label(device_id) or name
        for key, (about, level, bad, good) in self.DANGER_KEYS.items():
            if key not in said:
                continue
            on = self._truthy(said[key])
            was = self._truthy(before[key]) if key in before else None
            if on == was or (not on and was is None):
                continue
            self.say_event('device', bad if on else good, level if on else 'info', device_id, about=about,
                           title=('%s: %s' % (self.DANGER_TITLES[about], label)) if on else '%s: %s' % (label, good),
                           message='%s: %s' % (label, bad if on else good),
                           # a danger coming back is news every time it comes: the
                           # edges already keep repeats out, and "wet" again ten
                           # minutes after "dry" was swallowed as a duplicate for
                           # a quarter of an hour. Only a burst inside one minute
                           # is folded.
                           dedup=('%s|%s|%s|%d' % (about, device_id, on, int(time.time() // 60))) if on
                           else '%s|%s|%s' % (about, device_id, on))
        # a battery going under the lines set for devices, told once per line
        # per battery: it is not told again until it has been above the
        # warning line by ten - a new battery, not one wobbling round the line
        told = self.__dict__.setdefault('_battery_told', {})
        battery = None
        for key in ('battery', 'battery.percent'):
            if key in said:
                battery = numeric(said[key])
        low_flag = 'battery_low' in said and self._truthy(said['battery_low'])

        def stage_of(level, flag):
            if level is not None and level <= float(CONFIG.get('battery_crit') or 0):
                return 2
            if (level is not None and level <= float(CONFIG.get('battery_warn') or 0)) or flag:
                return 1
            return 0

        if battery is not None or low_flag:
            stage = stage_of(battery, low_flag)
            if device_id not in told:
                # what it said before a restart was told before it: the first
                # report after one is not news unless it went further down
                told[device_id] = stage_of(numeric(before.get('battery', before.get('battery.percent'))),
                                           self._truthy(before.get('battery_low')))
            had = told.get(device_id, 0)
            if stage > had:
                told[device_id] = stage
                words = ('battery %d%%' % battery) if battery is not None else 'says its battery is low'
                self.say_event('device', words + (' - change it soon' if stage == 2 else ''),
                               'crit' if stage == 2 else 'warn', device_id, about='battery',
                               title='Battery %s: %s' % ('nearly flat' if stage == 2 else 'low', label),
                               dedup='battery|%s|%d' % (device_id, stage))
            elif battery is not None and had and battery > float(CONFIG.get('battery_warn') or 0) + 10 \
                    and not low_flag:
                told[device_id] = 0
        # a room out of the range set for every device, and back in it
        out = self.__dict__.setdefault('_climate_out', {})
        checks = []
        temp = numeric(said.get('temperature')) if 'temperature' in said else None
        if temp is not None:
            if CONFIG.get('temperature_max') is not None:
                checks.append(('tmax', temp > float(CONFIG['temperature_max']),
                               temp <= float(CONFIG['temperature_max']) - 0.5,
                               '%.1f \u00b0C, over %.1f \u00b0C' % (temp, float(CONFIG['temperature_max']))))
            if CONFIG.get('temperature_min') is not None:
                checks.append(('tmin', temp < float(CONFIG['temperature_min']),
                               temp >= float(CONFIG['temperature_min']) + 0.5,
                               '%.1f \u00b0C, under %.1f \u00b0C' % (temp, float(CONFIG['temperature_min']))))
        hum = numeric(said.get('humidity')) if 'humidity' in said else None
        if hum is not None and CONFIG.get('humidity_max') is not None:
            checks.append(('hmax', hum > float(CONFIG['humidity_max']),
                           hum <= float(CONFIG['humidity_max']) - 3,
                           'humidity %.0f%%, over %.0f%%' % (hum, float(CONFIG['humidity_max']))))
        for which, gone_out, back_in, words in checks:
            key = (device_id, which)
            if key not in out:
                # the same after a restart: out of range before it is not news
                prev = numeric(before.get('humidity' if which == 'hmax' else 'temperature'))
                limit = float(CONFIG[{'tmax': 'temperature_max', 'tmin': 'temperature_min',
                                      'hmax': 'humidity_max'}[which]])
                out[key] = prev is not None and (prev < limit if which == 'tmin' else prev > limit)
            if gone_out and not out.get(key):
                out[key] = True
                self.say_event('device', words, 'warn', device_id, about='climate',
                               title='Out of range: %s' % label, dedup='climate|%s|%s|out' % key)
            elif back_in and out.get(key):
                out[key] = False
                self.say_event('device', 'back within its range (%s)' % words.split(',')[0], 'info', device_id,
                               about='climate', title='Back in range: %s' % label,
                               dedup='climate|%s|%s|in' % key)

    def record(self, device_id, name, payload):
        now = int(time.time())
        self.zigbee_seen[device_id] = now
        if self._set_sent and isinstance(payload, dict):
            # a report carrying a key we just set is the command's echo
            for (dev_id, key), sent in list(self._set_sent.items()):
                if dev_id == device_id and key in payload:
                    self._lat['set_rtt_ms'] = round((time.time() - sent) * 1000)
                    self._lat['set_rtt_what'] = name
                    self._set_sent.pop((dev_id, key), None)
                elif time.time() - sent > 120:
                    self._set_sent.pop((dev_id, key), None)
        if device_id == 'gw:coordinator' and self.store.device(device_id) is None:
            self.store.upsert_device({'id': device_id, 'name': name, 'source': 'gateway',
                                      'kind': 'Coordinator', 'vendor': None, 'last_seen': now})
        self._heat_watch(device_id, payload)
        if device_id in self._binding_waiting:
            # it is awake for a second or two: now or not at all
            threading.Thread(target=self.maybe_reconfigure, args=(device_id,),
                             name='reconfigure', daemon=True).start()
        if isinstance(payload, dict):
            # when each key was last said by the device itself, to the
            # fraction of a second: a toggle trusts what it sent until then
            heard = self.__dict__.setdefault('_zb_key_at', {})
            t_heard = time.time()
            for k in payload:
                heard[(device_id, k)] = t_heard
            if len(heard) > 20000:
                heard.clear()
        flat = flatten(payload)
        values = {}
        saw_action = False
        for key, value in flat.items():
            if key in IGNORE_KEYS or key.startswith('update'):
                continue
            if key == 'action':
                if value not in (None, '') and getattr(self, '_retained_msg', False):
                    log('%s: %s replayed by the broker (retained) - not a press' % (name, value), 'debug')
                elif value not in (None, ''):
                    saw_action = True
                    # the relay first, the paperwork after: a binding is the one
                    # thing here a person is physically waiting on
                    self.fire_bindings(device_id, name, str(value))
                    self.store.add_event('action', str(value), 'info', device_id, now)
                    log('%s: %s' % (name, value), 'debug')
                continue
            v = numeric(value)
            if v is not None:
                values[key] = v
        if values:
            self.queue_rules(device_id, name, values)    # motion -> light must not wait for a disk commit
            self.store.store_sample(device_id, now, values)
        clean = {k: v for k, v in flat.items() if not k.startswith('update')}
        merged = self.store.store_snapshot(device_id, now, clean)
        self.store.touch_device(device_id, now)
        entry = self.live.setdefault(device_id, {'payload': {}, 'ts': None, 'availability': None})
        before = entry.get('payload') or {}
        entry['payload'] = merged
        entry['ts'] = now
        try:
            self.watch_states(device_id, name, before, flat)
        except Exception as e:
            log('%s: watching what it said: %s' % (name, e), 'warn')
        # One up for every report. describe() is worked out once per report
        # and kept, and it knew a report by its timestamp - which is whole
        # seconds. Two readings inside one second therefore looked like one,
        # and the second of them did not reach the page at all: not on the
        # next status, and not when the second turned over either, because
        # the timestamp it is compared against had not changed. It waited for
        # the cache to grow half a minute old. A button pressed twice, a
        # socket answering right after it was switched, a sensor going on and
        # off again - all of them inside one second, all of them lost.
        entry['rev'] = (entry.get('rev') or 0) + 1
        # what makes this report more than a number (see the wake below)
        was_new = not before
        new_keys = bool(set(clean) - set(before or {}))
        availability_changed = False
        # A device that reports is by definition reachable.
        if entry.get('availability') == 'offline':
            self.set_availability(device_id, 'online', name)
            availability_changed = True
        log('%s: %s' % (name, ', '.join('%s=%s' % kv for kv in sorted(values.items()))), 'debug')
        # A report is usually a number: a temperature, a humidity, a link
        # quality. bump_soon exists for exactly that and was wired into the
        # sockets only - so two dozen sensors reporting every ten seconds woke
        # every open page several times a second, each time for a third of a
        # megabyte of status. A change of STATE still wakes them at once: a
        # new device, a key never seen before, something coming back from
        # offline, or anything watch_states thought worth an event.
        # Anything that changed and is not one of the slow numbers is on the
        # screen at once. Comparing against what the device said before is the
        # whole of it: a light reporting the same "ON" it already had changes
        # nothing and need not wake anybody.
        moved = [k for k, v in clean.items() if (before or {}).get(k) != v]
        state_change = (was_new or new_keys or availability_changed or saw_action
                        or any(self._is_state_key(k, clean[k]) for k in moved))
        if state_change:
            self.bump()
        else:
            self.bump_soon()

    def handle_plug_push(self, plugs, rest, raw):
        """The plug's own MQTT tells us the moment its relay changes - a wall
        button, its web page, the Shelly app - so the dashboard does not sit
        on the 15 s poll for state it can have now."""
        payload = self.decode(raw)
        if not isinstance(payload, dict):
            return
        updates = {}
        if rest == ['events', 'rpc'] and payload.get('method') == 'NotifyStatus':
            for key, value in (payload.get('params') or {}).items():
                m = re.match(r'^switch:(\d+)$', key)
                if m and isinstance(value, dict):
                    updates[int(m.group(1))] = value
        elif len(rest) == 2 and rest[0] == 'status':
            m = re.match(r'^switch:(\d+)$', rest[1])
            if m:
                updates[int(m.group(1))] = payload
        if not updates:
            return
        now = int(time.time())
        for p in plugs:
            value = updates.get(int(p.cfg.get('switch_id') or 0))
            if value is None:
                continue
            changed = False
            if 'output' in value:
                output = 1 if value.get('output') else 0
                if p.output is not None and output != p.output:
                    source = str(value.get('source') or 'outside this dashboard')
                    self.store.add_event('plug', 'switched %s (%s)' % ('on' if output else 'off', source),
                                         'info', p.device_id)
                    log('%s switched %s (%s, seen on its MQTT)' % (p.name, 'on' if output else 'off', source))
                    changed = True
                p.output = output
                # newer than any poll already on its way: an answer asked
                # before this push put the light back to what it was, and the
                # next rule asking for it was skipped as "already so"
                p.output_at = time.time()
                # ...and a box that pushes is a box that is there: a command
                # no longer waits it out as "known to be down"
                p.failures = 0
            if p.flat:
                for k, v in flatten(value).items():
                    if k in ('id', 'source'):
                        continue
                    p.flat['switch.' + k] = v
                p.generated = now
            entry = self.live.get(p.device_id)
            if entry:
                entry['ts'] = now
            # The rules must hear this too. They were told only by the reading
            # that comes round every fifteen seconds, so the box's own push -
            # the fast road, the one that says a wall button was pressed the
            # moment it happens - updated the page and the state and then
            # quietly skipped every rule watching that socket. A rule on a
            # socket's own watts or its relay was served by the poll alone,
            # up to fifteen seconds late, and once a box is on the broker the
            # poll is the slow road. Edge-triggered either way, so the push
            # and the reading that follows it do not fire twice.
            told = self._plug_values({'switch.' + k: v for k, v in flatten(value).items()
                                      if k not in ('id', 'source')})
            if told:
                self.queue_rules(p.device_id, p.name, told)
            if changed:
                self.bump()                   # a relay moved: everyone sees it now
            else:
                self.bump_soon()              # new watts: worth a repaint, not one per box per second

    def handle_generic(self, parts, raw):
        """shellies/<name>/status/<component> and similar: a WiFi device."""
        payload = self.decode(raw)
        prefix, name = (parts + ['', ''])[0], (parts + ['', ''])[1]
        rest = parts[2:]
        if rest and rest[0] == 'online' and name not in self.plug_mqtt_names():
            # a bare true or false, never a dict: asked about only after the
            # dict test below, a Shelly on MQTT never went offline or came back
            state = 'online' if str(payload).strip().lower() in ('true', '1', 'online') else 'offline'
            device_id = '%s:%s' % (prefix, name)
            if self.store.device(device_id):
                # A Shelly on a battery (an H&T) wakes, says what it reads and
                # goes back to sleep - and the broker then publishes its "last
                # will", online = false, every single time. That is a device
                # asleep, not one gone: it is left as it was, and a device that
                # really stops is caught by its silence like any sleeping
                # sensor (4.95 began to hear this word, and every battery H&T
                # turned red a minute after each report).
                if state == 'offline' and self._sleeps(device_id):
                    self.debug('%s went to sleep (its online=false is its last will)' % name)
                    return
                self.set_availability(device_id, state, name)
            return
        if not isinstance(payload, dict):
            return
        if name in self.plug_mqtt_names():
            return          # polled over RPC; the MQTT copy would only duplicate it
        if rest and rest[0] == 'status' and len(rest) >= 2:
            component = rest[1]              # temperature:0, switch:0, devicepower:0
            comp_name = component.split(':')[0]
            multiple = component.split(':')[1] if ':' in component and component.split(':')[1] != '0' else ''
            keyed = {}
            for k, v in flatten(payload).items():
                if k in ('id',):
                    continue
                key = k if comp_name in ('temperature', 'humidity', 'devicepower', 'illuminance') \
                    else '%s.%s' % (comp_name, k)
                if multiple:
                    key = '%s%s.%s' % (comp_name, multiple, k)
                keyed[key] = v
            payload = keyed
        elif rest and rest[0] in ('events', 'rpc', 'online', 'command'):
            if rest[0] == 'online':
                state = 'online' if str(payload).lower() in ('true', '1', 'online') else 'offline'
                device_id = '%s:%s' % (prefix, name)
                if self.store.device(device_id):
                    self.set_availability(device_id, state, name)
            return
        elif rest:
            return
        device_id = '%s:%s' % (prefix, name)
        # it is talking, so it is there: a device marked offline that reports
        # is online again without waiting for its own word about it
        if (self.live.get(device_id) or {}).get('availability') == 'offline' and self.store.device(device_id):
            self.set_availability(device_id, 'online', name)
        if self.store.device(device_id) is None:
            self.store.upsert_device({'id': device_id, 'name': name, 'source': 'shelly'
                                      if prefix == 'shellies' else 'mqtt', 'kind': 'wifi',
                                      'vendor': 'Shelly' if prefix == 'shellies' else None,
                                      'exposes': {}})
            log('new device: %s (%s)' % (name, prefix))
            self.store.add_event('device', 'first seen on %s/%s' % (prefix, name), 'info', device_id)
        self.record(device_id, name, payload)


