    def config_overrides(self):
        try:
            return {k: v for k, v in json.loads(self.store.get_meta('config_overrides') or '{}').items()
                    if k in self.TUNABLE}
        except ValueError:
            return {}

    def apply_config_overrides(self):
        for key, value in self.config_overrides().items():
            CONFIG[key] = value
        self.mend_stranger_setting()
        self.mend_true_secrets()
        self.store.mend_block_story()
        if str(CONFIG.get('pin') or '').strip():
            log('"pin" in config.json is not used any more: the dashboard signs people in by name '
                'and password (5.19). It can be taken out of the file', 'info')

    def mend_true_secrets(self):
        """Put back the secrets 3.58.0 to 3.58.3 wrote the word "true" over.

        The daemon stopped saying what a secret is and said only whether one
        was set; the settings page wrote what it was told into the box, which
        put the word there, and saving wrote that word over the secret. Every
        secret saved from that page in those four versions is now the four
        letters t-r-u-e. Where config.json has one, the override is dropped
        and the file's own value stands again; where it does not, it is gone
        and has to be typed in once more - and it is said here rather than
        found out by a gateway refusing to log in.
        """
        if self.store.get_meta('mended_true_secrets'):
            return
        self.store.set_meta('mended_true_secrets', '1')
        overrides = self.config_overrides()
        put_back, lost = [], []
        kinds = {k: v['kind'] for k, v in self.runtime_config().items()}
        for key, value in list(overrides.items()):
            if kinds.get(key) != 'secret' or str(value).strip().lower() not in ('true', 'false'):
                continue
            overrides.pop(key)
            CONFIG[key] = self.file_config.get(key, DEFAULTS.get(key, ''))
            (put_back if self.file_config.get(key) else lost).append(key)
        if put_back or lost:
            self.store.set_meta('config_overrides', json.dumps(overrides))
            if put_back:
                log('settings: %s had been written over with the word "true"; what config.json says '
                    'stands again' % ', '.join(sorted(put_back)), 'warn')
            if lost:
                log('settings: %s had been written over with the word "true" and there is nothing to '
                    'put back - type them in again' % ', '.join(sorted(lost)), 'warn')
                self.say_event('audit', 'these had been written over and must be typed in again: %s'
                               % ', '.join(sorted(lost)), 'warn', about='config_loss',
                               title='Settings were written over')

    def mend_stranger_setting(self):
        """'sms' used to mean "and by text as well", on top of the pushes.

        It now means the road of that name and nothing else, because the
        setting holds roads rather than three words somebody chose between.
        Those two readings are the same three letters, so a house that had
        asked for a text would quietly lose its pushes. Every value that can
        be standing there was written by the old dashboard, so it is read the
        old way once, written back as roads, and never read that way again.
        """
        if self.store.get_meta('sms_stranger_roads'):
            return
        self.store.set_meta('sms_stranger_roads', '1')
        was = str(CONFIG.get('sms_stranger_alert') or '').strip().lower()
        if was not in self.STRANGER_WORDS:
            return
        now = ','.join(self.STRANGER_WORDS[was])
        if now == was:
            return
        CONFIG['sms_stranger_alert'] = now
        if 'sms_stranger_alert' in self.config_overrides():
            overrides = self.config_overrides()
            overrides['sms_stranger_alert'] = now
            self.store.set_meta('config_overrides', json.dumps(overrides))
        log('a text from a number nobody knows: "%s" now reads as "%s"' % (was, now or 'written down only'))

    def save_config_overrides(self, body):
        overrides = self.config_overrides()
        changed = []
        for key, spec in self.TUNABLE.items():
            if key not in body:
                continue
            raw = body.get(key)
            # a phone setting the page was shown hidden, and sent back as it
            # was shown: the numbers already kept stand
            if key in self.TUNABLE_PHONES and self.is_masked_phone(raw):
                raw = ', '.join(self.unmask_phones(raw, CONFIG.get(key) or ''))
            if spec == 'str':
                value = str(raw or '').strip()[:200]
                # where new versions are looked for: https or nothing, because
                # a look over plain http could be answered by anybody between
                if key == 'upgrade_url' and not value.startswith('https://'):
                    raise ValueError('upgrade_url must start with https://')
                # ...and with no name and password in it, which would be
                # written into every event that says where a version came from
                if key == 'upgrade_url' and '@' in urlsplit(value).netloc:
                    raise ValueError('upgrade_url takes no name or password')
                if key == 'notify_ntfy' and value and not value.startswith(('http://', 'https://')):
                    raise ValueError('notify_ntfy must be a full topic URL (https://ntfy.sh/...)')
                if key in ('backup_time', 'reboot_at') and \
                        not re.match(r'^([01]?\d|2[0-3]):[0-5]\d$', value or ''):
                    raise ValueError('%s must look like 03:30' % key)
                if key == 'reboot_auto' and value not in ('off', 'daily', 'weekly'):
                    raise ValueError('reboot_auto is off, daily or weekly')
                if key == 'rbackup_at' and not re.match(r'^([01]?\d|2[0-3]):[0-5]\d$', value or ''):
                    raise ValueError('rbackup_at must look like 04:15')
                if key == 'rbackup_every' and value not in ('daily', 'weekly'):
                    raise ValueError('rbackup_every is daily or weekly')
                if key == 'rbackup_password':
                    # what root locks the copy with wants eight at least; the
                    # whole of it is the only way into every backup sent
                    value = str(raw or '')
                    if value and (len(value) < 8 or len(value) > 200 or re.search(r'[\r\n\x00]', value)):
                        raise ValueError('the password of the backups is one line of 8 to 200 characters')
                if key == 'tap_mode' and value not in ('link', 'both', 'header'):
                    raise ValueError('tap_mode is one of link, both, header')
                if key == 'tap_factor' and value not in ('totp', 'duo'):
                    raise ValueError('tap_factor is totp or duo')
                if key.startswith('duo_') and isinstance(value, str):
                    value = value.strip()
                    CONFIG[key] = value
                    overrides[key] = value
                if key == 'sms_sim' and value not in ('prepaid', 'contract'):
                    raise ValueError('sms_sim is prepaid or contract')
                if key == 'sms_stranger_alert':
                    # roads, or one of the three words that came before them
                    words = str(value or '').strip().lower()
                    if words not in Daemon.STRANGER_WORDS:
                        kept = [x for x in words.split(',') if x in ('ntfy', 'telegram', 'sms')]
                        value = ','.join(kept)
                        CONFIG[key] = value
                        overrides[key] = value
            else:
                low, high = spec[0], spec[1]
                allow_null = len(spec) > 2
                value = numeric(raw)
                if value is None:
                    if raw not in (None, '') or not allow_null:
                        if not allow_null:
                            raise ValueError('%s must be a number' % key)
                    value = None
                elif not low <= value <= high:
                    raise ValueError('%s must be between %g and %g' % (key, low, high))
                if value is not None and value == int(value) and key not in ('latitude', 'longitude', 'price_per_kwh', 'plug_min_request_gap', 'plug_command_gap'):
                    value = int(value)
            previous = CONFIG.get(key)
            if value == self.file_config.get(key):
                overrides.pop(key, None)     # back to what the file says
            else:
                overrides[key] = value
            CONFIG[key] = value
            if value != previous:
                changed.append(key)
        # A contract SIM has nothing to ask about, so the asking is put away
        # rather than left switched off by hand - and the figures that were
        # true of the SIM before it are taken off the card, because one that
        # stands there looking current is worse than none.
        if not self.sim_prepaid():
            if CONFIG.get('sms_credit_every_h'):
                CONFIG['sms_credit_every_h'] = 0
                overrides['sms_credit_every_h'] = 0
                if 'sms_credit_every_h' not in changed:
                    changed.append('sms_credit_every_h')
            if 'sms_sim' in changed:
                self.forget_credit()
        # Asking for a code with no phone to show one locks the house out of
        # its own links, from a page that cannot be reached to undo it. The
        # same for the last switch with nothing yet moved over: it is refused
        # while every link is still being opened the old way.
        # Choosing a factor and demanding one are two decisions, and only the
        # second can lock anybody out. Refusing both together made the choice
        # impossible to make: Duo's boxes are not asked for until Duo is the
        # factor, and Duo could not be made the factor until its boxes were
        # filled in. So the choice always stands, and the demand is what gives
        # way - switched off, with a line saying why, rather than left asking
        # for something nothing in the house can answer.
        self.last_config_note = ''
        # the whole of the blacklist turned on or off: the router follows,
        # because a rule there that outlives the thing that made it is a rule
        # nobody can explain
        if 'blacklist' in changed:
            self.blacklist_switched(self.blacklist_on())
        if CONFIG.get('tap_code') and CONFIG.get('tap_mode') != 'link':
            missing = ('no phone is set up to carry the code' if self.tap_factor() == 'totp'
                       and not self.tap_keys()
                       else ('Duo has no hostname, keys or username yet'
                             if self.tap_factor() == 'duo' and not self.duo_ready() else ''))
            if missing:
                CONFIG['tap_code'] = 0
                overrides['tap_code'] = 0
                if 'tap_code' not in changed:
                    changed.append('tap_code')
                self.last_config_note = ('%s, so asking for a second factor is off for now - '
                                         'switch it back on once it is' % missing)
        self.store.set_meta('config_overrides', json.dumps(overrides))
        if changed:
            if 'tap_mode' in changed or 'tap_code' in changed:
                # a door being opened wider is worth the same note as a secret
                # being shown: it is written down as a warning either way
                self.say_event('audit', 'one-tap links: opened %s%s'
                               % ({'link': 'by their address', 'both': 'either way',
                                   'header': 'by a header only'}[self.tap_mode()],
                                  ', with a code' if self.tap_code_wanted() else ''), 'warn',
                               about='link_secrets', title='How one-tap links open was changed')
            self.store.add_event('control', 'settings changed: ' + ', '.join(sorted(changed)))
            log('settings changed: %s' % ', '.join(sorted(changed)))
            # Some settings only show themselves the next time something is
            # fetched. Waiting an hour to see the name of a place take effect
            # is not what "applies immediately" means, so what they touch is
            # asked for again now.
            if any(k.startswith('weather') for k in changed):
                self._weather_cache = None
                threading.Thread(target=self.weather, kwargs={'force': True},
                                 name='weather', daemon=True).start()
            if any(k.startswith('sms') for k in changed):
                self._sms_drop_token()              # a new password, a new login - the old one logged out
                self._sms_modem_id = None
                self._sms_status_at = 0             # and how it is doing, on the next beat
                threading.Thread(target=self._sms_poll_thread, name='sms-poll', daemon=True).start()
        self.bump()
        return changed

