    TUNABLE_TIMES = ('backup_time', 'reboot_at', 'rbackup_at', 'digest_at', 'sms_quiet_from', 'sms_quiet_to')
    TUNABLE_PHONES = ('sms_to', 'sms_allow')     # a keypad rather than a keyboard

    def runtime_config(self, reveal=False):
        """Every setting the page may change, and what kind of thing it is.

        A secret goes out as whether it is set, not as what it is. The status
        is answered before the view lock - it has to be, or a locked dashboard
        could not say it was locked - so a secret in it is a secret anybody
        who can reach the page can read: the gateway's password, the Telegram
        token, the word the modem sends, and now a Duo key. The page never
        needed the value: it draws a password box that says (kept) and sends
        a new one only when one is typed. `--secret` and the PIN-gated list
        still show them, which is where they belong.
        """
        overrides = self.config_overrides()
        out = {}
        for key in self.TUNABLE:
            # what kind of thing it is, said by the one that checks it: the
            # page used to guess from the name, and put a number box under
            # anything it did not recognise as words
            rule = self.TUNABLE[key]
            if key in self.TUNABLE_CHOICES:
                kind = 'choice'
            elif key in self.TUNABLE_TIMES:
                kind = 'time'
            elif key in self.TUNABLE_PHONES:
                kind = 'phone'
            elif isinstance(rule, tuple) and rule[:2] == (0, 1):
                # Asked before the guess from the name below, or a switch
                # called debug_secrets is drawn as a secret to be typed in -
                # a masked box for a thing that is yes or no. What a setting
                # takes is known here; the name is only a hint.
                kind = 'switch'
            elif re.search(r'password|token|secret', key) or key in self.TUNABLE_SECRETS:
                # duo_skey is a secret key by every meaning except the letters
                # of its name, and a secret drawn as a text box is a secret in
                # the page, in the status and in anybody's screenshot
                kind = 'secret'
            elif rule == 'str':
                kind = 'text'
            elif isinstance(rule, tuple) and len(rule) > 2 and rule[2]:
                kind = 'decimal'
            else:
                kind = 'number'
            value, from_file = CONFIG.get(key), self.file_config.get(key)
            default = DEFAULTS.get(key)
            # which of the three is running: a value saved on the page wins
            # over config.json, and the file wins over the built-in default
            in_file = key in getattr(self, 'file_keys', ())
            source = 'dashboard' if key in overrides else ('file' if in_file else 'default')
            if kind == 'secret' and not reveal:
                value = bool(value)
                from_file = bool(from_file)
                default = bool(default)
            elif kind == 'phone' and not reveal:
                value = self.mask_phone(value or '')
                from_file = self.mask_phone(from_file or '')
            out[key] = {'value': value, 'file': from_file, 'default': default, 'source': source, 'in_file': in_file,
                        'kind': kind, 'overridden': key in overrides}
            if kind == 'choice':
                out[key]['choices'] = self.TUNABLE_CHOICES[key]
        return out

    # -- notifications: ntfy and/or Telegram ------------------------------------
    # what a per-device preset switches on (None = follow the global choices)

    def notify_channels(self):
        out = []
        if CONFIG.get('notify_ntfy'):
            out.append('ntfy')
        if CONFIG.get('notify_telegram_token') and CONFIG.get('notify_telegram_chat'):
            out.append('telegram')
        return out

    def notify_settings(self):
        try:
            saved = json.loads(self.store.get_meta('notify') or '{}')
        except ValueError:
            saved = {}
        devices = saved.get('devices') or {}
        channels = saved.get('channels') or {}
        return {'channels': {'ntfy': channels.get('ntfy', True) is not False,
                             'telegram': channels.get('telegram', True) is not False,
                             # a text costs money and wakes a phone at night, so
                             # an automatic alert does not take that road unless
                             # it is asked to
                             'sms': bool(channels.get('sms', False))},
                'crit': bool(saved.get('crit', True)), 'warn': bool(saved.get('warn', False)),
                'rule': bool(saved.get('rule', False)), 'offline': bool(saved.get('offline', True)),
                'switch': bool(saved.get('switch', False)),
                'devices': {str(k): v for k, v in devices.items()
                            if notify_override_set(v) is not None},
                # the ones that are not about a device: each may say which
                # roads it takes, or that it says nothing at all
                'systems': {str(k): v for k, v in (saved.get('systems') or {}).items()
                            if isinstance(v, dict) and (v.get('off') or v.get('roads') or v.get('follow'))}}

    def consider_notifying(self, kind, detail, level, device_id):
        if getattr(self._own_telling, 'on', False):
            return                       # told as its own kind, by say_event
        if self.alerts_hushed():
            return                       # hushed by hand, for a while
        if kind == 'alert':
            return                       # a written message has already been sent, in its own words
        if not self.notify_channels():
            return
        settings = self.notify_settings()
        name = None
        if device_id:
            row = self.store.device(device_id)
            name = (row.get('alias') or row['name']) if row else device_id
        offline_ish = 'lost contact' in detail or 'offline' in detail or 'went quiet' in detail \
            or 'unreachable' in detail or 'back online' in detail or 'reporting again' in detail
        switch_ish = kind in ('plug', 'switch') and ('switched' in detail or detail.startswith('set ') or detail.startswith('pulse'))
        rule_ish = kind == 'rule' and 'window' not in detail
        override = settings['devices'].get(device_id or '')
        enabled = notify_override_set(override) if override else None
        if enabled is None:
            enabled = {k for k in ('crit', 'warn', 'offline', 'rule', 'switch') if settings.get(k)}
        wanted = (level == 'crit' and 'crit' in enabled) \
            or (level == 'warn' and 'warn' in enabled) \
            or (offline_ish and 'offline' in enabled) \
            or (rule_ish and 'rule' in enabled) \
            or (switch_ish and 'switch' in enabled)
        if not wanted:
            return
        roads = dict(settings.get('channels') or {})
        only = notify_override_roads(override)
        if only is not None:                   # this device says which roads, whatever the house says
            roads = {k: (k in only) for k in ('ntfy', 'telegram', 'sms')}
        self.notify(('%s: %s' % (name, detail)) if name else detail, level,
                    ntfy=roads.get('ntfy', True), telegram=roads.get('telegram', True),
                    sms=roads.get('sms', False),
                    dedup='%s|%s|%s' % (kind, device_id, detail[:40]),
                    about='device')          # the device's own settings decided the roads above

    SMS_APIS = ('cgi', 'rpc')

    SMS_LOG_KEEP = 500

    def _sms_log_mark(self):
        """Something in the status that changes when a message is written down.

        The page redraws the SMS tab when the sms block of the status changes,
        and nothing in that block moved when a text arrived - so a reply that
        reached the phone at once took until the next thing changed to appear
        on screen, up to a minute later. The newest message's time and how
        many there are is enough, and costs one read of what is already held.
        """
        # kept beside the log rather than read out of it: the log is up to
        # half a megabyte of JSON, and it was parsed whole for every status
        mark = getattr(self, '_sms_mark', None)
        if mark is None:
            try:
                rows = json.loads(self.store.get_meta('sms_log') or '[]')
            except ValueError:
                rows = []
            mark = self._sms_mark = {'log_n': len(rows), 'log_at': (rows[0].get('at') if rows else 0),
                                     'log_rev': getattr(self, '_sms_rev', 0)}
        return dict(mark)

    def _sms_log_write(self, rows):
        """The log written back, and its mark with it. Called with the log's
        lock held."""
        rows = rows[:self.SMS_LOG_KEEP]
        # in memory at once, on disk behind: a text that switches something
        # is written down before it is acted on, and this write waited on
        # the database lock - a backup's second and a half - first
        self.store.set_meta('sms_log', json.dumps(rows), deferred=True)
        # ...and a count of every change, not only of the rows: a message
        # settled from "going" to "sent" changes neither how many there are
        # nor the newest one's time, and the page went on showing it as not
        # answered until it was reloaded
        self._sms_rev = getattr(self, '_sms_rev', 0) + 1
        self._sms_mark = {'log_n': len(rows), 'log_at': (rows[0].get('at') if rows else 0),
                          'log_rev': self._sms_rev}

    def _sms_lock(self):
        # One at a time for the log and the outbox: a message coming in by the
        # webhook while the reply worker wrote down the answer read the same
        # log, each added its own line, and the second write lost the first
        return self.__dict__.setdefault('_sms_log_guard', threading.RLock())

    def sms_log(self, limit=200):
        try:
            rows = json.loads(self.store.get_meta('sms_log') or '[]')
        except ValueError:
            rows = []
        return rows[:int(limit)]

    def sms_note(self, direction, number, text, ok=True, why='', key='', road=''):
        """Keep what went out and what came in, newest first, so the SMS tab
        can show a conversation rather than a scattering of events."""
        person = self.person_by_phone(number)
        with self._sms_lock():
            return self._sms_note_locked(direction, number, text, ok, why, key, road, person)

    def _sms_note_locked(self, direction, number, text, ok, why, key, road, person):
        try:
            rows = json.loads(self.store.get_meta('sms_log') or '[]')
        except ValueError:
            rows = []
        rows.insert(0, {'id': secrets.token_hex(5), 'dir': direction, 'number': str(number or ''),
                        'person': (person or {}).get('name', ''), 'text': str(text or '')[:1000],
                        # None is its own answer: the gateway never said, and
                        # calling that a failure is how a message that did
                        # arrive got written down as one that did not
                        'at': int(time.time()), 'ok': (None if ok is None else bool(ok)),
                        # handed to the gateway and not answered YET - which
                        # is not "it did not answer": the page showed every
                        # message on its way as one the gateway had ignored
                        'going': bool(direction == 'out' and ok is None),
                        'why': str(why or '')[:40],
                        # which way it came in: the modem's inbox, or pushed
                        # here the moment it arrived. Worth keeping because
                        # the two behave differently and a message that was
                        # slow is the first thing anybody asks about.
                        'road': str(road or '')[:10],
                        'key': str(key or '')})     # the device's own id, so it is kept only once
        self._sms_log_write(rows)
        self.bump()
        return rows[0]['id']

    def sms_note_settled(self, row_id, ok):
        """How a message that was written down as going out actually went.

        It is written down when it is handed to the gateway, not when the
        gateway answers - a box that takes a minute to answer meant a reply
        that reached the phone at once was not on the screen until the minute
        was up, which is exactly the wrong way round.
        """
        if not row_id:
            return
        with self._sms_lock():
            try:
                rows = json.loads(self.store.get_meta('sms_log') or '[]')
            except ValueError:
                return
            for row in rows:
                if row.get('id') == row_id:
                    row['ok'] = (None if ok is None else bool(ok))
                    row.pop('going', None)
                    self._sms_log_write(rows)
                    self.bump()
                    return

    def sms_forget(self, which=None):
        with self._sms_lock():
            return self._sms_forget_locked(which)

    def _sms_forget_locked(self, which=None):
        try:
            rows = json.loads(self.store.get_meta('sms_log') or '[]')
        except ValueError:
            rows = []
        if which:
            left = [r for r in rows if r.get('id') != which]
            if len(left) == len(rows):
                return False, 'no such message'
            self._sms_bin([r.get('key') for r in rows if r.get('id') == which])
            self._sms_log_write(left)
            self.bump()
            return True, 'that one is forgotten'
        # Thrown away on purpose: remember which, or the next round of reading
        # the device's inbox writes every one of them straight back.
        self._sms_bin([r.get('key') for r in rows])
        self._sms_log_write([])
        self.store.add_event('sms', 'the message history was cleared (%d)' % len(rows), 'info')
        self.bump()
        return True, '%d message(s) forgotten' % len(rows)

    def _sms_bin(self, keys):
        """Remember messages thrown away on purpose, so they stay thrown away."""
        binned = set(self._sms_binned)
        binned.update(str(k) for k in keys if k)
        self._sms_binned = binned
        self.store.set_meta('sms_binned', json.dumps(sorted(binned)[-2000:]))

    def _sms_audience(self, message):
        """Who a message goes to by text: the people and numbers it names,
        everybody with a number when it says anybody, or - naming nobody - the
        gateway's own list."""
        if message.get('sms_anyone'):
            return [p['phone'] for p in self.people() if p.get('phone')] or None
        return message.get('sms_to') or None

    def sms_ready(self):
        return bool(CONFIG.get('sms_enabled') and CONFIG.get('sms_host'))

    def _sms_url(self, path, params=None):
        host = str(CONFIG.get('sms_host') or '').strip()
        port = int(CONFIG.get('sms_port') or 0)
        scheme = 'https' if CONFIG.get('sms_https') else 'http'
        if '://' in host:
            scheme, host = host.split('://', 1)
        host = host.strip('/')
        base = '%s://%s%s' % (scheme, host, (':%d' % port) if port else '')
        url = base + path
        if params:
            url += ('&' if '?' in path else '?') + urlencode(params)
        return url

    @staticmethod
    def sms_number_for_gateway(number):
        """Teltonika wants a number as 00 + country code + the rest; a phone
        book writes +420 777 123 456. Both are the same phone, so the one the
        gateway asked for is what goes on the wire."""
        number = re.sub(r'[^0-9+]', '', str(number or ''))
        if not number:
            return ''
        if CONFIG.get('sms_api', 'rest') in ('rest', 'rpc'):
            # the device's own API asks for +370..., not 00370...
            if number.startswith('00'):
                return '+' + number[2:]
            return number if number.startswith('+') else number
        if (CONFIG.get('sms_number_format') or 'intl00') != 'intl00':
            return number
        if number.startswith('+'):
            return '00' + number[1:]
        if number.startswith('00'):
            return number
        if number.startswith('0'):                 # a national number: leave it be
            return number
        if len(number) <= 9:
            # 777 123 456 is a national number too - nine digits carry no
            # country code, and 00777... is a country that does not exist
            return number
        return '00' + number

    def sms_queue_add(self, number, text, why, send_after=0):
        """Keep a message to try again: one the gateway would not take, or
        one held back by the quiet hours until send_after comes round."""
        with self._sms_lock():
            queue = self.sms_outbox()
            queue.append({'id': secrets.token_hex(4), 'number': number, 'text': text, 'why': why,
                          'first': time.time(), 'tries': 0, 'last_error': '',
                          'after': float(send_after or 0)})
            self.store.set_meta('sms_outbox', json.dumps(queue[-200:]))
        self.bump()

    def sms_outbox(self):
        try:
            return json.loads(self.store.get_meta('sms_outbox') or '[]')
        except ValueError:
            return []

    def sms_outbox_drop(self, item_id=None):
        with self._sms_lock():
            queue = [] if not item_id else [x for x in self.sms_outbox() if x.get('id') != item_id]
            self.store.set_meta('sms_outbox', json.dumps(queue))
        self.bump()
        return True

    def sms_sent_today(self):
        """How many went out since midnight, so a cap can be kept. Counted
        from the events once, then kept: status() asks for it several times a
        second, and a walk over a thousand events each time was a third of
        the build."""
        lt = time.localtime()
        day = (lt.tm_year, lt.tm_mon, lt.tm_mday)
        cached = self._sms_today
        if cached and cached[0] == day and time.time() - cached[2] < 300:
            return cached[1]
        since = time.mktime(day + (0, 0, 0, 0, 0, -1))
        # counted in the table: the newest thousand events of every kind were
        # all a busy day kept in view, and the texts sent before them fell out
        # of the count - the cap let more go out than it was set to
        count = self.store.count_events('sms', since, 'sent to')
        self._sms_today = (day, count, time.time())
        return count

    def sms_flush(self):
        """Offer the outbox to the gateway again, so a box that comes back
        catches up by itself."""
        # one flush at a time - the clock's and a button's at once sent every
        # waiting message twice - and what arrives while it sends is added
        # back rather than written over
        flushing = self.__dict__.setdefault('_sms_flushing', threading.Lock())
        if not flushing.acquire(blocking=False):
            return 0
        try:
            return self._sms_flush_locked()
        finally:
            flushing.release()

    def _sms_flush_locked(self):
        queue = self.sms_outbox()
        if not queue or not self.sms_ready():
            return 0
        sent, keep = 0, []
        for item in queue:
            # one held for the morning waits where it is, and is not counted
            # against the hours a stuck message is given
            if float(item.get('after') or 0) > time.time():
                keep.append(item)
                continue
            # counted from when it was first let go: one held for the morning
            # was never given up on at all, and tried every half minute for good
            start = max(float(item.get('first') or 0), float(item.get('after') or 0))
            if time.time() - start > float(CONFIG.get('sms_queue_hours') or 6) * 3600:
                self.say_event('sms', 'gave up on a message to %s after %s'
                               % (item['number'], human_span(time.time() - item['first'])), 'warn',
                               about='sms_trouble', title='A text was given up on')
                continue
            ok, detail = self.sms_send(item['number'], item['text'], why=item['why'], queue=False)
            if ok:
                sent += 1
                continue
            if 'timed out' in str(detail).lower():
                continue                 # it very likely went: again would be a second text
            item['tries'] += 1
            item['last_error'] = str(detail)[:120]
            keep.append(item)
        with self._sms_lock():
            had = {x.get('id') for x in queue}
            dropped = {x.get('id') for x in queue} - {x.get('id') for x in self.sms_outbox()}
            later = [x for x in self.sms_outbox() if x.get('id') not in had]
            self.store.set_meta('sms_outbox', json.dumps(
                [x for x in keep if x.get('id') not in dropped] + later))
        if sent:
            self.bump()
        return sent

    def _sms_rest(self):
        """Whether to speak the device's own API. It is what a TRB140 offers
        out of the box; the older query interface has to be switched on by
        hand under Services, so it is not the default here either."""
        return (CONFIG.get('sms_api') or 'rest') in ('rest', 'rpc')

    def sms_reply(self, number, text):
        """An answer to a text, handed to a worker rather than sent here.

        The gateway does one thing at a time and takes up to a minute over it.
        Sent from where the command was worked out, that minute is spent
        inside the round of polling - which then reads no inbox and acts on
        nothing - or inside the webhook request, which leaves the gateway
        waiting for us and makes it send the message again. Both ways it looks
        like the house has stopped.

        So: queued here, sent by one worker, in the order they were made. One
        at a time because the box cannot do better, and off this thread so
        whatever was doing the working-out carries on.
        """
        if not number or not str(text or '').strip():
            return
        if not hasattr(self, '_sms_replies'):
            self._sms_replies = collections.deque()
            self._sms_reply_wake = threading.Event()
        self._sms_replies.append((str(number), str(text)))
        self._sms_reply_wake.set()
        if not getattr(self, '_sms_reply_worker', None) or not self._sms_reply_worker.is_alive():
            self._sms_reply_worker = threading.Thread(target=self._sms_reply_loop,
                                                     name='sms-replies', daemon=True)
            self._sms_reply_worker.start()

    SMS_AFTER_PUSH_S = 2.0

    def _sms_reply_loop(self):
        """One at a time, in order, for as long as the daemon runs.

        It used to go quiet after half a minute with nothing to do and be
        started again by the next answer - and that is a race with a plain
        losing side: an answer queued in the moment between the worker
        deciding to stop and actually stopping is seen by a worker that is
        still alive, and then nobody sends it. Nothing after it goes either,
        because nothing starts the worker again. Which is exactly what you
        saw: it works, and then from one message on it does not, for good.

        So it does not stop. It is a daemon thread and costs nothing while it
        waits.
        """
        while True:
            try:
                number, text = self._sms_replies.popleft()
            except IndexError:
                self._sms_reply_wake.clear()
                self._sms_reply_wake.wait(30)
                continue
            # An answer to a text the gateway pushed here was handed to it
            # within milliseconds - while the gateway was still in the middle
            # of that push, waiting for our "200" and then taking the message
            # off its SIM. Its modem does one thing at a time, so the answer
            # waited behind all of it and was written down as "no answer
            # from the gateway". A breath after the push, the box is free.
            wait = getattr(self, '_sms_push_at', 0) + self.SMS_AFTER_PUSH_S - time.time()
            if wait > 0:
                time.sleep(min(wait, self.SMS_AFTER_PUSH_S))
            try:
                self.sms_send(number, text, why='reply')
            except Exception as e:
                log('an answer to %s could not be sent: %s' % (number, e), 'warn')

    def sms_send(self, number, text, why='alert', queue=True):
        # One at a time, with a breath between: the gateway serialises anyway,
        # and asking it three things at once is what made the second and third
        # wait past our patience.
        with self._sms_send_lock:
            raw_gap = CONFIG.get('sms_send_gap_s')
            gap = 5.0 if raw_gap in (None, '') else float(raw_gap)
            since = time.time() - getattr(self, '_sms_sent_at', 0)
            if since < gap:
                time.sleep(gap - since)
            # A box that has just stopped answering is still wedged. The next
            # send fired straight into it was answered no better: each one
            # cost the whole patience again, and a queue of four replies came
            # out over a minute and a half. So after a stall, nothing is sent
            # for half a minute - long enough for the modem to finish what it
            # was doing and the box to come back.
            hold = getattr(self, '_sms_hold_until', 0) - time.time()
            if hold > 0:
                log('SMS: the gateway stalled a moment ago, waiting %.0fs before the next' % hold, 'debug')
                time.sleep(hold)
            self._sms_sent_at = time.time()
            ok, said = self._sms_send_now(number, text, why, queue)
            if not ok and 'no answer' in str(said):
                self._sms_hold_until = time.time() + 30
            else:
                self._sms_hold_until = 0
            return ok, said

    @staticmethod
    def sms_parts(text):
        """How many messages this will really be.

        Anything outside the GSM alphabet - a Czech letter with a diacritic,
        an emoji - turns the whole message into the wider encoding, where
        seventy characters fill a part instead of a hundred and sixty.
        """
        text = str(text or '')
        wide = any(ord(c) > 127 for c in text)
        one, more = (70, 67) if wide else (160, 153)
        # counted in what the network counts: UCS-2 units, where an emoji
        # beyond the first plane is two, and GSM septets, where {}[]~\|^
        # take an escape and are two as well
        if wide:
            size = len(text.encode('utf-16-le')) // 2
        else:
            size = len(text) + sum(1 for c in text if c in '{}[]~\\|^')
        if size <= one:
            return 1
        return (size + more - 1) // more

    def _sms_send_now(self, number, text, why='alert', queue=True):
        """One SMS through the gateway. Teltonika's boxes speak two dialects:
        the old CGI one (a GET with the message in the query) and the newer
        JSON-RPC over /api. Which one is a setting, since a box that has been
        upgraded changes its mind about this."""
        if not self.sms_ready():
            return False, 'no SMS gateway is set up'
        group = ''
        if str(number or '').startswith('group:'):
            group, number = str(number)[6:].strip(), ''
        else:
            number = self.sms_number_for_gateway(number)
        if not number and not group:
            return False, 'no number to send to'
        text = str(text or '')[:1000]
        cap = int(CONFIG.get('sms_daily_cap') or 0)
        if cap and why not in ('test', 'by hand') and self.sms_sent_today() >= cap:
            self.say_event('sms', 'not sent: %d messages already today, which is the cap' % cap, 'warn',
                           about='sms_cap', title='The day\'s texts are used up', dedup='sms_cap')
            return False, "the day's cap of %d messages is used up" % cap
        user = CONFIG.get('sms_user') or ''
        secret = CONFIG.get('sms_password') or ''
        # A long message is several messages. The gateway hands each to the
        # modem in turn, so one patience for all of them means a status reply
        # listing nine sockets - two parts - gets the same fifteen seconds as
        # "on", and times out while it is still working.
        parts = self.sms_parts(text)
        timeout = float(CONFIG.get('sms_timeout_s') or 15) * max(1, parts)
        if why == 'reply':
            # A reply that the box has not acknowledged in twenty seconds is
            # not going to be acknowledged: on that day's log every stall was
            # 55 to 63 seconds - our patience, to the second - and the message
            # had gone out regardless. Waiting the full minute only held the
            # next reply. Twenty is long enough to know and short enough that
            # the queue keeps moving; the message is marked unsure, as before.
            patience = float(CONFIG.get('sms_reply_timeout_s') or 0)
            if patience > 0:
                timeout = min(timeout, patience)
        self._sms_sending = time.time()      # hold the pollers off while it goes
        # Written down NOW, as it is handed over, not when the gateway gets
        # round to answering. That box takes up to a minute, and a reply that
        # reached the phone at once was not on the screen until it did - the
        # message looked lost while it was in the recipient's hand.
        going = self.sms_note('out', number, text, None, why)
        try:
            if self._sms_rest():
                # the modem is required even when the device has only one, and
                # the number must carry its country code with a leading +
                # ...with the patience worked out above, not the plain one: a
                # reply of two parts was being given the same seconds as "on"
                # and timing out while the modem was still working through it
                tries = 0
                while True:
                    tries += 1
                    try:
                        out = self._rest('/messages/actions/send', 'POST',
                                         {'data': {'number': number, 'message': text,
                                                   'modem': self.sms_modem_id()}},
                                         timeout=timeout)
                        break
                    except Exception as e:
                        # only where it certainly never arrived, and only
                        # twice: a fresh connection is worth trying when the
                        # box refused one, and worth nothing when it took the
                        # request and went quiet
                        if tries >= 3 or not self._sms_never_arrived(e):
                            raise
                        # a new connection - the token is not what was refused,
                        # and a new login each time was one more session on the box
                        log('the gateway would not take the connection (%s); trying again'
                            % str(e)[:60], 'debug')
                        time.sleep(1.0 * tries)
                body = json.dumps(out)
            else:
                params = {'username': user, 'password': secret, 'text': text}
                params['group' if group else 'number'] = group or number
                url = self._sms_url(CONFIG.get('sms_send_path') or '/cgi-bin/sms_send', params)
                body = self._sms_open(url, timeout).read().decode('utf-8', 'replace')
        except Exception as e:
            # A gateway that does not answer in time is not a gateway that
            # refused: it sends one message at a time, and three questions in
            # a row leave the second and third waiting past our patience while
            # the messages themselves go out perfectly well. Saying "failed"
            # about a message that arrives is worse than saying nothing.
            timed_out = isinstance(e, socket.timeout) or 'timed out' in str(e).lower()
            if timed_out:
                log('SMS to %s: no answer within %gs, it may still have gone out'
                    % (number, timeout), 'warn')
                self.say_event('sms', 'no answer from the gateway within %gs for %s - the '
                                      'message may still have gone out' % (timeout, number), 'warn',
                               about='sms_trouble', title='The text gateway did not answer',
                               dedup='sms_trouble|slow')
                self.sms_note_settled(going, None)
            else:
                log('SMS to %s failed after %gs (%d part%s): %s'
                % (number, timeout, parts, '' if parts == 1 else 's', e), 'warn')
                self.store.add_event('sms', 'could not send to %s: %s' % (number, e), 'warn')
                self.sms_note_settled(going, False)
                # Down the other roads, never by text: the text road is the
                # one that just failed. Said once an hour, since a gateway
                # that is away fails every message until it comes back.
                if time.time() - getattr(self, '_sms_told', 0) > 3600:
                    self._sms_told = time.time()
                    self.notify('The text gateway would not send to %s: %s' % (number, str(e)[:120]),
                                'warn', sms=False, dedup='gateway-will-not-send',
                                title='A text would not go', about='gateway')
            if timed_out and why == 'reply':
                # it very likely went; sending it again would arrive twice
                self._sms_sending = 0
                return False, ('no answer within %gs for a message of %d part%s - it may still '
                               'have gone out' % (timeout, parts, '' if parts == 1 else 's'))
            kept = False
            # A message the gateway did not answer for has, as said above,
            # very likely gone: kept, it was sent again by every flush, every
            # half minute, and timed out again each time - one boiler fault
            # was five paid texts in two and a half minutes.
            if queue and not timed_out and CONFIG.get('sms_queue', True) and why not in ('test', 'reply'):
                # the gateway is away rather than the message being wrong: keep
                # it and try again, so an alert is not simply lost
                self.sms_queue_add(number or ('group:' + group), text, why)
                kept = True
            # The hold on the pollers comes off HERE, on every way out of this
            # branch. It used to come off only where a message was queued or
            # where a reply timed out - so a reply that failed for any other
            # reason left it set, and nothing read the inbox for the next two
            # minutes. With the webhook off that is two minutes of no texts at
            # all, which reads as "it stopped working" and is the worst of
            # these faults by a distance.
            self._sms_sending = 0
            return False, ('%s - kept to try again' % e) if kept else str(e)
        ok = 'error' not in body.lower() or 'ok' in body.lower()[:20]
        self.store.add_event('sms', 'sent to %s (%s): %s' % (number, why, text[:80]), 'info' if ok else 'warn')
        if ok and self._sms_today:
            self._sms_today = (self._sms_today[0], self._sms_today[1] + 1, self._sms_today[2])
        self.sms_note_settled(going, ok)
        self.debug('SMS out %s' % number, text[:120])
        self._sms_sending = 0
        return ok, body.strip()[:200] or 'sent'

    def _rest(self, path, method='GET', payload=None, retry=True, timeout=None):
        """One call on the device's own REST API. It lives under /api, wants a
        Bearer token from /api/login, and hands out tokens that last five
        minutes - so a refusal means log in again and try once more rather
        than give up."""
        if timeout is None:
            timeout = float(CONFIG.get('sms_timeout_s') or 15)
        with self._sms_watch(path):
            return self._rest_once(path, method, payload, retry, timeout)

    SMS_SLOW_S = 5.0

    @contextlib.contextmanager
    def _sms_watch(self, what):
        """Every question to the gateway timed, and when one is slow, said
        with whatever else was asked of it meanwhile. "No answer from the
        gateway" alone does not tell a box that hung from a box that was
        busy with something of ours."""
        flying = self.__dict__.setdefault('_sms_flying', {})
        done = self.__dict__.setdefault('_sms_done', collections.deque(maxlen=40))
        start = time.time()
        key = (threading.get_ident(), what, start)
        flying[key] = True
        try:
            yield
        finally:
            flying.pop(key, None)
            end = time.time()
            done.append((start, end, what))
            if end - start >= self.SMS_SLOW_S:
                # what else was asked of the box while this one waited: still
                # asking, or asked and answered in the meantime
                others = ['%s (still asking, %.0fs)' % (w, end - at) for (_t, w, at) in list(flying)
                          if at < end]
                others += ['%s (%.1fs)' % (w, e - b_) for (b_, e, w) in list(done)[:-1]
                           if e > start and b_ < end]
                log('SMS gateway: %s took %.1fs%s' % (
                    what, end - start, ('; asked of it meanwhile: ' + ', '.join(others)) if others else
                    ' with nothing else of ours asking it - the box itself was slow'), 'warn')

    def _rest_once(self, path, method, payload, retry, timeout):
        import urllib.request
        token = self._sms_token()
        data = json.dumps(payload).encode() if payload is not None else None
        req = urllib.request.Request(self._sms_url('/api' + path), data=data,
                                     headers={'Content-Type': 'application/json',
                                              'Authorization': 'Bearer ' + token},
                                     method=method)
        t0 = time.time()
        try:
            resp = urllib.request.urlopen(req, timeout=timeout, context=self._sms_ssl())
            t_head = time.time()
            # The answer's head has come: the box has done what it was asked.
            # Its body is then a few bytes, and is given seconds, not the whole
            # patience. A day's log had every stall of a send last exactly our
            # patience - 55 to 63 s, to the second - and the message gone out
            # regardless: the box had answered and not finished the answer,
            # and for that minute the house sent nothing and, the gateway
            # being held, heard nothing either.
            self._sms_body_patience(resp, min(timeout, self.SMS_BODY_S))
            try:
                raw = resp.read()
            except (socket.timeout, TimeoutError, OSError) as e:
                if resp.status == 200 and method == 'POST':
                    log('SMS gateway: %s answered %d after %.1fs and never finished its answer '
                        '(%s; %s) - taken as done' % (path, resp.status, t_head - t0, e,
                                                       self._sms_head_words(resp)), 'warn')
                    return {}
                raise
            took = time.time() - t0
            if took >= self.SMS_SLOW_S:
                log('SMS gateway: %s - its answer began after %.1fs, ended after %.1fs (%s)'
                    % (path, t_head - t0, took, self._sms_head_words(resp)), 'warn')
            answer = json.loads(raw or b'{}')
        except urllib.error.HTTPError as e:
            body = ''
            try:
                body = e.read().decode('utf-8', 'replace')[:300]
            except Exception:
                pass
            if e.code in (401, 403) and retry:
                self._sms_tok = None                 # the token went stale
                return self._rest_once(path, method, payload, False, timeout)
            raise RuntimeError('%s %s: HTTP %d %s' % (method, path, e.code, body))
        if answer.get('success') is False:
            raise RuntimeError('%s %s: %s' % (method, path, json.dumps(answer.get('errors') or answer)[:200]))
        return answer.get('data', answer)

    SMS_BODY_S = 5.0

    @staticmethod
    def _sms_body_patience(resp, seconds):
        """The socket under an answer given its own, shorter patience for the
        body. Reached through what http.client keeps; where it cannot be, the
        request's own patience stands, as before."""
        try:
            sock = resp.fp.raw._sock
            sock.settimeout(seconds)
        except AttributeError:
            pass

    @staticmethod
    def _sms_head_words(resp):
        try:
            h = resp.headers
            return ', '.join('%s: %s' % (k, h.get(k)) for k in
                             ('Content-Length', 'Transfer-Encoding', 'Connection') if h.get(k)) or 'no length given'
        except Exception:                               # noqa: BLE001
            return '?'

    @staticmethod
    def _sms_never_arrived(e):
        """Whether a failed request certainly never reached the gateway.

        The distinction matters more than anything else about retrying: a
        connection refused, reset or never made means the box never saw the
        request, so trying again costs nothing. A read timing out means the
        box TOOK it and did not answer - and for a send, that message is
        usually on its way. Trying that one again is a second text to
        somebody's phone, which is worse than one that was not acknowledged.
        """
        if isinstance(e, socket.timeout):
            return False
        reason = getattr(e, 'reason', e)
        if isinstance(reason, socket.timeout):
            return False
        words = str(e).lower()
        if 'timed out' in words or 'timeout' in words:
            return False
        return isinstance(reason, (ConnectionRefusedError, ConnectionResetError,
                                   ConnectionAbortedError, socket.gaierror)) \
            or 'refused' in words or 'reset by peer' in words or 'not known' in words \
            or 'no route' in words or 'broken pipe' in words

    def _sms_open(self, what, timeout=None):
        """Every request to the gateway goes through here, so the certificate
        rule is the same whichever interface is in use - the older ones were
        opening plain connections and failing the moment HTTPS was on."""
        import urllib.request
        return urllib.request.urlopen(what, timeout=timeout or float(CONFIG.get('sms_timeout_s') or 15),
                                      context=self._sms_ssl())

    def _sms_ssl(self):
        """A TRB serves HTTPS with a certificate of its own making; on the home
        network that is fine, and refusing it would only mean nothing works."""
        if not CONFIG.get('sms_https'):
            return None
        import ssl
        ctx = ssl.create_default_context()
        if not CONFIG.get('sms_verify_cert'):
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
        return ctx

    def sms_modem_id(self):
        """Which modem to send from. The API insists on being told, even when
        there is only one, so it is asked once and remembered."""
        if CONFIG.get('sms_modem'):
            return CONFIG['sms_modem']
        if self._sms_modem_id:
            return self._sms_modem_id
        rows = self._rest('/modems/status') or []
        if isinstance(rows, dict):
            rows = [rows]
        first = next((r for r in rows if r.get('id')), None)
        if not first:
            raise RuntimeError('the device did not name a modem')
        self._sms_modem_id = first['id']
        return self._sms_modem_id

    def _sms_token(self):
        """A login on the device's own API. The token it gives lasts five
        minutes, not the twenty-five a session usually does, so it is renewed
        well before that rather than after a refusal."""
        import urllib.request
        now = time.time()
        if self._sms_tok and now < self._sms_tok[1]:
            return self._sms_tok[0]
        with self._sms_watch('/login'):
            return self._sms_login(now)

    def _sms_login(self, now):
        import urllib.request
        req = urllib.request.Request(self._sms_url('/api/login'),
                                     data=json.dumps({'username': CONFIG.get('sms_user') or 'admin',
                                                      'password': CONFIG.get('sms_password') or ''}).encode(),
                                     headers={'Content-Type': 'application/json'}, method='POST')
        try:
            answer = json.loads(urllib.request.urlopen(req, timeout=float(CONFIG.get('sms_timeout_s') or 15),
                                                       context=self._sms_ssl()).read())
        except urllib.error.HTTPError as e:
            body = ''
            try:
                body = e.read().decode('utf-8', 'replace')[:200]
            except Exception:
                pass
            raise RuntimeError('the device would not let us in (HTTP %d %s) - check the username, the password, '
                               'and that this account may use the API' % (e.code, body))
        data = answer.get('data') or {}
        token = data.get('token') or answer.get('token') or ''
        if not token:
            raise RuntimeError('the device gave no token: %s' % json.dumps(answer)[:150])
        # Kept for as long as the box takes it - not renewed every four minutes
        # ahead of its "expires". Each login is a session on the gateway, and
        # nothing ever logged the old ones out: a day of it was hundreds of
        # sessions held on a small box whose modem is slow enough already. A
        # token the box refuses is logged in again then (see _rest_once).
        self._sms_tok = (token, float('inf'))
        return token

    def _sms_drop_token(self):
        """A token we are done with, logged out on the gateway rather than left
        to sit there as one more session. Behind, and briefly: it must never
        hold up what comes next."""
        held, self._sms_tok = self._sms_tok, None
        if not held or not self._sms_rest():
            return

        def bye(token=held[0]):
            import urllib.request
            try:
                req = urllib.request.Request(self._sms_url('/api/logout'), data=b'{}',
                                             headers={'Content-Type': 'application/json',
                                                      'Authorization': 'Bearer ' + token}, method='POST')
                urllib.request.urlopen(req, timeout=5, context=self._sms_ssl()).read()
            except Exception:                           # noqa: BLE001
                pass
        threading.Thread(target=bye, name='sms-logout', daemon=True).start()

    def sms_test(self, number=None):
        """Is the gateway there, does it take our password, and - if a number
        is given - does a message actually arrive."""
        if not self.sms_ready():
            return False, 'switch the gateway on and give it an address first'
        try:
            if self._sms_rest():
                self._sms_drop_token()
                self._sms_token()
                modem = self.sms_modem_id()
                reached = 'the device let us in, and its modem is %s' % modem
            else:
                url = self._sms_url(CONFIG.get('sms_read_path') or '/cgi-bin/sms_list',
                                    {'username': CONFIG.get('sms_user') or '', 'password': CONFIG.get('sms_password') or ''})
                body = self._sms_open(url).read().decode('utf-8', 'replace')
                if 'error' in body.lower() and 'no messages' not in body.lower():
                    return False, 'the gateway answered: %s' % body.strip()[:120]
                reached = 'the gateway answered'
        except Exception as e:
            return False, 'could not reach it: %s' % e
        # what it is doing, not only that it is there
        told = []
        status = {}
        try:
            status = self.sms_modem_status() or {}
        except Exception:
            status = {}
        if status.get('operator'):
            told.append('%s%s' % (status['operator'], (' on ' + status['network']) if status.get('network') else ''))
        if status.get('rssi') is not None:
            told.append('signal %s dBm' % status['rssi'])
        if status.get('sim'):
            told.append('SIM %s' % status['sim'])
        if status.get('data_month_mb') is not None:
            told.append('%s MB this month' % status['data_month_mb'])
        try:
            inbox = self.sms_poll(force=True)
            if inbox:
                told.append('%d message(s) in the inbox' % inbox['read'])
        except Exception:
            pass
        detail_bits = (' \u2014 ' + ', '.join(told)) if told else ''
        if number:
            ok, detail = self.sms_send(number, 'zigmon: this is the test message.', why='test')
            return ok, ('%s, and the message went out%s' % (reached, detail_bits)) if ok else detail
        return True, reached + detail_bits

    def sms_commands(self):
        """What a text message may do. Each is a phrase to match and a target
        with an action - the same targets everything else uses - so "lights
        off" from a phone with no data is worth having."""
        return self.store.meta_json('sms_commands')

    @staticmethod
    def clean_vars(items, phrase=''):
        """The names a row has made up, tidied.

        A name is a name: letters, digits and underscores, so it can be
        written between braces and read back out. Where it comes from is said
        here too - a place in the phrase, the rest of the message, or a header
        of the press - because the name alone does not say it.
        """
        out, seen = [], set()
        for one in (items or []):
            if isinstance(one, str):
                one = {'name': one}
            if not isinstance(one, dict):
                continue
            name = re.sub(r'[^A-Za-z0-9_]', '', str(one.get('name') or ''))[:24]
            if not name or name[0].isdigit() or name.lower() in seen:
                continue
            seen.add(name.lower())
            # where it comes from is a header name or the word rest; anything
            # else is not a place and is not kept as though it were
            where = re.sub(r'[^A-Za-z0-9_-]', '', str(one.get('from') or '').strip())[:60]
            out.append({'name': name, 'from': where, 'note': str(one.get('note') or '')[:80]})
            if len(out) >= 12:
                break
        # a name written into the phrase is one of these whether or not
        # anybody wrote it down here as well
        for name in Daemon.phrase_catches(phrase):
            if name.lower() not in seen:
                seen.add(name.lower())
                out.append({'name': name, 'from': 'phrase', 'note': 'named in the phrase'})
        return out

    # ---- little scripts, written by hand and given a name --------------
    # A rule may do one thing. Sometimes the thing wanted is three things, or
    # a thing with a value worked out from what the rule caught. A script is a
    # few lines of plain verbs, each one of them something this could already
    # do on its own, with the rule's own names filled in before anything runs.
    SCRIPT_WAIT_TOTAL = 30.0

    SCRIPT_VERBS = [
        ('on', 'TARGET', 'switch something on', 'on Plug-WorkshopTV'),
        ('off', 'TARGET', 'switch something off', 'off Plug-WorkshopTV'),
        ('toggle', 'TARGET', 'switch it the other way', 'toggle Plug-OldPC-Left'),
        ('pulse', 'TARGET [ms]', 'on, then off again', 'pulse Plug-Gate 600'),
        ('set', 'TARGET VALUE', 'set a number - a thermostat, a brightness', 'set Heating-Loznice 21.5'),
        # the whole of the heating in one word, so a text message can drive
        # it without a target being written into the command first
        ('heat', 'WHAT [HOW]', 'the heating: on, off, away, a room’s setting, or what a '
                               'setting is worth', 'heat Loznice eco'),
        ('ban', 'ADDRESS [minutes]', 'keep an address out', 'ban {ip} 120'),
        ('unban', 'ADDRESS', 'let an address back in', 'unban {ip}'),
        ('say', 'WORDS', 'add a line to what goes back', 'say {ip} is let back in'),
        ('notify', 'WORDS', 'send it the usual way, to the usual places', 'notify the gate opened'),
        ('wait', 'SECONDS', 'pause before the next line (up to 30)', 'wait 2'),
        ('stop', '[WORDS]', 'go no further, and say why', 'stop nothing to do'),
        # asking a question, and going round a list: the lines between these
        # and their "end" are done only when the question holds, or once for
        # every thing in the list
        ('if', 'CONDITION', 'do the lines under it only when this holds',
         'if anyone_home and {temp} < 18'),
        ('else', '[CONDITION]', 'otherwise - or otherwise, if this holds', 'else'),
        ('end', '', 'the end of an if or a for', 'end'),
        ('for', 'NAME in LIST', 'go round a list, one turn for each thing in it',
         'for p in {plugs_on_list}'),
        ('while', 'CONDITION', 'go round while this still holds (a hundred turns at most)',
         'while {Plug-UPS.state} == on'),
        ('repeat', 'TIMES', 'go round that many times, with {loop_i} counting',
         'repeat 3'),
        ('break', '', 'leave the loop it is in', 'break'),
        ('next', '', 'go straight to the next turn of the loop', 'next'),
        ('let', 'NAME VALUE', 'give a name to something, for the lines after it',
         'let room {Temp-Loznice.temperature}'),
        ('answer', 'WORDS', 'what goes back to whoever asked - a text message, a one-tap link',
         'answer {room} is at {Temp-Loznice.temperature} \u00b0C'),
    ]
    SCRIPT_BLOCK_VERBS = ('if', 'else', 'end', 'for', 'while', 'repeat', 'break', 'next')
    # Name.member = value: a property set (4.87). What stands left of the "="
    # is written by whoever wrote the script and may hold no {name}: a value
    # may come from a message, the thing it is set on may not.
    SCRIPT_ASSIGN = re.compile(r'^([^\s{}=][^{}=]*?)\.([A-Za-z_][A-Za-z0-9_]*)\s*=(?!=)\s*(.*)$')
    # Name.procedure(args): what the object can be told to do, called
    SCRIPT_CALL = re.compile(r'^([^\s{}=(][^{}=(]*?)\.([A-Za-z_][A-Za-z0-9_]*)\(\s*(.*?)\s*\)\s*$')
    SCRIPT_LINES_MOST = 400        # a loop that would run for ever stops here
    SCRIPT_TURNS_MOST = 200        # and one loop goes round this many times at most

    def scripts(self):
        out = []
        for one in self.store.meta_json('scripts'):
            # the names this one asks for, worked out from what it says, so
            # whoever runs it can be asked for them
            one = dict(one)
            one['wants'] = sorted(set(self.phrase_catches(one.get('body') or '')))
            # what it hands back: the ones written down on the row, and the
            # ones its own lines give a value to with "let"
            made = [str(x.get('name')) for x in (one.get('results') or [])]
            made += re.findall(r'^\s*let\s+([A-Za-z][A-Za-z0-9_]*)', str(one.get('body') or ''), re.M)
            one['gives'] = sorted({m for m in made if m}, key=str.lower)
            one['slug'] = self.name_slug(one.get('name'))
            out.append(one)
        return out

    def script_by_id(self, wanted):
        return next((s for s in self.scripts() if s['id'] == str(wanted)), None)

    def save_scripts(self, items):
        clean, seen = [], set()
        # the scripts being saved together may call one another by name
        coming = {str(x.get('name') or '').strip().lower() for x in (items or []) if isinstance(x, dict)}
        for index, one in enumerate(items or []):
            if not isinstance(one, dict):
                continue
            name = str(one.get('name') or '').strip()[:40]
            body = str(one.get('body') or '')[:4000]
            if not name and not body.strip():
                continue
            if not name:
                raise ValueError('script %d needs a name' % (index + 1))
            if name.lower() in seen:
                raise ValueError('two scripts called "%s"' % name)
            seen.add(name.lower())
            bad = self.script_faults(body, also=coming)
            if bad:
                raise ValueError('%s: %s' % (name, bad[0]))
            clean.append({'id': str(one.get('id') or '') or secrets.token_hex(4),
                          # the section it is filed under, like every other row
                          'group': _grp(one),
                          'name': name, 'body': body,
                          # switched off it stays, and runs for nobody (4.97)
                          'enabled': one.get('enabled', True) is not False,
                          # the names this one hands back, said out loud: a
                          # command's answer and a link's own words may quote
                          # them, and nothing can offer them until they are
                          # written down somewhere
                          'results': self.clean_vars(one.get('results')),
                          'note': str(one.get('note') or '')[:120]})
        self.snapshot('scripts', 'saved from the dashboard')
        self.store.set_meta('scripts', json.dumps(clean))
        self.store.add_event('control', '%d script(s) saved' % len(clean))
        self.bump()
        return clean

    def script_faults(self, body, also=()):
        """What is wrong with a script, said in the words of the line itself.

        Checked when it is saved rather than when it runs, so a line that
        cannot work is refused while somebody is looking at it.
        """
        known = {v[0] for v in self.SCRIPT_VERBS}
        out = []
        # an if or a for that is never ended, and an end with nothing open
        _plan, unclosed = self.script_plan(body)
        out.extend(unclosed)
        for number, raw in enumerate(str(body or '').splitlines(), 1):
            line = raw.strip()
            if not line or line.startswith('#'):
                continue
            verb = line.split()[0].lower()
            rest = line[len(verb):].strip()
            if verb in ('endif', 'endfor'):
                verb = 'end'
            if verb not in known:
                call = self.SCRIPT_CALL.match(line)
                if call:
                    try:
                        # a value from a message is checked when it runs; here
                        # only whether the call is one that can be made
                        args = call.group(3).strip()
                        if call.group(1).strip().lower() in also and call.group(2).lower() == 'run' \
                                and not self.object_find(call.group(1).strip()):
                            continue          # a script saved alongside this one
                        self.object_call_line(call.group(1).strip(), call.group(2),
                                              '1' if args and '{' in args else args)
                    except ValueError as e:
                        if not ('{' in call.group(3) and 'takes a number' in str(e)):
                            out.append('line %d: %s' % (number, str(e)[:120]))
                    continue
                assign = self.SCRIPT_ASSIGN.match(line)
                if assign:
                    # a property set: said now if the thing or its member is
                    # not there, or cannot be set; the value is checked when
                    # it runs, since it may come from a message
                    who, member = assign.group(1).strip(), assign.group(2)
                    found = self.object_find(who)
                    if not found:
                        out.append('line %d: there is nothing here called "%s"' % (number, who[:30]))
                        continue
                    rows = [m for m in self._obj_members(found[0], found[1], found[3], values=False, only=member)
                            if m['name'].lower() == member.lower()]
                    if not rows:
                        out.append('line %d: %s has no member called "%s"' % (number, found[2], member[:30]))
                    elif rows[0].get('locked'):
                        out.append('line %d: %s.%s keeps the house safe and is not set from a script'
                                   % (number, found[2], rows[0]['name']))
                    elif not rows[0].get('settable'):
                        out.append('line %d: %s.%s cannot be set%s' % (
                            number, found[2], rows[0]['name'],
                            {'func': ' - it is worked out', 'proc': ' - it is done: %s.%s()'
                             % (found[2], rows[0]['name'])}.get(rows[0]['kind'], '')))
                    elif not assign.group(3).strip():
                        out.append('line %d: %s.%s = needs a value' % (number, found[2], rows[0]['name']))
                    elif '{' not in assign.group(3):
                        # a value written out is checked now, as it will be
                        # checked when it runs - nothing is set
                        try:
                            self.object_set(who, member, assign.group(3).strip(), dry=True)
                        except ValueError as e:
                            out.append('line %d: %s' % (number, str(e)[:120]))
                    continue
                out.append('line %d: %r is not one of the things it can do' % (number, verb[:20]))
                continue
            if verb == 'if' and not rest:
                out.append('line %d: if needs something to ask' % number)
            if verb == 'for' and not re.match(r'^\s*(?:each\s+)?[A-Za-z][A-Za-z0-9_]*\s+(?:in|of)\s+\S', rest):
                out.append('line %d: for goes "for a name in a list" \u2014 for p in {plugs_on_list}' % number)
            if verb == 'while' and not rest:
                out.append('line %d: while needs something to ask' % number)
            if verb == 'repeat' and not (numeric(rest) is not None or '{' in rest):
                out.append('line %d: repeat needs a number of times' % number)
            if verb == 'answer' and not rest:
                out.append('line %d: answer needs the words to send back' % number)
            if verb == 'let' and len(rest.split(None, 1)) < 2:
                out.append('line %d: let goes "let a-name something"' % number)
            if verb in self.SCRIPT_BLOCK_VERBS or verb == 'let':
                continue
            if verb in ('on', 'off', 'toggle', 'pulse', 'set', 'ban', 'unban') and not rest:
                out.append('line %d: %s needs something to act on' % (number, verb))
            # {myip) is not a name, it is a name with the wrong bracket on the
            # end - and it reads as ordinary words, so the line quietly acts
            # on the characters themselves. Said while somebody is looking.
            for odd in re.findall(r'\{[A-Za-z][A-Za-z0-9_.]*[)\]>]', line):
                out.append('line %d: %s is not closed - a name ends with }' % (number, odd))
            if line.count('{') != line.count('}'):
                out.append('line %d: a { without its }' % number)
            if verb == 'set' and len(rest.split()) < 2:
                out.append('line %d: set needs a thing and a number' % number)
            # a line naming something outright is checked here and now; one
            # naming it with {a name} can only be checked when it runs
            if verb in ('on', 'off', 'toggle', 'pulse', 'set') and rest and '{' not in rest:
                thing = rest
                if verb == 'pulse' and len(rest.rsplit(' ', 1)) > 1 and rest.rsplit(' ', 1)[1].isdigit():
                    thing = rest.rsplit(' ', 1)[0]
                if verb == 'set' and len(rest.rsplit(' ', 1)) > 1:
                    thing = rest.rsplit(' ', 1)[0]
                if not self._valid_target(thing.strip()):
                    out.append('line %d: there is nothing here called "%s"' % (number, thing.strip()[:40]))
        return out

    @staticmethod
    def name_slug(name):
        """A name written the way a fact is written: lower case, no spaces."""
        return re.sub(r'[^a-z0-9_]+', '_', str(name or '').strip().lower()).strip('_')[:24]

    def caller_facts(self, kind, values, who=''):
        """The names a caller hands a script, each under three names.

        A script may be run by a text command, by a one-tap link or by hand,
        and each of those makes up names of its own. Plainly - {ip} - they
        can collide: two commands may each have an ip and neither means the
        other's, and a script cannot tell which it was given. So each name
        is also here as the kind that gave it ({sms.ip}, {tap.ip}), as the
        caller's own name ({ban.ip}, {gate.ip}), and as {in.ip}, which is
        "whoever called this one".
        """
        out = {}
        slug = self.name_slug(who)
        for key, value in (values or {}).items():
            key = str(key or '').strip().lower()
            if not key or '.' in key:
                continue
            text = '' if value is None else str(value)
            out[key] = text
            out['%s.%s' % (kind, key)] = text
            out['in.%s' % key] = text
            if slug:
                out['%s.%s' % (slug, key)] = text
        return out

    def script_result_facts(self, out, script=None):
        """What a script leaves behind for whoever asked to quote.

        A text message and a one-tap link both answer with words somebody
        wrote, and until now those words could only hold what was known
        before the script ran. {result} is what it wants said, {said} the
        running commentary, {failed} what did not happen, and every name the
        script made up with "let" is a fact of its own."""
        out = out or {}
        said = str(out.get('said') or '')
        answer = str(out.get('answer') or '')
        facts = {}
        slug = self.name_slug((script or {}).get('name'))
        for key, value in (out.get('names') or {}).items():
            key = str(key).lower()
            facts[key] = str(value)
            facts['out.%s' % key] = str(value)          # whichever script it was
            if slug:
                facts['%s.%s' % (slug, key)] = str(value)   # and this one by name
        facts.update({
            'result': answer or said,
            'answer': answer,
            'said': said,
            'said_lines': str(len([x for x in said.splitlines() if x.strip()])),
            'failed': '\n'.join(out.get('faults') or []),
            'failed_n': str(len(out.get('faults') or [])),
            'ok': 'no' if out.get('faults') else 'yes',
            'lines_done': str(out.get('lines') or 0),
            'script': str((script or {}).get('name') or ''),
        })
        # the same four under the script's own name, so an answer that runs
        # two of them can say which it means
        if slug:
            for key in ('result', 'answer', 'said', 'ok', 'failed'):
                facts['%s.%s' % (slug, key)] = facts[key]
            facts['out.result'] = facts['result']
            facts['out.said'] = facts['said']
            facts['out.ok'] = facts['ok']
        return facts

    def _script_stands_for(self, name, facts):
        """What a bare name in a script's condition stands for right now."""
        key = str(name or '').strip().lower()
        if key in facts:
            return facts[key]
        if '.' in key:
            try:
                return self.device_fact(name)
            except Exception:
                return None
        return None

    def script_plan(self, body):
        """The lines of a script as a little tree: plain lines, and the
        if/else/for blocks with what belongs inside them.

        Returns (plan, trouble). An if or a for that is never ended closes
        itself at the end, and says so - a script is a thing somebody wrote
        by hand, and half of it running is worse than being told."""
        plan, stack, trouble = [], [], []
        here = plan
        for number, raw in enumerate(str(body or '').splitlines(), 1):
            line = raw.strip()
            if not line or line.startswith('#'):
                continue
            verb = line.split()[0].lower()
            rest = line[len(verb):].strip()
            if verb == 'if':
                node = ('if', rest, [[rest, []]])
                here.append(node)
                stack.append(('if', node, number))
                here = node[2][0][1]
            elif verb in ('for', 'while', 'repeat'):
                node = (verb, rest, [])
                here.append(node)
                stack.append((verb, node, number))
                here = node[2]
            elif verb == 'else':
                if not stack or stack[-1][0] != 'if':
                    trouble.append('line %d: else without an if' % number)
                    continue
                node = stack[-1][1]
                # "else" plainly, "else if …" or "else …" - all the same thing
                node[2].append([re.sub(r'^if\s+', '', rest, flags=re.I).strip(), []])
                here = node[2][-1][1]
            elif verb in ('end', 'endif', 'endfor'):
                if not stack:
                    trouble.append('line %d: end without an if or a for' % number)
                    continue
                stack.pop()
                if not stack:
                    here = plan
                else:
                    kind, node, _n = stack[-1]
                    here = node[2][-1][1] if kind == 'if' else node[2]
            elif verb in ('break', 'next'):
                here.append(('jump', verb, []))
            else:
                here.append(line)
        for kind, _node, number in stack:
            trouble.append('line %d: this %s is never ended - "end" on a line of its own' % (number, kind))
        return plan, trouble

    def run_script(self, script, facts=None, origin='a script', hold=None):
        """Run one, line by line, with the rule's own names already in it.

        Every line is something this could do on its own; nothing here reaches
        further than the rest of the dashboard does, which is the whole point
        of writing it as lines rather than as code.
        """
        if isinstance(script, dict) and script.get('enabled', True) is False:
            return {'lines': 0, 'said': '%s is switched off' % (script.get('name') or 'the script'), 'ran': [],
                    'names': {}, 'answer': '', 'faults': ['%s is switched off' % (script.get('name') or 'the script')]}
        facts = dict(facts or {})
        said, done, ran, faults = [], 0, [], []
        # what the script wants said back, when it says so itself: a text
        # message and a one-tap link both wait on an answer, and "say" is a
        # running commentary rather than one
        answers = []
        names = {}
        # A script runs on the thread that asked for it - a press holds its
        # connection, a text holds the modem - so the waiting in the whole of
        # it is capped, not only the waiting on one line.
        left_to_wait = self.SCRIPT_WAIT_TOTAL
        stopped = [False]
        steps = [0]

        def line_facts(scope):
            return dict(facts, **(scope or {}))

        def do_line(raw, scope):
            nonlocal left_to_wait, done
            here = line_facts(scope)
            # A name that stands for nothing leaves a hole in the middle of a
            # line, and the line then means something else entirely: "ban
            # {ip} 120" with no address reads as "ban 120". Said plainly
            # instead, naming the name.
            empty = [n for n in self.phrase_catches(raw)
                     if not str(here.get(n) or '').strip()]
            if empty:
                trouble = ('%s was not done: %s stood for nothing'
                           % (raw.split()[0], ', '.join('{%s}' % n for n in empty)))
                said.append(trouble)
                faults.append(trouble)
                return
            call = self.SCRIPT_CALL.match(raw.strip())
            if call and raw.split()[0].lower() not in {v[0] for v in self.SCRIPT_VERBS}:
                who, member, args_raw = call.groups()
                try:
                    args = self.fill_message(args_raw, here).strip() if args_raw else ''
                    line_now = self.object_call_line(who.strip(), member, args)
                    if line_now is None:
                        said.append(self.object_call(who.strip(), member, args, origin))
                        ran.append(raw.strip()[:80])
                        done += 1
                        return
                except Exception as e:
                    # a call that failed inside a call says the innermost why once
                    reason = re.sub(r'^(?:\S+\(\) could not be done: )+', '', str(e))
                    trouble = '%s.%s() could not be done: %s' % (who.strip()[:30], member, reason[:90])
                    said.append(trouble)
                    faults.append(trouble)
                    return
                # the line it stands for, done as that line is done - with the
                # same checks, and the same words back
                return do_line(line_now, scope)
            assign = self.SCRIPT_ASSIGN.match(raw.strip())
            if assign and raw.split()[0].lower() not in {v[0] for v in self.SCRIPT_VERBS}:
                who, member, value_raw = assign.groups()
                try:
                    value = self.fill_message(value_raw, here).strip() if value_raw else ''
                    said.append(self.object_set(who.strip(), member, value, origin))
                    ran.append(raw.strip()[:80])
                    done += 1
                except Exception as e:
                    trouble = '%s.%s could not be set: %s' % (who.strip()[:30], member, str(e)[:90])
                    said.append(trouble)
                    faults.append(trouble)
                    log('script %s: %s' % ((script or {}).get('name'), str(e)[:100]), 'warn')
                return
            line = self.fill_message(raw, here)
            if not line:
                return
            # What a name stands for came from outside - a message, a press -
            # and a line written as "on {thing}" would otherwise let whoever
            # sent it name anything at all, the house's own switches included.
            # A line may name those, but only where the writer wrote them.
            if line != raw:
                filled = line[len(raw.split()[0]):].strip().lower()
                if filled.startswith(('sys:', 'act:', 'rule:', 'sched:', 'script:')):
                    trouble = ('%s was not done: a name may not stand for %s'
                               % (raw.split()[0], filled.split(':')[0] + ':'))
                    said.append(trouble)
                    faults.append(trouble)
                    return
            verb = line.split()[0].lower()
            rest = line[len(verb):].strip()
            try:
                if verb in ('on', 'off', 'toggle'):
                    # A target nobody knows switches nothing and used to say
                    # nothing either, which reads exactly like a script that
                    # did its work.
                    if not self._valid_target(rest):
                        raise ValueError('there is nothing here called "%s"' % rest[:40])
                    self._fire_target(rest, verb, origin, facts=here)
                elif verb == 'pulse':
                    bits = rest.rsplit(' ', 1)
                    ms = int(bits[1]) if len(bits) > 1 and bits[1].isdigit() else 600
                    if not self._valid_target(bits[0].strip()):
                        raise ValueError('there is nothing here called "%s"' % bits[0].strip()[:40])
                    self._fire_target(bits[0].strip(), 'pulse', origin, pulse_ms=ms, facts=here)
                elif verb == 'set':
                    thing, value = rest.rsplit(' ', 1)
                    if not self._valid_target(thing.strip()):
                        raise ValueError('there is nothing here called "%s"' % thing.strip()[:40])
                    self._fire_target(thing.strip(), 'set:%s' % value.strip(), origin, facts=here)
                elif verb == 'heat':
                    said.append(self.heat_say(rest, origin))
                elif verb in ('ban', 'unban'):
                    # "ban {ip} 120" keeps it out for two hours; with no
                    # number, for as long as the settings say
                    bits = rest.split()
                    if not bits:
                        # the name it was given stood for nothing: said in
                        # those words rather than as whatever Python would
                        # have called it
                        said.append('%s had no address to work on \u2014 the name in that line was '
                                    'empty' % verb)
                        return
                    span = int(bits[1]) if len(bits) > 1 and bits[1].isdigit() else None
                    said.append(self.ban_by_name(verb, bits[0], origin, span))
                elif verb == 'say':
                    said.append(rest)
                elif verb == 'notify':
                    self.notify(rest, 'info', about='house', title=str(origin)[:40])
                elif verb == 'wait':
                    want = max(0.0, min(30.0, float(rest or 0)))
                    if want > left_to_wait:
                        said.append('waited %d s rather than %d: a script may not sleep longer '
                                    'than %d s in all' % (left_to_wait, want, self.SCRIPT_WAIT_TOTAL))
                        want = left_to_wait
                    left_to_wait -= want
                    time.sleep(want)
                elif verb == 'answer':
                    if rest:
                        answers.append(rest)
                elif verb == 'let':
                    bits = rest.split(None, 1)
                    if len(bits) < 2:
                        raise ValueError('let goes "let a-name something"')
                    if scope is None:
                        raise ValueError('a name can only be given inside the script')
                    scope[bits[0].strip().lower()] = bits[1].strip()
                elif verb == 'stop':
                    if rest:
                        said.append(rest)
                    stopped[0] = True
                ran.append(line[:80])
                done += 1
            except Exception as e:
                trouble = '%s could not be done: %s' % (verb, str(e)[:60])
                said.append(trouble)
                faults.append(trouble)
                log('script %s: %s' % ((script or {}).get('name'), str(e)[:100]), 'warn')

        # 'break' and 'next' are said by throwing a word up to the loop
        # that is running, which is the only way out of the middle of one
        class _Leave(Exception):
            pass

        class _Next(Exception):
            pass

        def ask(head, scope):
            return condition_holds(head, lambda n: self._script_stands_for(n, line_facts(scope)))

        def walk(nodes, scope):
            for node in nodes:
                if stopped[0] or steps[0] > self.SCRIPT_LINES_MOST:
                    return
                if isinstance(node, tuple):
                    kind, what, branches = node
                    if kind == 'jump':
                        raise _Leave() if what == 'break' else _Next()
                    if kind == 'if':
                        for index, branch in enumerate(branches):
                            head, body_lines = branch
                            # asked as it was written: the names in it are
                            # looked up here rather than put in first, or a
                            # name standing for "Falco" would leave the word
                            # Falco where a question about a name had been
                            holds = True if (index and not head) else ask(head, scope)
                            if holds:
                                walk(body_lines, scope)
                                break
                    elif kind in ('for', 'while', 'repeat'):
                        run_loop(kind, what, branches, scope)
                    continue
                steps[0] += 1
                if steps[0] > self.SCRIPT_LINES_MOST:
                    trouble = 'stopped after %d lines: a loop that does not end' % self.SCRIPT_LINES_MOST
                    said.append(trouble)
                    faults.append(trouble)
                    return
                do_line(node, scope)

        def one_turn(branches, inner):
            """One turn of a loop. False when the loop is to stop here."""
            try:
                walk(branches, inner)
            except _Next:
                return True
            except _Leave:
                return False
            return not stopped[0]

        LOOP_MARKS = ('loop_i', 'loop_n', 'loop_first', 'loop_last')

        def run_loop(kind, what, branches, scope):
            # A loop inside a loop shares the one set of names - that is what
            # makes "let" carry from turn to turn, and what makes a "while"
            # move at all - so the inner loop's own marks would be left behind
            # over the outer one's: after two turns of an inner loop, the
            # outer loop thought it was on its last turn and {loop_first}
            # stood for nothing, which skipped the line that asked for it.
            # The names a person writes are shared as before; only these four
            # are put back as the inner loop found them.
            held = [(k, (scope or {}).get(k)) for k in LOOP_MARKS]
            try:
                return _run_loop(kind, what, branches, scope)
            finally:
                if scope is not None:
                    for k, was in held:
                        if was is None:
                            scope.pop(k, None)
                        else:
                            scope[k] = was

        def _run_loop(kind, what, branches, scope):
            if kind == 'for':
                found = re.match(r'^\s*(?:each\s+)?([A-Za-z][A-Za-z0-9_]*)\s+(?:in|of)\s+(.+)$', what)
                if not found:
                    faults.append('for: %s is not "for a name in a list"' % what[:40])
                    return
                name, over = found.group(1).lower(), found.group(2).strip()
                items = _fact_items(self.fill_message(over if '{' in over else '{%s}' % over,
                                                      line_facts(scope)))
                if not items and ',' in over:
                    items = _fact_items(over)     # a list written out on the line itself
                # the same names all the way round, so a "let" inside a loop
                # still means something on the next turn - which is how a
                # while loop is meant to move at all
                inner = scope if scope is not None else {}
                items = items[:self.SCRIPT_TURNS_MOST]     # loop_last on the last turn gone round
                for number, item in enumerate(items, 1):
                    inner[name] = item
                    if not one_turn(branches, loop_marks(inner, number, len(items))):
                        return
            elif kind == 'repeat':
                times = numeric(self.fill_message(what, line_facts(scope)))
                if times is None:
                    faults.append('repeat: %s is not a number of times' % what[:40])
                    return
                times = max(0, min(self.SCRIPT_TURNS_MOST, int(times)))
                inner = scope if scope is not None else {}
                for number in range(1, times + 1):
                    if not one_turn(branches, loop_marks(inner, number, times)):
                        return
            else:                                   # while
                number = 0
                inner = scope if scope is not None else {}
                while ask(what, inner) and number < self.SCRIPT_TURNS_MOST:
                    number += 1
                    if steps[0] > self.SCRIPT_LINES_MOST:
                        return
                    if not one_turn(branches, loop_marks(inner, number, 0)):
                        return
                if number >= self.SCRIPT_TURNS_MOST:
                    trouble = ('a "while" went round %d times and was stopped: %s'
                               % (self.SCRIPT_TURNS_MOST, what[:40]))
                    said.append(trouble)
                    faults.append(trouble)

        def loop_marks(inner, number, total):
            inner['loop_i'] = str(number)
            inner['loop_n'] = str(total or '')
            inner['loop_first'] = 'yes' if number == 1 else ''
            inner['loop_last'] = 'yes' if total and number == total else ''
            return inner

        plan, trouble = self.script_plan(str((script or {}).get('body') or ''))
        for one in trouble:
            said.append(one)
            faults.append(one)
        try:
            walk(plan, names)
        except (_Leave, _Next):
            faults.append('break or next outside a loop')
        if not str((script or {}).get('body') or '').strip():
            # A script with nothing in it did nothing and said nothing, and
            # whatever answer was written by hand went back as though it had
            # worked. It says so now.
            trouble = '"%s" has no lines in it' % (script or {}).get('name')
            said.append(trouble)
            faults.append(trouble)
        elif not done and not faults:
            trouble = '"%s" did nothing' % (script or {}).get('name')
            said.append(trouble)
            faults.append(trouble)
        self.store.add_event('control', 'script "%s" ran %d line(s)%s for %s'
                             % ((script or {}).get('name'), done,
                                (', %d did not' % len(faults)) if faults else '', origin))
        for one in ((script or {}).get('results') or []):
            names.setdefault(str(one.get('name') or '').lower(), '')
        return {'lines': done, 'said': '\n'.join([x for x in said if x]), 'ran': ran,
                # the names the script made up as it ran, and what it wants
                # said back - both of them things the answer may quote
                'names': {k: v for k, v in names.items() if not k.startswith('loop_')},
                'answer': '\n'.join([x for x in answers if x]),
                # what went wrong, kept apart: an answer written by hand says
                # what was meant to happen, and must not be allowed to say it
                # over the top of a line that did not happen
                'faults': faults}

    def save_sms_commands(self, items):
        clean, seen = [], set()
        for index, c in enumerate(items or []):
            if not isinstance(c, dict):
                continue
            if untouched_row(c, ('phrase', 'target', 'reply')):
                continue
            phrase = str(c.get('phrase') or '').strip()[:60]
            if not phrase:
                raise ValueError('command %d needs a word to listen for' % (index + 1))
            if phrase.lower() in seen:
                raise ValueError('two commands listening for "%s"' % phrase)
            seen.add(phrase.lower())
            wanted = str(c.get('do') or 'on')
            if str(c.get('target') or '').startswith('script:'):
                target, do = str(c.get('target'))[:60], 'script'
            elif wanted in ('ban', 'unban'):
                # what it acts on is an address the message carries, written
                # as a name, not a thing in the house
                target = str(c.get('target') or '{args}')[:60]
            else:
                target = self._valid_target(str(c.get('target') or ''))
            # A reply used to be cut at one text message's worth, silently, so
            # anything longer came back missing its tail. A long answer is not
            # wrong - it is several messages, and the gateway is given time
            # for them - so it is allowed the room an alert has, and what it
            # costs is shown beside the box.
            reply = str(c.get('reply') or '').strip()[:500]
            if target is None and not reply:
                raise ValueError('command "%s" needs something to switch, or something to answer' % phrase)
            do = (wanted if wanted in ('ban', 'unban', 'script')
                  else valid_action(c.get('do') or 'on'))
            if target is not None and do is None:
                raise ValueError('command "%s": %r is not an action' % (phrase, c.get('do')))
            clean.append({'id': str(c.get('id') or '') or secrets.token_hex(4), 'group': _grp(c),
                          'phrase': phrase, 'target': target or '', 'do': do or 'on', 'reply': reply,
                          'takes_value': bool(c.get('takes_value')),
                          # a command that raises an alarm does not want a text
                          # back at whoever sent it; this says so per command
                          'answer': c.get('answer', True) is not False,
                          'from_anyone': bool(c.get('from_anyone')),
                          # names this command makes up for itself, each
                          # standing for something the message carries
                          'vars': self.clean_vars(c.get('vars'), phrase),
                          'enabled': c.get('enabled', True) is not False})
        self.snapshot('sms_commands', 'saved from the dashboard')
        self.store.set_meta('sms_commands', json.dumps(clean))
        self.store.add_event('control', '%d SMS command(s) saved' % len(clean))
        self.bump()
        return clean

    @staticmethod
    def _same_number(a, b):
        """Two ways of writing one phone: +420 777 123 456 and 777123456.

        The last nine digits decide only where one of the two was written
        without its country. Two numbers that both say which country they are
        in are compared whole: on the last nine alone, +421 777 123 456 - a
        different phone in another country, and a sender anybody can claim -
        was the owner of +420 777 123 456, with the run of the house by text.
        And nine digits it has to be: an entry shorter than that matched every
        sender whose number happened to end with it.
        """
        def plain(n):
            n = str(n or '').strip()
            whole = n.startswith('+') or n.startswith('00')
            digits = re.sub(r'[^0-9]', '', n)
            if n.startswith('00'):
                digits = digits[2:]
            return digits, whole
        (da, wa), (db, wb) = plain(a), plain(b)
        if not da or not db:
            return False
        if da == db:
            return True
        if wa and wb:
            return False
        return len(da) >= 9 and len(db) >= 9 and da[-9:] == db[-9:]

    def sms_recipients(self):
        """Who an alert goes to: everybody ticked for alerts on their own
        card, plus any number in the settings that belongs to nobody."""
        out = [p['phone'] for p in self.people() if p.get('phone') and p.get('sms_alerts')]
        for extra in [x.strip() for x in str(CONFIG.get('sms_to') or '').split(',') if x.strip()]:
            if not any(self._same_number(extra, x) for x in out):
                out.append(re.sub(r'[^0-9+]', '', extra))
        return [x for x in out if x]

    def sms_commanders(self):
        """Which numbers may ask for something: everybody ticked for commands,
        plus the extra numbers in the settings."""
        out = [p['phone'] for p in self.people() if p.get('phone') and p.get('sms_commands')]
        out += [x.strip() for x in str(CONFIG.get('sms_allow') or '').split(',') if x.strip()]
        return [re.sub(r'[^0-9+]', '', x) for x in out if x]

    def person_by_phone(self, number):
        for person in self.people():
            if person.get('phone') and self._same_number(person['phone'], number):
                return person
        return None

    def phone_of(self, who):
        """A number for a person, by id or by name."""
        for person in self.people():
            if str(who) in (person['id'], person['name']) and person.get('phone'):
                return person['phone']
        return None

    def sms_allowed(self, number):
        number = re.sub(r'[^0-9+]', '', str(number or ''))
        if not number:
            return False
        # having a number on a card is not permission by itself; the tick
        # beside it is, which is why both live in the same place
        return any(self._same_number(entry, number) for entry in self.sms_commanders())

    def _sms_poll_thread(self):
        # the inbox only: how the modem is doing has a beat of its own, see
        # _sms_status_thread
        try:
            self.sms_poll()
        except Exception as e:
            log('SMS poll: %s' % e, 'warn')
        finally:
            self._sms_busy = False

    def _sms_status_thread(self):
        try:
            self.sms_status_poll()
        except Exception as e:
            log('SMS gateway status: %s' % e, 'warn')
        finally:
            self._sms_status_busy = False

    def _ubus_call(self, obj, method, params=None):
        """One call on the gateway's own bus. The session is kept while it
        lasts; RutOS hands out a token that expires, so a refusal means log in
        again rather than give up."""
        import urllib.request
        timeout = float(CONFIG.get('sms_timeout_s') or 15)
        def rpc(session, obj_, method_, params_):
            body = {'jsonrpc': '2.0', 'id': 1, 'method': 'call',
                    'params': [session, obj_, method_, params_ or {}]}
            req = urllib.request.Request(self._sms_url('/ubus'), data=json.dumps(body).encode(),
                                         headers={'Content-Type': 'application/json'}, method='POST')
            return json.loads(self._sms_open(req, timeout).read())
        if not self._ubus_session:
            answer = rpc('0' * 32, 'session', 'login',
                         {'username': CONFIG.get('sms_ubus_user') or 'root',
                          'password': CONFIG.get('sms_ubus_password') or CONFIG.get('sms_password') or ''})
            result = (answer.get('result') or [None, {}])
            self._ubus_session = (result[1] or {}).get('ubus_rpc_session')
            if not self._ubus_session:
                raise RuntimeError('the gateway would not log us in over ubus')
        answer = rpc(self._ubus_session, obj, method, params)
        if answer.get('error') or (answer.get('result') or [1])[0] == 6:
            self._ubus_session = None              # the session went stale
            raise RuntimeError('ubus refused %s %s' % (obj, method))
        out = answer.get('result') or []
        return out[1] if len(out) > 1 else {}

    def modem_ussd(self, code=None, origin='the dashboard'):
        """Ask the network something in its own language: *101# for what is
        left on a prepaid SIM, and whatever else the operator answers to. The
        answer is kept as a reading, so a chart can show the credit going
        down and a rule can watch it."""
        if not self.sim_prepaid():
            return False, 'this SIM is on a contract - there is no credit to ask about'
        code = str(code or CONFIG.get('sms_credit_code') or '').strip()
        if not code:
            return False, 'no code to send - the operator says which one, often *101#'
        if not self._sms_rest():
            return False, 'the older interface cannot ask this; use the device\'s own API'
        try:
            out = self._rest('/modems/%s/actions/send_ussd' % self.sms_modem_id(), 'POST',
                             {'data': {'ussd': code}})
        except Exception as e:
            return False, str(e)[:200]
        text = ''
        if isinstance(out, dict):
            text = str(out.get('message') or out.get('response') or '').strip()
        elif isinstance(out, str):
            text = out.strip()
        self.store.add_event('sms', 'asked the network %s: %s' % (code, text[:120] or '(nothing back)'), 'info')
        if not text:
            return True, 'the network said nothing'
        self.store.set_meta('sms_credit', json.dumps({'code': code, 'text': text, 'at': int(time.time())}))
        parts = credit_parts(text)
        if CONFIG.get('sms_credit_pattern'):     # a pattern of your own wins over all of it
            own = credit_from(text, CONFIG['sms_credit_pattern'])
            if own is not None:
                parts['credit'] = own
                parts.pop('credit_total', None)
        parts = {k: v for k, v in parts.items() if v is not None}
        if parts and self.sms_ready():
            self.record('sms:gateway', str(CONFIG.get('sms_name') or 'SMS-Gateway'), parts)
        self.bump()
        return True, text

    def forget_credit(self):
        """Take the credit readings away.

        A figure that was true of the old SIM is worse than no figure: it
        stands there on the modem's card looking current. Switching to a
        contract takes them off the card, out of the readings and out of the
        last answer from the network; switching back fills them again the
        next time the network is asked.
        """
        entry = self.live.get('sms:gateway')
        left = None
        if entry:
            left = {k: v for k, v in (entry.get('payload') or {}).items() if not k.startswith('credit')}
            entry['payload'] = left
            entry['rev'] = (entry.get('rev') or 0) + 1
        if left is not None:
            self.store.replace_snapshot('sms:gateway', left)
        self.store.set_meta('sms_credit', '')
        self.bump()

    # -- Duo, as a second factor ---------------------------------------------
    def duo_devices(self):
        """The account's devices as the last test saw them."""
        try:
            out = json.loads(self.store.get_meta('duo_devices') or '[]')
        except ValueError:
            return []
        return [d for d in out if isinstance(d, dict) and d.get('device')]

    def duo_device_name(self, which):
        """A device by the name Duo shows, not by the twenty letters of its id."""
        which = str(which or '')
        if not which or which == 'auto':
            return ''
        for dv in self.duo_devices():
            if dv.get('device') == which:
                return dv.get('name') or which
        return which

    def duo_ready(self):
        return all(str(CONFIG.get(k) or '').strip() for k in ('duo_host', 'duo_ikey', 'duo_skey', 'duo_user'))

    def duo_call(self, method, path, params, timeout=20):
        """One signed request. Returns the `response` part, or raises.

        Which way Duo wants the request signed is not something this can know
        from here: the Auth API documents version 2, the published client now
        defaults to version 5, and an account will take one and answer
        "Invalid signature in request credentials" to the other - which says
        nothing about which. So the documented one is tried, the other is
        tried once if that is what comes back, and whichever answered is
        remembered, so it is asked at most once per daemon.
        """
        host = str(CONFIG.get('duo_host') or '').strip().replace('https://', '').strip('/')
        if not host:
            raise ValueError('no Duo host is set')
        # Duo's own client, when the machine has it: it is the reference for
        # every detail of the signing, and four releases went by here getting
        # those details wrong one at a time. `pip install duo-client`, and
        # what follows is never reached. Without it the daemon signs for
        # itself, as it must - this ships as one file with no dependencies.
        lib = self.duo_lib(timeout)
        if lib is not None:
            try:
                out = lib.json_api_call(method, path, params)
                if getattr(self, '_duo_said_lib', None) != id(lib):
                    self._duo_said_lib = id(lib)
                    log('Duo: using the duo_client package')
                if CONFIG.get('debug'):
                    log('duo <- %s through duo_client: %s' % (path, self.duo_gist(out)), 'debug')
                return out if isinstance(out, dict) else {}
            except Exception as e:
                said = str(e)[:200]
                if CONFIG.get('debug'):
                    log('duo <- %s through duo_client: %s' % (path, said), 'debug')
                if 'signature' not in said.lower():
                    raise ValueError(said)
                log('Duo: the duo_client package was refused too; signing here instead', 'warn')
        known = getattr(self, '_duo_way', None) or self.store.get_meta('duo_way') or ''
        ways = [tuple(known.split(':'))] if ':' in known else list(DUO_WAYS)
        trouble = None
        for version, digest in ways:
            try:
                out = self._duo_once(method, path, params, host, version, digest, timeout)
            except ValueError as e:
                trouble = e
                if 'signature' not in str(e).lower():
                    raise
                continue
            if getattr(self, '_duo_way', None) != '%s:%s' % (version, digest):
                self._duo_way = '%s:%s' % (version, digest)
                self.store.set_meta('duo_way', self._duo_way)
                log('Duo takes signature version %s with %s' % (version, digest))
            return out
        raise trouble

    @staticmethod
    def duo_gist(answer):
        """The few words of an answer worth writing down - never a secret,
        unless the house has asked for everything open with debug_secrets."""
        if CONFIG.get('debug_secrets'):
            try:
                return json.dumps(answer)[:2000]
            except Exception:
                return str(answer)[:2000]
        if not isinstance(answer, dict):
            return 'ok'
        keep = [(k, answer.get(k)) for k in ('result', 'status', 'status_msg', 'waiting', 'success',
                                             'txid', 'time') if answer.get(k) is not None]
        devices = answer.get('devices')
        if isinstance(devices, list):
            keep.append(('devices', ', '.join(
                '%s[%s]' % (str(dv.get('display_name') or dv.get('device') or '?')[:24],
                            '+'.join(str(c) for c in (dv.get('capabilities') or [])))
                for dv in devices[:4] if isinstance(dv, dict))))
        return ', '.join('%s=%s' % (k, str(v)[:60]) for k, v in keep) or 'ok'

    def duo_lib(self, timeout=20):
        """Duo's own client, if this machine has it."""
        if getattr(self, '_duo_lib_gone', False):
            return None
        try:
            import duo_client
        except Exception:
            self._duo_lib_gone = True
            log('Duo: the duo_client package is not installed; signing here instead '
                '(pip install duo-client)')
            return None
        try:
            return duo_client.Auth(ikey=str(CONFIG.get('duo_ikey') or '').strip(),
                                   skey=str(CONFIG.get('duo_skey') or '').strip(),
                                   host=str(CONFIG.get('duo_host') or '').strip()
                                   .replace('https://', '').strip('/'),
                                   # a waiting request must not be able to hang
                                   # a thread of the daemon for ever
                                   timeout=timeout)
        except Exception as e:
            log('Duo: the duo_client package would not start: %s' % str(e)[:120], 'warn')
            self._duo_lib_gone = True
            return None

    def _duo_once(self, method, path, params, host, version, digest, timeout):
        import email.utils
        import urllib.request
        when = email.utils.formatdate()
        # Stripped here as well as when they are saved: a key pasted from a
        # web page brings a space or a newline with it more often than not,
        # and a key with one stuck to it signs a request Duo refuses with the
        # same words as a key that is simply wrong.
        ikey = str(CONFIG.get('duo_ikey') or '').strip()
        skey = str(CONFIG.get('duo_skey') or '').strip()
        head = {'Date': when, 'User-Agent': 'zigmon/%s' % __version__,
                'Authorization': duo_sign(ikey, skey, method, host, path, when, params, version, digest)}
        url = 'https://%s%s' % (host, path)
        data = None
        if method == 'POST':
            if str(version) == '5':
                head['Content-Type'] = 'application/json'
                data = duo_body(params).encode('utf-8')
            else:
                head['Content-Type'] = 'application/x-www-form-urlencoded'
                data = urlencode({k: str(v) for k, v in params.items()}).encode('utf-8')
        elif params:
            url += '?' + urlencode({k: str(v) for k, v in params.items()})
        req = urllib.request.Request(url, data=data, headers=head, method=method)
        # Enough to mend a refusal with and nothing more: which request went,
        # signed which way, and what came back. The Authorization header, the
        # keys and any code in the parameters are not written down - a bad
        # signature is mended by knowing the shape of what was signed, not by
        # knowing the secret it was signed with.
        if CONFIG.get('debug'):
            log('duo -> %s %s%s sig v%s %s, %d parameter(s): %s'
                % (method, host, path, version, digest, len(params),
                   ', '.join(sorted(params)) or 'none'), 'debug')
        started = time.perf_counter()
        try:
            with urllib.request.urlopen(req, timeout=timeout) as answer:
                out = json.loads(answer.read().decode('utf-8', 'replace'))
            if CONFIG.get('debug'):
                log('duo <- %s in %.0f ms: %s' % (path, (time.perf_counter() - started) * 1000,
                                                  self.duo_gist(out.get('response') or {})), 'debug')
        except urllib.error.HTTPError as e:
            try:
                out = json.loads(e.read().decode('utf-8', 'replace'))
            except Exception:
                if CONFIG.get('debug'):
                    log('duo <- %s HTTP %s in %.0f ms, and not JSON - is the hostname the Auth API one?'
                        % (path, e.code, (time.perf_counter() - started) * 1000), 'debug')
                raise ValueError('Duo answered HTTP %s with nothing to say - check the hostname' % e.code)
            if CONFIG.get('debug'):
                log('duo <- %s HTTP %s in %.0f ms: %s (code %s)'
                    % (path, e.code, (time.perf_counter() - started) * 1000,
                       str(out.get('message') or '')[:120], out.get('code')), 'debug')
            said = str(out.get('message') or out.get('code') or ('HTTP %s' % e.code))[:160]
            if 'signature' in said.lower():
                # the one refusal that says nothing about its own cause: three
                # things look identical to Duo from here
                said += (' - check that the integration key and the secret key are not the other '
                         'way round, that neither carries a stray space, and that the hostname is '
                         'the one from the same Auth API application')
            raise ValueError(said)
        if str(out.get('stat')) != 'OK':
            raise ValueError(str(out.get('message') or 'Duo refused the request')[:160])
        return out.get('response') or {}

    def duo_check(self):
        """Whether the keys are right - what the Test button asks."""
        try:
            self.duo_call('GET', '/auth/v2/check', {})
        except Exception as e:
            return False, str(e)[:180]
        try:
            pre = self.duo_call('POST', '/auth/v2/preauth',
                                {'username': str(CONFIG.get('duo_user') or ''),
                                 'client_supports_verified_push': '1'})
        except Exception as e:
            return False, 'the keys are good but the user is not: %s' % str(e)[:140]
        result = str(pre.get('result') or '')
        if result in ('deny', 'enroll'):
            return False, str(pre.get('status_msg') or 'that user cannot be asked')[:160]
        # A device that cannot take a push is no use to a link: the test has to
        # say so here rather than let the first press vanish into nothing.
        # What preauth says about the account's devices, kept so the dashboard
        # can offer them: a house with three of them cannot be asked to guess
        # which one Duo's "auto" will pick, and auto picks one of its own
        # choosing rather than the one in your pocket.
        self.store.set_meta('duo_devices', json.dumps(
            [{'device': str(dv.get('device') or ''),
              'name': str(dv.get('display_name') or dv.get('name') or dv.get('device') or '?'),
              'type': str(dv.get('type') or ''),
              'capabilities': [str(c) for c in (dv.get('capabilities') or [])]}
             for dv in (pre.get('devices') or []) if isinstance(dv, dict) and dv.get('device')]))
        self.bump()
        pushable = [str(dv.get('display_name') or dv.get('device') or '?')
                    for dv in (pre.get('devices') or [])
                    if isinstance(dv, dict) and 'push' in (dv.get('capabilities') or [])]
        every = sorted({str(dv.get('display_name') or dv.get('device') or '?')
                        for dv in (pre.get('devices') or []) if isinstance(dv, dict)})
        if not pushable:
            return False, ('Duo knows %s, but none of its devices can take a push: %s. '
                           'Enrol the Duo Mobile app for that user'
                           % (CONFIG.get('duo_user'), ', '.join(every) or 'no device at all'))
        return True, 'Duo knows %s and can push to %s' % (CONFIG.get('duo_user'), ', '.join(pushable))

    def duo_push(self, what, who=''):
        """Ask Duo, and wait for the answer. Called on a thread of its own."""
        pushinfo = urlencode([('what', what[:120])] + ([('from', who[:60])] if who else []))
        started = self.duo_call('POST', '/auth/v2/auth',
                                {'username': str(CONFIG.get('duo_user') or ''),
                                 'factor': 'push',
                                 'device': str(CONFIG.get('duo_device') or 'auto').strip() or 'auto',
                                 'async': '1',
                                 'type': 'zigmon', 'display_username': str(CONFIG.get('duo_user') or ''),
                                 'pushinfo': pushinfo})
        txid = str(started.get('txid') or '')
        if not txid:
            raise ValueError('Duo did not say which request this is')
        deadline = time.time() + max(10, int(CONFIG.get('duo_wait_s') or 60))
        while time.time() < deadline:
            state = self.duo_call('GET', '/auth/v2/auth_status', {'txid': txid},
                                  timeout=max(5, int(deadline - time.time()) + 5))
            # What the endpoint itself answers is a `result` of waiting, allow
            # or deny. The published client's own auth_status() turns that
            # into `waiting` and `success`, and this asks the endpoint
            # directly, so it gets neither: reading those off the raw answer
            # made every press refused a fifth of a second after it was made,
            # before the phone had finished buzzing. Both shapes are read now,
            # since which one arrives depends on which road the request took.
            said = str(state.get('status_msg') or state.get('status') or '')[:160]
            if 'waiting' in state or 'success' in state:
                if not state.get('waiting'):
                    return bool(state.get('success')), said
                continue
            result = str(state.get('result') or '').lower()
            if result == 'allow':
                return True, said or 'approved'
            if result and result != 'waiting':
                return False, said or result
        return False, 'nobody answered in time'

    def sim_prepaid(self):
        """Whether this SIM has credit worth asking about."""
        return str(CONFIG.get('sms_sim') or 'prepaid').strip().lower() != 'contract'

    def sms_credit(self):
        try:
            return json.loads(self.store.get_meta('sms_credit') or '{}')
        except ValueError:
            return {}

    def modem_data_base(self):
        """The mark the data counters are measured from."""
        try:
            return json.loads(self.store.get_meta('modem_data_base') or '{}')
        except ValueError:
            return {}

    def modem_data_reset(self, origin='the dashboard'):
        """Start counting again from here. The modem's own total is left
        alone - it is the mark that moves."""
        raw = {}
        try:
            rows = self._rest('/modems/status') or []
            if isinstance(rows, dict):
                rows = rows.get('data') or [rows]
            row = next((r for r in rows if r.get('id')), {}) if isinstance(rows, list) else {}
            raw = {'sent': numeric(row.get('txbytes')) or 0, 'received': numeric(row.get('rxbytes')) or 0}
        except Exception as e:
            return False, str(e)[:150]
        raw['at'] = time.time()
        self.store.set_meta('modem_data_base', json.dumps(raw))
        self.store.add_event('sms', 'the data counters were set back to zero (%s)' % origin, 'info')
        try:
            self.sms_status_poll()
        except Exception:
            pass
        self.bump()
        return True, 'counting again from now'

    def sms_modem_status(self):
        """Signal, network, operator, SIM and what the SIM has spent, asked of
        the modem itself. Far more than the status page gives, and the same on
        every RutOS device."""
        values = {}
        try:
            signal = self._ubus_call('gsm.modem0', 'get_signal_query') or {}
            for ours, theirs in (('rssi', 'rssi'), ('rsrp', 'rsrp'), ('rsrq', 'rsrq'), ('sinr', 'sinr')):
                if numeric(signal.get(theirs)) is not None:
                    values[ours] = numeric(signal.get(theirs))
            if signal.get('conn_type') or signal.get('nettype'):
                values['network'] = signal.get('conn_type') or signal.get('nettype')
        except Exception as e:
            self.debug('ubus signal', str(e))
        try:
            info = self._ubus_call('gsm.modem0', 'info') or {}
            for ours, theirs in (('operator', 'operator'), ('network', 'net_mode'), ('sim', 'sim_state'),
                                 ('imei', 'imei'), ('cell', 'cell_id'), ('roaming', 'roaming')):
                if info.get(theirs) not in (None, ''):
                    values.setdefault(ours, info.get(theirs))
            if numeric(info.get('temperature')) is not None:
                values['modem_temperature'] = numeric(info.get('temperature')) / (10.0 if numeric(info['temperature']) > 200 else 1)
        except Exception as e:
            self.debug('ubus info', str(e))
        try:
            usage = self._ubus_call('gsm.modem0', 'get_data_usage') or {}
            for ours, theirs in (('data_month_mb', 'month'), ('data_today_mb', 'today')):
                value = numeric((usage.get(theirs) or {}).get('total') if isinstance(usage.get(theirs), dict) else usage.get(theirs))
                if value is not None:
                    values[ours] = round(value / 1048576.0, 1) if value > 100000 else value
        except Exception as e:
            self.debug('ubus usage', str(e))
        return values

    def sms_status_poll(self):
        """What the gateway itself has to say: signal, network, operator, the
        state of its SIM. Recorded like any other device's reading, so the
        History tab charts it and a rule can watch it - a mast that fades to
        nothing is worth knowing about before the alert that needs it."""
        if not self.sms_ready():
            return None
        # Not while a message is going out or has just gone. A day's log says
        # this runs six times a minute - 13,665 times in twenty-four hours -
        # and every one is two questions to a box that struggles to answer
        # one while its radio is working. Asking it how it feels can wait
        # thirty seconds; the message cannot.
        busy = getattr(self, '_sms_sending', 0)
        if busy and time.time() - busy < 120:
            return None
        if time.time() - getattr(self, '_sms_sent_at', 0) < 30:
            return None
        # ...and the same lock the sending takes, not only the flag beside it.
        # The flag is set as a message is handed over; a status question that
        # went out a moment earlier is still in flight, and that box answers
        # one thing at a time. So the message queued behind "how do you feel",
        # waited out our patience and was written down as "no answer from the
        # gateway" - while going out perfectly well. It is the one thing still
        # asking the box when the webhook brings the messages and the gateway
        # deletes them itself, which is where it was seen.
        #
        # Taken without waiting: a status that cannot have the box right now
        # simply does not happen this time round, and the message goes.
        if not self._sms_send_lock.acquire(blocking=False):
            return None
        try:
            return self._sms_status_now()
        finally:
            self._sms_send_lock.release()

    def _sms_status_now(self):
        timeout = float(CONFIG.get('sms_timeout_s') or 15)
        values = {}
        via = CONFIG.get('sms_status_via') or 'auto'
        if via == 'auto':
            # follow the interface that is set: a TRB140 answers its own API,
            # and asking a bus it does not run would cost a timeout every poll
            via = 'ubus' if not self._sms_rest() and CONFIG.get('sms_ubus_password') else 'same'
        if via == 'ubus':
            # the bus knows far more than the status page; when it is not to be
            # had, fall back rather than leave the card empty
            values = self.sms_modem_status()
            if values or via == 'ubus':
                return self._sms_record_status(values)
        try:
            if self._sms_rest():
                rows = self._rest('/modems/status') or []
                if isinstance(rows, dict):
                    rows = rows.get('data') or [rows]
                row = next((r for r in rows if r.get('id')), {}) if isinstance(rows, list) else {}
                # The names the device itself uses. It says far more about
                # itself than a signal figure, and all of it is worth keeping:
                # a mast that changes, a band that drops, a SIM with two PIN
                # tries left are all things one wants to see before they bite.
                values = {}
                for ours, theirs in (
                        ('rssi', 'rssi'), ('rsrp', 'rsrp'), ('rsrq', 'rsrq'), ('sinr', 'sinr'),
                        ('ecio', 'ecio'), ('rscp', 'rscp'), ('signal_quality', 'signal_quality'),
                        ('modem_temperature', 'temperature'), ('pin_tries_left', 'pinleft')):
                    value = numeric(row.get(theirs))
                    if value is not None:
                        values[ours] = value
                if row.get('volte') is not None:
                    values['volte'] = 'yes' if row['volte'] in (True, 'yes', 1, '1') else 'no'
                for ours, theirs in (
                        ('operator', 'operator'), ('provider', 'provider'), ('network', 'conntype'),
                        ('band', 'band'), ('cell', 'cellid'), ('area_code', 'lac'), ('tracking_area', 'tac'),
                        ('sim', 'simstate'), ('pin', 'pinstate'), ('state', 'state'),
                        ('registration', 'netstate'), ('operator_state', 'operator_state'),
                        ('active_sim', 'active_sim'), ('imei', 'imei'),
                        ('firmware', 'version'), ('sms_centre', 'sms_center_address'),
                        ('antenna', 'external_antenna_enabled')):
                    if row.get(theirs) not in (None, ''):
                        values[ours] = row[theirs]
                iccid = str(row.get('iccid') or '')
                if len(iccid) > 4:
                    values['sim_card'] = '\u2026' + iccid[-4:]     # enough to tell two SIMs apart
                    self._secrets['sim_card'] = iccid              # the whole of it, for --secret
                # What the modem has carried. It counts from the moment it
                # connected and has no way of being told to start again, so the
                # counting from a mark of our own is done here: the raw figures
                # are kept beside them, and a modem that has restarted (its own
                # count gone backwards) moves the mark rather than showing a
                # negative.
                base = self.modem_data_base()
                for ours, theirs in (('sent', 'txbytes'), ('received', 'rxbytes')):
                    bytes_ = numeric(row.get(theirs))
                    if bytes_ is None:
                        continue
                    values[ours + '_total_mb'] = round(bytes_ / 1048576.0, 2)
                    mark = numeric(base.get(ours)) or 0
                    if bytes_ < mark:
                        mark = 0
                        base[ours] = 0
                        self.store.set_meta('modem_data_base', json.dumps(base))
                    values[ours + '_mb'] = round((bytes_ - mark) / 1048576.0, 2)
                if base.get('at'):
                    values['data_since'] = human_span(time.time() - base['at'])
                # what it says about the SIM and the cell it is on
                for ours, theirs in (('provider', 'provider'), ('operator_state', 'operator_state'),
                                     ('network_type', 'ntype'), ('busy', 'busy_state'),
                                     ('esim', 'esim_profile'), ('mimo', 'mimo_4g_max')):
                    if row.get(theirs) not in (None, ''):
                        values[ours] = row[theirs]
                for ours, theirs in (('sim_slots', 'sim_count'), ('signal_quality', 'signal_quality')):
                    value = numeric(row.get(theirs))
                    if value is not None:
                        values[ours] = value
                imsi = str(row.get('imsi') or '')
                if len(imsi) > 5:
                    # the country and network are worth having; the subscriber
                    # is not, so the rest of it never reaches the database
                    values['mcc'] = imsi[:3]
                    values['mnc'] = imsi[3:5]
                if row.get('ca_signal'):
                    values['carrier_aggregation'] = 'active' if len(row['ca_signal']) > 1 else 'inactive'
                try:                                   # the bands, one row each
                    signal = self._rest('/modems/signal/status') or []
                    part = (signal[0] if isinstance(signal, list) and signal else signal) or {}
                    bands = part.get('signal') or []
                    best = bands[0] if bands else {}
                    for ours, theirs in (('rsrp', 'rsrp'), ('rsrq', 'rsrq'), ('sinr', 'sinr'), ('rssi', 'rssi'),
                                         ('earfcn', 'earfcn'), ('physical_cell', 'pcid'),
                                         ('bandwidth_mhz', 'bandwidth')):
                        value = numeric(best.get(theirs))
                        if value is not None:
                            values.setdefault(ours, value)
                    if best.get('band') and not values.get('band'):
                        values['band'] = best['band']
                    if bands:
                        values['bands'] = len(bands)
                    for entry in bands:                # older firmware lists them by name
                        name = str(entry.get('name') or entry.get('type') or '').lower()
                        value = numeric(entry.get('value'))
                        if name in ('rsrp', 'rsrq', 'sinr', 'rssi') and value is not None:
                            values[name] = value
                    self._modem_bands = bands
                except Exception as e:
                    self.debug('modem signal', str(e))
            else:
                url = self._sms_url(CONFIG.get('sms_status_path') or '/cgi-bin/status',
                                    {'username': CONFIG.get('sms_user') or '', 'password': CONFIG.get('sms_password') or ''})
                body = self._sms_open(url, timeout).read().decode('utf-8', 'replace')
                for line in body.splitlines():
                    if ':' not in line:
                        continue
                    key, value = line.split(':', 1)
                    key = key.strip().lower().replace(' ', '_')
                    value = value.strip()
                    if key in ('rssi', 'rsrp', 'rsrq', 'sinr', 'signal', 'signal_strength'):
                        values['rssi' if key.startswith('sig') else key] = numeric(re.sub(r'[^0-9.\-]', '', value))
                    elif key in ('operator', 'network', 'connection_type', 'sim_state', 'imei'):
                        values[{'connection_type': 'network', 'sim_state': 'sim'}.get(key, key)] = value
        except Exception as e:
            self.debug('SMS status', str(e))
            return None
        return self._sms_record_status(values)

    def _sms_record_status(self, values):
        values = {k: v for k, v in (values or {}).items() if v is not None and v != ''}
        if not values:
            return None
        name = str(CONFIG.get('sms_name') or 'SMS-Gateway')
        self.store.upsert_device({'id': 'sms:gateway', 'name': name, 'source': 'sms',
                                  'kind': 'SMS gateway', 'vendor': 'Teltonika',
                                  'model': values.get('network') or 'modem',
                                  'last_seen': int(time.time())})
        values['sent_today'] = self._sms_counted('out')
        values['received_today'] = self._sms_counted('in')
        values['waiting_to_go'] = len(self.sms_outbox())
        # How many the device is holding - but NOT on every status reading.
        # This runs six times a minute, and reading that box's inbox is what
        # wedges it: 4.59.0 never read it and never stalled. Once every ten
        # minutes is plenty for a number on a card.
        #
        # And never with the webhook on. There the rule is that the inbox is
        # read only when a webhook has its own message to take off it - and
        # this count, riding on the status reading, was a read of it every ten
        # minutes that nobody had asked for. The status reading had quietly
        # stopped when looking was set to never, which hid it; giving the
        # status its own beat would have brought it straight back.
        if int(CONFIG.get('sms_push') or 0):
            self._sms_inbox_count = None
        elif time.time() - getattr(self, '_sms_counted_inbox_at', 0) > 600:
            self._sms_counted_inbox_at = time.time()
            try:
                self._sms_inbox_count = len(self.sms_listing())
            except Exception:
                pass
        if getattr(self, '_sms_inbox_count', None) is not None:
            values['in_the_inbox'] = self._sms_inbox_count
        commands = [c for c in self.sms_commands() if c.get('enabled', True)]
        values['commands'] = len(commands)
        self.record('sms:gateway', name, values)
        return values

    def _sms_counted(self, way):
        lt = time.localtime()
        since = time.mktime((lt.tm_year, lt.tm_mon, lt.tm_mday, 0, 0, 0, 0, 0, -1))   # today, as it says
        return self.store.count_events('sms', since, 'sent to' if way == 'out' else 'from ')

    @staticmethod
    def _sms_key(message):
        """What tells one message from another. The slot alone will not: the
        device gives a slot back when a message is deleted, so the same words
        from the same number can land in it twice."""
        return '%s|%s|%s|%s' % (message.get('id') or '', message.get('date') or '',
                                message.get('from') or '', (message.get('text') or '')[:40])

    def _sms_remember(self, key):
        """This one has been dealt with. Oldest first, so what is dropped when
        the list grows long is what came first."""
        self._sms_seen.pop(key, None)
        self._sms_seen[key] = int(time.time())
        while len(self._sms_seen) > 200:
            self._sms_seen.popitem(last=False)
        self._sms_save_seen()

    def _sms_save_seen(self):
        self.store.set_meta('sms_seen', json.dumps([[k, v] for k, v in self._sms_seen.items()]))

    def sms_listing(self):
        """Exactly what the device lists, untouched: the answer to "it says it
        has none" without having to trust anything in between."""
        if self._sms_rest():
            rows = self._rest('/messages/status') or []
            if isinstance(rows, dict):
                rows = rows.get('data') or []
            return [{'id': str(r.get('id') or ''), 'from': r.get('sender') or '',
                     'text': r.get('message') or '', 'status': r.get('status') or '',
                     'date': r.get('date') or ''} for r in rows]
        url = self._sms_url(CONFIG.get('sms_read_path') or '/cgi-bin/sms_list',
                            {'username': CONFIG.get('sms_user') or '', 'password': CONFIG.get('sms_password') or ''})
        return self._sms_parse_list(self._sms_open(url).read().decode('utf-8', 'replace'))

    def sms_poll(self, force=False):
        """Look for messages that came in, act on the ones that are allowed to
        ask for something, and answer. A number that is not on the list is
        recorded and otherwise ignored - the gateway is on the internet, and a
        wrong number should not be able to open the house."""
        # Two ways in, and only ever one of them. Switched off, the inbox is
        # read and emptied here exactly as it always was. Switched on, nothing
        # here touches the inbox at all: messages arrive by the webhook and
        # the modem does its own deleting. Trying to do both at once is what
        # made a mess of it - each way is simple on its own and there is
        # nothing to tell apart, nothing to skip and nothing to duplicate.
        if int(CONFIG.get('sms_push') or 0) and not force:
            # Nothing deleted from here unless asked. The modem's own urcd
            # removes a forwarded message five seconds after it is forwarded
            # - that is in its log - and anybody else deleting the same slot,
            # the forwarder or this house, is the fight that stalls the box.
            # Left to itself it cleans up cleanly. Tidying from here is for a
            # gateway that does not, and is a switch.
            # Nothing from here while the webhook is on - not even a sweep.
            # 4.59.0 read this box's inbox never, and in that build the
            # sending never stalled once; reading it on any kind of beat is
            # what wedges it. The inbox is read only where a webhook has its
            # own message to take off, on that webhook's thread, and once more
            # twenty seconds later if the box had not stored it yet.
            self._sms_last_poll = time.time()
            return None

        every = float(CONFIG.get('sms_poll_s') or 0)
        if not force and (not every or not self.sms_ready() or time.time() - self._sms_last_poll < every):
            return None
        # Not while something is going out. A small gateway does one thing at
        # a time, and asking it for the inbox in the middle of handing a
        # two-part message to the modem is what makes the send time out.
        if getattr(self, '_sms_sending', 0) and time.time() - self._sms_sending < 120:
            return None
        # ...and the lock as well as the flag, for the reason sms_status_poll
        # gives: the flag goes up as a message is handed over, and a question
        # asked a moment before it is still in flight.
        #
        # A poll on the beat does not wait - an inbox unread this time round
        # is read on the next one, and the message must not queue behind it.
        # One somebody asked for does wait, because they are looking at the
        # button and an empty answer would read as an empty inbox.
        if not self._sms_send_lock.acquire(timeout=90 if force else -1,
                                           blocking=bool(force)):
            return None
        try:
            return self._sms_poll_now()
        finally:
            self._sms_send_lock.release()

    def _sms_poll_now(self):
        self._sms_last_poll = time.time()
        try:
            if self._sms_rest():
                rows = self._rest('/messages/status') or []
                if isinstance(rows, dict):
                    rows = rows.get('data') or []
                # Every message the device lists. It was filtered on "unread"
                # here, and a TRB marks a message read the moment it stores
                # it - so nothing ever came through. What keeps a message from
                # being acted on twice is the list of ones already seen, which
                # outlives a restart, and taking them off the device after.
                messages = [{'id': str(r.get('id') or ''), 'from': r.get('sender') or '',
                             'text': r.get('message') or '', 'date': r.get('date') or '',
                             'status': r.get('status') or ''} for r in rows]
            else:
                url = self._sms_url(CONFIG.get('sms_read_path') or '/cgi-bin/sms_list',
                                    {'username': CONFIG.get('sms_user') or '', 'password': CONFIG.get('sms_password') or ''})
                body = self._sms_open(url).read().decode('utf-8', 'replace')
                messages = self._sms_parse_list(body)
        except Exception as e:
            self.debug('SMS poll failed', str(e))
            return None
        # Whatever was already sitting in the inbox when this daemon first
        # looked is not a command somebody just sent: it is history. It is
        # remembered as seen and left alone, once, with a word about it.
        if self._sms_first_look:
            self._sms_first_look = False
            if messages and not self._sms_seen:
                for message in messages:
                    self._sms_remember(self._sms_key(message))
                    # they are still worth keeping and showing - only the
                    # doing is skipped, since they are not fresh commands
                    self.sms_note('in', message.get('from') or '', message.get('text') or '',
                                  True, 'was already here',
                                  key=self._sms_key(message), road='modem')
                self._sms_save_seen()
                self.store.add_event('sms', '%d message(s) were already in the inbox; they were kept but not acted on'
                                     % len(messages), 'info')
                return {'read': len(messages), 'acted': 0, 'left_alone': len(messages)}
        try:
            logged = {str(r.get('key') or '') for r in json.loads(self.store.get_meta('sms_log') or '[]')}
        except ValueError:
            logged = set()
        acted, done = 0, []
        for message in messages:
            # the device numbers its messages by storage slot and gives the
            # slot back when one is deleted, so the number alone would make a
            # new message look like an old one
            key = self._sms_key(message)
            # A gateway that gives no date makes this key the slot, the number
            # and the words - and the modem hands a slot back when a message
            # is deleted. So the SECOND "Status" from the same phone, landing
            # in the slot the first one left, has exactly the key of the
            # first: it was taken for one already dealt with, deleted without
            # being acted on, and vanished. One reply, then nothing, which is
            # what you saw. Where there is no date there is nothing to tell
            # two such messages apart, so this does not try: deleting is what
            # stops a message coming back, and if a delete has failed, acting
            # twice is the better way round to be wrong.
            # ...unless there is no slot to delete it by either. Deleting is
            # what stops a message coming back, and where it cannot be deleted
            # nothing else will: a gateway that gives neither a date nor a
            # slot would otherwise have its one message acted on again on
            # every round, for ever. Then remembering is all there is, and it
            # is used however thin the key.
            cannot_delete = not str(message.get('id') or '').strip()
            if key in self._sms_seen and (cannot_delete or str(message.get('date') or '').strip()):
                # Already acted on, or from before we started. If it has never
                # been written down, write it down, so the tab shows the whole
                # conversation rather than half of it - unless it was thrown
                # away on purpose, which used to bring the lot straight back
                # on the next round.
                if message.get('id') and CONFIG.get('sms_clear_inbox', True):
                    # dealt with, and still sitting on the device: take it off
                    done.append((str(message['id']), key))
                if key and key not in logged and key not in self._sms_binned:
                    self.sms_note('in', message.get('from') or '', message.get('text') or '',
                                  True, 'was already here', key=key, road='modem')
                    logged.add(key)
                continue
            self._sms_remember(key)
            acted += 1 if self.sms_handle(message.get('from') or '', message.get('text') or '', key=key) else 0
            if message.get('id'):
                done.append((str(message['id']), key))
        if done and CONFIG.get('sms_clear_inbox', True):
            # These include ones dealt with on an earlier round that are still
            # sitting on the device - a delete that failed once used to mean
            # the message stayed there for good, and a full inbox stops new
            # ones arriving.
            log('taking %d message(s) off the gateway' % len(done), 'debug')
            if self.sms_clear([x[0] for x in done]):
                # off the device, so it can never be offered again: forgetting
                # it keeps the memory small and lets the slot be reused
                for _, key in done:
                    self._sms_seen.pop(key, None)
                self._sms_save_seen()
        return {'read': len(messages), 'acted': acted}

    def _sms_tidy(self, wanted=None, getting_late=False, hurry=False):
        """With the webhook on: take everything off the modem, act on nothing.

        Once a minute, and never while a message is going out. What is found
        is written down as "was already here" only if it is not in the log
        already - the webhook wrote it down when it arrived, so normally
        nothing is written and everything is deleted.
        """
        if not self.sms_ready():
            return
        # "now" is for a webhook hurrying its own message off, and it belongs
        # to that one call - not to whatever sweep happens next, which would
        # then ignore the minute for ever after.
        # (passed in, not only left on the daemon: the second look twenty
        # seconds on found the flag long cleared and the last tidy under a
        # minute old, and never looked; two webhooks together shared the one
        # flag and the second was skipped)
        hurry = bool(wanted) and (hurry or getting_late or bool(getattr(self, '_sms_tidy_now', False)))
        self._sms_tidy_now = False
        if time.time() - getattr(self, '_sms_tidied', 0) < 60 and not hurry:
            return
        if getattr(self, '_sms_sending', 0) and time.time() - self._sms_sending < 120:
            return
        # ...and the lock as well, for the reason sms_status_poll gives. This
        # one waits rather than skipping: it is here to take one named message
        # off the box, and not doing it leaves that message there for ever.
        # Bounded, so the thread cannot outlive the reason it was started.
        if not self._sms_send_lock.acquire(timeout=90):
            log('tidying the modem: it was busy sending for 90s; leaving it', 'debug')
            return
        try:
            return self._sms_tidy_now_locked(wanted, getting_late)
        finally:
            self._sms_send_lock.release()

    def _sms_tidy_now_locked(self, wanted=None, getting_late=False):
        self._sms_tidied = time.time()
        try:
            found = self.sms_listing() or []
        except Exception as e:
            log('tidying the modem: could not read its inbox: %s' % e, 'debug')
            return
        if wanted:
            # ONE message - the one that just came in by the webhook - and not
            # whatever else is in the inbox. Five arriving together means five
            # webhooks; deleting the lot on the first would take away the four
            # whose webhooks are still on their way, and those would never be
            # acted on at all. Worse than not deleting.
            who, what = wanted
            who = str(who or '').strip()[-9:]
            what = str(what or '').strip()[:60]
            mine = [m for m in found
                    if str(m.get('from') or '').strip()[-9:] == who
                    and str(m.get('text') or '').strip()[:60] == what]
            if not mine:
                # it may not be there yet: the box forwards before it stores.
                # One more look in a little while, and then let it be.
                if not getting_late:
                    log('tidying the modem: no copy of the pushed message yet (%s: %s); '
                        'looking again shortly' % (who, what[:30]), 'debug')
                    threading.Timer(20.0, self._sms_tidy, args=(wanted,),
                                    kwargs={'getting_late': True}).start()
                else:
                    log('tidying the modem: no copy of the pushed message at all (%s: %s)'
                        % (who, what[:30]), 'debug')
                return
            # the OLDEST of the ones that match: four identical "Status" in a
            # row are four messages and four webhooks, and taking the oldest
            # each time pairs them up in the order they arrived
            mine.sort(key=lambda m: str(m.get('date') or ''))
            ids = [str(mine[0].get('id'))] if mine[0].get('id') else []
        else:
            ids = [str(m.get('id')) for m in found if m.get('id')]
        if not ids:
            return
        log('tidying the modem: %d message(s) still on it, taking them off' % len(ids), 'debug')
        try:
            self.sms_clear(ids)
        except Exception as e:
            log('tidying the modem: could not delete: %s' % e, 'debug')
            return
        # ...and make sure. A delete the box accepted and did not do is the
        # thing that hands the same message over again, and "we asked it to"
        # is not the same as "it is gone".
        try:
            left = {str(m.get('id')) for m in (self.sms_listing() or []) if m.get('id')}
        except Exception:
            return
        stuck = [one for one in ids if one in left]
        if stuck:
            log('tidying the modem: %d message(s) would not come off (%s); trying each on its own'
                % (len(stuck), ', '.join(stuck[:4])), 'warn')
            for one in stuck:
                try:
                    self.sms_clear([one])
                except Exception as e:
                    log('tidying the modem: slot %s will not delete: %s' % (one, e), 'warn')
            try:
                still = {str(m.get('id')) for m in (self.sms_listing() or []) if m.get('id')}
            except Exception:
                return
            beaten = [one for one in stuck if one in still]
            if beaten:
                self.store.add_event(
                    'sms', 'the modem will not let go of %d message(s) (%s) - it may hand them '
                           'over again; its own inbox may need clearing by hand'
                           % (len(beaten), ', '.join(beaten[:4])), 'warn')

    def sms_clear(self, ids):
        """Take the messages we have acted on off the device. Its inbox is
        small, and a full one stops new ones arriving; the words themselves
        are kept here, in the events and the SMS log."""
        try:
            if self._sms_rest():
                self._rest('/messages/actions/remove_messages', 'POST',
                           {'data': {'modem_id': self.sms_modem_id(), 'sms_id': [str(x) for x in ids]}})
            elif CONFIG.get('sms_delete_path'):
                for one in ids:
                    self._sms_open(self._sms_url(CONFIG['sms_delete_path'],
                                                 {'username': CONFIG.get('sms_user') or '',
                                                  'password': CONFIG.get('sms_password') or '',
                                                  'number': one})).read()
            return True
        except Exception as e:
            # A failure here fills the device's inbox until nothing new can
            # arrive, so it is said out loud rather than left in the debug
            # trace where nobody looks until messages stop coming.
            self.debug('clearing the inbox', str(e))
            log('could not take %d message(s) off the gateway: %s' % (len(list(ids)), e), 'warn')
            self.say_event('sms', 'the gateway would not let go of %d message(s): %s - its inbox '
                                  'fills up and new ones stop arriving'
                           % (len(list(ids)), str(e)[:90]), 'warn', about='sms_trouble',
                           title='The text gateway inbox will not empty', dedup='sms_trouble|inbox')
            return False

    @staticmethod
    def _sms_parse_list(body):
        """Teltonika's plain-text listing: blocks of Index/Sender/Text lines.

        The headers come before the message and the message runs to the end
        of its block. Both matter, and neither was true before: every line of
        a block was tested against the header names and a later one overwrote
        the earlier, so the message's own second line could say
        "Sender: <somebody else's number>" and be believed - and the only
        thing standing between a text message and the house's commands is
        which number it came from. So a header is read once, the first time
        it appears, and once the message has begun every line of it is the
        message. That also keeps the rest of a message that runs over more
        than one line, which used to be thrown away.
        """
        out, current = [], {}

        def done(block):
            if block.get('text') is not None:
                out.append({'id': block.get('id', ''), 'from': block.get('from', ''),
                            'text': block.get('text', '')})
        for line in body.splitlines():
            bare = line.strip()
            if not bare:
                done(current)
                current = {}
                continue
            if current.get('text') is not None:
                current['text'] = (current['text'] + '\n' + line.rstrip()).strip()
                continue
            low = bare.lower()
            for prefix, field in (('index:', 'id'), ('sender:', 'from'),
                                  ('text:', 'text'), ('message:', 'text')):
                if low.startswith(prefix):
                    if field not in current:              # the first one stands
                        current[field] = bare.split(':', 1)[1].strip()
                    break
        done(current)
        return out

    @staticmethod
    def phrase_catches(phrase):
        """The names a phrase asks for: "unban {ip}" catches one called ip."""
        return re.findall(r'\{([a-zA-Z][a-zA-Z0-9_]{0,23})\}', str(phrase or ''))

    @classmethod
    def phrase_match(cls, phrase, text):
        """Whether a message is this command, and what it carried.

        A phrase with no names in it is matched as it always was - the words
        it starts with, or a word of its own somewhere in the message. One
        with names is matched as a shape: "unban {ip}" takes the word after
        "unban" and calls it ip, so one command serves every address rather
        than one command per address.
        """
        phrase, text = str(phrase or '').strip(), str(text or '').strip()
        if not phrase:
            return None
        names = cls.phrase_catches(phrase)
        if not names:
            # The phrase as the start of the message - but as whole words:
            # "off" used to be the start of "offline", "status" of
            # "statusbar", "sms" of "SMS-Gateway", and each fired its command.
            # Or the phrase as a word of its own somewhere in the message,
            # which is a weaker thing and yields to a built-in command that
            # understands the whole message (see sms_match_strength).
            low, want = ' '.join(text.lower().split()), ' '.join(phrase.lower().split())
            words = low.split()
            return {} if (low == want or low.startswith(want + ' ') or want in words) else None
        shape = re.escape(phrase)
        # the same name twice is one name asked for twice: written straight
        # out, the pattern would name two groups the same and the whole of the
        # matching would raise rather than answer - which is to say one badly
        # written phrase would stop every message being read
        seen, ordered = set(), []
        for name in names:
            if name.lower() in seen:
                continue
            seen.add(name.lower())
            ordered.append(name)
        for name in ordered:
            # the last one takes the rest of the line, so a name may hold
            # something with spaces in it
            last = shape.endswith(re.escape('{%s}' % name))
            shape = shape.replace(re.escape('{%s}' % name),
                                  '(?P<%s>.+)' % name if last else '(?P<%s>\\S+)' % name, 1)
        # a second and later mention of a name matches what the first caught
        for name in ordered:
            shape = shape.replace(re.escape('{%s}' % name), '(?P=%s)' % name)
        try:
            found = re.match(r'\s*' + shape + r'\s*$', text, re.IGNORECASE)
        except re.error as e:
            log('a command phrase could not be read: %s' % str(e)[:80], 'warn')
            return None
        if not found:
            return None
        return {k: (v or '').strip() for k, v in found.groupdict().items()}

    # what a reply or a script can do with the words after the phrase
    SMS_REST_FACTS = ('sms_rest', 'args', 'sms_text', 'sms_words', 'sms_first_word')

    def sms_uses_rest(self, c):
        """Whether a command does anything with the words that follow its
        phrase: a value, names of its own, a script that is handed them, or
        an answer that quotes them."""
        if c.get('takes_value') or c.get('vars') or self.phrase_catches(c.get('phrase') or ''):
            return True
        if str(c.get('target') or '').startswith('script:') or c.get('do') == 'script':
            return True
        reply = str(c.get('reply') or '')
        return any('{%s' % name in reply for name in self.SMS_REST_FACTS)

    def sms_match_strength(self, c, text):
        """'strong', 'weak' or None: how surely a message is this command.

        Strong: the message is the phrase itself, or the phrase followed by
        words the command does something with. Weak: the phrase followed by
        words it ignores, or a word of the phrase somewhere in a longer
        message. A strong one always wins; a weak one only when no built-in
        command understands the message whole - so an own command called
        "off" still answers "off", and no longer answers "heating off" or
        "Plug-UPS off" with the scene it was written for."""
        phrase = str(c.get('phrase') or '').strip()
        if not phrase or self.phrase_match(phrase, text) is None:
            return None
        if self.phrase_catches(phrase):
            return 'strong'
        low, want = ' '.join(str(text or '').lower().split()), ' '.join(phrase.lower().split())
        if low == want:
            return 'strong'
        if low.startswith(want + ' ') and self.sms_uses_rest(c):
            return 'strong'
        return 'weak'

    def sms_facts(self, sender, text, who, command=None, caught=None):
        """What a text may say about itself and the one who sent it. Written
        once, so the answer, the events and anything the command fires all see
        the same things."""
        command = command or {}
        state = (self.presence.get((who or {}).get('id')) or {}) if who else {}
        words = str(text or '').split()
        phrase = str(command.get('phrase') or '')
        if phrase and str(text or '').lower().startswith(phrase.lower()):
            rest = str(text or '')[len(phrase):].strip()
        else:
            rest = ' '.join(words[1:])
        home = state.get('home')
        # what the phrase asked for, if it asked for anything: "unban {ip}"
        # against "unban 1.1.1.1" leaves {ip} standing for 1.1.1.1 wherever
        # the command uses it - in what it does and in what it answers
        extra = dict(caught or {})
        if caught is None and phrase:
            extra = self.phrase_match(phrase, text) or {}
        # A name declared on the row but not written into the phrase takes its
        # turn from the words that follow it: "unban" with a name called ip
        # against "unban 1.1.1.1" is the same as writing "unban {ip}".
        # Where each name takes its value from. Left empty it takes the next
        # word, in the order the names are written; "all" takes everything
        # that follows, spaces and all; a number takes that word. The box
        # beside the name said nothing at all before this, which made it a
        # control that did nothing.
        words = [w for w in str(rest or '').split() if w]
        spare = list(words)
        for one in ((command or {}).get('vars') or []):
            if one['name'] in extra:
                continue
            where = str(one.get('from') or '').strip().lower()
            if where == 'all':
                extra[one['name']] = str(rest or '').strip()
            elif where.isdigit():
                which = int(where) - 1
                extra[one['name']] = words[which] if 0 <= which < len(words) else ''
            else:
                extra[one['name']] = spare.pop(0) if spare else ''
        out = dict(extra)
        out['args'] = ' '.join(str(v) for v in extra.values()) or rest
        out.update({
            'device': sender, 'action': command.get('do', ''),
            'target': self.target_label(command['target']) if command.get('target') else '',
            # the message itself
            'sms_from': sender, 'sms_text': text, 'sms_words': str(len(words)),
            'sms_length': str(len(str(text or ''))),
            'sms_first_word': words[0] if words else '',
            'sms_rest': rest,                     # what followed the phrase, for "heating 22"
            'sms_number': re.sub(r'[^0-9+]', '', str(sender or '')),
            'sms_phrase': phrase,
            # whoever sent it
            'person': (who or {}).get('name', ''), 'sms_person': (who or {}).get('name', ''),
            'person_known': 'yes' if who else 'no',
            'person_home': ('yes' if home else 'no') if home is not None else '',
            'person_since': human_span(time.time() - state['since']) if state.get('since') else '',
            'person_device': state.get('device') or '',
            'person_may_command': 'yes' if (who or {}).get('sms_commands') else 'no',
            'person_gets_alerts': 'yes' if (who or {}).get('sms_alerts') else 'no',
        })
        return out

    def sms_handle(self, sender, text, key='', road='modem'):
        """One message in: work out who sent it, match it against the commands
        and do as it says. A number nobody owns and nobody allowed is worth
        knowing about - it is said out loud and nothing else happens."""
        text = str(text or '').strip()
        who = self.person_by_phone(sender)
        self.sms_note('in', sender, text, True, 'received', key=key, road=road)
        self.store.add_event('sms', 'from %s: %s' % (who['name'] if who else (sender or '?'), text[:100]), 'info')
        self.debug('SMS in %s' % sender, text[:120])
        allowed = self.sms_allowed(sender)
        if not allowed:
            # a number on somebody's card that has not been ticked is a
            # different thing from a number nobody has ever seen
            if who:
                self.store.add_event('sms', '%s wrote, but their number is not ticked for commands: %s'
                                     % (who['name'], text[:80]), 'warn')
                self.notify('%s sent "%s", but their number is not allowed to give commands.'
                            % (who['name'], text[:100]), 'warn', dedup='sms-untick-' + who['id'],
                            title='A message that could not act',
                            sms='sms' in self.stranger_roads(), about='sms_in')
            else:
                self.store.add_event('sms', 'a number nobody knows (%s) sent: %s' % (sender or '?', text[:80]), 'warn')
                # Telling somebody about it must not mean texting them the
                # message: an operator's notice, a bank's code, any marketing
                # would be forwarded to a phone at the house's own expense.
                # The event is always kept; how loudly to say it is a setting.
                roads = self.stranger_roads()
                if roads:
                    self.notify('An unknown number %s sent: %s' % (sender or '?', text[:120]),
                                'warn', dedup='sms-stranger-' + str(sender), title='SMS from a stranger',
                                ntfy='ntfy' in roads, telegram='telegram' in roads, sms='sms' in roads,
                                about_number=sender, about='sms_in')
        low = text.lower()
        # Which command answers. One of your own that is sure of the message
        # - it is the whole message, or the command does something with the
        # rest of it - always does. One that only found its word somewhere
        # in a longer message gives way to a built-in command that
        # understands the message whole: an own "off" still answers "off",
        # but not "heating off" or "Plug-UPS off", which mean something else
        # entirely. Nothing understood it whole: the weak one answers, as it
        # always did.
        strong, weak = [], []
        for c in self.sms_commands():
            if not c.get('enabled', True):
                continue
            how = self.sms_match_strength(c, text)
            if how == 'strong':
                strong.append(c)
            elif how == 'weak':
                weak.append(c)
        if strong:
            chosen = strong[:1]
        elif weak and not (allowed and self.sms_system_key(text)):
            chosen = weak[:1]
        else:
            chosen = []
        for c in chosen:
            caught = self.phrase_match(c.get('phrase'), text)
            if caught is None:
                continue
            on_trial = self.trial_of('sms_commands', c.get('id'))
            if on_trial:
                # on trial: only a number allowed to give commands reaches it,
                # whatever the command says about strangers, and nothing is
                # done - what would have been is written down and said back
                if not allowed:
                    continue
                what = '%s %s' % (c.get('do') or 'on', self.target_label(c['target'])
                                  if c.get('target') else '(an answer only)')
                self.trial_would(on_trial, 'answered SMS "%s" from %s: %s'
                                 % (c['phrase'], who['name'] if who else (sender or '?'), what))
                if c.get('answer', True) is not False and CONFIG.get('sms_reply') and sender:
                    self.sms_reply(sender, ('[TEST] "%s" would: %s' % (c['phrase'], what))[:300])
                return True
            if not allowed and not c.get('from_anyone'):
                self.store.add_event('sms', 'ignored "%s" from %s: that number may not give commands'
                                     % (c['phrase'], sender or '?'), 'warn')
                # said once a day to a number, and by the reply worker: sent
                # here, a stranger's message held the poll or the webhook for
                # up to a minute (so the gateway sent it again), a refusal
                # that failed was queued to be paid for again, and a spammer
                # got a paid answer to every message
                told = self.__dict__.setdefault('_refused_told', {})
                if CONFIG.get('sms_reply') and sender and time.time() - told.get(sender, 0) > 86400:
                    told[sender] = time.time()
                    if len(told) > 500:
                        told.clear()
                        told[sender] = time.time()
                    self.sms_reply(sender, 'Sorry - this number is not allowed to give commands.')
                return False
            # "heating 22" - the words after the phrase become the value, so
            # one command serves every temperature rather than one command per
            # number. Only where the command asks for it.
            act = c.get('do') or 'on'
            facts_now = self.sms_facts(sender, text, who, c, caught)
            # A command may work on the blocked list rather than on a thing in
            # the house: "unban {ip}" against "unban 1.1.1.1" lets that
            # address back in. What it works on is written the same way
            # anything else is written - as a fact - so the phrase decides
            # what is caught and the action decides what is done with it.
            if act == 'script' or str(c.get('target') or '').startswith('script:'):
                found = self.script_by_id(str(c.get('target') or '')[7:])
                if not found:
                    log('command "%s" points at a script that is gone' % c['phrase'], 'warn')
                    return True
                # A script says which names it wants. Any of those the command
                # did not catch is taken from the words after the phrase, in
                # order, so a command with nothing declared still works the
                # obvious way: "ban 1.2.3.4" fills the {ip} the script asks
                # for. Declaring one is then a way of being particular, not a
                # thing to remember before anything works at all.
                facts_now = dict(facts_now)
                spare = [w for w in str(facts_now.get('sms_rest') or '').split() if w]
                if not spare:
                    spare = [w for w in str(facts_now.get('args') or '').split() if w]
                given = dict(caught or {})
                for one in (c.get('vars') or []):
                    if one.get('name'):
                        given[one['name']] = facts_now.get(one['name'], '')
                for name in self.phrase_catches(found.get('body') or ''):
                    if str(facts_now.get(name) or '').strip():
                        given.setdefault(name, facts_now.get(name))
                        continue
                    facts_now[name] = spare.pop(0) if spare else ''
                    given[name] = facts_now[name]
                # each of them also as {sms.name}, {in.name} and under the
                # command's own phrase, so two commands with a name in common
                # can still be told apart inside one script
                facts_now.update(self.caller_facts('sms', given, c.get('phrase')))
                out = self.run_script(found, facts_now, 'SMS from %s'
                                      % (who['name'] if who else (sender or '?')))
                # A command that wrote its own answer gets to say it - with
                # the names it caught, AND with what the script left behind:
                # {result} what the script answered, {said} its commentary,
                # and every name it made up with "let". Until now the answer
                # could only hold what was known before the script ran, so a
                # script that worked something out had no way of saying it.
                facts_after = dict(facts_now, **self.script_result_facts(out, found))
                answer = self.fill_message(str(c.get('reply') or ''), facts_after).strip()
                if not answer:
                    answer = out['answer'] or out['said'] or '%s: %d line(s)' % (found['name'], out['lines'])
                elif out['faults']:
                    # the answer says what was meant to happen; the script says
                    # what did not, and the second must not be silenced by the
                    # first
                    answer = answer + '\n' + '\n'.join(out['faults'])
                if c.get('answer', True) is not False and CONFIG.get('sms_reply') and sender:
                    self.sms_reply(sender, answer[:300])
                return True
            if act in ('ban', 'unban'):
                wanted = self.fill_message(str(c.get('target') or '{args}'), facts_now).strip()
                said = self.ban_by_name(act, wanted, 'SMS from %s'
                                        % (who['name'] if who else (sender or '?')))
                if c.get('answer', True) is not False and CONFIG.get('sms_reply') and sender:
                    self.sms_reply(sender, said[:300])
                self.store.add_event('sms', 'did "%s" for %s: %s'
                                     % (c['phrase'], sender or '?', said), 'info')
                return True
            if c.get('takes_value'):
                rest = text[len(c['phrase']):].strip() if low.startswith(c['phrase'].lower()) else ''
                if not rest:
                    rest = ' '.join(text.split()[1:])
                value = numeric(rest.replace(',', '.')) if rest else None
                if value is None:
                    word = rest.strip().lower()
                    if word in ('on', 'off', 'toggle', 'comfort', 'eco', 'night', 'max', 'plan', 'manual',
                                'away', 'home'):
                        act = word if word in ('on', 'off', 'toggle') else 'set:' + word
                    elif CONFIG.get('sms_reply') and sender:
                        self.sms_reply(sender, 'I need a number or a word after "%s".' % c['phrase'])
                        return False
                else:
                    act = 'set:%g' % value
            if c.get('target'):
                # "who:me" stands for whoever sent the message, so one command
                # serves the whole household: I am out / I am back
                target = c['target']
                if target in ('who:me', 'who:sender'):
                    if not who:
                        if CONFIG.get('sms_reply') and sender:
                            self.sms_reply(sender, 'I do not know whose number this is - add it to a person first.')
                        return False
                    target = 'who:' + who['id']
                why = 'SMS from %s' % (who['name'] if who else (sender or '?'))
                fired = self._binding_targets(target)
                if not fired:
                    log('SMS command "%s": %s is disabled or gone' % (c['phrase'], target), 'warn')
                    self.say_event('sms', 'could not do "%s": %s is disabled or gone'
                                   % (c['phrase'], self.target_label(target)), 'warn',
                                   about='broken_refs', title='A text command points at nothing')
                for one in fired:
                    self._fire_target(one, act, why, facts=facts_now)
            if c.get('answer', True) is False:
                self.store.add_event('sms', 'did "%s" for %s (no answer sent back)'
                                     % (c['phrase'], who['name'] if who else (sender or '?')), 'info')
                return True
            answer = c.get('reply') or ('%s %s' % (self.target_label(c['target']), act) if c.get('target') else 'done')
            answer = self.fill_message(answer, self.message_facts(
                'SMS from %s' % (who['name'] if who else (sender or '?')), facts_now))
            if CONFIG.get('sms_reply') and sender:
                self.sms_reply(sender, answer[:300])
            self.store.add_event('sms', 'did "%s" for %s' % (c['phrase'], sender or '?'), 'info')
            return True
        # The built-in commands, after every command written on the card and
        # before the plain "how is X" question: a house that has given
        # something its own word keeps that word, and "loznice eco" is taken
        # as an instruction rather than as a question about a room of that
        # name. Only a number allowed to give commands reaches them.
        if allowed:
            built_in = self.sms_system_do(text, 'SMS from %s'
                                          % (who['name'] if who else (sender or '?')))
            if built_in:
                self.store.add_event('sms', 'answered "%s" from %s with a built-in command'
                                     % (text[:60], who['name'] if who else (sender or '?')), 'info')
                if CONFIG.get('sms_reply') and sender:
                    self.sms_reply(sender, built_in)
                return True
        asked = self.sms_ask(text) if allowed else None
        if asked:
            self.store.add_event('sms', 'answered a question from %s: %s' % (sender or '?', text[:60]), 'info')
            if CONFIG.get('sms_reply') and sender:
                self.sms_reply(sender, asked)
            return True
        if allowed and CONFIG.get('sms_reply') and sender:
            self.sms_reply(sender, 'I do not know that one. ' + self.sms_help())
        return False

    # ---- what a text message can do without anybody writing a command -------
    # Families, not a fixed list: each one says what it understands, and the
    # things it covers are whatever the house holds at the moment it is
    # asked. Add a thermometer and it can be asked about; add a room and its
    # heating can be driven - with a switch of its own, and nothing here to
    # rewrite. A command written on the SMS card always wins over one of
    # these, so a house that has its own word for something keeps it.
    #
    #   (key, topic, phrase as it is typed, what it does, an example, who it covers)
    #
    # "who it covers" is the name of a list: rooms, devices, sockets, scenes,
    # scripts - or '' for a family that covers nothing but itself.
    SMS_FAMILIES = (
        ('help', 'asking', 'help', 'The topics, and the commands written on the SMS card.', 'help', ''),
        ('help_topic', 'asking', 'help TOPIC', 'One topic in full, with every command in it.',
         'help heating', ''),
        ('status', 'the house', 'status', 'The house in one line: who is in, how warm, what is on.',
         'status', ''),
        ('whats_on', 'the house', 'on', 'What is switched on right now, by name.', 'on', ''),
        ('ask_thing', 'the house', 'NAME', 'Any thing by name, or a word out of it: how it is.',
         'temp venek', 'devices'),
        ('plug_switch', 'sockets', 'NAME on | off | toggle', 'Switch that socket.',
         'plug-ups off', 'sockets'),
        ('scene_run', 'scenes', 'SCENE', 'Run that scene.', 'good night', 'scenes'),
        ('script_run', 'scripts', 'SCRIPT', 'Run that little script.', 'evening', 'scripts'),
        ('heat_state', 'heating', 'heating', 'How the heating stands, room by room.', 'heating', ''),
        ('heat_onoff', 'heating', 'heating on | off', 'The heating control itself.', 'heating off', ''),
        ('heat_away', 'heating', 'away on | off', 'Away mode.', 'away on', ''),
        ('heat_away_c', 'heating', 'away NUMBER', 'What away is worth, in \u00b0C.', 'away 16', ''),
        ('room_state', 'heating', 'ROOM', 'That room: how warm, what it holds and why.', 'loznice', 'rooms'),
        ('room_level', 'heating', 'ROOM comfort | eco | night | max | plan | manual | off | next',
         'Put that room on that setting. "max" opens its valves wide and holds no temperature at all.',
         'loznice eco', 'rooms'),
        ('room_temp', 'heating', 'ROOM NUMBER', 'Hold that room there until the plan next turns. '
                                                'A + or - turns it by that much.', 'loznice 21.5', 'rooms'),
        ('room_setting', 'heating', 'ROOM comfort | eco | night NUMBER',
         'What that setting is worth in that room, kept for good.', 'loznice eco 19', 'rooms'),
        ('room_all', 'heating', 'all SETTING [NUMBER]', 'The same, every heated room at once.',
         'all night', ''),
        ('ban', 'keeping addresses out', 'ban ADDRESS [minutes]', 'Keep an address out.',
         'ban 185.36.81.23 120', ''),
        ('unban', 'keeping addresses out', 'unban ADDRESS', 'Let an address back in.',
         'unban 185.36.81.23', ''),
        ('blocked', 'keeping addresses out', 'blocked', 'How many are kept out, and the newest few.',
         'blocked', ''),
        # everything as an object (4.88): what the mark after a name shows,
        # asked for, set and done by text, as a script writes it
        ('obj_read', 'objects', 'NAME.member', 'What one member of anything is now.',
         'Loznice.eco_c', ''),
        ('obj_set', 'objects', 'NAME.member = VALUE', 'Set it - what the object view says can be set.',
         'Loznice.eco_c = 19', ''),
        ('obj_call', 'objects', 'NAME.procedure()', 'Do it - what the object view says can be done.',
         'Vecer.run()', ''),
    )

    def sms_family_members(self, covers):
        """What a family covers right now: (id, name) pairs, live.

        Nothing is written down, so a thermometer put up this morning can be
        asked about this afternoon and appears on the card with a switch of
        its own."""
        if covers == 'rooms':
            return [(r['id'], r['name']) for r in self.rooms()]
        if covers == 'sockets':
            return sorted(((p.cfg.get('name') or p.name, p.name) for p in self.plugs.values()
                           if not p.cfg.get('monitor_only')), key=lambda x: x[1].lower())
        if covers == 'scenes':
            return [(str(x.get('id') or x.get('name')), x.get('name') or '')
                    for x in self.scenes() if x.get('name')]
        if covers == 'scripts':
            return [(str(x.get('id') or x.get('name')), x.get('name') or '')
                    for x in self.scripts() if x.get('name')]
        if covers == 'devices':
            out = [(x['id'], x.get('alias') or x.get('name') or x['id'])
                   for x in self.store.devices() if not x.get('removed')]
            out += [(p.name, p.name) for p in self.plugs.values()]
            return sorted(out, key=lambda x: str(x[1]).lower())
        return []

    def sms_system_topics(self):
        """The topics, in the order they are written above."""
        out = []
        for row in self.SMS_FAMILIES:
            if row[1] not in out:
                out.append(row[1])
        return out

    def sms_builtin_off(self):
        """What this house has switched off: a family key, or "family:thing".

        Read with get_meta rather than meta_json: that one keeps only the
        dictionaries in a list, because everything else it holds is a list of
        records, and a list of plain names came back empty."""
        try:
            kept = json.loads(self.store.get_meta('sms_builtin_off') or '[]')
        except ValueError:
            kept = []
        if not isinstance(kept, list):
            kept = []
        return {str(k) for k in kept if str(k)}

    def save_sms_builtin(self, off):
        """Which built-in commands are switched off, by family or by thing.

        Anything not named here works - so a thermometer put up tomorrow can
        be asked about tomorrow, without anybody going back to this card."""
        kept = sorted({str(k) for k in (off or []) if str(k) and len(str(k)) < 120})
        self.store.set_meta('sms_builtin_off', json.dumps(kept))
        self.store.add_event('sms', '%d built-in command(s) or thing(s) switched off' % len(kept), 'info')
        self.bump()
        return kept

    def sms_builtin_on(self, key, thing=None):
        """Is this family on - and, when a thing is named, this thing of it."""
        off = self.sms_builtin_off()
        if key in off:
            return False
        return not (thing is not None and ('%s:%s' % (key, thing)) in off)

    def sms_caught_by(self, text):
        """The command written on the SMS card that would answer this text,
        or None. The very matching a message goes through, in the very
        order, so what the card says is what a phone would get."""
        # the same choice sms_handle makes: a command of your own that is
        # sure of the message takes it; one that only found its word in it
        # does not take a message a built-in command understands whole -
        # which a built-in command's own words always are
        for c in self.sms_commands():
            if not c.get('enabled', True) or not c.get('phrase'):
                continue
            try:
                if self.sms_match_strength(c, text) == 'strong':
                    return str(c.get('phrase'))
            except Exception:
                continue
        return None

    def sms_system_rows(self):
        """What the card shows: every family, and what each covers right now.

        A command written on the card is matched first, so a built-in one
        with the same words never runs. Each family says so - and so does
        each thing of it, since "loznice eco" written on the card takes that
        one room and leaves the others to the built-in command. Worked out,
        not stored: delete your own command and the built-in one is back,
        with the switch it had."""
        off = self.sms_builtin_off()
        out = []
        for key, topic, phrase, what, example, covers in self.SMS_FAMILIES:
            shape = self.SMS_HELP_FOR_ONE.get(key)
            members = []
            for mid, name in self.sms_family_members(covers):
                taken = self.sms_caught_by(shape % name) if shape else None
                members.append({'id': str(mid), 'name': str(name),
                                'enabled': ('%s:%s' % (key, mid)) not in off,
                                'overridden_by': taken})
            if members and shape:
                takers = {m['overridden_by'] for m in members}
                family_taken = takers.pop() if len(takers) == 1 and None not in takers else None
            else:
                family_taken = self.sms_caught_by(example)
            out.append({'key': key, 'topic': topic, 'phrase': phrase, 'what': what,
                        'example': example, 'covers': covers, 'enabled': key not in off,
                        'overridden_by': family_taken, 'members': members})
        return out

    # what the phrase of a family reads like when it is about one named thing
    SMS_HELP_FOR_ONE = {
        'room_state': '%s', 'room_level': '%s eco', 'room_temp': '%s 21.5',
        'room_setting': '%s eco 19', 'plug_switch': '%s off', 'scene_run': '%s',
        'script_run': '%s', 'ask_thing': '%s',
    }

    @staticmethod
    def _sms_fit(lead, items, room=300):
        """As many of them as fit in one message, and how many did not."""
        out, left = [], room - len(lead) - 12
        for one in items:
            if left - len(one) - 2 < 0:
                break
            out.append(one)
            left -= len(one) + 2
        said = lead + ', '.join(out)
        if len(out) < len(items):
            said += ' and %d more' % (len(items) - len(out))
        return said[:room]

    # A word for a topic, however it is asked for: the card calls them "the
    # house" and "keeping addresses out", a phone types "house" or "ban".
    SMS_TOPIC_WORDS = {'house': 'the house', 'home': 'the house', 'dum': 'the house',
                       'blocking': 'keeping addresses out', 'block': 'keeping addresses out',
                       'ban': 'keeping addresses out', 'bans': 'keeping addresses out',
                       'addresses': 'keeping addresses out', 'socket': 'sockets', 'plugs': 'sockets',
                       'plug': 'sockets', 'zasuvky': 'sockets', 'scene': 'scenes', 'sceny': 'scenes',
                       'script': 'scripts', 'skripty': 'scripts', 'heat': 'heating', 'topeni': 'heating',
                       'vytapeni': 'heating', 'object': 'objects', 'objekty': 'objects', 'ask': 'asking'}
    SMS_TOPIC_SHORT = {'the house': 'house', 'keeping addresses out': 'blocking'}
    SMS_LISTS = ('devices', 'rooms', 'sockets', 'scenes', 'scripts')
    SMS_ONE = 160

    def _sms_one(self, text):
        """One message, whatever it says: plain letters (one accent turns a
        160-character message into a 70-character one) and no longer than
        a single part. A modem sends a message of three parts part by part,
        and that is where the gateway is slowest to answer."""
        text = ' '.join(_fact_ascii(str(text or '').replace('\u00b0C', ' C').replace('\u00b0', '')).split())
        if len(text) > self.SMS_ONE:
            text = text[:self.SMS_ONE - 3].rstrip(' ,.;:-|') + '...'
        return text

    def _sms_fit_one(self, lead, items, tail='', sep=', '):
        """As many as fit in one message with the tail after them."""
        lead, tail = _fact_ascii(lead), _fact_ascii(tail)
        room = self.SMS_ONE - len(lead) - len(tail)
        out = []
        for one in items:
            one = _fact_ascii(one)
            more = len(sep) if out else 0
            if room - len(one) - more < 10 and len(out) < len(items) - 1:
                break
            if room - len(one) - more < 0:
                break
            out.append(one)
            room -= len(one) + more
        left = len(items) - len(out)
        said = lead + sep.join(out) + ((' +%d' % left) if left else '') + tail
        return self._sms_one(said)

    def _sms_topic_of(self, word):
        low = str(word or '').strip().lower()
        topics = self.sms_system_topics()
        if low in topics:
            return low
        if low in self.SMS_TOPIC_WORDS:
            return self.SMS_TOPIC_WORDS[low]
        short = {v: k for k, v in self.SMS_TOPIC_SHORT.items()}
        if low in short:
            return short[low]
        hits = [t for t in topics if t.startswith(low) or (low and low in t)]
        return hits[0] if len(hits) == 1 else None

    def _sms_example(self, row, live_members):
        """A family's own example, with a real name of this house in it."""
        key, _topic, _phrase, _what, example, covers = row
        shape = self.SMS_HELP_FOR_ONE.get(key)
        if shape and covers:
            names = [n for mid, n in live_members if self.sms_builtin_on(key, mid)]
            if names:
                return shape % names[0]
        return example

    def sms_help(self, what=''):
        """What the house can be asked - and how to find out the rest of it
        from a phone, with no dashboard in front of you. Every answer is one
        message.

            help                  where to start
            help heating          that topic, as examples with this house's names
            help rooms            the names, a page at a time: help rooms 2
            help loznice          what may be said to that one thing
            help loznice.         what that object has, to read, set or do
        """
        what = str(what or '').strip()
        low = what.lower()
        off = self.sms_builtin_off()
        live = [r for r in self.SMS_FAMILIES if r[0] not in off]
        shorts = [self.SMS_TOPIC_SHORT.get(t, t) for t in self.sms_system_topics() if t != 'asking']

        if not low:
            words = [c['phrase'] for c in self.sms_commands() if c.get('enabled', True)]
            lead = 'Ask: status, on, heating, blocked. More: help %s.' % '|'.join(shorts)
            if words:
                return self._sms_fit_one(lead + ' Yours: ', words)
            return self._sms_one(lead)

        bits = low.split()
        # somebody who typed the word the help itself used
        if bits[0] in ('topic', 'topics', 'name', 'names') and len(bits) == 1:
            return self._sms_one('Try: help heating. Topics: %s. Names: help rooms, help devices.'
                                 % ', '.join(shorts))

        # a list of names, a page at a time
        if bits[0] == 'list' and len(bits) > 1:
            bits = bits[1:]
        if bits[0] in self.SMS_LISTS and (len(bits) == 1 or bits[1].isdigit()) \
                and not (bits[0] in ('sockets', 'scenes', 'scripts') and len(bits) == 1):
            names = [n for _mid, n in self.sms_family_members(bits[0])]
            if bits[0] == 'devices':
                # what can be switched first: a list of eighty mostly
                # buttons and door sensors says nothing about what to do
                names = [n for _m, n in self.sms_family_members('sockets')] + \
                        [n for n in names if n not in {x for _m, x in self.sms_family_members('sockets')}]
            page = int(bits[1]) if len(bits) > 1 else 1
            per = []
            start, count, pages = 0, 0, []
            while start < len(names):
                chunk, room = [], self.SMS_ONE - 30
                while start < len(names) and room - len(_fact_ascii(names[start])) - 2 >= 0:
                    chunk.append(names[start])
                    room -= len(_fact_ascii(names[start])) + 2
                    start += 1
                if not chunk:
                    chunk.append(names[start][:60])
                    start += 1
                pages.append(chunk)
            if not pages:
                return self._sms_one('No %s yet.' % bits[0])
            page = max(1, min(page, len(pages)))
            tail = (' Next: help %s %d' % (bits[0], page + 1)) if page < len(pages) else ''
            return self._sms_one('%s %d/%d: %s.%s' % (bits[0], page, len(pages), ', '.join(pages[page - 1]), tail))

        # an object and what it has: "help loznice." (and "help loznice. 2")
        if bits[0].endswith('.') and len(bits[0]) > 1:
            found = self.object_find(what.split()[0][:-1])
            if not found:
                return self._sms_one('Nothing called "%s". Names: help devices, help rooms.' % what.split()[0][:-1][:24])
            kind, oid, name, item, _g = found
            members = self._obj_members(kind, oid, item, values=False)
            sets = [m['name'] for m in members if m.get('settable')]
            does = ['%s(%s)' % (m['name'], 'x' if m.get('takes') == 'value' else '') for m in members
                    if m['kind'] == 'proc' and m.get('use')]
            reads = [m['name'] for m in members if m['kind'] in ('prop', 'func') and not m.get('settable')]
            parts = []
            if sets:
                parts.append('set ' + ' '.join(sets))
            if does:
                parts.append('do ' + ' '.join(does))
            if reads:
                parts.append('read ' + ' '.join(reads))
            page = int(bits[1]) if len(bits) > 1 and bits[1].isdigit() else 1
            text = '; '.join(parts)
            lead = '%s: ' % name
            room = self.SMS_ONE - len(_fact_ascii(lead)) - 22
            chunks, rest = [], _fact_ascii(text)
            while rest:
                if len(rest) <= room:
                    chunks.append(rest)
                    break
                cut = rest.rfind(' ', 0, room)
                cut = cut if cut > 0 else room
                chunks.append(rest[:cut])
                rest = rest[cut:].strip()
            page = max(1, min(page, len(chunks) or 1))
            tail = (' ..help %s. %d' % (name, page + 1)) if page < len(chunks) else ''
            return self._sms_one(lead + (chunks[page - 1] if chunks else 'nothing') + tail)

        # a topic
        topic = self._sms_topic_of(low)
        if topic:
            rows = [r for r in live if r[1] == topic]
            short = self.SMS_TOPIC_SHORT.get(topic, topic)
            if topic == 'objects':
                return self._sms_one('objects: Loznice.eco_c | Loznice.eco_c = 19 | Vecer.run(). '
                                     'What one has: help Loznice.')
            if not rows:
                return self._sms_one('%s: all of it is switched off in Settings > SMS.' % short)
            examples = []
            covers = ''
            for row in rows:
                members = self.sms_family_members(row[5]) if row[5] else []
                one = self._sms_example(row, members)
                if one and one not in examples:
                    examples.append(one)
                covers = covers or row[5]
            names = {'rooms': 'help rooms', 'devices': 'help devices', 'sockets': 'help sockets 1',
                     'scenes': 'help scenes 1', 'scripts': 'help scripts 1'}.get(covers, '')
            # led by the topic as the card calls it, so the answer and the
            # card say the same thing
            return self._sms_fit_one('%s: ' % topic, examples, ('. Names: %s' % names) if names else '',
                                     sep=' | ')

        # one named thing: a room, a socket, a scene, a script, a device
        for key, _topic, _phrase, _what, _example, covers in live:
            shape = self.SMS_HELP_FOR_ONE.get(key)
            if not shape or not covers:
                continue
            for mid, name in self.sms_family_members(covers):
                if str(name).strip().lower() != low:
                    continue
                if not self.sms_builtin_on(key, mid):
                    continue
                says = []
                for k2, _t2, _p2, _w2, _e2, c2 in live:
                    shape2 = self.SMS_HELP_FOR_ONE.get(k2)
                    if not shape2 or c2 != covers:
                        continue
                    if not self.sms_builtin_on(k2, mid):
                        continue
                    says.append(shape2 % name)
                return self._sms_fit_one('%s - say: ' % name, says)
        # any other object: what it has
        found = self.object_find(what)
        if found:
            return self.sms_help(what + '.')
        # a word that is nearly a topic
        import difflib
        near = difflib.get_close_matches(low, shorts + list(self.SMS_TOPIC_WORDS), n=1, cutoff=0.6)
        guess = (' Did you mean help %s?' % self.SMS_TOPIC_SHORT.get(self._sms_topic_of(near[0]) or near[0],
                                                                       near[0])) if near else ''
        return self._sms_one('Nothing called "%s".%s Topics: %s.' % (what[:20], guess, ', '.join(shorts)))

    def sms_system_key(self, text):
        """Which built-in command would answer this message, without doing it:
        (family key, the thing it is about or None, the words it acts on), or
        None when no built-in command understands it - or the one that would
        is switched off.

        sms_system_do decides by this very thing and then acts, so asking
        "would a built-in command take this?" and letting it are the same
        question, answered the same way."""
        # A message may run over more than one line now that the whole of it
        # is kept - a signature, a stray second line - and a command lives on
        # the first. Read whole, "status" followed by "Sent from my iPhone"
        # matched nothing at all and the sender got the help text back.
        text = str(text or '').strip().splitlines()[0] if str(text or '').strip() else ''
        words = [w for w in text.strip().split() if w]
        if not words:
            return None
        low = ' '.join(words).lower()
        head = words[0].lower()
        on = self.sms_builtin_on

        def said(key, thing=None, use=None):
            return (key, thing, use if use is not None else words) if on(key, thing) else None

        if head in ('help', '?', 'commands') or low == 'what can you do':
            return said('help_topic' if len(words) > 1 else 'help')
        if low in ('status', 'house', 'how is the house'):
            return said('status')
        if low in ('on', 'what is on', 'whats on', "what's on"):
            return said('whats_on')
        if low == 'blocked':
            return said('blocked')
        if head in ('ban', 'unban') and len(words) > 1:
            return said(head)

        # an object, written as a script writes it: Loznice.eco_c,
        # Loznice.eco_c = 19, Vecer.run()
        whole = ' '.join(words)
        if '.' in whole:
            if self.SCRIPT_CALL.match(whole):
                return said('obj_call')
            if self.SCRIPT_ASSIGN.match(whole):
                return said('obj_set')
            asked = re.match(r'^([^\s{}=(?][^{}=(?]*?)\.([A-Za-z_][A-Za-z0-9_]*)\s*\??$', whole)
            if asked and self.object_find(asked.group(1).strip()):
                return said('obj_read')

        # the heating, in the shapes the verb takes
        if head in ('heating', 'heat', 'topeni', 'vytapeni'):
            rest = words[1:]
            if not rest:
                return said('heat_state')
            first = rest[0].lower()
            if first in ('on', 'off', 'toggle'):
                return said('heat_onoff', None, rest)
            if first in ('away', 'all') or self._sms_room_named(first):
                return self.sms_system_key(' '.join(rest))
            return said('heat_state')
        if head == 'away':
            # on / off / toggle first: numeric() reads "on" as a one
            after = words[1].lower() if len(words) > 1 else ''
            key = ('heat_away_c' if after and after not in ('on', 'off', 'toggle')
                   and numeric(after.replace(',', '.')) is not None else 'heat_away')
            return said(key)
        if head == 'all' and len(words) > 1:
            return said('room_all')

        # a room named outright. Its own switch as well as the family's, so
        # one room can be left out of everything a phone may do.
        room = self._sms_room(words[0])
        if room is not None:
            after = words[1].lower() if len(words) > 1 else ''
            if not after:
                key = 'room_state'
            elif after in ('comfort', 'eco', 'night') and len(words) > 2:
                key = 'room_setting'
            elif after in self.HEAT_WORDS:
                key = 'room_level'
            elif numeric(after.replace(',', '.').lstrip('+')) is not None:
                key = 'room_temp'
            else:
                key = ''
            if key:
                return said(key, room['id'])

        # a socket switched by its own name: "plug-ups off"
        if len(words) > 1 and words[-1].lower() in ('on', 'off', 'toggle'):
            plug = self.plug_by_name(' '.join(words[:-1]))
            if plug is not None and not plug.cfg.get('monitor_only'):
                return said('plug_switch', plug.cfg.get('name') or plug.name)

        # a scene or a little script by its name
        for one in self.scenes():
            if str(one.get('name') or '').strip().lower() == low:
                return said('scene_run', str(one.get('id') or one.get('name')))
        for one in self.scripts():
            if str(one.get('name') or '').strip().lower() == low:
                return said('script_run', str(one.get('id') or one.get('name')))
        return None

    def _sms_object(self, key, text, origin):
        """Loznice.eco_c, Loznice.eco_c = 19, Vecer.run() - by text, through
        the same door the script and the object view use, so what keeps the
        house safe is refused here too, and a wrong value says what it takes."""
        try:
            if key == 'obj_call':
                who, member, args = self.SCRIPT_CALL.match(text).groups()
                return self._sms_one(self.object_call(who.strip(), member, args, origin))
            if key == 'obj_set':
                who, member, value = self.SCRIPT_ASSIGN.match(text).groups()
                return self._sms_one(self.object_set(who.strip(), member, value, origin, by_text=True))
            asked = re.match(r'^([^\s{}=(?][^{}=(?]*?)\.([A-Za-z_][A-Za-z0-9_]*)\s*\??$', text)
            who, member = asked.group(1).strip(), asked.group(2)
            found = self.object_find(who)
            rows = [m for m in self._obj_members(found[0], found[1], found[3], values=True, only=member)
                    if m['name'].lower() == member.lower()] if found else []
            if not rows:
                return self._sms_one('%s has no %s. What it has: help %s.' % (found[2] if found else who,
                                                                             member, who))
            m = rows[0]
            if m['kind'] == 'proc':
                return self._sms_one('%s.%s is done, not read: %s.%s()' % (found[2], m['name'], found[2], m['name']))
            v = m['value']
            v = ('yes' if v else 'no') if isinstance(v, bool) else (', '.join(v) if isinstance(v, list) else v)
            return self._sms_one('%s.%s = %s' % (found[2], m['name'], '-' if v in (None, '') else v))
        except ValueError as e:
            return self._sms_one('Not done: %s' % e)

    def sms_system_do(self, text, origin='a text message'):
        """The built-in commands. None when the text is not one of them.

        Tried after the commands written on the SMS card that are sure of the
        message (see sms_match_strength), and before the plain "how is X"
        question, so "loznice eco" is an instruction rather than a question
        about a room of that name."""
        found = self.sms_system_key(text)
        if not found:
            return None
        key, thing, words = found
        joined = ' '.join(words)
        if key in ('help', 'help_topic'):
            return self.sms_help(' '.join(words[1:]))
        if key in ('obj_read', 'obj_set', 'obj_call'):
            return self._sms_object(key, joined, origin)
        if key == 'status':
            return self._sms_status_line()
        if key == 'whats_on':
            facts = self.message_facts(origin)
            return ('On now: %s. Lights: %s.'
                    % (facts.get('plugs_on_list') or 'nothing',
                       facts.get('lights_on_list') or 'none'))[:300]
        if key == 'blocked':
            many, _newest = self.store.blocked_summary()
            names = ', '.join(self.store.blocked_names(5))
            return ('%d address(es) kept out%s' % (many, (': ' + names) if names else '.'))[:300]
        if key in ('ban', 'unban'):
            span = int(words[2]) if len(words) > 2 and words[2].isdigit() else None
            return self.ban_by_name(key, words[1], origin, span)[:300]
        if key == 'heat_state':
            return self._sms_heating_line()
        if key == 'room_state':
            room = next((r for r in self.rooms() if r['id'] == thing), None)
            return self.heat_say(room['name'] if room else joined, origin)[:300]
        if key in ('heat_onoff', 'heat_away', 'heat_away_c', 'room_all',
                   'room_level', 'room_temp', 'room_setting'):
            return self.heat_say(joined, origin)[:300]
        if key == 'plug_switch':
            plug = self.plug_by_name(' '.join(words[:-1]))
            self._fire_target('plug:' + plug.name, words[-1].lower(), origin)
            return '%s %s' % (plug.name, words[-1].lower())
        if key == 'scene_run':
            one = next((x for x in self.scenes() if str(x.get('id') or x.get('name')) == thing), None)
            self.run_scene(one.get('id'), origin)
            return 'ran the scene %s' % one.get('name')
        if key == 'script_run':
            one = next((x for x in self.scripts() if str(x.get('id') or x.get('name')) == thing), None)
            out = self.run_script(one, {}, origin=origin)
            said = out.get('said') or ''
            said = said if isinstance(said, str) else '\n'.join(said)
            return (said or 'ran %s' % one.get('name'))[:300]
        return None

    def _sms_room(self, word):
        want = str(word or '').strip().lower()
        return next((r for r in self.rooms()
                     if str(r.get('name') or '').strip().lower() == want), None)

    def _sms_room_named(self, word):
        want = str(word or '').strip().lower()
        return any(str(r.get('name') or '').strip().lower() == want for r in self.rooms())

    def _sms_heating_line(self):
        heat = self.heating_state()
        bits = ['Heating %s' % ('on' if heat.get('enabled') else 'off')]
        if heat.get('away'):
            bits.append('away on (%s °C)' % fmt_num(heat.get('away_c')))
        for room in heat.get('rooms', []):
            bits.append('%s %s %s°' % (room['name'], room.get('mode') or room.get('level') or 'plan',
                                            fmt_num(room.get('temperature'))))
        return ', '.join(bits)[:300]

    def _sms_status_line(self):
        facts = self.message_facts('a text message')
        bits = ['%s in' % (facts.get('home') or 'nobody'),
                '%s °C inside' % facts.get('inside_c') if facts.get('inside_c') != '' else '',
                '%s on' % (facts.get('plugs_on') if facts.get('plugs_on') is not None else '?'),
                'heating %s' % facts.get('heating_on')]
        if facts.get('attention'):
            bits.append('%s want a look' % facts.get('attention'))
        return ', '.join(b for b in bits if b)[:300]

    def sms_ask(self, text):
        """A question about a thing, rather than a command: the name of a
        device, a room or a socket, and it says how that thing is. Written so
        "temp loznice", "loznice" and "Temp-Loznice" all find the same
        thermometer."""
        words = [w for w in re.split(r'[\s,]+', str(text or '').strip()) if w]
        if not words or len(words) > 4:
            return None
        wanted = ' '.join(words).lower()
        skip = {'temp', 'temperature', 'teplota', 'how', 'is', 'what', 'stav', 'status'}
        core = ' '.join(w for w in words if w.lower() not in skip).lower().strip() or wanted

        # Two passes: the thing that is called exactly that, and only if there
        # is none, the thing whose name is part of it. Otherwise a sensor
        # called "Temp" answers every question with the word temp in it.
        loose = [False]

        def matches(name):
            name = str(name or '').lower()
            if not core or not name:
                return False
            if core == name:
                return True
            if not loose[0]:
                return False
            return core in name or name in core or all(part in name for part in core.split())

        for pass_ in (0, 1):
            loose[0] = bool(pass_)
            found = self._sms_ask_pass(matches)
            if found:
                return found
        return None

    def _sms_ask_pass(self, matches):
        # a room, with its temperature and whether it is calling for heat
        for room in self.heating_state().get('rooms') or []:
            if matches(room['name']):
                bits = ['%s:' % room['name']]
                if room.get('temperature') is not None:
                    bits.append('%.1f \u00b0C' % room['temperature'])
                if room.get('wanted_c') is not None:
                    bits.append('wants %.1f' % room['wanted_c'])
                bits.append('heating' if room.get('calling') else 'not heating')
                return ' '.join(bits)[:300]
        # a socket
        for name, plug in self.plugs.items():
            if matches(name):
                power = self.latest_value('plug:' + name, 'switch.apower')
                on = plug.output
                if on is None:                    # never polled in this run: what was written down
                    on = bool(self.latest_value('plug:' + name, 'switch.output'))
                return ('%s is %s%s' % (name, 'on' if on else 'off',
                                        (', %.0f W' % power) if power else ''))[:300]
        # any device, with its headline readings
        for dev in self.store.devices():
            # a device may answer to two names: what the network calls it and
            # what this house calls it. Whichever was asked for is the one to
            # say back.
            called = dev.get('alias') or dev.get('name')
            if matches(called):
                pass
            elif matches(dev.get('name')):
                called = dev.get('name')
            else:
                continue
            described = self.describe(dev, self.live.get(dev['id']))
            bits = []
            for h in (described.get('headline') or [])[:4]:
                value = h.get('value')
                bits.append('%s %s%s' % (h.get('label'), value, (' ' + h['unit']) if h.get('unit') else ''))
            when = described.get('age_s')
            tail = (', %s ago' % human_span(when)) if when else ''
            return ('%s: %s%s' % (called, ', '.join(bits) or 'nothing to say', tail))[:300]
        return None

