    if waiting:
        print(pal.title('Waiting to be approved'))
        for one in waiting:
            print('  %s %-16s %-28s %s  %ss left' % (
                pal.warn('\u23f3'), one.get('link', '')[:16], (one.get('what') or '')[:28],
                pal.dim((one.get('who') or '')[:24]), one.get('left', 0)))
