def cmd_taps(args, pal):
    """The one-tap links, and where to point a watch at them."""
    data = _need_daemon(pal, '/api/status')
    if data is None:
        return 2
    taps = data.get('taps') or []
    whole = {}
    if SHOW_SECRETS:
        # the addresses themselves, which take the PIN like any other secret
        pin = getattr(args, 'pin', None) or ask_for_pin(pal)
        answer = fetch_secrets(pin)
        for group in ((answer or {}).get('secrets') or []):
            if group.get('title') == 'One-tap links':
                whole = {i['name']: i['value'] for i in group['items']}
    if args.json:
        print(json.dumps(taps, indent=2, ensure_ascii=False))
        return 0
    if not taps:
        print(pal.dim('no links yet. Settings \u2192 One-tap links'))
        return 0
    mode = str((data.get('runtime_config') or {}).get('tap_mode', {}).get('value') or 'link')
    wants_code = bool((data.get('runtime_config') or {}).get('tap_code', {}).get('value')) and mode != 'link'
    if mode != 'link':
        print(pal.dim('  links are opened %s' % {'both': 'either by their address or by a header',
                                                  'header': 'by a header only - old addresses are refused'}[mode]))
        where = str((data.get('runtime_config') or {}).get('public_url', {}).get('value') or '').strip()
        where = (where[:-len('/index.php')] + '/tap') if where.endswith('/index.php') else (where or 'https://your-dashboard') + '/tap'
        print(pal.dim('    POST %s' % where))
        print(pal.dim('    X-Zigmon-Tap: <the address\'s secret, without the URL around it>'))
        if wants_code:
            print(pal.dim('    X-Zigmon-Code: <six digits from the phone>'))
        print()
    for tap in taps:
        what = ('tells you: %s' % next((t for k, t, _ in Daemon.TELL_PRESETS if k == tap.get('do')),
                                       'something of your own')) if tap.get('target') == 'tell' \
            else '%s %s' % (tap.get('does') or tap.get('do'), tap.get('label') or tap.get('target'))
        print('  ' + pal.key(tap['name']) + pal.dim('   ' + what))
        print('    ' + (pal.key(whole[tap['name']]) if tap['name'] in whole
                        else pal.dim('the address is kept back - zigmon --taps --secret for it')))
        if tap['name'] in whole and '/tap/' in whole[tap['name']]:
            print(pal.dim('    that shape needs the /tap/ rule in nginx; the installer\'s '
                          'configuration has it'))
        if tap.get('used'):
            print(pal.dim('    used %d time(s), last %s ago%s'
                          % (tap.get('uses') or 0, human_age(time.time() - tap['used']),
                             {'link': ', by its address', 'header': ', by a header'}.get(tap.get('way') or '', ''))))
    print()
    print(pal.dim('  Each link does one thing and nothing else. Anyone who has it can do that one'))
    print(pal.dim('  thing, so keep them to what you would not mind a stranger doing.'))
    return 0


def cmd_secret(args, pal):
    """`zigmon --secret` - show what is ordinarily shortened or blanked.

    A shortened SIM and a blanked password are there so that a screenshot, a
    log or somebody over one's shoulder does not carry them away. They are
    still one\'s own, though, and reading a configuration by hand to find a
    password one set last year is a poor sort of secrecy.
    """
    pin = getattr(args, 'pin', None) or ask_for_pin(pal)
    try:
        args.pin = pin
    except Exception:
        pass
    answer = fetch_secrets(pin)
    if not (answer or {}).get('ok'):
        print(pal.crit('\u2718  ') + str((answer or {}).get('error') or 'refused'))
        return 1
    groups = (answer or {}).get('secrets') or []
    if not groups:
        print(pal.dim('nothing is being kept back'))
        return 0
    print_secret_groups(groups, pal)
    print()
    print(pal.dim('  It has been written down in the events that these were shown.'))
    return 0


def reload_broker_here():
    """Ask mosquitto to read its ACL again, from this process.

    The daemon cannot: it runs as its own user and one user may not signal
    another's process. Whoever types `zigmon --acl mend` usually can, so it
    is tried here before anybody is told to do it by hand.
    """
    import signal
    import subprocess
    try:
        out = subprocess.run(['pidof', 'mosquitto'], capture_output=True, text=True, timeout=5)
        pids = [int(x) for x in (out.stdout or '').split()]
    except Exception:
        pids = []
    for pid in pids:
        try:
            os.kill(pid, signal.SIGHUP)
            return True, 'mosquitto was asked to read it again'
        except OSError:
            break
    for argv in (['systemctl', 'kill', '-s', 'HUP', 'mosquitto'],
                 ['sudo', '-n', 'systemctl', 'kill', '-s', 'HUP', 'mosquitto']):
        try:
            if subprocess.run(argv, capture_output=True, text=True, timeout=10).returncode == 0:
                return True, 'mosquitto was asked to read it again'
        except Exception:
            continue
    return False, 'mosquitto still has to be told: sudo systemctl kill -s HUP mosquitto'


def cmd_acl(args, pal):
    """What the broker must allow, and - if asked - the lines put in for you."""
    what = str(getattr(args, 'acl', 'check') or 'check').lower()
    if what in ('mend', 'fix', 'add'):
        code, r = api_call('/api/mqtt/acl/mend', 'POST', {'pin': _pin_for(args)}, token=read_token(), timeout=40.0)
        ok = code == 200 and (r or {}).get('ok')
        message = str((r or {}).get('message') or (r or {}).get('error'))
        if ok and (r or {}).get('reloaded') is False:
            # The daemon runs as itself and may not signal another user's
            # process. This command, though, is usually run by the person who
            # can - so rather than telling them what to type, try it here.
            told, how = reload_broker_here()
            if told:
                # say what was done, not what the daemon could not do
                added = re.match(r'(added \d+ line\(s\))', message)
                print(pal.ok('\u2714  ') + '%s; %s' % (added.group(1) if added else 'the ACL was mended', how))
                if (r or {}).get('kept'):
                    print(pal.dim('   the file as it was is kept at %s' % r['kept']))
                return 0
        print((pal.ok('\u2714  ') if ok else pal.crit('\u2718  ')) + message)
        if ok and (r or {}).get('kept'):
            print(pal.dim('   the file as it was is kept at %s' % r['kept']))
        return 0 if ok else 1
    data = _need_daemon(pal, '/api/mqtt/acl')
    if data is None:
        return 2
    print(pal.dim(str(data.get('file') or '')))
    for host, names in sorted((data.get('muddled_prefixes') or {}).items()):
        print(pal.warn('%s has %d MQTT prefixes for one box (%s).' % (host, len(names), ', '.join(names))))
        print(pal.dim('   A box publishes under one. Give its sockets the same prefix and this list '
                      'shrinks to one set of lines.'))
    for w in data.get('wanted') or []:
        mark = pal.ok('\u2714') if w.get('covered') else pal.crit('\u2718')
        print('  %s  %-9s %-9s %-28s %s' % (mark, w.get('user'), w.get('access'), w.get('topic'), pal.dim(w.get('why') or '')))
    missing = [w for w in (data.get('wanted') or []) if not w.get('covered')]
    if data.get('error'):
        print(pal.warn('\n' + str(data['error'])))
        if data.get('fix'):
            print(data['fix'])
    elif missing:
        print(pal.warn('\n%d line(s) missing. zigmon --acl mend puts them in.' % len(missing)))
    else:
        print(pal.ok('\nthe broker allows everything this needs'))
    return 0


def cmd_modem(args, pal):
    """Everything the modem says about itself, the way the gateway command
    reads a Zigbee coordinator: dump, info, sim, signal, bands, data."""
    what = (args.modem or 'dump').strip().lower()
    code, r = api_call('/api/modem/status', 'POST', {'pin': _pin_for(args)}, token=read_token(), timeout=40.0)
    if code != 200 or not (r or {}).get('ok'):
        print(pal.crit(str((r or {}).get('error') or 'the modem did not answer')))
        return 2
    v = r.get('values') or {}
    bands = r.get('bands') or []
    def block_(title, keys):
        rows = [(k, v[k]) for k in keys if v.get(k) not in (None, '')]
        if not rows:
            return
        print(pal.dim(title))
        for key, value in rows:
            label, unit = KEY_INFO.get(key, (key.replace('_', ' '), ''))
            print('  %-22s %s%s' % (label, value, (' ' + unit) if unit else ''))
    if what in ('dump', 'all'):
        wanted = ['sim', 'sim_card', 'sim_slots', 'active_sim', 'pin', 'pin_tries_left', 'esim',
                  'provider', 'operator', 'operator_state', 'state', 'registration',
                  'network', 'network_type', 'band', 'bandwidth_mhz', 'carrier_aggregation',
                  'signal_quality', 'rssi', 'rsrp', 'rsrq', 'sinr', 'ecio', 'rscp',
                  'cell', 'physical_cell', 'earfcn', 'area_code', 'tracking_area', 'mcc', 'mnc',
                  'imei', 'model', 'firmware', 'mimo', 'modem_temperature', 'volte', 'antenna',
                  'sms_centre', 'credit', 'credit_bonus', 'credit_total', 'credit_until',
                  'received_mb', 'sent_mb', 'data_since',
                  'received_total_mb', 'sent_total_mb', 'sent_today', 'received_today',
                  'in_the_inbox', 'waiting_to_go', 'commands']
        block_('SIM card', wanted[:7])
        block_('Connection', wanted[7:16])
        block_('Signal', wanted[16:23])
        block_('Cell', wanted[23:31])
        block_('The modem', wanted[31:39])
        block_('Traffic and messages', wanted[39:])
        left = [k for k in sorted(v) if k not in wanted]
        block_('Anything else it said', left)
    elif what in ('sim', 'card'):
        block_('SIM card', ['sim', 'sim_card', 'sim_slots', 'active_sim', 'pin', 'pin_tries_left',
                            'esim', 'provider', 'mcc', 'mnc'])
    elif what in ('signal', 'radio'):
        block_('Signal', ['signal_quality', 'rssi', 'rsrp', 'rsrq', 'sinr', 'ecio', 'rscp',
                          'band', 'bandwidth_mhz', 'carrier_aggregation'])
    elif what in ('data', 'traffic'):
        block_('Traffic and messages', ['credit', 'credit_bonus', 'credit_total', 'credit_until',
                                        'received_mb', 'sent_mb', 'data_since',
                                        'received_total_mb', 'sent_total_mb',
                                        'sent_today', 'received_today',
                                        'in_the_inbox', 'waiting_to_go', 'commands'])
        print(pal.dim('  zigmon --modem reset starts the first two counting again'))
    elif what in ('info', 'device'):
        block_('The modem', ['model', 'firmware', 'imei', 'mimo', 'modem_temperature', 'volte',
                             'antenna', 'sms_centre'])
    elif what in ('cell', 'cells'):
        block_('Cell', ['cell', 'physical_cell', 'earfcn', 'area_code', 'tracking_area', 'mcc', 'mnc'])
    elif what in ('credit', 'balance', 'ussd', 'ask'):
        # whatever was typed after the word, so any code can be sent as it is
        code = getattr(args, 'code', None) or ' '.join(getattr(args, 'text', None) or []) or None
        c, r = api_call('/api/modem/ussd', 'POST', {'pin': _pin_for(args), 'code': code},
                        token=read_token(), timeout=60.0)
        ok = c == 200 and (r or {}).get('ok')
        if not ok:
            print(pal.crit('\u2718  ') + str((r or {}).get('error') or 'the network said nothing'))
            return 1
        answer = str((r or {}).get('message') or '')
        print(pal.dim('sent %s' % (code or CONFIG.get('sms_credit_code') or '(the code in the settings)')))
        print(pal.ok('the network says'))
        import textwrap
        for line in answer.split('\n'):
            for wrapped in textwrap.wrap(line, max(40, _terminal_width() - 4)) or ['']:
                print('  ' + wrapped)
        parts = credit_parts(answer)
        if CONFIG.get('sms_credit_pattern'):
            own = credit_from(answer, CONFIG['sms_credit_pattern'])
            if own is not None:
                parts = {'credit': own}
        parts = {k: v for k, v in parts.items() if v is not None}
        if parts:
            print(pal.dim('  \u2014 read as ' + ', '.join(
                '%s %s' % (KEY_INFO.get(k, (k, ''))[0].lower(), v) for k, v in sorted(parts.items()))))
        else:
            print(pal.dim('  \u2014 no figure in it that looks like money, so nothing was recorded'))
        return 0
    elif what in ('reset', 'zero'):
        code, r = api_call('/api/modem/reset-data', 'POST', {'pin': _pin_for(args), 'by': 'the command line'},
                           token=read_token(), timeout=40.0)
        ok = code == 200 and (r or {}).get('ok')
        print((pal.ok('\u2714') if ok else pal.crit('\u2718')) + '  ' + str((r or {}).get('message') or (r or {}).get('error')))
        return 0 if ok else 1
    elif what not in ('bands', 'band'):
        print(pal.crit('%r is not one of dump, info, sim, signal, cell, data, bands, reset, credit' % what))
        return 2
    if what in ('dump', 'all', 'bands', 'band'):
        if not bands:
            print(pal.dim('no per-band figures - the modem gives them on 4G and 5G'))
        else:
            print(pal.dim('Bands'))
            print(pal.dim('  %-10s %-8s %-10s %-6s %-8s %-8s %-8s %s'
                          % ('band', 'earfcn', 'bandwidth', 'pci', 'rssi', 'rsrp', 'rsrq', 'sinr')))
            for b in bands:
                print('  %-10s %-8s %-10s %-6s %-8s %-8s %-8s %s'
                      % (b.get('band', '-'), b.get('earfcn', '-'), b.get('bandwidth', '-'),
                         b.get('pcid', '-'), b.get('rssi', '-'), b.get('rsrp', '-'),
                         b.get('rsrq', '-'), b.get('sinr', '-')))
    return 0


def cmd_check_sms(args, pal):
    """Walk the whole road to the gateway and say, step by step, what is well
    and what is not - the answer to "it does not work" without guesswork."""
    code, cfg = api_call('/api/status')
    settings = (cfg or {}).get('runtime_config') or {}
    def value(key, default=None):
        got = settings.get(key)
        if isinstance(got, dict):
            got = got.get('value')
        return default if got in (None, '') else got
    steps, worry = [], []
    def step(what, ok, detail='', fix=''):
        steps.append((what, ok, detail, fix))
        if not ok and fix:
            worry.append(fix)
        return ok

    if code != 200:
        print(pal.crit('daemon not reachable: %s' % (cfg or {}).get('error')))
        return 2
    if not step('the gateway is switched on', bool(value('sms_enabled')),
                'sms_enabled', 'switch it on in Control -> System -> SMS gateway'):
        _print_sms_steps(steps, worry, pal)
        return 1
    host = value('sms_host', '')
    step('it has an address', bool(host), str(host), 'fill in the modem\'s address')
    scheme = 'https' if value('sms_https') else 'http'
    port = int(value('sms_port', 0) or 0)
    where = '%s://%s%s' % (scheme, host, (':%d' % port) if port else '')
    step('over %s' % scheme.upper(), True, where)
    api = str(value('sms_api', 'rest'))
    step('the interface is the one a TRB140 offers', api in ('rest', 'rpc'), api,
         "set 'Which interface' to rest - cgi has to be switched on by hand on the modem")
    step('it has a username', bool(value('sms_user')), str(value('sms_user', '')),
         'fill in an account that may use the API')
    step('it has a password', bool(value('sms_password')),
         value('sms_password') if SHOW_SECRETS else '(kept)', 'fill in that account\'s password')

    # now the device itself
    code, r = api_call('/api/sms/test', 'POST', {'pin': _pin_for(args)}, token=read_token(), timeout=40.0)
    ok = code == 200 and r.get('ok')
    message = str(r.get('message') or r.get('error') or '')
    fix = ''
    if not ok:
        low = message.lower()
        if 'would not let us in' in low or '403' in low:
            fix = 'the username or password is wrong, or that account may not use the API'
        elif 'could not reach' in low or 'timed out' in low:
            fix = 'wrong address, HTTPS off on the modem, or a firewall in between'
        elif 'certificate' in low:
            fix = 'switch off "Insist on a valid certificate" - a TRB signs its own'
        elif 'did not name a modem' in low:
            fix = 'the SIM is missing or locked; look at Network -> Mobile on the modem'
        else:
            fix = 'see what the device said, above'
    step('the device answers and lets us in', ok, message, fix)

    if ok:
        code, dev = api_call('/api/devices')
        gateway = next((x for x in (dev or {}).get('devices', []) if x.get('id') == 'sms:gateway'), None)
        readings = {k: (v.get('value') if isinstance(v, dict) else v)
                    for k, v in ((gateway or {}).get('values') or {}).items()}
        sim = str(readings.get('sim') or '')
        step('the SIM is in and unlocked', bool(sim) and 'lock' not in sim.lower() and 'absent' not in sim.lower(),
             sim or 'the modem said nothing about it', 'put the SIM in, or take its PIN off')
        signal = numeric(readings.get('rssi'))
        step('the signal is worth having', signal is None or signal > -105,
             ('%s dBm' % signal) if signal is not None else 'not reported',
             'move the modem or its aerial - below -105 dBm a message may not go out')
        state = str(readings.get('state') or '')
        step('the modem is registered', 'connect' in state.lower() or not state, state or 'not reported',
             'the SIM has no service, or the operator is refusing it')

    # who it would talk to
    to = str(value('sms_to', ''))
    code, st = api_call('/api/status')
    people = ((st or {}).get('sms') or {}).get('people') or []
    with_alerts = [p['name'] for p in people if p.get('alerts')]
    with_commands = [p['name'] for p in people if p.get('may_command')]
    step('somebody would get an alert', bool(with_alerts or to),
         ', '.join(with_alerts + ([to] if to else [])) or 'nobody',
         'tick "Gets alerts" beside a person with a number, or add a number in the settings')
    step('somebody may give commands', bool(with_commands or value('sms_allow')),
         ', '.join(with_commands) or str(value('sms_allow', '') or 'nobody'),
         'tick "May command" beside a person, or add a number - without this every text is ignored')
    commands = ((st or {}).get('sms') or {}).get('commands') or 0
    step('there is something a text may do', commands > 0, '%d command(s)' % commands,
         'add one in Control -> Automation -> What a text message may do')
    push = bool(value('sms_push_secret'))
    every = int(value('sms_poll_s', 0) or 0)
    step('incoming messages are noticed', push or every > 0,
         ('forwarded by the modem' if push else '') + (' and ' if push and every else '')
         + ('looked for every %d s' % every if every else ''),
         'either set a word for forwarding, or give "Look for incoming messages every" a number')
    waiting = len((st or {}).get('sms_outbox') or [])
    step('nothing is stuck waiting to go', waiting == 0, '%d waiting' % waiting,
         'run zigmon --sms outbox to see why they would not go')
    _print_sms_steps(steps, worry, pal)
    return 0 if all(x[1] for x in steps) else 1


def _print_sms_steps(steps, worry, pal):
    for what, ok, detail, _ in steps:
        mark = pal.ok('\u2714') if ok else pal.crit('\u2718')
        print('  %s  %-42s %s' % (mark, what, pal.dim(str(detail)[:70])))
    if worry:
        print('\n' + pal.warn('what to do'))
        for line in worry:
            print('  - %s' % line)
    else:
        print('\n' + pal.ok('all well'))


def _tidy_date(text):
    """The modem writes 'Wed Sep 10 18:01:12 2026'; the house writes
    10.09.2026 18:01:12."""
    text = str(text or '').strip()
    if not text:
        return '-'
    for shape in ('%a %b %d %H:%M:%S %Y', '%Y-%m-%d %H:%M:%S', '%d/%m/%Y %H:%M:%S'):
        try:
            return time.strftime('%d.%m.%Y %H:%M:%S', time.strptime(text, shape))
        except ValueError:
            continue
    return text


def _when(ts):
    """A moment written the way a person writes one: 20.01.2026 17:34:35."""
    return time.strftime('%d.%m.%Y %H:%M:%S', time.localtime(ts or 0))


def _terminal_width():
    try:
        import shutil
        return shutil.get_terminal_size((100, 24)).columns
    except Exception:
        return 100


def _print_sms_log(pal, args, way, empty):
    """The conversation as this house has it: what came in, what went out."""
    limit = int(getattr(args, 'limit', 20) or 20)
    data = _need_daemon(pal, '/api/sms/log?limit=%d' % max(limit, 50))
    if data is None:
        return 2
    rows = [m for m in (data.get('messages') or []) if not way or m.get('dir') == way][:limit]
    if not rows:
        print(pal.dim(empty))
        return 0
    import textwrap
    width = max(40, _terminal_width() - 42)
    for m in rows:
        arrow = pal.ok('<-') if m.get('dir') == 'in' else pal.dim('->')
        who = m.get('person') or m.get('number') or '?'
        mark = '' if m.get('ok', True) else pal.crit(' (did not go)')
        head = '  %s %s %-18s ' % (_when(m.get('at')), arrow, who)
        # the whole message, wrapped under itself - a text is often three lines
        lines = textwrap.wrap(str(m.get('text') or ''), width) or ['']
        print(head + lines[0] + (mark if len(lines) == 1 else ''))
        for line in lines[1:]:
            print(' ' * len(head.replace(arrow, '  ')) + line)
        if len(lines) > 1 and mark:
            print(' ' * len(head.replace(arrow, '  ')) + mark.strip())
    return 0


def cmd_whatif(args, pal):
    """What the rules would make of a reading, without switching anything."""
    device, key, value = args.what_if
    code, r = api_call('/api/what-if', 'POST',
                       {'pin': _pin_for(args), 'device': device, 'key': key, 'value': value},
                       token=read_token())
    if code != 200 or not r.get('ok'):
        print(pal.crit(str(r.get('error') or code)))
        return 2
    print('if %s reported %s = %s%s' % (pal.value(r['device']),
                                        key, r['value'],
                                        pal.dim(' (it says %s now)' % r['was']) if r.get('was') is not None else ''))
    for rule in r.get('rules') or []:
        mark = pal.ok('\u2714') if rule['would_fire'] else pal.dim('\u2013')
        line = '%-44s %s %s' % (rule['rule'][:44], rule['do'], rule['target'])
        print('  %s %s' % (mark, line if rule['would_fire'] else pal.dim(line)))
        if not rule['would_fire']:
            print('      %s' % pal.dim(rule['why']))
    print(pal.ok('%d rule(s) would fire' % r.get('would_fire', 0)))
    return 0


def cmd_diagnose(args, pal):
    """Why a socket is not answering, step by step."""
    code, r = api_call('/api/plug/diagnose', 'POST', {'pin': _pin_for(args), 'name': args.diagnose},
                       token=read_token())
    if code != 200 or not r.get('ok'):
        print(pal.crit(str(r.get('error') or code)))
        return 2
    print('%s  %s' % (r['plug'], pal.dim(str(r.get('host') or ''))))
    for step in r.get('steps') or []:
        print('  %s  %-38s %s' % (pal.ok('\u2714') if step['ok'] else pal.crit('\u2718'),
                                  step['what'], pal.dim(step['detail'])))
    print('  %s' % (pal.ok(r['verdict']) if 'working' in r['verdict'] else pal.warn(r['verdict'])))
    return 0


