def cmd_rules(args, pal):
    status_code, data = api_call('/api/status')
    if status_code != 200:
        print(pal.crit('daemon not reachable: %s' % data.get('error')))
        return 2
    rules = data.get('rules') or []
    if args.json:
        print(json.dumps(rules, indent=2))
        return 0
    if not rules:
        print(pal.dim('no rules; add them on the Control tab of the dashboard'))
        return 0
    names = {x['id']: x['name'] for x in data.get('devices', [])}
    targets = {t['value']: t['name'] for t in data.get('switch_targets', [])}
    for sc in data.get('scenes', []):
        targets['scene:' + sc['id']] = 'scene ' + sc['name']
    table = [['\u25cf' if r.get('enabled', True) else '\u25cb',
              names.get(r['device'], r['device']),
              '%s %s %g' % (r['key'], r['op'], r['value']), '\u2192',
              targets.get(r['plug'], r['plug']),
              r['do'] + (' %d ms' % r['pulse_ms'] if r.get('pulse_ms') else ''),
              '?' if r.get('holds') is None else ('TRUE' if r['holds'] else 'false'),
              'now %g' % r['reading'] if r.get('reading') is not None else '']
             for r in rules]
    def paint(col, text, n):
        r = rules[n]
        if col == 0:
            return pal.ok(text) if r.get('enabled', True) else pal.dim(text)
        if col == 5:
            return pal.bold(text)
        if col == 6:
            return pal.dim(text) if r.get('holds') is None else (pal.warn(text) if r['holds'] else pal.ok(text))
        if col == 7:
            return pal.dim(text)
        return text
    print_table(pal, [' ', 'SOURCE', 'WHEN', ' ', 'TARGET', 'DOES', 'HOLDS', 'READING'], table, colour=paint)
    return 0


def plug_check_line(snap):
    """What `zigmon check` makes of one socket's reading.

    "first": it has not been polled yet, which right after a restart is not a
    fault. "unplugged": an optional socket that is not answering, which is
    what optional means - the daemon says the same of it and leaves its level
    alone. "ok" and "bad" are the two that are what they look like."""
    if (snap.get('error') or '') == 'waiting for the first reading':
        return 'first'
    if snap.get('online') and not snap.get('stale'):
        return 'ok'
    return 'unplugged' if snap.get('unplugged') else 'bad'


def cmd_check(args, pal):
    problems = 0

    def verdict(ok, text, detail=''):
        nonlocal problems
        if not ok:
            problems += 1
        print('  %s  %s%s' % (pal.ok('✔') if ok else pal.crit('✘'), text,
                              pal.dim('  ' + detail) if detail else ''))

    print(pal.bold('zigmon %s' % __version__))
    verdict(mqtt is not None, 'paho-mqtt importable', '' if mqtt else 'dnf install python3-paho-mqtt')
    verdict(not CONFIG_FATAL, 'configuration readable', '; '.join(CONFIG_FATAL))
    t0 = time.time()
    status_code, health = api_call('/api/health', timeout=5)
    ms = (time.time() - t0) * 1000
    verdict(status_code == 200, 'daemon API answering', '%.0f ms' % ms if status_code == 200 else health.get('error', ''))
    if status_code != 200:
        print(pal.dim('  is zigmon.service running?  journalctl -u zigmon -n 30'))
        return 1
    verdict(health['connected'], 'connected to the broker', health.get('last_error') or '')
    verdict(health.get('bridge_state') == 'online', 'Zigbee2MQTT bridge online',
            'state: %s' % health.get('bridge_state'))
    age = time.time() - health['last_message'] if health.get('last_message') else None
    verdict(age is not None and age < 3600, 'messages flowing',
            'last %s ago' % human_age(age) if age is not None else 'none since start')
    if health['connected']:
        # reading the broker and being allowed to write to it are two things:
        # without the second, every Zigbee switch command dies silently
        st_code, probe = api_call('/api/mqtt/selftest', timeout=8)
        verdict(st_code == 200 and probe.get('ok'), 'the broker accepts what we publish',
                (probe or {}).get('message') or 'no answer from the daemon')
    code, acl = api_call('/api/mqtt/acl', timeout=5)
    if code == 200:
        missing = acl.get('missing') or []
        if not acl.get('readable'):
            print('  %s  %s%s' % (pal.warn('!'), 'the broker ACL could not be read',
                                  pal.dim('  %s: %s' % (acl.get('file'), acl.get('error') or 'unreadable'))))
            for line in (acl.get('fix') or '').split('\n'):
                if line:
                    print('     ' + pal.dim(line))
        else:
            verdict(not missing, 'the broker\'s ACL covers every topic in use',
                    acl['file'] if not missing else '%d line(s) missing from %s' % (len(missing), acl['file']))
            for w in missing:
                print('     %s user %s: topic %s %s  %s' % (pal.warn('\u2022'), w['user'], w['access'], w['topic'], pal.dim(w['why'])))
            if missing:
                print(pal.dim('  add to %s, then: kill -HUP $(pidof mosquitto)' % acl['file']))
                for line in acl['suggestion'].split('\n'):
                    print('     ' + pal.dim(line))
    token = read_token()
    verdict(bool(token), 'API token readable by %s' % _whoami(), str(token_path()))
    # The PHP the dashboard is served by. Both holes published on 21 October
    # 2026 are reached before any page of this house runs, so no setting here
    # is between a caller and them - only the version.
    php = php_now(force=True)
    if php.get('found'):
        if php.get('patched_by'):
            verdict(True, 'PHP %s, patched by the distribution' % php['version'],
                    '%s names %s in its changelog' % (php['patched_by'], ', '.join(PHP2SHELL)))
        else:
            verdict(not php.get('vulnerable'),
                    'PHP %s (%s)' % (php['version'], php['how']),
                    php.get('fix') or 'carries the fix of 21 October 2026')
            if php.get('vulnerable'):
                print('     %s %s' % (pal.warn('•'),
                                      pal.dim('php2shell: %s, both 9.2. One request from '
                                              'anybody who can reach php-fpm is enough.'
                                              % ', '.join(PHP2SHELL))))
                print('     %s %s' % (pal.warn('•'),
                                      pal.dim('until it is updated: pm.max_requests = 1 in '
                                              '/etc/php-fpm.d/www.conf retires a worker after '
                                              'every request, which is what the second of the '
                                              'two needs to survive. A fork per request is the '
                                              'cost.')))
        # ...and the shape that reaches PHP's own parser, refused in front of
        # it. Nothing of this house ever sends one, so this stays switched on
        # after the update as well.
        guard = nginx_refuses_multipart()
        if guard is not None:
            verdict(guard, 'nginx refuses multipart bodies in front of PHP',
                    'the shape PHP\'s parser is broken by; nothing here sends one'
                    if guard else 'add: if ($http_content_type ~* "^multipart/") '
                                  '{ return 415; }')
    status_code, status = api_call('/api/status', timeout=5)
    if status_code == 200:
        c = status['counts']
        verdict(c['devices'] > 0, '%d device(s): %d ok, %d warn, %d crit' % (
            c['devices'], c['ok'], c['warn'], c['crit']), '')
        for d in status['devices']:
            if d['level'] != 'ok':
                print('     %s %s: %s' % (pal.level(d['level'], '●'), d['name'], '; '.join(d['reasons'])))
    status_code, plugs = api_call('/api/plugs', timeout=5)
    if status_code == 200:
        # right after a (re)start the plugs have not been asked yet: give the
        # first poll a moment instead of reporting a failure that is not one
        # `online` is true the moment the daemon comes up, because the reading
        # stored before the restart stands in until a fresh one lands - so
        # this never waited for anything and reported seven sockets as "not
        # polled yet" instead. What it is waiting for is the first poll, and
        # that is what the error says.
        pending = [snap for snap in plugs['plugs'] if snap['error'] == 'waiting for the first reading']
        if pending and (health.get('uptime_s') or 0) < 60:
            deadline = time.time() + 20
            while pending and time.time() < deadline:
                time.sleep(1.5)
                status_code, plugs = api_call('/api/plugs', timeout=5)
                if status_code != 200:
                    break
                pending = [snap for snap in plugs['plugs'] if snap['error'] == 'waiting for the first reading']
        for snap in plugs['plugs']:
            said = plug_check_line(snap)
            if said == 'first':
                print('  %s  plug %s%s' % (pal.warn('◔'), snap['name'], pal.dim('  not polled yet (the daemon just started)')))
                continue
            if said == 'unplugged':
                # A socket marked optional that is not answering is what
                # optional means. The daemon says so itself and leaves its
                # level alone; the check used to call it a failure, so every
                # upgrade of this house ended with "the check reported
                # problems" over a socket somebody had deliberately pulled
                # out, and exited non-zero with it.
                print('  %s  plug %s%s' % (pal.dim('○'), snap['name'],
                                           pal.dim('  not answering - optional, treated as unplugged')))
                continue
            verdict(said == 'ok', 'plug %s' % snap['name'],
                    snap['error'] or ('%s, %.1f W' % ('on' if snap['output'] else 'off', snap['values'].get('power') or 0)))
    db = health['db']
    # the counts are taken off the asking thread (see Storage.stats), so a
    # check run in the first seconds of a restart may be told "still counting"
    def rows(key):
        return '?' if db.get(key) is None else '%d' % db[key]
    verdict(True, 'database %s' % db['path'], '%s, %s samples, %s hourly, %s events%s' % (
        '%.1f MB' % (db['bytes'] / 1048576.0) if db.get('bytes') else '?', rows('samples'),
        rows('samples_hourly'), rows('events'),
        ' (being counted)' if db.get('counting') and db.get('samples') is None else ''))
    return 1 if problems else 0


def cmd_diag(args, pal):
    # where the time goes, first: it is what people run this for when it lags
    code, st = api_call('/api/status')
    if code == 200:
        L = st.get('latency') or {}
        print(pal.bold('Where the time goes'))
        def line(label, value, unit, good, bad):
            if isinstance(value, (int, float)):
                text = '%.1f%s' % (value, unit) if value < 10 else '%.0f%s' % (value, unit)
                paint = pal.ok if value <= good else (pal.warn if value <= bad else pal.crit)
            else:
                text, paint = '-', pal.dim
            print('  %-42s %s' % (label, paint(text)))
        line('daemon: message -> dashboard woken', st.get('wake_ms'), ' ms', 5, 50)
        line('daemon: status build', st.get('status_ms'), ' ms', 10, 60)
        line('daemon: clock thread late by', L.get('timer_jitter_ms'), ' ms', 20, 200)
        line('daemon: writes waiting', L.get('write_queue'), '', 20, 200)
        for x in (L.get('switches') or [])[-4:][::-1]:
            line('switching %s' % x.get('name'), x.get('ms'), ' ms', 120, 500)
        for host, info in (L.get('rate_limited') or {}).items():
            print('  ' + pal.crit('%-42s %d time(s), last %s ago' % (
                'box %s said too many requests' % host, info.get('times', 0),
                human_span(time.time() - (info.get('at') or 0)))))
        line('broker round trip', L.get('broker_rtt_ms'), ' ms', 5, 50)
        line('zigbee command -> device echo' + (' (%s)' % L['set_rtt_what'] if L.get('set_rtt_what') else ''), L.get('set_rtt_ms'), ' ms', 300, 2000)
        for name, rtt in sorted((L.get('plugs') or {}).items(), key=lambda x: -x[1]):
            line('box %s' % name, rtt, ' ms', 150, 600)
        print()
    print(pal.bold('Configuration in force (%s)' % CONFIG_FILE))
    for key in sorted(CONFIG):
        print('  %-24s %s' % (key, json.dumps(shown_value(key, CONFIG[key]))))
    for note in CONFIG_NOTES:
        print('  ' + pal.warn(note))
    for note in CONFIG_FATAL:
        print('  ' + pal.crit(note))
    print()
    for path in ('/api/health', '/api/status', '/api/events?limit=5'):
        t0 = time.time()
        status_code, data = api_call(path, timeout=5)
        print('  %-24s %s  %.0f ms' % (path, pal.ok(str(status_code)) if status_code == 200 else pal.crit(str(status_code)),
                                       (time.time() - t0) * 1000))
    status_code, health = api_call('/api/health', timeout=5)
    if status_code == 200:
        print()
        print(pal.bold('Daemon'))
        for key in ('version', 'uptime_s', 'connected', 'connect_failures', 'last_error', 'messages',
                    'bridge_state', 'subscriptions'):
            print('  %-24s %s' % (key, health.get(key)))
        print(pal.bold('Database'))
        for key, value in health['db'].items():
            if key == 'oldest' and value:
                value = datetime.fromtimestamp(value).strftime('%Y-%m-%d')
            if key == 'bytes' and value:
                value = '%.1f MB' % (value / 1048576.0)
            print('  %-24s %s' % (key, value))
    return 0


