def _thing_main(thing, argv):
    """'sms', 'modem' and 'wifi' as words of their own, each with its own help."""
    words = {'sms': SMS_WORDS, 'wifi': WIFI_WORDS, 'plug': PLUG_WORDS,
             'zigbee': ZIGBEE_WORDS}.get(thing, MODEM_WORDS)
    parser = argparse.ArgumentParser(
        prog='zigmon ' + thing,
        description=('The SMS gateway: what it has sent and received, what is waiting, and whether '
                     'it is well.' if thing == 'sms' else
                     'The wireless network as the controller sees it: the points and their radios, '
                     'how much of the air is in use and whose, what else is on it, and who is '
                     'connected.' if thing == 'wifi' else
                     'The sockets and the lights: what each is doing, what it is drawing, and '
                     'switching any of them.' if thing == 'plug' else
                     'The Zigbee mesh: who talks through whom, what the bridge is saying, and '
                     'letting a new device in.' if thing == 'zigbee' else
                     'The modem inside the gateway: what it says about itself, in the same words its '
                     'own status page uses.'),
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog='\n'.join(
            ['', 'what to ask for'] +
            ['  %-22s %s' % ('zigmon ' + thing + ' ' + w, why) for w, why in words] +
            ['', 'examples'] + THING_EXAMPLES.get(thing, []) + ['']))
    parser.add_argument('what', nargs='?', default=words[0][0], metavar='WHAT',
                        help='one of: ' + ', '.join(w for w, _ in words))
    parser.add_argument('code', nargs='?', metavar='CODE',
                        help="for ussd: the code to send, e.g. '*123#' (quote it, the shell eats stars)")
    parser.add_argument('--number', metavar='N', help='whose number, for send and test')
    parser.add_argument('--text', metavar='WORD', nargs='*', help='what to say, for send')
    parser.add_argument('--limit', type=int, default=20, help='how many rows to print (default 20)')
    parser.add_argument('--pin', metavar='PIN', help='not used any more: root is let in by its key')
    parser.add_argument('--secret', action='store_true',
                        help='and then the whole of what is ordinarily shortened or blanked')
    parser.add_argument('--force', action='store_true',
                        help='for zigbee remember: record a shape this would otherwise refuse')
    parser.add_argument('--config', metavar='PATH', help='a configuration file other than the usual one')
    parser.add_argument('--no-color', action='store_true', help='plain output with no colour codes')
    parser.add_argument('--json', action='store_true', help='machine-readable output where there is any')
    args = parser.parse_args(argv)
    global CONFIG_FILE
    if args.config:
        CONFIG_FILE = Path(args.config)
    load_config()
    pal = Palette(not args.no_color and sys.stdout.isatty())
    # --secret, before anything is printed: what this command shortens comes
    # out whole in its own place, and the passwords this command's subject
    # keeps are listed after it. It used to be set up after the branch that
    # runs `zigmon sms`, so that one died on a name that did not exist yet.
    held = None
    if getattr(args, 'secret', False):
        held = unmask_secrets(args, pal)
        if held is None:
            return 1
        globals()['SHOW_SECRETS'] = True

    def done(code):
        return finish_secrets(held, args, pal, thing) or code

    if thing == 'sms':
        args.sms = args.what
        if args.what in ('check', 'check-sms'):
            args.check_sms = True
            return done(cmd_check_sms(args, pal))
        return done(cmd_sms(args, pal))

    if thing == 'wifi':
        args.wifi = True
        return done(cmd_wifi_word(args, pal))
    if thing == 'plug':
        return done(cmd_plug_word(args, pal))
    if thing == 'zigbee':
        return done(cmd_zigbee_word(args, pal))
    args.modem = args.what
    return done(cmd_modem(args, pal))

def _upgrade_ask(pal, body=None, timeout=60.0):
    """/api/upgrade, read or asked, with the command line's own key. It is an
    administrator's road, so without root's key it is refused - and said so
    in words a person can act on rather than as a 403."""
    code, out = api_call('/api/upgrade', 'POST' if body else 'GET', body, timeout=timeout)
    if code == 200 and isinstance(out, dict):
        return out
    why = (out or {}).get('error') if isinstance(out, dict) else None
    if code in (401, 403):
        print(pal.crit('refused: %s (as root: sudo zigmon %s)' % (why or code, ' '.join(sys.argv[1:]))))
    elif code == 0:
        print(pal.crit('daemon not reachable: %s' % (why or 'no answer')))
    else:
        print(pal.crit('refused: %s' % (why or code)))
    return None


def cmd_upgrade_check(args, pal):
    """Look at upgrade_url now, as Control - Upgrades - Look now does."""
    out = _upgrade_ask(pal, {'action': 'online_look'}, timeout=90.0)
    if out is None:
        return 2
    row = (out.get('web') or {}).get('online') or {}
    if args.json:
        print(json.dumps(row, indent=2, default=str))
        return 0 if not row.get('error') else 1
    print(pal.title('looked at %s' % row.get('url')))
    if row.get('error'):
        print(pal.crit('  ' + row['error']))
        return 1
    for pk in row.get('packages') or []:
        mark = pal.ok('newer') if _online_ver(pk['version']) > _online_ver(__version__) else pal.dim('not newer')
        print('  %-26s %-10s %s' % (pk['name'], mark, pal.dim(pk['url'])))
    newest = row.get('newest')
    if not newest:
        print(pal.warn('  no zigmon package there'))
    elif row.get('newer'):
        print(pal.ok('  zigmon %s is there - this server runs %s: zigmon --upgrade-online'
                     % (newest['version'], __version__)))
    else:
        print(pal.ok('  nothing newer than %s' % __version__))
    return 0


def cmd_upgrade_online(args, pal):
    """Fetch the newest version (or the one named) from upgrade_url, have it
    checked exactly as a package sent on the dashboard is, put it in, and
    follow it here until it has ended - the daemon restarts on the way, so
    a few questions going unanswered is expected, not a failure."""
    out = _upgrade_ask(pal, {'action': 'online_look'}, timeout=90.0)
    if out is None:
        return 2
    row = (out.get('web') or {}).get('online') or {}
    if row.get('error'):
        print(pal.crit('%s: %s' % (row.get('url'), row['error'])))
        return 1
    want = str(args.upgrade_online or 'newest')
    pk = row.get('newest') if want == 'newest' else next(
        (x for x in row.get('packages') or [] if x.get('version') == want), None)
    if not pk:
        print(pal.crit('%s is not at %s' % ('no zigmon package' if want == 'newest' else want, row.get('url'))))
        return 1
    if _online_ver(pk['version']) <= _online_ver(__version__):
        print(pal.ok('nothing newer than %s at %s' % (__version__, row.get('url'))))
        return 0
    print(pal.title('zigmon %s -> %s' % (__version__, pk['version'])) + pal.dim('  from %s' % pk['url']))
    print('  a backup of the whole installation first; then it is put in and zigmon restarts -')
    print('  the house stops following its sensors for a minute or so. If the new version does')
    print('  not answer, the old one is put back by itself.')
    if not args.yes:
        try:
            ok = input('  go on? (y/N) ').strip().lower() in ('y', 'yes')
        except (EOFError, KeyboardInterrupt):
            ok = False
        if not ok:
            print('  nothing done')
            return 1
    print(pal.dim('  fetching it and checking its signature...'))
    out = _upgrade_ask(pal, {'action': 'online_get', 'version': pk['version'], 'start': True}, timeout=600.0)
    if out is None:
        return 1
    print(pal.ok('  ' + str(out.get('message') or 'asked')))
    said, misses, ends = None, 0, time.time() + 1800
    while time.time() < ends:
        time.sleep(3)
        code, st = api_call('/api/upgrade', timeout=10.0)
        if code != 200 or not isinstance(st, dict):
            misses += 1
            if misses == 1:
                print(pal.dim('  zigmon is restarting - asking again...'))
            continue
        now = st.get('status') or {}
        line = '%s %s' % (now.get('state'), now.get('step') or '')
        if line != said:
            said = line
            print('  ' + (now.get('step') or now.get('state') or '?'))
        if now.get('state') == 'done':
            print(pal.ok('  zigmon %s is in and answers' % (st.get('version') or pk['version'])))
            return 0
        if now.get('state') == 'failed':
            print(pal.crit('  %s%s' % (now.get('said') or 'it failed',
                                       ' - the old version was put back' if now.get('rolled_back') else '')))
            return 1
    print(pal.warn('  still going after half an hour: zigmon --root-status says where it is'))
    return 1


def _follow_upgrade(pal, version, what='put in'):
    """An upgrade or a going back asked of root, followed here until it ends -
    zigmon restarts on the way, so questions unanswered for a while are
    expected, not a failure."""
    said, misses, ends = None, 0, time.time() + 1800
    while time.time() < ends:
        time.sleep(3)
        code, st = api_call('/api/upgrade', timeout=10.0)
        if code != 200 or not isinstance(st, dict):
            misses += 1
            if misses == 1:
                print(pal.dim('  zigmon is restarting - asking again...'))
            continue
        now = st.get('status') or {}
        line = '%s %s' % (now.get('state'), now.get('step') or '')
        if line != said:
            said = line
            print('  ' + (now.get('step') or now.get('state') or '?'))
        if now.get('state') == 'done':
            print(pal.ok('  zigmon %s is %s and answers' % (st.get('version') or version, what)))
            return 0
        if now.get('state') == 'failed':
            print(pal.crit('  %s%s' % (now.get('said') or 'it failed',
                                       ' - the version before was put back' if now.get('rolled_back') else '')))
            return 1
    print(pal.warn('  still going after half an hour: zigmon --root-status says where it is'))
    return 1


def cmd_downgrade_check(args, pal):
    """Which older versions this machine may go back to, and why not the
    others: the versions at upgrade_url, judged by the same table root uses."""
    out = _upgrade_ask(pal, {'action': 'online_look'}, timeout=90.0)
    if out is None:
        return 2
    back = out.get('back') or {}
    row = (out.get('web') or {}).get('online') or {}
    if args.json:
        print(json.dumps({'back': back, 'older': row.get('older_list') or []}, indent=2, default=str))
        return 0
    print(pal.title('going back from zigmon %s' % __version__))
    print('  the highest version this database has seen: %s' % (back.get('high') or __version__))
    print('  as far back as it goes: %s' % (('zigmon %s' % back['floor']) if back.get('floor') else 'any version'))
    if back.get('busy'):
        print(pal.warn('  not now: %s' % back['busy']))
    older = row.get('older_list') or []
    if not back.get('on'):
        print(pal.warn('  going back is switched off (downgrade_show): Control - Upgrades, or as root'))
        print(pal.warn('  give the package file: sudo zigmon --downgrade /path/zigmon-X.Y.Z.tar.gz'))
        return 0
    if row.get('error'):
        print(pal.crit('  %s: %s' % (row.get('url'), row['error'])))
    elif not older:
        print(pal.dim('  no older version at %s' % row.get('url')))
    for x in older:
        print('  zigmon %-10s %s' % (x['version'], pal.ok('safe: zigmon --downgrade %s' % x['version'])
                                    if x.get('ok') else pal.dim(x.get('why') or 'not safe')))
    print(pal.dim('  a package of your own: sudo zigmon --downgrade /path/zigmon-X.Y.Z.tar.gz'))
    return 0


def cmd_downgrade(args, pal):
    """Go back to an older version: VERSION from upgrade_url through the daemon,
    or a package FILE straight through root's helper. Either way the database
    is left as it is, and only where that is safe."""
    want = str(args.downgrade or '').strip()
    if os.path.isfile(want):
        if os.geteuid() != 0:
            print(pal.crit('going back from a file is root\'s: sudo zigmon --downgrade %s' % want))
            return 2
        helper = Daemon.helper_file('zigmon_upgrade.py')
        got = subprocess.run([sys.executable, '-I', str(helper), '--inspect', os.path.abspath(want)],
                             capture_output=True, text=True, timeout=120)
        try:
            info = json.loads(got.stdout or '{}')
        except ValueError:
            info = {'ok': False, 'said': (got.stderr or 'the check did not answer')[-300:]}
        if not info.get('ok'):
            print(pal.crit('refused: %s' % info.get('said')))
            return 1
        back = info.get('back') or {}
        if not info.get('older') or not back.get('ok'):
            print(pal.crit('not going back to %s: %s' % (info.get('version'), back.get(
                'why') or 'it is not older than %s' % info.get('installed'))))
            return 1
        version = info['version']
    else:
        if not re.match(r'^\d+\.\d+\.\d+$', want):
            print(pal.crit('which version? zigmon --downgrade X.Y.Z, or a package file'))
            return 2
        out = _upgrade_ask(pal, {'action': 'online_look'}, timeout=90.0)
        if out is None:
            return 2
        row = (out.get('web') or {}).get('online') or {}
        pk = next((x for x in row.get('older_list') or [] if x.get('version') == want), None)
        if not pk:
            print(pal.crit('zigmon %s is not an older version at %s' % (want, row.get('url'))))
            return 1
        if not pk.get('ok'):
            print(pal.crit('not going back to %s: %s' % (want, pk.get('why'))))
            return 1
        version = want
    print(pal.title('zigmon %s -> %s (going back)' % (__version__, version)))
    print('  the older program is put in and zigmon restarts with it; the database is left as')
    print('  it is - no backup of it is made and none is put back. If %s does not answer, this' % version)
    print('  version is put back by itself.')
    if not args.yes:
        try:
            ok = input('  go on? (y/N) ').strip().lower() in ('y', 'yes')
        except (EOFError, KeyboardInterrupt):
            ok = False
        if not ok:
            print('  nothing done')
            return 1
    if os.path.isfile(want):
        helper = Daemon.helper_file('zigmon_upgrade.py')
        return subprocess.call([sys.executable, '-I', str(helper), '--run', os.path.abspath(want),
                                '--downgrade'])
    print(pal.dim('  fetching it and checking its signature...'))
    out = _upgrade_ask(pal, {'action': 'online_get', 'version': version, 'back': True, 'start': True},
                       timeout=600.0)
    if out is None:
        return 1
    print(pal.ok('  ' + str(out.get('message') or 'asked')))
    return _follow_upgrade(pal, version, 'back')


# ======================================================================
# Backups to other machines (5.21)
# ======================================================================
# A backup kept only on this machine goes with this machine: the disk that
# dies takes the database and its copies with it. So the backup of the whole
# installation root already makes - the database, the configuration, nginx,
# the certificate and its key, the broker, the firewall, the units - is also
# sent somewhere else, on a schedule or by hand: an FTP or FTPS server, SFTP
# or SCP (OpenSSH), or an SMB share (smbclient).
#
# The order of one run, each step waiting for the one before:
#
#   1. root makes a backup of the whole installation (full_make);
#   2. root hands over a copy of it locked with the password of the backups
#      (full_get with a passphrase: openssl enc -aes-256-cbc -pbkdf2 -iter
#      600000 - opened by zigmon_root.py, or by openssl alone on any machine);
#   3. it is sent to every destination switched on, beside a .sha256 and a
#      RESTORE.txt, each written as .NAME.part and renamed when whole, and the
#      size the server then lists is compared with the size sent;
#   4. the old ones there are taken away - only files named the way this
#      machine names them, never the newest, as many and as old as the
#      settings say, with their companions;
#   5. the copy here is deleted, and the run written into the history.
#
# Never sent unlocked: the backup holds the certificate's private key and
# every password of the house, and whoever can read the share could read
# them. Without the password nothing is sent at all.
#
# A folder on this machine is not one of the destinations: the daemon may
# write only into its own ReadWritePaths (ProtectSystem=strict), and a mount
# of a NAS is reached as well, and checked better, as SMB or SFTP.
#
# What is secret about a destination - its password, its SSH key and that
# key's passphrase, the key of a client certificate - is kept in the database
# the way every other secret of the house is (the settings, the router's
# key), and never goes back out: the page is told only that one is set, and
# the fingerprints. It is never put on a command line (SSH_ASKPASS reads it
# from the environment, smbclient from a file of mode 0600) and never written
# into the log.
import ftplib                                   # noqa: E402 - only these use them
import shlex                                    # noqa: E402

RB_KINDS = ('ftp', 'ftps', 'sftp', 'scp', 'smb')
RB_KIND_WORDS = {'ftp': 'FTP', 'ftps': 'FTPS', 'sftp': 'SFTP', 'scp': 'SCP (ssh)',
                 'smb': 'SMB (Windows share, Samba)'}
RB_PORTS = {'ftp': 21, 'ftps': 21, 'sftp': 22, 'scp': 22, 'smb': 445}
RB_SECRETS = ('password', 'key', 'client_key', 'key_pass')
RB_MOST_TARGETS = 20
RB_MOST_RUNS = 60
RB_TIMEOUT = 60
RB_MOST_BYTES = 4 * 1024 ** 3                    # what root takes back in (MOST_FULL)
RB_LOCK = threading.Lock()
RB_JOB = {'running': False, 'what': '', 'says': '', 'done': 0, 'whole': 0, 'error': '',
          'began': 0, 'ended': 0, 'result': None, 'by': ''}
# zigmon-full-HOST-2026-10-28-041503.tar.gz.enc, as zigmon_root.py names
# them (full_make), with -2 when two were made in the same second
RB_NAME_RE = re.compile(r'^zigmon-full-(?P<host>[A-Za-z0-9.-]+?)-(?P<stamp>\d{4}-\d{2}-\d{2}-\d{6})'
                        r'(?:-\d{1,3})?\.tar\.gz\.enc\Z')
RB_PEM_CERT = re.compile(r'-----BEGIN CERTIFICATE-----[A-Za-z0-9+/=\s]+?-----END CERTIFICATE-----')
RB_NEED = {'sftp': ('ssh', 'sftp'), 'scp': ('ssh', 'scp'), 'smb': ('smbclient',)}


class RbError(Exception):
    pass


def rb_host():
    """This machine's name as root writes it into the name of a backup."""
    return re.sub(r'[^A-Za-z0-9.-]', '', socket.gethostname())[:60] or 'zigmon'


def rb_password():
    return str(CONFIG.get('rbackup_password') or '')


def rb_clean(text, what, most=200, pattern=None, empty=True):
    t = str(text if text is not None else '').strip()
    if not t and empty:
        return ''
    if not t:
        raise ValueError('%s is needed' % what)
    if len(t) > most or re.search(r'[\x00-\x1f\x7f]', t):
        raise ValueError('%s: at most %d characters, one line' % (what, most))
    if pattern and not re.match(pattern, t):
        raise ValueError('%s: %r is not one' % (what, t[:60]))
    return t


def rb_safe_name(name):
    name = str(name or '')
    if not re.match(r'^[A-Za-z0-9][A-Za-z0-9_.-]{0,200}\Z', name):
        raise RbError('not a file name of a backup: %r' % name[:80])
    return name


def rb_companions(name):
    """The .sha256 and the RESTORE.txt that travel beside a backup."""
    if not RB_NAME_RE.match(str(name or '')):
        return []
    base = name[:-len('.tar.gz.enc')]
    return [name + '.sha256', base + '-RESTORE.txt']


# ---- the destinations, kept in the database ------------------------------------
def rb_targets(d):
    got = d._json_meta('rbackup:targets', [])
    return [t for t in (got if isinstance(got, list) else []) if isinstance(t, dict) and t.get('id')]


def rb_put_targets(d, targets):
    d.store.set_meta('rbackup:targets', json.dumps(targets))


def rb_target(d, tid):
    return next((t for t in rb_targets(d) if t['id'] == str(tid or '')), None)


def rb_scrub(text, *targets):
    """An error in words with every secret it could carry taken out - a tool
    that echoes what it was given, a URL with a password in it."""
    text = str(text or '')
    known = [rb_password()] + [str(t.get(k) or '') for t in targets if isinstance(t, dict)
                               for k in RB_SECRETS]
    for s in sorted(set(x for x in known if len(x) >= 4), key=len, reverse=True):
        text = text.replace(s, '…')
    return text


def rb_hostkey_fps(lines):
    """The SHA256 fingerprints of known_hosts lines, as ssh-keygen -l says
    them - worked out here, so the page shows them without ssh-keygen."""
    out = []
    for line in str(lines or '').splitlines():
        f = line.split()
        if len(f) < 3 or line.startswith('#'):
            continue
        try:
            blob = base64.b64decode(f[2], validate=True)
        except ValueError:
            continue
        out.append('SHA256:%s (%s)' % (base64.b64encode(hashlib.sha256(blob).digest()).decode().rstrip('='),
                                       f[1]))
    return out


def rb_cert_info(pem):
    """Whom a certificate names, until when, and its SHA-256."""
    if not pem or not shutil.which('openssl'):
        return None
    got = subprocess.run(['openssl', 'x509', '-noout', '-subject', '-enddate', '-fingerprint', '-sha256'],
                         input=pem, capture_output=True, text=True, timeout=20)
    if got.returncode != 0:
        return None
    info = {}
    for line in got.stdout.splitlines():
        k, _, v = line.partition('=')
        if k.startswith('subject'):
            info['subject'] = v.strip()
        elif k == 'notAfter':
            try:
                info['not_after'] = calendar.timegm(time.strptime(v.strip(), '%b %d %H:%M:%S %Y %Z'))
            except ValueError:
                info['not_after'] = 0
        elif 'Fingerprint' in k:
            info['sha256'] = v.strip().replace(':', '').lower()
    return info


def rb_view(t):
    """A destination as the page sees it: nothing secret, what it has said."""
    out = {k: v for k, v in t.items() if k not in RB_SECRETS}
    for k in RB_SECRETS:
        out['has_' + k] = bool(t.get(k))
    out['kind_words'] = RB_KIND_WORDS.get(t.get('kind'), t.get('kind'))
    if t.get('hostkey'):
        out['hostkey_fp'] = rb_hostkey_fps(t['hostkey'])
        out.pop('hostkey')
        out['hostkey'] = True
    for k in ('client_cert', 'ca'):
        if t.get(k):
            try:
                out[k + '_info'] = rb_cert_info(t[k])
            except (OSError, subprocess.SubprocessError):
                out[k + '_info'] = None
    return out


def rb_checked(data, old=None):
    """A destination as typed on the page, checked. A secret left out or
    left empty keeps the one there is.

    Nothing a tool on the way would read as more than a value gets through:
    smbclient takes ; as the next command whatever the quotes, the sftp batch
    a " as the end of a name, ssh a leading - as an option of its own, an FTP
    server a line break as the next command, and .. is a way out of the
    folder."""
    old = dict(old or {})
    if not isinstance(data, dict):
        raise ValueError('a destination is an object')
    kind = str(data.get('kind') or old.get('kind') or '')
    if kind not in RB_KINDS:
        raise ValueError('the kind is one of %s' % ', '.join(RB_KINDS))
    t = {'id': old.get('id') or secrets.token_hex(6), 'kind': kind}
    t['host'] = rb_clean(data.get('host'), 'the server', 253, r'^[A-Za-z0-9][A-Za-z0-9.:_-]*\Z', empty=False)
    t['name'] = rb_clean(data.get('name'), 'the name', 60) or ('%s %s' % (RB_KIND_WORDS[kind], t['host']))
    t['enabled'] = 1 if data.get('enabled', old.get('enabled', 1)) not in (0, '0', False, None) else 0
    t['path'] = rb_clean(data.get('path'), 'the folder', 400)
    try:
        port = int(data.get('port') or 0) or (990 if kind == 'ftps' and data.get('implicit') not in
                                              (None, 0, '0', False) else RB_PORTS[kind])
    except (TypeError, ValueError):
        raise ValueError('the port is a number')
    if not 1 <= port <= 65535:
        raise ValueError('the port is 1 to 65535')
    t['port'] = port
    t['user'] = rb_clean(data.get('user'), 'the account', 128, r'^[^\s:@/\\;"\'`$]+\Z')
    if t['user'].startswith('-'):
        raise ValueError('the account does not begin with -')
    if re.search(r'[;"\x00-\x1f]', t['path']) or t['path'].startswith('-'):
        raise ValueError('the folder has no ; or " in it, and does not begin with -')
    if re.search(r'(^|[\\/])\.\.([\\/]|$)', t['path']):
        raise ValueError('the folder has no .. in it')
    if kind == 'scp' and not re.match(r'^[A-Za-z0-9._/~+-]*\Z', t['path']):
        # scp hands the far end's path to a shell there: letters, digits and
        # . _ / ~ + - only, and nothing it would split or expand
        raise ValueError('for SCP the folder is letters, digits and . _ / ~ + - only')
    pw = data.get('password')
    if data.get('password_clear'):
        t['password'] = ''
    elif pw is None or pw == '':
        t['password'] = old.get('password') or ''
    else:
        pw = str(pw)
        if len(pw) > 512 or re.search(r'[\r\n\x00]', pw):
            raise ValueError('the password is one line, at most 512 characters')
        t['password'] = pw
    if kind in ('sftp', 'scp'):
        for k in ('key', 'pub', 'ssh_cert', 'hostkey', 'key_pass'):
            if old.get(k):
                t[k] = old[k]
        if data.get('ssh_cert') is not None:
            c = str(data.get('ssh_cert') or '').strip()
            if c and not re.match(r'^[a-z0-9@.-]+-cert-v01@openssh\.com AAAA[A-Za-z0-9+/=]+( [^\r\n]*)?\Z', c):
                raise ValueError('the SSH certificate is the one line of a ...-cert.pub file')
            t['ssh_cert'] = c
    if kind in ('ftp', 'ftps'):
        t['passive'] = 0 if data.get('passive', old.get('passive', 1)) in (0, '0', False) else 1
    if kind == 'ftps':
        t['implicit'] = 1 if data.get('implicit', old.get('implicit')) not in (None, 0, '0', False) else 0
        check = str(data.get('tls_check') or old.get('tls_check') or 'system')
        if check not in ('system', 'ca', 'pin', 'none'):
            raise ValueError('the server certificate is checked against system, ca, pin or none')
        t['tls_check'] = check
        for k in ('ca', 'pin', 'client_cert', 'client_key'):
            if old.get(k):
                t[k] = old[k]
        if data.get('ca') is not None:
            ca = str(data.get('ca') or '').strip()
            if ca and not RB_PEM_CERT.search(ca):
                raise ValueError('the authority is a PEM certificate (-----BEGIN CERTIFICATE-----)')
            t['ca'] = '\n'.join(m.group(0) for m in RB_PEM_CERT.finditer(ca)) + '\n' if ca else ''
        if data.get('pin') is not None:
            pin = re.sub(r'[^0-9A-Fa-f]', '', str(data.get('pin') or '')).lower()
            if pin and len(pin) != 64:
                raise ValueError('the pinned fingerprint is SHA-256: 64 hex digits')
            t['pin'] = pin
        if check == 'ca' and not t.get('ca'):
            raise ValueError('checked against an authority: give its certificate')
        if check == 'pin' and not t.get('pin'):
            raise ValueError('pinned: the fingerprint is needed - Try it shows the server\'s')
    if kind == 'smb':
        t['share'] = rb_clean(data.get('share'), 'the share', 80, r'^[^\\/:*?"<>|;\-][^\\/:*?"<>|;]*\Z',
                              empty=False)
        t['domain'] = rb_clean(data.get('domain'), 'the domain', 64, r'^[A-Za-z0-9._-]+\Z')
        t['smb_encrypt'] = 1 if data.get('smb_encrypt', old.get('smb_encrypt', 1)) not in (0, '0', False) else 0
    for k in ('last', 'tried', 'made'):
        if k in old:
            t[k] = old[k]
    return t


def rb_save(d, data, by):
    with RB_LOCK:
        targets = rb_targets(d)
        old = next((x for x in targets if x['id'] == str(data.get('id') or '')), None)
        if data.get('id') and not old:
            raise ValueError('no such destination')
        t = rb_checked(data, old)
        if old:
            targets = [t if x['id'] == t['id'] else x for x in targets]
        else:
            if len(targets) >= RB_MOST_TARGETS:
                raise ValueError('%d destinations at most' % RB_MOST_TARGETS)
            t['made'] = time.time()
            targets.append(t)
        rb_put_targets(d, targets)
    d.store.add_event('control', '%s the backup destination %s (%s)%s' % (
        'changed' if old else 'added', t['name'], RB_KIND_WORDS[t['kind']], (' by ' + by) if by else ''))
    return t


def rb_set_fields(d, tid, by, said, **fields):
    with RB_LOCK:
        targets = rb_targets(d)
        t = next((x for x in targets if x['id'] == str(tid or '')), None)
        if not t:
            raise ValueError('no such destination - save it first')
        for k, v in fields.items():
            if v is None:
                t.pop(k, None)
            else:
                t[k] = v
        rb_put_targets(d, targets)
    if said:
        d.store.add_event('control', 'the backup destination %s: %s%s' % (t['name'], said,
                                                                          (' (by %s)' % by) if by else ''))
    return t


def rb_delete(d, tid, by):
    with RB_LOCK:
        targets = rb_targets(d)
        t = next((x for x in targets if x['id'] == str(tid or '')), None)
        if not t:
            raise ValueError('no such destination')
        rb_put_targets(d, [x for x in targets if x['id'] != t['id']])
    d.store.add_event('control', 'the backup destination %s taken away%s' % (
        t['name'], (' by ' + by) if by else ''), 'warn')


# ---- keys and certificates ----------------------------------------------------------
def rb_askpass(folder, env):
    """A program that says the secret in $ZIGMON_RB_SECRET, for SSH_ASKPASS:
    the secret never on a command line, never in a file."""
    ask = os.path.join(folder, 'ask')
    fd = os.open(ask, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o700)
    with os.fdopen(fd, 'w') as f:
        f.write('#!/bin/sh\nprintf "%s\\n" "$ZIGMON_RB_SECRET"\n')
    env.update(SSH_ASKPASS=ask, SSH_ASKPASS_REQUIRE='force', DISPLAY=':0')
    return ask


def rb_ssh_keygen(comment):
    if not shutil.which('ssh-keygen'):
        raise ValueError('ssh-keygen is not on this machine (dnf install openssh-clients)')
    with tempfile.TemporaryDirectory(prefix='zigmon-key-') as tmp:
        path = os.path.join(tmp, 'k')
        got = subprocess.run(['ssh-keygen', '-q', '-t', 'ed25519', '-N', '', '-C', comment, '-f', path],
                             capture_output=True, text=True, timeout=30, stdin=subprocess.DEVNULL)
        if got.returncode != 0:
            raise ValueError('ssh-keygen: %s' % (got.stderr or got.stdout).strip()[:200])
        with open(path) as f:
            private = f.read()
        with open(path + '.pub') as f:
            public = f.read().strip()
    return private, public


def rb_ssh_public_of(private, passphrase=''):
    """The public half of a private key given - and that it is one."""
    if not shutil.which('ssh-keygen'):
        raise ValueError('ssh-keygen is not on this machine (dnf install openssh-clients)')
    private = str(private or '').replace('\r\n', '\n').strip() + '\n'
    if 'PRIVATE KEY-----' not in private or len(private) > 16384:
        raise ValueError('that is not a private key (-----BEGIN OPENSSH PRIVATE KEY----- or another '
                         'PEM private key)')
    with tempfile.TemporaryDirectory(prefix='zigmon-key-') as tmp:
        path = os.path.join(tmp, 'k')
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(fd, 'w') as f:
            f.write(private)
        env = dict(os.environ)
        if passphrase:
            rb_askpass(tmp, env)
            env['ZIGMON_RB_SECRET'] = passphrase
            argv = ['ssh-keygen', '-y', '-f', path]
        else:
            argv = ['ssh-keygen', '-y', '-P', '', '-f', path]
        got = subprocess.run(argv, capture_output=True, text=True, timeout=20, env=env,
                             stdin=subprocess.DEVNULL, start_new_session=True)
    if got.returncode != 0:
        said = rb_scrub((got.stderr or got.stdout).strip())
        if 'passphrase' in said.lower() or 'incorrect' in said.lower():
            raise ValueError('the key is locked with a passphrase: give it too')
        raise ValueError('ssh-keygen does not read it: %s' % said[:200])
    return private, got.stdout.strip()


def rb_openssl(args, data=b'', env=None, what='openssl'):
    got = subprocess.run(['openssl'] + args, input=data, capture_output=True, timeout=60,
                         env=dict(os.environ, **(env or {})))
    if got.returncode != 0:
        raise ValueError('%s: %s' % (what, got.stderr.decode('utf-8', 'replace').strip()[-200:]))
    return got.stdout


def rb_client_cert_make(cn, days=1825):
    """A key and a self-signed client certificate for FTPS (EC P-256)."""
    cn = re.sub(r'[^A-Za-z0-9.@_-]', '', str(cn or 'zigmon-backup'))[:64] or 'zigmon-backup'
    with tempfile.TemporaryDirectory(prefix='zigmon-crt-') as tmp:
        kf, cf = os.path.join(tmp, 'k.pem'), os.path.join(tmp, 'c.pem')
        rb_openssl(['req', '-x509', '-newkey', 'ec', '-pkeyopt', 'ec_paramgen_curve:P-256', '-nodes',
                    '-keyout', kf, '-out', cf, '-days', str(int(days)), '-subj', '/CN=' + cn,
                    '-addext', 'extendedKeyUsage=clientAuth'], what='the certificate')
        with open(kf) as f:
            key = f.read()
        with open(cf) as f:
            crt = f.read()
    return key, crt


def rb_client_cert_given(text, password=''):
    """A client certificate brought: PEM (certificate and key, in any order)
    or PFX (base64 of it, with its password)."""
    text = str(text or '').strip()
    if 'BEGIN' in text:
        certs = [m.group(0) for m in RB_PEM_CERT.finditer(text)]
        m = re.search(r'-----BEGIN (?:[A-Z ]*)PRIVATE KEY-----[\s\S]+?-----END (?:[A-Z ]*)PRIVATE KEY-----', text)
        if not certs or not m:
            raise ValueError('a client certificate needs its certificate and its private key')
        key = m.group(0) + '\n'
        if 'ENCRYPTED' in key:
            key = rb_openssl(['pkey', '-passin', 'env:ZIGMON_RB_SECRET'], key.encode(),
                             env={'ZIGMON_RB_SECRET': password}, what='the key (its password?)').decode()
        pub_key = rb_openssl(['pkey', '-pubout'], key.encode(), what='the key')
        pub_crt = rb_openssl(['x509', '-pubkey', '-noout'], certs[0].encode(), what='the certificate')
        if pub_key.strip() != pub_crt.strip():
            raise ValueError('the key is not the one of this certificate')
        return key, '\n'.join(certs) + '\n'
    try:
        pfx = base64.b64decode(text, validate=False)
    except ValueError:
        raise ValueError('neither PEM nor PFX')
    if not pfx:
        raise ValueError('neither PEM nor PFX')
    with tempfile.TemporaryDirectory(prefix='zigmon-pfx-') as tmp:
        pf = os.path.join(tmp, 'c.pfx')
        with open(pf, 'wb') as f:
            f.write(pfx)
        both = ''
        for extra in ([], ['-legacy']):
            try:
                both = rb_openssl(['pkcs12', '-in', pf, '-nodes', '-passin', 'env:ZIGMON_RB_SECRET'] + extra,
                                  env={'ZIGMON_RB_SECRET': password}, what='the PFX (its password?)').decode()
                break
            except ValueError:
                if extra:
                    raise
    return rb_client_cert_given(both)


# ---- the transports: open, put, get, list, delete, close -----------------------------
class _RbImplicitFtpTls(ftplib.FTP_TLS):
    """FTPS on its own port (990): TLS from the first byte."""
    def connect(self, host='', port=0, timeout=-999, source_address=None):
        if host:
            self.host = host
        if port > 0:
            self.port = port
        if timeout != -999:
            self.timeout = timeout
        self.sock = socket.create_connection((self.host, self.port), self.timeout)
        self.af = self.sock.family
        self.sock = self.context.wrap_socket(self.sock, server_hostname=self.host)
        self.file = self.sock.makefile('r', encoding=self.encoding)
        self.welcome = self.getresp()
        return self.welcome


class _RbReuseMixin(object):
    """The data connection resumes the control connection's TLS session:
    vsftpd, ProFTPD and FileZilla Server refuse one that does not (522)."""
    def ntransfercmd(self, cmd, rest=None):
        conn, size = ftplib.FTP.ntransfercmd(self, cmd, rest)
        if self._prot_p:
            conn = self.context.wrap_socket(conn, server_hostname=self.host, session=self.sock.session)
        return conn, size


class RbFtpTls(_RbReuseMixin, ftplib.FTP_TLS):
    pass


class RbFtpTlsImplicit(_RbReuseMixin, _RbImplicitFtpTls):
    pass


class RbFtp(object):
    """FTP, and FTPS explicit (AUTH TLS) or implicit, with the server's
    certificate checked against the system's authorities, one of the house's
    own, or pinned by its SHA-256."""
    def __init__(self, t):
        self.t = t
        self.ftp = None
        self.tmp = None
        self.seen = {}

    def _context(self):
        t = self.t
        check = t.get('tls_check') or 'system'
        if check == 'ca':
            ctx = ssl.create_default_context(cadata=t.get('ca') or '')
        elif check == 'system':
            ctx = ssl.create_default_context()
        else:
            # pinned: the fingerprint is compared below, whatever signed it
            ctx = ssl.create_default_context()
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
        if t.get('client_cert') and t.get('client_key'):
            self.tmp = tempfile.mkdtemp(prefix='zigmon-ftps-')
            cf, kf = os.path.join(self.tmp, 'c.pem'), os.path.join(self.tmp, 'k.pem')
            with open(cf, 'w') as f:
                f.write(t['client_cert'])
            fd = os.open(kf, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(fd, 'w') as f:
                f.write(t['client_key'])
            ctx.load_cert_chain(cf, kf)
        return ctx

    def open(self):
        t = self.t
        try:
            if t['kind'] == 'ftps':
                cls = RbFtpTlsImplicit if t.get('implicit') else RbFtpTls
                self.ftp = cls(context=self._context(), timeout=RB_TIMEOUT)
                self.ftp.connect(t['host'], int(t['port']))
                if not t.get('implicit'):
                    self.ftp.auth()
                der = self.ftp.sock.getpeercert(True)
                fp = hashlib.sha256(der).hexdigest() if der else ''
                self.seen = {'fingerprint': fp}
                try:
                    self.seen['cert'] = rb_cert_info(ssl.DER_cert_to_PEM_cert(der))
                except (ValueError, OSError, subprocess.SubprocessError):
                    pass
                if t.get('tls_check') == 'pin' and fp != (t.get('pin') or ''):
                    raise RbError('the server answers with another certificate than the one pinned '
                                  '(SHA-256 %s)' % fp)
            else:
                self.ftp = ftplib.FTP(timeout=RB_TIMEOUT)
                self.ftp.connect(t['host'], int(t['port']))
            self.ftp.login(t.get('user') or 'anonymous', t.get('password') or '')
            if t['kind'] == 'ftps':
                self.ftp.prot_p()
            self.ftp.set_pasv(bool(t.get('passive', 1)))
            self._cd(t.get('path') or '')
        except ssl.SSLCertVerificationError as e:
            raise RbError('the server\'s certificate is not trusted: %s - check it against its '
                          'authority, or pin it' % e.verify_message)
        except ftplib.error_perm as e:
            raise RbError('the FTP server said: %s' % str(e)[:200])
        except (OSError, EOFError, ftplib.Error) as e:
            raise RbError(str(e)[:200] or e.__class__.__name__)

    def _cd(self, path):
        if not path:
            return
        if path.startswith('/'):
            self.ftp.cwd('/')
        for part in [p for p in path.split('/') if p and p != '.']:
            try:
                self.ftp.cwd(part)
            except ftplib.error_perm:
                self.ftp.mkd(part)
                self.ftp.cwd(part)

    def put(self, local, name):
        name = rb_safe_name(name)
        with open(local, 'rb') as f:
            self.ftp.storbinary('STOR .%s.part' % name, f, blocksize=262144)
        try:
            self.ftp.delete(name)
        except ftplib.error_perm:
            pass
        self.ftp.rename('.%s.part' % name, name)

    def get(self, name, local):
        with open(local, 'wb') as f:
            self.ftp.retrbinary('RETR %s' % rb_safe_name(name), f.write, blocksize=262144)

    def list(self):
        out = []
        try:
            for name, facts in self.ftp.mlsd(facts=['type', 'size', 'modify']):
                if facts.get('type') == 'file':
                    m = facts.get('modify') or ''
                    try:
                        mt = calendar.timegm(time.strptime(m[:14], '%Y%m%d%H%M%S'))
                    except ValueError:
                        mt = 0
                    out.append({'name': name, 'size': int(facts.get('size') or 0), 'mtime': mt})
            return out
        except ftplib.error_perm:
            pass
        for name in self.ftp.nlst():
            name = name.rsplit('/', 1)[-1]
            if name in ('.', '..'):
                continue
            try:
                size = self.ftp.size(name) or 0
            except ftplib.error_perm:
                continue                                # a folder
            out.append({'name': name, 'size': size, 'mtime': 0})
        return out

    def delete(self, name):
        self.ftp.delete(rb_safe_name(name))

    def close(self):
        try:
            if self.ftp:
                self.ftp.quit()
        except Exception:                               # noqa: BLE001 - it is going anyway
            try:
                self.ftp.close()
            except Exception:                           # noqa: BLE001
                pass
        if self.tmp:
            shutil.rmtree(self.tmp, ignore_errors=True)


def rb_ssh_keyscan(host, port):
    """The server's host keys, as known_hosts lines, and their fingerprints."""
    if not shutil.which('ssh-keyscan'):
        raise ValueError('ssh-keyscan is not on this machine (dnf install openssh-clients)')
    host = rb_clean(host, 'the server', 253, r'^[A-Za-z0-9][A-Za-z0-9.:_-]*\Z', empty=False)
    got = subprocess.run(['ssh-keyscan', '-T', '10', '-p', str(int(port)), host],
                         capture_output=True, text=True, timeout=30, stdin=subprocess.DEVNULL)
    lines = [x for x in got.stdout.splitlines() if x.strip() and not x.startswith('#')]
    if not lines:
        tail = (got.stderr or '').strip().splitlines()[-1:]
        raise ValueError('%s:%s did not show a host key: %s' % (host, port, tail[0] if tail else 'no answer'))
    text = '\n'.join(sorted(lines)) + '\n'
    return text, rb_hostkey_fps(text)


class RbSsh(object):
    """SFTP (the sftp program) or SCP (scp, and ssh for the list and the
    deleting) - OpenSSH itself: the server's host key checked against the one
    trusted on the page and no other (StrictHostKeyChecking, a known_hosts of
    its own, no ~/.ssh/config), a key made here or brought, or a password."""
    def __init__(self, t):
        self.t = t
        self.d = None
        self.env = {}

    def open(self):
        t = self.t
        for tool in RB_NEED[t['kind']]:
            if not shutil.which(tool):
                raise RbError('%s is not on this machine (dnf install openssh-clients)' % tool)
        if not t.get('hostkey'):
            raise RbError('the server\'s host key is not trusted yet: Try reaching it, then trust the '
                          'fingerprint it shows')
        self.d = tempfile.mkdtemp(prefix='zigmon-ssh-', dir=rb_work_root())
        kh = os.path.join(self.d, 'known_hosts')
        with open(kh, 'w') as f:
            f.write(t['hostkey'])
        self.opts = ['-F', '/dev/null', '-o', 'StrictHostKeyChecking=yes', '-o', 'UserKnownHostsFile=' + kh,
                     '-o', 'GlobalKnownHostsFile=/dev/null', '-o', 'ConnectTimeout=20',
                     '-o', 'ServerAliveInterval=15', '-o', 'ServerAliveCountMax=4',
                     '-o', 'LogLevel=ERROR', '-o', 'IdentitiesOnly=yes']
        key = t.get('key') or ''
        if key:
            kf = os.path.join(self.d, 'id')
            fd = os.open(kf, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(fd, 'w') as f:
                f.write(key if key.endswith('\n') else key + '\n')
            self.opts += ['-i', kf]
            if t.get('ssh_cert'):
                cf = os.path.join(self.d, 'id-cert.pub')
                with open(cf, 'w') as f:
                    f.write(t['ssh_cert'] + '\n')
                self.opts += ['-o', 'CertificateFile=' + cf]
        else:
            self.opts += ['-o', 'IdentityFile=/dev/null']
        # A password (or the key's passphrase) through SSH_ASKPASS, from the
        # environment of this one program: never a command line, never a file.
        self.env = dict(os.environ)
        rb_askpass(self.d, self.env)
        self.env['ZIGMON_RB_SECRET'] = t.get('password') or t.get('key_pass') or ''
        auths = ['publickey'] if key else []
        if t.get('password'):
            auths += ['password', 'keyboard-interactive']
        if not auths:
            raise RbError('neither a key nor a password is set')
        self.opts += ['-o', 'PreferredAuthentications=' + ','.join(auths), '-o', 'NumberOfPasswordPrompts=1']
        if t.get('password') or t.get('key_pass'):
            # sftp -b asks ssh for batch mode, which takes no password; the
            # first value given wins, and this comes first
            self.opts += ['-o', 'BatchMode=no']
        self.dest = '%s@%s' % (t.get('user') or 'root', t['host'])
        self.dir = (t.get('path') or '').rstrip('/') or '.'
        # signed in and the folder made, at once - the errors said here
        if t['kind'] == 'sftp':
            cmds, acc = [], '/' if self.dir.startswith('/') else ''
            for p in [p for p in self.dir.split('/') if p and p != '.']:
                acc = (acc + '/' + p) if acc not in ('', '/') else (acc + p)
                cmds.append('-mkdir "%s"' % acc)
            cmds.append('cd "%s"' % self.dir)
            self._sftp(cmds)
        else:
            q = shlex.quote(self.dir)
            self._ssh('mkdir -p -- %s && test -w %s' % (q, q))

    def _run(self, args, what, timeout=3600):
        got = subprocess.run(args, capture_output=True, text=True, timeout=timeout, env=self.env,
                             stdin=subprocess.DEVNULL, start_new_session=True)
        if got.returncode != 0:
            said = [x for x in (got.stderr or got.stdout or '').strip().splitlines()
                    if x.strip() and not x.startswith('Warning: Permanently')]
            tail = rb_scrub(' / '.join(said[-3:])[:300], self.t) or 'it said nothing (exit %d)' % got.returncode
            if 'Host key verification failed' in tail or 'REMOTE HOST IDENTIFICATION' in tail:
                tail = ('the server shows another host key than the one trusted - if it was reinstalled '
                        'on purpose, Try reaching it and trust the new one')
            elif 'Permission denied' in tail:
                tail = 'the server did not let the account in (%s)' % tail
            raise RbError('%s: %s' % (what, tail))
        return got.stdout

    def _ssh(self, command):
        return self._run(['ssh'] + self.opts + ['-p', str(int(self.t['port'])), self.dest, command], 'ssh')

    def _sftp(self, cmds, timeout=3600):
        batch = os.path.join(self.d, 'batch')
        with open(batch, 'w') as f:
            f.write('\n'.join(cmds) + '\n')
        return self._run(['sftp'] + self.opts + ['-P', str(int(self.t['port'])), '-b', batch, self.dest],
                         'sftp', timeout=timeout)

    @staticmethod
    def _local(path):
        path = str(path)
        if re.search(r'["\r\n]', path):
            raise RbError('a local file name with a " in it')
        return path

    def put(self, local, name):
        name, local = rb_safe_name(name), self._local(local)
        if self.t['kind'] == 'sftp':
            self._sftp(['cd "%s"' % self.dir, 'put "%s" ".%s.part"' % (local, name),
                        '-rm "%s"' % name, 'rename ".%s.part" "%s"' % (name, name)])
        else:
            self._run(['scp'] + self.opts + ['-P', str(int(self.t['port'])), '-q', local,
                                             '%s:%s/.%s.part' % (self.dest, self.dir, name)], 'scp')
            self._ssh('mv -f -- %s %s' % (shlex.quote('%s/.%s.part' % (self.dir, name)),
                                          shlex.quote('%s/%s' % (self.dir, name))))

    def get(self, name, local):
        name, local = rb_safe_name(name), self._local(local)
        if self.t['kind'] == 'sftp':
            self._sftp(['cd "%s"' % self.dir, 'get "%s" "%s"' % (name, local)])
        else:
            self._run(['scp'] + self.opts + ['-P', str(int(self.t['port'])), '-q',
                                             '%s:%s/%s' % (self.dest, self.dir, name), local], 'scp')

    def list(self):
        if self.t['kind'] == 'sftp':
            text = self._sftp(['cd "%s"' % self.dir, 'ls -ln'])
        else:
            text = self._ssh('LC_ALL=C ls -ln -- %s' % shlex.quote(self.dir))
        out = []
        for line in text.splitlines():
            f = line.split(None, 8)
            if len(f) == 9 and f[0].startswith('-'):
                try:
                    out.append({'name': f[8].rsplit('/', 1)[-1], 'size': int(f[4]), 'mtime': 0})
                except ValueError:
                    pass
        return out

    def delete(self, name):
        name = rb_safe_name(name)
        if self.t['kind'] == 'sftp':
            self._sftp(['cd "%s"' % self.dir, 'rm "%s"' % name])
        else:
            self._ssh('rm -f -- %s' % shlex.quote('%s/%s' % (self.dir, name)))

    def close(self):
        if self.d:
            shutil.rmtree(self.d, ignore_errors=True)


class RbSmb(object):
    """SMB through smbclient: an authentication file of its own, mode 0600
    (never the password on a command line), SMB2 at least, SMB3 encryption
    when asked."""
    def __init__(self, t):
        self.t = t
        self.d = None

    def open(self):
        t = self.t
        if not shutil.which('smbclient'):
            raise RbError('smbclient is not on this machine (dnf install samba-client)')
        self.d = tempfile.mkdtemp(prefix='zigmon-smb-', dir=rb_work_root())
        auth = os.path.join(self.d, 'auth')
        fd = os.open(auth, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(fd, 'w') as f:
            f.write('username = %s\npassword = %s\n' % (t.get('user') or 'guest', t.get('password') or ''))
            if t.get('domain'):
                f.write('domain = %s\n' % t['domain'])
        self.args = ['smbclient', '//%s/%s' % (t['host'], t['share']), '-A', auth, '-p', str(int(t['port'])),
                     '--option=client min protocol=SMB2', '-t', str(RB_TIMEOUT)]
        if t.get('smb_encrypt'):
            self.args += ['--client-protection=encrypt']
        self.dir = (t.get('path') or '').replace('/', '\\').strip('\\')
        cmds, acc = [], ''
        for p in [x for x in self.dir.split('\\') if x]:
            acc = (acc + '\\' + p) if acc else p
            cmds.append('mkdir "%s"' % acc)
        self._run(cmds + [self._cd(), 'ls'], ignore=('NT_STATUS_OBJECT_NAME_COLLISION',))

    def _run(self, cmds, ignore=(), timeout=3600):
        got = subprocess.run(self.args + ['-c', '; '.join(cmds)], capture_output=True, text=True,
                             timeout=timeout, cwd=self.d, stdin=subprocess.DEVNULL, start_new_session=True)
        text = (got.stdout or '') + (got.stderr or '')
        bad = [x for x in text.splitlines() if 'NT_STATUS_' in x and not any(i in x for i in ignore)]
        if got.returncode != 0 or bad:
            said = rb_scrub(' / '.join((bad or text.strip().splitlines() or ['no answer'])[-2:])[:300], self.t)
            if 'NT_STATUS_LOGON_FAILURE' in said:
                said = 'the server did not take the account and password (%s)' % said
            elif 'NT_STATUS_BAD_NETWORK_NAME' in said:
                said = 'there is no share %s on %s' % (self.t['share'], self.t['host'])
            elif 'protection' in said.lower() and 'unknown' in said.lower():
                said = ('this smbclient does not know --client-protection: switch "SMB3 encryption '
                        'required" off or install a newer samba-client')
            raise RbError('smbclient: %s' % said)
        return got.stdout or ''

    def _cd(self):
        return 'cd "\\%s"' % self.dir

    def put(self, local, name):
        name = rb_safe_name(name)
        if re.search(r'[";]', str(local)):
            raise RbError('a local file name with a " or ; in it')
        self._run([self._cd(), 'put "%s" ".%s.part"' % (local, name), 'del "%s"' % name,
                   'rename ".%s.part" "%s"' % (name, name)],
                  ignore=('NT_STATUS_NO_SUCH_FILE', 'NT_STATUS_OBJECT_NAME_NOT_FOUND'))

    def get(self, name, local):
        if re.search(r'[";]', str(local)):
            raise RbError('a local file name with a " or ; in it')
        self._run([self._cd(), 'get "%s" "%s"' % (rb_safe_name(name), local)])

    def list(self):
        out = []
        for line in self._run([self._cd(), 'ls']).splitlines():
            m = re.match(r'^\s\s(.+?)\s+([ADHNRS]*)\s+(\d+)\s+(\w{3} \w{3}\s+\d+ [\d:]+ \d{4})\s*$', line)
            if m and 'D' not in m.group(2) and m.group(1) not in ('.', '..'):
                try:
                    mt = time.mktime(time.strptime(re.sub(r'\s+', ' ', m.group(4)), '%a %b %d %H:%M:%S %Y'))
                except ValueError:
                    mt = 0
                out.append({'name': m.group(1), 'size': int(m.group(3)), 'mtime': mt})
        return out

    def delete(self, name):
        self._run([self._cd(), 'del "%s"' % rb_safe_name(name)])

    def close(self):
        if self.d:
            shutil.rmtree(self.d, ignore_errors=True)


# by kind; the checks put a transport of their own in here
RB_TRANSPORTS = {'ftp': RbFtp, 'ftps': RbFtp, 'sftp': RbSsh, 'scp': RbSsh, 'smb': RbSmb}


def rb_transport(t):
    return RB_TRANSPORTS[t['kind']](t)


def rb_said(e, t=None):
    """An error in words, whatever raised it - and nothing secret in them."""
    if isinstance(e, EOFError):
        return 'the server closed the connection'
    if isinstance(e, socket.timeout):
        return 'the server did not answer in time'
    if isinstance(e, subprocess.TimeoutExpired):
        return 'it took too long'
    if isinstance(e, ssl.SSLCertVerificationError):
        return ('the server\'s certificate is not trusted: %s - check it against its authority, or pin it'
                % e.verify_message)
    if isinstance(e, ftplib.Error):
        return rb_scrub('the FTP server said: %s' % str(e)[:300], t)
    return rb_scrub(str(e) or e.__class__.__name__, t)[:400]


def rb_work_root():
    """Where a backup waits while it is sent, and a fetched one while it is
    handed on: beside the database, not in /tmp (which may be memory), and
    for this account alone."""
    p = Path(CONFIG.get('state_dir') or STATE_DIR) / 'rbackup'
    p.mkdir(mode=0o700, exist_ok=True)
    return str(p)


def rb_try(t):
    """Signed in, a small file written, seen in the list, taken away again."""
    out = {'ok': False, 'steps': []}
    began = time.time()
    tr = rb_transport(t)
    try:
        tr.open()
        out['steps'].append('signed in, the folder is there')
        if getattr(tr, 'seen', None):
            out['server_cert'] = tr.seen
        name = 'zigmon-try-%s-%s.txt' % (rb_host(), secrets.token_hex(4))
        fd, local = tempfile.mkstemp(prefix='zigmon-try-', dir=rb_work_root())
        with os.fdopen(fd, 'w') as f:
            f.write('zigmon %s on %s tried this destination at %s - this file is taken away again\n'
                    % (__version__, rb_host(), time.strftime('%Y-%m-%d %H:%M:%S')))
        try:
            tr.put(local, name)
        finally:
            os.unlink(local)
        out['steps'].append('a file written')
        names = [x['name'] for x in tr.list()]
        if name not in names:
            raise RbError('the file written is not in the list the server gives')
        out['steps'].append('it is in the list (%d file(s) there)' % len(names))
        tr.delete(name)
        out['steps'].append('taken away again')
        out['ok'] = True
    except Exception as e:                              # noqa: BLE001 - said, never lost
        out['error'] = rb_said(e, t)
        if getattr(tr, 'seen', None):
            out['server_cert'] = tr.seen
    finally:
        tr.close()
    out['secs'] = round(time.time() - began, 1)
    return out


def rb_retain(tr, keep, days, now=None, host=None):
    """This machine's backups at a destination beyond what is kept, taken
    away with their companions - never the newest, and nothing of anybody
    else's: another house's backups, or a file somebody put there by hand,
    are not this machine's to delete."""
    now = now or time.time()
    host = host or rb_host()
    files = tr.list()
    names = set(x['name'] for x in files)
    ours = []
    for x in files:
        m = RB_NAME_RE.match(x['name'])
        if not m or m.group('host') != host:
            continue
        try:
            when = time.mktime(time.strptime(m.group('stamp'), '%Y-%m-%d-%H%M%S'))
        except ValueError:
            continue
        ours.append((when, x['name']))
    ours.sort(reverse=True)
    gone = []
    for i, (when, name) in enumerate(ours):
        if i == 0:
            continue                                    # the newest, always
        if (keep and i >= keep) or (days and now - when > days * 86400):
            for n in [name] + [c for c in rb_companions(name) if c in names]:
                try:
                    tr.delete(n)
                except Exception:                       # noqa: BLE001 - the next one still goes
                    pass
            gone.append(name)
    return gone


RB_RESTORE_TXT = """A backup of a whole zigmon installation: the database, the configuration,
nginx, the certificate and its private key, the broker with its users, the
firewall, the units and Zigbee2MQTT's backup. Locked with the password of the
backups (Control - Backup - When, how many, and the password), AES-256-CBC,
PBKDF2 with 600000 rounds - without that password nobody can open it.

    NAME

Check it arrived whole:

    sha256sum -c NAME.sha256

Put it back on the dashboard of this machine, or of one freshly installed
from the same version of zigmon or a newer one (./install.sh first):
Control - Backup - Where they go - Backups there - Put this back. The
parts to put back are chosen after it has been looked into.

Or on the command line, as root, with the password in a file only root
can read:

    sudo zigmon --full-inspect NAME --passphrase-file /root/backup-password
    sudo zigmon --full-restore NAME --passphrase-file /root/backup-password

And with openssl alone, on any machine:

    openssl enc -d -aes-256-cbc -pbkdf2 -iter 600000 -in NAME -out PLAIN.tar.gz

MANIFEST.json in it says what each file is and where it goes, with its owner,
mode and SHA-256. Keep this file as carefully as the passwords it holds.
"""


def rb_restore_txt(name='zigmon-full-HOST-STAMP.tar.gz.enc'):
    return RB_RESTORE_TXT.replace('NAME', name).replace('PLAIN', name[:-len('.tar.gz.enc')]
                                                        if name.endswith('.tar.gz.enc') else name)


def rb_root_wait(d, ident, most=None):
    """Until root has done request `ident`, and how it ended."""
    until = time.time() + (most or Daemon.ROOT_ASK_MAX_S)
    while True:
        for name in ('status.json', 'status-full.json'):
            st = d.root_read(name)
            if st.get('id') == ident and st.get('state') in ('done', 'failed'):
                return st
        if time.time() > until:
            raise RbError('root has not finished what it was asked in %d minutes'
                          % ((most or Daemon.ROOT_ASK_MAX_S) // 60))
        time.sleep(1)


def rb_root_free(d, most=900):
    """Until root has finished whatever it was asked before (the nightly
    backup, an upgrade) - one request at a time."""
    until = time.time() + most
    while d.root_busy():
        if time.time() > until:
            raise RbError('root has been busy with something else for %d minutes' % (most // 60))
        time.sleep(2)


def rb_history(d):
    got = d._json_meta('rbackup:runs', [])
    return [x for x in (got if isinstance(got, list) else []) if isinstance(x, dict)]


def rb_history_add(d, run):
    with RB_LOCK:
        d.store.set_meta('rbackup:runs', json.dumps(([run] + rb_history(d))[:RB_MOST_RUNS], default=str))


def rb_history_forget(d, at=None, file=None):
    """One line off the list, or all of it. The backups stay where they went."""
    with RB_LOCK:
        runs = rb_history(d)
        if at is None:
            left = []
        else:
            left = [r for r in runs if not (abs(float(r.get('at') or 0) - float(at)) < 0.001
                                            and str(r.get('file') or '') == str(file or ''))]
        d.store.set_meta('rbackup:runs', json.dumps(left, default=str))
        return len(runs) - len(left)


def rb_make_locked(d, work, progress):
    """Root makes a backup of the whole installation and hands over a copy
    locked with the password of the backups: it is moved into `work` at once,
    so neither the next hand-over nor the hourly tidy takes it from under
    the sending. Its path."""
    pw = rb_password()
    if not root_ok(d):
        raise RbError('root has not been given this to do on this machine yet: run install.sh --upgrade '
                      'once, which installs zigmon-root.path')
    progress(1, 5, 'waiting for root to be free')
    rb_root_free(d)
    progress(1, 5, 'root is making a backup of the whole installation')
    st = rb_root_wait(d, d.full_make('to other machines'))
    if st.get('state') != 'done' or not (st.get('made') or {}).get('file'):
        raise RbError('root did not make the backup: %s' % '; '.join(st.get('said') or ['it said nothing']))
    made = st['made']['file']
    progress(2, 5, 'root is locking it with the password')
    rb_root_free(d, 120)
    st = rb_root_wait(d, d.root_ask('full_get', {'file': made, 'passphrase': pw}, quiet=True))
    if st.get('state') != 'done' or not st.get('out'):
        raise RbError('root did not hand it over: %s' % rb_scrub('; '.join(st.get('said') or ['it said nothing'])))
    src = d.root_dir('out', os.path.basename(st['out']))
    if not RB_NAME_RE.match(src.name):
        raise RbError('root handed over %r, which is not a locked backup' % src.name)
    path = os.path.join(work, src.name)
    try:
        os.replace(str(src), path)
    except OSError:
        shutil.copyfile(str(src), path)
        try:
            src.unlink()
        except OSError:
            pass
    with open(path, 'rb') as f:
        if f.read(8) != b'Salted__':
            raise RbError('the copy root handed over is not locked')
    return path


def root_ok(d):
    return d.root_installed()


def rb_run(d, by, only=None, progress=None):
    """Made once, sent to every destination switched on (or the ones asked
    for): the result of each, kept in the history."""
    progress = progress or (lambda *a: None)
    targets = [t for t in rb_targets(d) if (only and t['id'] in only) or (not only and t.get('enabled'))]
    if not targets:
        raise RbError('no destination is switched on')
    pw = rb_password()
    if not pw or len(pw) < 8:
        raise RbError('the backups have no password (or one shorter than eight characters): set one under '
                      'Control - Backup - When, how many, and the password. Unlocked, a copy would hand the '
                      'certificate\'s key and every password of the house to whoever can read the destination')
    work = tempfile.mkdtemp(prefix='run-', dir=rb_work_root())
    began = time.time()
    run = {'at': began, 'by': by, 'host': rb_host(), 'targets': [], 'ok': False, 'encrypted': True}
    try:
        path = rb_make_locked(d, work, progress)
        name = os.path.basename(path)
        h = hashlib.sha256()
        with open(path, 'rb') as f:
            for chunk in iter(lambda: f.read(1 << 20), b''):
                h.update(chunk)
        size = os.path.getsize(path)
        run.update(file=name, bytes=size, sha256=h.hexdigest())
        sha, txt = [os.path.join(work, c) for c in rb_companions(name)]
        with open(sha, 'w') as f:
            f.write('%s  %s\n' % (h.hexdigest(), name))
        with open(txt, 'w') as f:
            f.write(rb_restore_txt(name))
        keep = int(CONFIG.get('rbackup_keep') or 0)
        days = int(CONFIG.get('rbackup_keep_days') or 0)
        for i, t in enumerate(targets):
            progress(3, 5, 'sending to %s (%d of %d)' % (t['name'], i + 1, len(targets)))
            one = {'id': t['id'], 'name': t['name'], 'kind': t['kind'], 'ok': False}
            t0 = time.time()
            tr = rb_transport(t)
            try:
                tr.open()
                tr.put(path, name)
                tr.put(sha, os.path.basename(sha))
                tr.put(txt, os.path.basename(txt))
                got = {x['name']: x['size'] for x in tr.list()}
                if name not in got:
                    raise RbError('it is not in the list the server gives after sending')
                if int(got[name] or 0) != size:
                    raise RbError('the server holds %s bytes of it, not %s' % (got[name], size))
                one['ok'] = True
                progress(4, 5, 'taking the old ones away at %s' % t['name'])
                try:
                    one['taken_away'] = rb_retain(tr, keep, days)
                except Exception as e:                  # noqa: BLE001 - sent all the same
                    one['retain_error'] = rb_said(e, t)[:200]
            except Exception as e:                      # noqa: BLE001 - the next destination still gets it
                one['error'] = rb_said(e, t)
            finally:
                tr.close()
            one['secs'] = round(time.time() - t0, 1)
            run['targets'].append(one)
            try:
                rb_set_fields(d, t['id'], '', '', last={'at': time.time(), 'ok': one['ok'],
                                                        'error': one.get('error') or '', 'file': name,
                                                        'bytes': size})
            except ValueError:
                pass                                    # taken away meanwhile
        run['ok'] = all(x['ok'] for x in run['targets'])
    except Exception as e:                              # noqa: BLE001 - written down, never lost
        run['error'] = rb_said(e)
    finally:
        shutil.rmtree(work, ignore_errors=True)
    progress(5, 5, 'done')
    run['secs'] = round(time.time() - began, 1)
    rb_history_add(d, run)
    good = [x['name'] for x in run['targets'] if x['ok']]
    bad = ['%s (%s)' % (x['name'], x.get('error')) for x in run['targets'] if not x['ok']]
    words = 'a backup of the whole installation (%s) %s%s%s' % (
        human_size(run.get('bytes') or 0), ('went to ' + ', '.join(good)) if good else 'went nowhere',
        ('; not to ' + '; '.join(bad)) if bad else '', ('; ' + run['error']) if run.get('error') else '')
    d.store.add_event('control', words[:300], 'info' if run['ok'] else 'warn')
    log('backup to other machines: %s' % words[:400], 'info' if run['ok'] else 'warn')
    if not run['ok']:
        # the one thing between a dead disk and losing the lot, quietly not
        # happening: worth a message, once until it works again
        d._rb_failed_told = True
        d.notify('The backup to other machines failed: %s' % (run.get('error') or '; '.join(bad))[:200],
                 'warn', dedup='rbackup-failed', about='backup', title='A backup did not go out')
    elif getattr(d, '_rb_failed_told', False):
        d._rb_failed_told = False
        d.notify('The backup to other machines works again.', 'info', dedup='rbackup-back', about='backup')
    return run


def rb_job_start(d, by, what, work):
    """One job at a time, in a thread of its own; the page follows RB_JOB."""
    with RB_LOCK:
        if RB_JOB['running']:
            raise ValueError('a backup is being made or fetched already - wait for it')
        RB_JOB.update(running=True, what=what, says='starting', done=0, whole=5, error='',
                      began=time.time(), ended=0, result=None, by=by)

    def progress(done, whole, says):
        RB_JOB.update(done=done, whole=whole, says=says)

    def go():
        try:
            got = work(progress)
            RB_JOB['result'] = got
            if isinstance(got, dict) and got.get('error'):
                RB_JOB['error'] = got['error']
        except Exception as e:                          # noqa: BLE001 - said on the page
            RB_JOB['error'] = rb_said(e)
            log('backup to other machines (%s): %s' % (what, RB_JOB['error']), 'warn')
        finally:
            RB_JOB.update(running=False, ended=time.time())
    threading.Thread(target=go, name='rbackup', daemon=True).start()
    return dict(RB_JOB)


def rb_due(now=None):
    """The day the scheduled backup is due for, now - or None."""
    if not int(CONFIG.get('rbackup') or 0):
        return None
    m = re.match(r'^([01]?\d|2[0-3]):([0-5]\d)$', str(CONFIG.get('rbackup_at') or '04:15'))
    hh, mm = (int(m.group(1)), int(m.group(2))) if m else (4, 15)
    now = now or datetime.now()
    if (now.hour, now.minute) < (hh, mm):
        return None
    if str(CONFIG.get('rbackup_every') or 'daily') == 'weekly' and \
            now.isoweekday() != int(CONFIG.get('rbackup_day') or 7):
        return None
    return now.strftime('%Y-%m-%d')


def rb_tick(d, now=None):
    """From root_chores, every half minute: the scheduled backup, once a day
    - the day is written into the database before it starts, so a restart
    neither loses it nor makes it twice."""
    day = rb_due(now)
    if not day or RB_JOB['running']:
        return None
    if d.store.get_meta('rbackup:day') == day:
        return None
    d.store.set_meta('rbackup:day', day)
    if not any(t.get('enabled') for t in rb_targets(d)):
        return None
    rb_job_start(d, 'zigmon (on the clock)', 'backup', lambda progress: rb_run(d, 'zigmon (on the clock)',
                                                                             None, progress))
    return day


def rb_next(now=None):
    if not int(CONFIG.get('rbackup') or 0):
        return ''
    m = re.match(r'^([01]?\d|2[0-3]):([0-5]\d)$', str(CONFIG.get('rbackup_at') or '04:15'))
    hh, mm = (int(m.group(1)), int(m.group(2))) if m else (4, 15)
    now = now or datetime.now()
    nxt = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
    if nxt <= now:
        nxt += timedelta(days=1)
    if str(CONFIG.get('rbackup_every')) == 'weekly':
        want = int(CONFIG.get('rbackup_day') or 7)
        while nxt.isoweekday() != want:
            nxt += timedelta(days=1)
    return nxt.isoformat(timespec='minutes')


def rb_fetch(d, tid, name, dst):
    t = rb_target(d, tid)
    if not t:
        raise ValueError('no such destination')
    if not RB_NAME_RE.match(str(name or '')):
        raise ValueError('not a backup of zigmon: %r' % str(name)[:80])
    tr = rb_transport(t)
    try:
        tr.open()
        tr.get(name, dst)
    except RbError:
        raise
    except Exception as e:                              # noqa: BLE001 - in words
        raise RbError(rb_said(e, t))
    finally:
        tr.close()


def rb_remote_list(d, tid):
    t = rb_target(d, tid)
    if not t:
        raise ValueError('no such destination')
    tr = rb_transport(t)
    try:
        tr.open()
        files = tr.list()
    except RbError:
        raise
    except Exception as e:                              # noqa: BLE001
        raise RbError(rb_said(e, t))
    finally:
        tr.close()
    names = set(x['name'] for x in files)
    host = rb_host()
    out = []
    for x in files:
        m = RB_NAME_RE.match(x['name'])
        if not m:
            continue
        try:
            when = time.mktime(time.strptime(m.group('stamp'), '%Y-%m-%d-%H%M%S'))
        except ValueError:
            when = x.get('mtime') or 0
        out.append({'name': x['name'], 'bytes': x['size'], 'when': when, 'host': m.group('host'),
                    'mine': m.group('host') == host, 'sha256': (x['name'] + '.sha256') in names})
    out.sort(key=lambda x: -x['when'])
    return out


def rb_restore_start(d, tid, name, password, by):
    """A backup at a destination fetched into root's in-tray and handed to
    root to take in (full_put) - the same as one sent from the page, so what
    follows is the same too: root looks into it, and the parts to put back are
    chosen on the page."""
    t = rb_target(d, tid)
    name = str(name or '')
    if not t or not RB_NAME_RE.match(name):
        raise ValueError('which backup?')
    password = str(password or '') or rb_password()
    if not password:
        raise ValueError('it is locked: give its password, or set the password of the backups')
    if not root_ok(d):
        raise ValueError('root has not been given this to do on this machine yet: run install.sh --upgrade once')
    if d.root_busy():
        raise ValueError('root is still busy with what was asked a moment ago - try again when that is done')

    def work(progress):
        uid = secrets.token_hex(8)
        d.root_folders()
        part = d.root_dir('in', '.upload-%s.part' % uid)
        final = d.root_dir('in', 'upload-%s.bin' % uid)
        try:
            progress(1, 3, 'fetching %s from %s' % (name, t['name']))
            rb_fetch(d, t['id'], name, str(part))
            if part.stat().st_size > RB_MOST_BYTES:
                raise RbError('bigger than any backup of this house can be')
            os.replace(str(part), str(final))
            progress(2, 3, 'root is looking into it')
            rb_root_free(d, 300)
            ident = d.root_ask('full_put', {'file': final.name, 'passphrase': password[:200]}, quiet=True)
        except BaseException:
            for p in (part, final):
                try:
                    p.unlink()
                except OSError:
                    pass
            raise
        d.store.add_event('control', 'the backup %s fetched from %s and handed to root to be looked into%s'
                          % (name, t['name'], (' (by %s)' % by) if by else ''), 'warn')
        progress(3, 3, 'handed to root')
        return {'asked': ident, 'file': name}
    return rb_job_start(d, by, 'restore', work)


def rb_tools():
    return {k: bool(shutil.which(k)) for k in ('ssh', 'sftp', 'scp', 'ssh-keygen', 'ssh-keyscan',
                                                'smbclient', 'openssl')}


def rb_page(d):
    return {'ok': True, 'targets': [rb_view(t) for t in rb_targets(d)], 'runs': rb_history(d)[:40],
            'job': dict(RB_JOB), 'host': rb_host(), 'locked': len(rb_password()) >= 8,
            'kinds': [{'kind': k, 'words': RB_KIND_WORDS[k], 'port': RB_PORTS[k]} for k in RB_KINDS],
            'tools': rb_tools(), 'next': rb_next(), 'helper': root_ok(d),
            'on': bool(int(CONFIG.get('rbackup') or 0)),
            'keep': int(CONFIG.get('rbackup_keep') or 0), 'keep_days': int(CONFIG.get('rbackup_keep_days') or 0)}


def rb_target_for(d, b):
    """The destination asked about: the one saved, with what is typed over it
    (Try it before Save)."""
    tid = str(b.get('id') or '')
    old = rb_target(d, tid) if tid else None
    if tid and not old:
        raise ValueError('no such destination')
    if isinstance(b.get('target'), dict):
        t = rb_checked(dict(b['target']), old)
        if not old:
            t.pop('id', None)
        return t
    if not old:
        raise ValueError('which destination?')
    return old


def rb_post(d, b, by):
    """POST /api/rbackup, by its action. A ValueError or an RbError is the
    answer the page shows."""
    act = str(b.get('action') or '')
    if act == 'save':
        t = rb_save(d, dict(b.get('target') or {}, id=b.get('id') or (b.get('target') or {}).get('id')), by)
        return {'message': 'saved', 'target': rb_view(t)}
    if act == 'delete':
        rb_delete(d, b.get('id'), by)
        return {'message': 'taken away - nothing was deleted on the server'}
    if act == 'try':
        t = rb_target_for(d, b)
        if t['kind'] in ('sftp', 'scp') and not t.get('hostkey'):
            lines, fps = rb_ssh_keyscan(t['host'], t['port'])
            return {'hostkey_needed': True, 'hostkey': lines, 'fingerprints': fps,
                    'message': 'the server\'s host key is not trusted yet'}
        out = rb_try(t)
        d.store.add_event('control', 'the backup destination %s tried: %s' % (
            t['name'], 'it works' if out['ok'] else out.get('error')), 'info' if out['ok'] else 'warn')
        if t.get('id') and rb_target(d, t['id']):
            rb_set_fields(d, t['id'], '', '', tried={'at': time.time(), 'ok': out['ok'],
                                                     'error': out.get('error') or ''})
        return out
    if act == 'hostkey_scan':
        t = rb_target_for(d, b)
        lines, fps = rb_ssh_keyscan(t['host'], t['port'])
        return {'hostkey': lines, 'fingerprints': fps}
    if act == 'hostkey_trust':
        t = rb_target_for(d, b)
        if not t.get('id') or not rb_target(d, t['id']):
            raise ValueError('save the destination first')
        lines = str(b.get('hostkey') or '')
        fresh, fps = rb_ssh_keyscan(t['host'], t['port'])
        # only what the server shows now, as the page showed it - nothing
        # typed in its place
        if sorted(x.strip() for x in lines.splitlines() if x.strip()) != \
                sorted(x.strip() for x in fresh.splitlines() if x.strip()):
            raise ValueError('the server shows other host keys now than the ones shown: Try reaching it again')
        rb_set_fields(d, t['id'], by, 'its host key trusted (%s)' % '; '.join(fps), hostkey=fresh)
        return {'message': 'trusted', 'fingerprints': fps}
    if act == 'hostkey_forget':
        t = rb_target_for(d, b)
        rb_set_fields(d, t.get('id'), by, 'its host key forgotten', hostkey=None)
        return {'message': 'forgotten'}
    if act == 'keygen':
        t = rb_target_for(d, b)
        private, public = rb_ssh_keygen('zigmon-backup@%s' % rb_host())
        rb_set_fields(d, t.get('id'), by, 'a new ssh key made here', key=private, pub=public, key_pass=None)
        return {'message': 'made', 'pub': public}
    if act == 'key_paste':
        t = rb_target_for(d, b)
        pp = str(b.get('passphrase') or '')
        if len(pp) > 512 or re.search(r'[\r\n\x00]', pp):
            raise ValueError('the passphrase is one line, at most 512 characters')
        private, public = rb_ssh_public_of(b.get('key'), pp)
        rb_set_fields(d, t.get('id'), by, 'an ssh key of their own given', key=private, pub=public,
                      key_pass=pp or None)
        return {'message': 'taken', 'pub': public}
    if act == 'key_download':
        t = rb_target_for(d, b)
        private = t.get('key') or ''
        if not private:
            raise ValueError('there is no key')
        d.say_event('audit', 'the private ssh key of the backup destination %s was downloaded%s'
                    % (t['name'], (' by %s' % by) if by else ''), 'warn', about='secrets_out',
                    title='A private key was downloaded')
        return {'pem': private if private.endswith('\n') else private + '\n',
                'file': 'zigmon-backup-%s-key' % re.sub(r'[^A-Za-z0-9_.-]+', '_', t['name'])[:40]}
    if act == 'key_forget':
        t = rb_target_for(d, b)
        rb_set_fields(d, t.get('id'), by, 'its ssh key forgotten', key=None, pub=None, key_pass=None,
                      ssh_cert=None)
        return {'message': 'forgotten'}
    if act == 'cert_make':
        t = rb_target_for(d, b)
        key, crt = rb_client_cert_make(b.get('cn') or 'zigmon-backup-%s' % rb_host())
        rb_set_fields(d, t.get('id'), by, 'a client certificate made here', client_cert=crt, client_key=key)
        return {'message': 'made', 'cert': crt, 'info': rb_cert_info(crt)}
    if act == 'cert_given':
        t = rb_target_for(d, b)
        key, crt = rb_client_cert_given(b.get('text'), str(b.get('password') or ''))
        rb_set_fields(d, t.get('id'), by, 'a client certificate of their own given', client_cert=crt,
                      client_key=key)
        return {'message': 'taken', 'cert': crt, 'info': rb_cert_info(crt)}
    if act == 'cert_forget':
        t = rb_target_for(d, b)
        rb_set_fields(d, t.get('id'), by, 'its client certificate forgotten', client_cert=None, client_key=None)
        return {'message': 'forgotten'}
    if act == 'pin':
        t = rb_target_for(d, b)
        pin = re.sub(r'[^0-9a-f]', '', str(b.get('pin') or '').lower())
        if len(pin) != 64:
            raise ValueError('the fingerprint is SHA-256: 64 hex digits')
        rb_set_fields(d, t.get('id'), by, 'the server\'s certificate pinned (%s)' % pin, pin=pin, tls_check='pin')
        return {'message': 'pinned'}
    if act == 'run':
        only = [str(x) for x in (b.get('ids') or []) if isinstance(x, str)] or None
        if not rb_password() or len(rb_password()) < 8:
            raise ValueError('the backups have no password yet: set one first (When, how many, and the password)')
        job = rb_job_start(d, by, 'backup', lambda progress: rb_run(d, by, only, progress))
        return {'message': 'the backup is being made', 'job': job}
    if act == 'job':
        return {'job': dict(RB_JOB)}
    if act == 'list':
        return {'files': rb_remote_list(d, b.get('id'))}
    if act == 'delete_file':
        t = rb_target(d, b.get('id'))
        name = str(b.get('name') or '')
        if not t or not RB_NAME_RE.match(name):
            raise ValueError('which backup?')
        tr = rb_transport(t)
        try:
            tr.open()
            names = set(x['name'] for x in tr.list())
            for n in [name] + [c for c in rb_companions(name) if c in names]:
                tr.delete(n)
        except RbError:
            raise
        except Exception as e:                          # noqa: BLE001
            raise RbError(rb_said(e, t))
        finally:
            tr.close()
        d.store.add_event('control', 'the backup %s deleted at %s%s' % (name, t['name'],
                                                                         (' by %s' % by) if by else ''), 'warn')
        return {'message': 'deleted'}
    if act == 'restore_txt':
        return {'text': rb_restore_txt(), 'file': 'RESTORE.txt'}
    if act == 'runs_forget':
        if b.get('all'):
            n = rb_history_forget(d)
            d.store.add_event('control', 'the list of backups sent cleared (%d line(s))%s; the backups stay '
                              'where they went' % (n, (' by %s' % by) if by else ''))
            return {'message': 'the list is empty; the backups stay where they went', 'runs': rb_history(d)[:40]}
        try:
            at = float(b.get('at'))
        except (TypeError, ValueError):
            raise ValueError('which line?')
        if not rb_history_forget(d, at, b.get('file')):
            raise ValueError('that line is not on the list any more')
        return {'message': 'taken off the list', 'runs': rb_history(d)[:40]}
    if act == 'restore':
        job = rb_restore_start(d, b.get('id'), b.get('name'), b.get('password'), by)
        return {'message': 'it is being fetched', 'job': job}
    raise ValueError('nothing is done for that')


def cmd_rbackup(args, pal):
    """zigmon --rbackup-status, and --rbackup-now: the backups to other
    machines, through the daemon - root's command line, as on the page."""
    if getattr(args, 'rbackup_now', False):
        code, out = api_call('/api/rbackup', method='POST', payload={'action': 'run'}, timeout=30.0)
        if not isinstance(out, dict) or not out.get('ok'):
            print(pal.crit('refused: %s' % (out or {}).get('error', 'no answer')))
            return 1
        print(pal.ok(out.get('message') or 'started'))
        said = ''
        while True:
            time.sleep(2)
            code, out = api_call('/api/rbackup', method='POST', payload={'action': 'job'}, timeout=30.0)
            job = (out or {}).get('job') or {}
            if job.get('says') and job.get('says') != said:
                said = job['says']
                print(pal.dim('  ' + said))
            if code != 200 or not job.get('running'):
                break
        res = job.get('result') or {}
        for x in res.get('targets') or []:
            print('  %s %s%s' % (pal.ok('sent to') if x.get('ok') else pal.crit('not sent to'), x.get('name'),
                                 '' if x.get('ok') else ': %s' % x.get('error')))
        if job.get('error') or not res.get('ok'):
            print(pal.crit(job.get('error') or 'it did not reach every destination'))
            return 1
        print(pal.ok('%s sent (%s)' % (res.get('file'), human_size(res.get('bytes') or 0))))
        return 0
    code, data = api_call('/api/rbackup', timeout=20.0)
    if code != 200 or not isinstance(data, dict):
        print(pal.crit('the daemon said: %s' % (data or {}).get('error', code)))
        return 2
    if args.json:
        print(json.dumps(data, indent=2, ensure_ascii=False))
        return 0
    print(pal.title('backups to other machines'))
    print('  %-14s %s' % ('schedule', ('next %s' % data.get('next')) if data.get('next') else 'by hand only'))
    print('  %-14s %s' % ('locked', 'with the password' if data.get('locked') else pal.crit('no password set')))
    print('  %-14s %d, none older than %s' % ('kept', data.get('keep') or 0,
                                              ('%d days' % data['keep_days']) if data.get('keep_days') else '-'))
    for t in data.get('targets') or []:
        last = t.get('last') or {}
        state = (pal.ok('ok ' + time.strftime('%Y-%m-%d %H:%M', time.localtime(last['at'])))
                 if last.get('ok') else pal.crit('failed: %s' % last.get('error')) if last else pal.dim('never sent'))
        print('  %-3s %-24s %-6s %s:%s  %s' % ('on' if t.get('enabled') else 'off', str(t.get('name'))[:24],
                                               t.get('kind'), t.get('host'), t.get('port'), state))
    if not data.get('targets'):
        print(pal.dim('  no destination yet - add one on the dashboard: Control - Backup'))
    for r in (data.get('runs') or [])[:5]:
        print('  %s  %-6s %s' % (time.strftime('%Y-%m-%d %H:%M', time.localtime(r.get('at') or 0)),
                                 'ok' if r.get('ok') else 'FAILED', r.get('file') or r.get('error') or ''))
    return 0


def root_status_main():
    """What root last did for the dashboard, and what it says is in place:
    the certificate, the firewall, who may reach the pages, the backups of
    the whole installation, the last upgrade."""
    base = Path(CONFIG.get('state_dir') or STATE_DIR)

    def read(p):
        try:
            with open(str(p)) as f:
                got = json.load(f)
            return got if isinstance(got, dict) else {}
        except (OSError, ValueError):
            return {}
    look, st, up = read(base / 'root' / 'look.json'), read(base / 'root' / 'status.json'), \
        read(base / 'upgrade' / 'status.json')
    if not look and not st and not up:
        print('root has said nothing yet (is zigmon-root.path installed? install.sh --upgrade)')
        return 1
    if look:
        print('looked at %s' % time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(look.get('at') or 0)))
        info = (look.get('tls') or {}).get('info') or {}
        if info:
            print('certificate  %s, until %s%s' % (
                info.get('cn'), time.strftime('%Y-%m-%d', time.localtime(info.get('not_after') or 0)),
                ' (the broker reads it too)' if (look.get('tls') or {}).get('broker') else ''))
        fw = look.get('fw') or {}
        print('firewall     %s' % (fw.get('backend') or 'neither firewalld nor iptables'))
        for k, v in sorted((look.get('access') or {}).items()):
            print('%-12s %s' % (k, 'everybody' if v.get('any') else ', '.join(v.get('from') or []) or '-'))
        full = look.get('full') or []
        print('backups      %d of the whole installation in %s%s' % (
            len(full), look.get('full_dir'), (', newest %s' % full[0]['file']) if full else ''))
    if st:
        print('last asked   %s: %s - %s' % (st.get('kind'), st.get('state'), '; '.join(st.get('said') or [])))
    if up:
        print('last upgrade %s: %s %s' % (up.get('version'), up.get('state'), up.get('said') or ''))
    return 0


def change_main(arguments):
    """A change on trial (5.21) kept, or put back, from the command line -
    where somebody is when the new network does not answer on the page."""
    load_config()
    word = arguments[0]
    if word == '--changes':
        code, out = api_call('/api/status', timeout=15.0)
        rows = (out or {}).get('changes') or [] if code == 200 else None
        if rows is None:
            print('the daemon did not answer: %s' % ((out or {}).get('error') or code))
            return 1
        if not rows:
            print('nothing waits to be kept')
        for c in rows:
            left = max(0, int(float(c.get('until') or 0) - time.time()))
            print('%-4s %s waits to be kept: %d min %d s left, then it goes back by itself '
                  '(zigmon --change-keep %s)' % (c.get('kind'), c.get('words'), left // 60, left % 60,
                                                 c.get('kind')))
        return 0
    kind = arguments[1] if len(arguments) > 1 else ''
    if kind not in ('net', 'fw'):
        print('which change: zigmon %s net   (the network)  or  zigmon %s fw   (the firewall)'
              % (word, word))
        return 2
    code, out = api_call('/api/change', method='POST', timeout=30.0,
                         payload={'kind': kind, 'action': 'keep' if word == '--change-keep' else 'back'})
    if code != 200:
        print('not done: %s' % ((out or {}).get('error') or code))
        return 1
    print((out or {}).get('message') or 'done')
    return 0


# ---------------------------------------------------------------------------
# The console: zigmon run by its menus, on the server's own screen (5.21)
# ---------------------------------------------------------------------------
# `zigmon --console` - and, with `zigmon --console-at-login on`, what root sees
# first after signing in at the machine's own screen or over SSH. Ported from
# the console of otp 1.0.138, whose framework it keeps as it was (the key
# reader, the menus, the windows, the lists, the scrolled pages, the live
# views); only the menus are ZIGMon's own.
#
# Everything it does is done by a `zigmon ...` command, run as it would be
# typed, as a process of its own - so the console can do nothing the command
# line cannot, and a fault in it can break nothing the command line keeps.
# The live log, the journal and the broker are only read. q leaves it for the
# ordinary shell, exactly as that shell was; ! opens a shell and comes back
# when it is closed.
#
# Where the flag lives: in /etc itself, where only root writes. /etc/zigmon is
# the service's group's to write (config.json is changed from the dashboard),
# so a flag there could have been turned into a link or a pipe for root's
# login to follow - the same mistake otp made in 1.0.130 and mended in 1.0.136.
import textwrap as _textwrap

CONSOLE_PROFILE = '/etc/profile.d/zz-zigmon-console.sh'


def console_flag_path():
    """Where the switch is: asked each time, so a check can point it elsewhere."""
    return os.environ.get('ZIGMON_CONSOLE_FLAG') or '/etc/zigmon-console-login'


# What else other parts of zigmon put in the console's menus. Each entry is
# (words, fn(console)) or (words, fn(console), 'plain') for one that is a view
# of its own on the ordinary terminal; they come after the console's own
# items, numbered on from them. Kept as a table rather than written into the
# menus below so that a feature can add itself where it is written, without
# the console having to know of it:
#   'main'      - "Network, time and power" belongs here (its own submenu,
#                 built with console.sub(title, items))
#   'backups'   - "Backups to other machines: how they went" and "...: one now"
#   'upgrades'  - "Look for a new version on the web" and "Upgrade from the web"
#   'security', 'service', 'status', 'devices' - anything else of the kind
CONSOLE_MORE = {'main': [], 'status': [], 'live': [], 'devices': [], 'accounts': [],
                'settings': [], 'security': [], 'backups': [], 'upgrades': [], 'service': []}

# The keys a terminal sends as Esc followed by more, by what follows the Esc.
# curses names most of them itself; these are for the terminals whose
# description says one thing while they send another (PuTTY among them),
# and for the screens that read the terminal without curses.
CONSOLE_SEQ = {'[A': 'up', '[B': 'down', '[C': 'right', '[D': 'left',
               'OA': 'up', 'OB': 'down', 'OC': 'right', 'OD': 'left',
               '[H': 'home', '[F': 'end', 'OH': 'home', 'OF': 'end',
               '[1~': 'home', '[4~': 'end', '[7~': 'home', '[8~': 'end',
               '[5~': 'pgup', '[6~': 'pgdn', '[3~': 'del', '[2~': 'ins'}


def console_key(raw):
    """One key's bytes, as the terminal sent them, by name: 'esc', 'enter',
    'bs', 'up', 'pgdn', 'ctrl-c'..., or the character itself. A sequence
    that is not known is 'seq' and is ignored by whoever reads it; bytes
    that are not yet a whole character are ''."""
    if not raw:
        return ''
    if raw[:1] == b'\x1b':
        rest = raw[1:]
        if not rest:
            return 'esc'
        seq = rest.decode('latin-1')
        if seq in CONSOLE_SEQ:
            return CONSOLE_SEQ[seq]
        # an arrow with a modifier (ESC [ 1 ; 5 A) is still the arrow
        m = re.match(r'^\[1;\d+([ABCDHF])$', seq)
        if m:
            return CONSOLE_SEQ['[' + m.group(1)]
        return CONSOLE_SEQ.get(seq[:2], 'seq')
    named = {b'\r': 'enter', b'\n': 'enter', b'\x7f': 'bs', b'\x08': 'bs', b'\t': 'tab',
             b'\x03': 'ctrl-c', b'\x04': 'ctrl-d', b'\x15': 'ctrl-u'}
    if raw in named:
        return named[raw]
    try:
        return raw.decode('utf-8')
    except UnicodeDecodeError:
        return ''


def console_grep(find):
    """What is typed in a live view, taken as `grep -i` takes it: a test of
    one line. Words that are not a regular expression ("[1", "a(") are looked
    for as they are, rather than refused while they are still being typed."""
    if not find:
        return lambda s: True
    try:
        rx = re.compile(find, re.I)
        return lambda s: rx.search(s) is not None
    except re.error:
        low = find.lower()
        return lambda s: low in s.lower()


def console_jump(typed, keys):
    """Digits typed in a menu: `typed` is what has been typed within the last
    second, `keys` the menu's numbers. Gives (the item now chosen or None,
    whether it is chosen for good - no longer number begins with it - and
    what counts as typed from now). With eleven items, 1 waits for a second
    digit; 1 then 1 is the eleventh; 1 then 7 is the seventh."""
    if typed and not any(k.startswith(typed) for k in keys) and len(typed) > 1:
        typed = typed[-1]
    hit = [i for i, k in enumerate(keys) if k == typed]
    if not hit:
        return None, False, ('' if not any(k.startswith(typed) for k in keys) else typed)
    done = not any(k.startswith(typed) and k != typed for k in keys)
    return hit[0], done, ('' if done else typed)


def console_plain(text):
    """The words without their colours."""
    return re.sub(r'\x1b\[[0-9;?]*[A-Za-z]', '', str(text or ''))


def console_slice(line, start, width):
    """Columns start..start+width of `line` on the screen, its colours kept -
    the window of a live view scrolled sideways."""
    out, seen = [], 0
    end = start + width
    for part in re.split(r'(\x1b\[[0-9;?]*[A-Za-z])', line):
        if not part:
            continue
        if part.startswith('\x1b['):
            out.append(part)
            continue
        a, b = seen, seen + len(part)
        if b > start and a < end:
            out.append(part[max(0, start - a):max(0, end - a)])
        seen = b
    return ''.join(out) + ('\x1b[0m' if '\x1b[' in line else '')


class ConsoleBack(Exception):
    """Back to the menu."""


class Console(object):
    HELP = ' Up/Down move   Enter choose   Esc back   ! shell   q leave '
    # what a live view keeps; a log can be gigabytes
    LIVE_KEEP = 20000
    LOG_TONES = {'error': 'bad', 'crit': 'bad', 'warn': 'warn', 'info': '', 'debug': 'dim'}

    def __init__(self, pal):
        self.pal = pal
        # The program itself, not /usr/local/bin/zigmon that points at it: the
        # helpers root runs are found beside the program, and only there.
        self.me = os.path.realpath(__file__)
        self.st, self.st_gen, self.st_now, self.closing, self.plain = {}, 0, False, False, False
        self.backdrop = None

    # ---- the commands it runs ----------------------------------------------------
    def argv(self, *args):
        """`zigmon ARGS` as this very program, whatever it was started as."""
        return [sys.executable, self.me] + [str(a) for a in args]

    @staticmethod
    def _quote(a):
        a = str(a)
        return a if re.match(r'^[A-Za-z0-9_@%+=:,./-]+\Z', a) else "'%s'" % a.replace("'", "'\\''")

    def shown(self, args):
        return '$ zigmon ' + ' '.join(self._quote(a) for a in args)

    def out(self, *args):
        """`zigmon ARGS --json`, read; None when it said nothing a program can read."""
        try:
            got = subprocess.run(self.argv(*args) + ['--json'], capture_output=True, text=True,
                                 timeout=60, stdin=subprocess.DEVNULL)
            return json.loads(got.stdout or 'null')
        except Exception:                               # noqa: BLE001 - None is the answer
            return None

    def cmd(self, *args):
        """`zigmon ARGS` straight on the terminal; its exit code."""
        argv = self.argv(*args) + ([] if self.pal.on else ['--no-color'])
        print(self.pal.dim(self.shown(args)))
        try:
            return subprocess.call(argv)
        except KeyboardInterrupt:
            print()
            return 130

    def capture(self, argv, env=None):
        """What a command writes: (text, exit code)."""
        e = dict(os.environ, **(env or {}))
        e['COLUMNS'] = str(max(60, self._cols() - 2))
        try:
            got = subprocess.run(argv, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                 stdin=subprocess.DEVNULL, env=e, timeout=1800)
            return got.stdout.decode('utf-8', 'replace'), got.returncode
        except subprocess.TimeoutExpired:
            return 'it took more than 30 minutes and was stopped', 124
        except OSError as ex:
            return str(ex), 127

    def act(self, *args, env=None, title=None, quiet_ok=None):
        """`zigmon ARGS` run: a short answer in a window, a long one on a
        screen of its own to scroll. Returns the exit code."""
        return self.act_argv(self.argv(*args), title or self.shown(args), env=env,
                             quiet_ok=quiet_ok)

    def act_argv(self, argv, title, env=None, quiet_ok=None):
        self.working('working...  ' + title)
        text, rc = self.capture(argv, env=env)
        plain = console_plain(text).rstrip()
        if rc == 0 and not plain and quiet_ok:
            plain = text = quiet_ok
        h, w = self.scr.getmaxyx()
        lines = self._wrap(plain, max(30, min(100, w - 4)) - 4)
        if len(lines) <= max(3, min(14, h - 8)):
            self.note(title if rc == 0 else '%s - it ended with %d' % (title, rc),
                      plain or '(it said nothing)', '' if rc == 0 else 'bad')
        else:
            if rc not in (0, None):
                text += '\n' + self.pal.dim('(it ended with %d)' % rc)
            self.go_plain(lambda: self.page(title, text))
        return rc

    def show_live(self, argv, title):
        """A command straight on the terminal - one that asks something, or
        tells as it goes - and Enter to come back."""
        self.clear_screen()
        print(self.pal.dim(title))
        try:
            subprocess.call(argv)
        except KeyboardInterrupt:
            print()
        self.pause()

    # ---- keys on the ordinary terminal: Esc goes back everywhere -----------------
    def _raw(self):
        """The terminal's settings, to be put back; None without a terminal."""
        try:
            import termios
            return termios.tcgetattr(sys.stdin.fileno())
        except Exception:                               # noqa: BLE001
            return None

    def _restore(self, was):
        if was is None:
            return
        import termios
        termios.tcsetattr(sys.stdin.fileno(), termios.TCSADRAIN, was)

    def key(self, wait=None):
        """One key, without Enter, by name (console_key) - or None when `wait`
        seconds went by without one."""
        import tty
        fd = sys.stdin.fileno()
        was = self._raw()
        try:
            if was is not None:
                # TCSANOW: what was typed ahead is kept, not thrown away
                import termios
                tty.setcbreak(fd, termios.TCSANOW)
            r, _w, _x = select.select([fd], [], [], wait)
            if not r:
                return None
            ch = os.read(fd, 1)
            if ch == b'\x1b':
                # alone, Esc; followed at once by more, a key's sequence
                r, _w, _x = select.select([fd], [], [], 0.05)
                if r:
                    ch += os.read(fd, 8)
                return console_key(ch)
            got = console_key(ch)
            while got == '' and len(ch) < 4:
                ch += os.read(fd, 1)
                got = console_key(ch)
            return got
        finally:
            self._restore(was)

    def pause(self):
        sys.stdout.write(self.pal.dim('\n  Enter or Esc - back to the menu '))
        sys.stdout.flush()
        if self._raw() is None:
            try:
                input()
            except EOFError:
                pass
            return
        while self.key() not in ('enter', 'esc', 'ctrl-c', 'ctrl-d', 'q'):
            pass
        sys.stdout.write('\n')

    def clear_screen(self):
        if sys.stdout.isatty():
            sys.stdout.write('\033[H\033[2J')
            sys.stdout.flush()

    # ---- the status at the top, asked for off the screen's thread ----------------
    def status_thread(self):
        """The bar at the top, asked for again every 30 s by `zigmon --status
        --json` - the menu never waits for it. Nothing is asked while nobody
        sees the bar (in a live view, a page or a shell); it is asked again
        on the way back."""
        def look():
            while not self.closing:
                if self.plain and not self.st_now:
                    time.sleep(0.5)
                    continue
                self.st_now = False
                got = self.out('--status')
                active = '?'
                if shutil.which('systemctl'):
                    try:
                        active = subprocess.run(['systemctl', 'is-active', 'zigmon'],
                                                capture_output=True, text=True,
                                                timeout=10).stdout.strip() or '?'
                    except Exception:                   # noqa: BLE001
                        pass
                st = got if isinstance(got, dict) else {}
                self.st = dict(st, _active=active, _down=not isinstance(got, dict))
                self.st_gen += 1
                for _ in range(60):
                    if self.closing or self.st_now:
                        break
                    time.sleep(0.5)
        threading.Thread(target=look, name='zigmon-console-status', daemon=True).start()

    # ---- the menus: a text screen, arrows and Enter -------------------------------
    # curses: only what changed is written, so nothing blinks; a window made
    # bigger or smaller (PuTTY's too, which does not always say so) is drawn
    # again to its new size. Leaving it for a command's output and coming back
    # is the one full redraw.
    def _put(self, y, x, text, attr=0):
        try:
            h, w = self.scr.getmaxyx()
            if y < 0 or y >= h or x >= w:
                return
            self.scr.addnstr(y, x, str(text), max(0, w - x - (1 if y == h - 1 else 0)), attr)
        except Exception:                               # noqa: BLE001 - the edge
            pass

    def _colours(self):
        c = self.curses
        self.A = {'head': c.A_REVERSE, 'sel': c.A_REVERSE | c.A_BOLD, 'ok': c.A_BOLD,
                  'warn': c.A_BOLD, 'bad': c.A_BOLD, 'dim': c.A_DIM, 'key': c.A_BOLD,
                  'title': c.A_BOLD}
        # --no-color and NO_COLOR are honoured here too: reverse and bold only
        if not self.pal.on or not c.has_colors():
            return
        try:
            c.start_color()
            try:
                c.use_default_colors()
                bg = -1
            except Exception:                           # noqa: BLE001
                bg = c.COLOR_BLACK
            c.init_pair(1, c.COLOR_BLACK, c.COLOR_CYAN)
            c.init_pair(2, c.COLOR_BLACK, c.COLOR_GREEN)
            c.init_pair(3, c.COLOR_GREEN, bg)
            c.init_pair(4, c.COLOR_YELLOW, bg)
            c.init_pair(5, c.COLOR_RED, bg)
            c.init_pair(6, c.COLOR_CYAN, bg)
            self.A.update(head=c.color_pair(1), sel=c.color_pair(2) | c.A_BOLD,
                          ok=c.color_pair(3) | c.A_BOLD, warn=c.color_pair(4) | c.A_BOLD,
                          bad=c.color_pair(5) | c.A_BOLD, key=c.color_pair(6) | c.A_BOLD)
        except Exception:                               # noqa: BLE001
            pass

    def status_bits(self, st):
        """What the bar says on its right, as `zigmon --status --json` has it."""
        bits = []
        if st.get('_down'):
            return ['the daemon is not answering']
        if 'connected' in st:
            bits.append('broker %s' % ('connected' if st.get('connected') else 'NOT connected'))
        bridge = st.get('bridge') or {}
        if bridge.get('state'):
            bits.append('bridge %s' % bridge['state'])
        counts = st.get('counts') or {}
        if counts.get('devices') is not None:
            more = ['%d %s' % (counts[k], k) for k in ('warn', 'crit') if counts.get(k)]
            bits.append('%d devices%s' % (counts['devices'], (' (%s)' % ', '.join(more)) if more
                                          else ''))
        return bits

    def draw(self, title, items, sel, top, path):
        scr, A = self.scr, self.A
        scr.erase()
        h, w = scr.getmaxyx()
        st = self.st or {}
        self._put(0, 0, ' ' * w, A['head'])
        left = ' zigmon %s  %s ' % (__version__, socket.gethostname())
        self._put(0, 0, left, A['head'] | self.curses.A_BOLD)
        active = st.get('_active') or '...'
        svc = ' service %s ' % active
        self._put(0, len(left) + 1, svc, A['sel'] if active == 'active' else
                  (A['head'] if active in ('...', '?') else self.curses.A_REVERSE | A['bad']))
        bits = self.status_bits(st)
        # Too long for the bar: the device count gives way, then it goes on
        # the line under the bar.
        y = 1
        for b in (bits, bits[:-1]):
            right = ' ' + ' | '.join(b) + ' '
            if len(left) + len(svc) + len(right) + 2 < w:
                self._put(0, w - len(right), right, A['head'])
                break
        else:
            self._put(1, 1, ' | '.join(bits), A['key'])
            y = 2
        if st.get('_down'):
            self._put(y, 1, 'the daemon is not answering (The service > Its state)', A['bad'])
            y += 1
        if (st.get('bridge') or {}).get('permit_join'):
            self._put(y, 1, 'the Zigbee network is open: new devices may join', A['warn'])
            y += 1
        for one in (st.get('alerts') or [])[:max(0, min(4, h - 12))]:
            text = one.get('text') if isinstance(one, dict) else one
            self._put(y, 1, '! ' + str(text), A['warn'])
            y += 1
        y += 1
        self._put(y, 2, path, A['dim'])
        self._put(y, 2 + len(path), title, A['title'])
        y += 2
        # the items, a window of them when the screen is short
        room = max(1, h - y - 2)
        if sel < top:
            top = sel
        if sel >= top + room:
            top = sel - room + 1
        width = max(20, min(w - 6, max(len(it[1]) for it in items) + 10))
        for n, it in enumerate(items[top:top + room]):
            i = top + n
            line = ' %3s  %s' % (it[0], it[1])
            line = line + ' ' * max(0, width - len(line))
            if i == sel:
                self._put(y + n, 2, line, A['sel'])
            else:
                self._put(y + n, 2, ' %3s' % it[0], A['key'])
                self._put(y + n, 8, it[1])
        if top > 0:
            self._put(y - 1, 4, '^ more', A['dim'])
        if top + room < len(items):
            self._put(y + room, 4, 'v more', A['dim'])
        self._put(h - 1, 0, ' ' * (w - 1), A['head'])
        self._put(h - 1, 0, self.HELP[:w - 1], A['head'])
        scr.noutrefresh()
        return top

    def menu(self, title, items, path=''):
        """items: [(number, words, function[, 'plain'])]; returns 'back' or 'quit'."""
        c = self.curses
        sel, top, typed, typed_at = 0, 0, '', 0.0
        keys = [it[0] for it in items]
        while True:
            self._fresh()
            top = self.draw(title, items, sel, top, path)
            c.doupdate()
            self.backdrop = (lambda _s=sel, _t=top: self.draw(title, items, _s, _t, path))
            seen = self.st_gen
            self.scr.timeout(500)
            while True:
                k = self._getkey()
                if k is not None or self.st_gen != seen:
                    break
            if k is None or k == 'resize':
                continue
            if k in ('up', 'k'):
                sel = (sel - 1) % len(items)
            elif k in ('down', 'j', 'tab'):
                sel = (sel + 1) % len(items)
            elif k in ('home', 'pgup'):
                sel = 0
            elif k in ('end', 'pgdn'):
                sel = len(items) - 1
            elif k in ('esc', 'left', 'bs'):
                if path:
                    return 'back'
            elif k in ('q', 'Q'):
                return 'quit'
            elif k == '!':
                self.go_plain(self.shell)
            elif len(k) == 1 and k.isdigit():
                now = time.time()
                typed = (typed if now - typed_at < 1.0 else '') + k
                typed_at = now
                hit, done, typed = console_jump(typed, keys)
                if hit is not None:
                    sel = hit
                    if done:
                        k = 'enter'
            if k in ('enter', 'right'):
                it = items[sel]
                # Run on the text screen - its questions are windows there;
                # only a view of its own ('plain') leaves it.
                if len(it) > 3 and it[3] == 'plain':
                    r = self.go_plain(it[2])
                else:
                    try:
                        r = it[2]()
                    except ConsoleBack:
                        r = None
                if r == 'quit':
                    return 'quit'

    def go_plain(self, fn):
        """`fn` on the ordinary terminal - a command's output, the live log -
        and back to the text screen after it."""
        c = self.curses
        c.def_prog_mode()
        c.endwin()
        self.plain = True
        # a clean screen for it, not what the last command left there
        if sys.stdout.isatty():
            sys.stdout.write('\033[H\033[2J\033[3J')
            sys.stdout.flush()
        try:
            return fn()
        except ConsoleBack:
            return None
        except KeyboardInterrupt:
            print()
            return None

    def _numbered(self, rows, more=None):
        """Menu rows numbered by where they stand: the console's own, then
        whatever CONSOLE_MORE[more] holds."""
        out = []
        for row in list(rows) + [(r[0], (lambda _f=r[1]: _f(self))) + tuple(r[2:])
                                 for r in CONSOLE_MORE.get(more, [])]:
            out.append((str(len(out) + 1),) + tuple(row))
        return out

    def run(self):
        main = self._numbered([
            ('Status and checks', self.m_status),
            ('Live log', self.m_live),
            ('Devices and sockets', self.m_devices),
            ('Accounts of the dashboard', self.m_accounts),
            ('Settings', self.m_settings),
            ('Security', self.m_security),
            ('Backups', self.m_backups),
            ('Upgrades', self.m_upgrades),
            ('The service', self.m_service),
            # "Network, time and power" comes here, from CONSOLE_MORE['main']
        ], 'main')
        os.environ.setdefault('ESCDELAY', '25')     # Esc at once, not after a second
        # Lines and blocks drawn as UTF-8 characters, as PuTTY in UTF-8 shows
        # them - not the line-drawing set, which it draws as letters.
        os.environ.setdefault('NCURSES_NO_UTF8_ACS', '1')
        try:
            import locale
            locale.setlocale(locale.LC_ALL, '')
        except Exception:                               # noqa: BLE001
            pass
        import curses
        self.curses = curses

        def body(scr):
            self.scr = scr
            try:
                curses.curs_set(0)
            except Exception:                           # noqa: BLE001
                pass
            scr.keypad(True)
            self._colours()
            self.status_thread()
            # It opens on the live log, as otp's does; Esc there is the menu.
            if os.environ.get('ZIGMON_CONSOLE_START', 'log') == 'log':
                self.go_plain(self.live_log)
            while True:
                try:
                    self.menu('Main menu', main)
                    return
                except KeyboardInterrupt:
                    # Ctrl+C on a menu is nothing; q leaves
                    self.scr.clear()
        try:
            curses.wrapper(body)
        finally:
            self.closing = True
        print(self.pal.dim('  The zigmon console is closed - `zigmon --console` opens it again.'))
        return 0

    def shell(self):
        sh = os.environ.get('SHELL') or '/bin/bash'
        print(self.pal.dim('  A shell - exit (or Ctrl+D) comes back to the zigmon console.'))
        try:
            # ZIGMON_CONSOLE tells the login hook not to open a console in it
            subprocess.call([sh], env=dict(os.environ, ZIGMON_CONSOLE='1'))
        except KeyboardInterrupt:
            pass

    def sub(self, title, items, more=None):
        """A submenu: rows (words, fn[, 'plain']) numbered from 1."""
        r = self.menu(title, self._numbered(items, more), path='Main menu > ')
        return 'quit' if r == 'quit' else None

    # ---- long output: a screen of its own, scrolled --------------------------------
    # The terminal is not scrolled, a window (top) into the lines is; each
    # frame is one write (home, each line cleared to its end, the rest cleared)
    # so nothing blinks, and the scroll bar is drawn after it into the last
    # column. Arrows, PgUp/PgDn, Home/End, Space; Esc, q or Enter back.
    @staticmethod
    def _cols():
        try:
            return os.get_terminal_size(sys.__stdout__.fileno()).columns
        except (OSError, ValueError):
            return 100

    def page(self, title, text):
        p = self.pal
        lines = [ln.expandtabs(8).replace('\r', '') for ln in text.rstrip('\n').split('\n')] or ['']
        if self._raw() is None or not sys.stdout.isatty():
            print(text)
            return
        out = sys.stdout
        out.write('\x1b[?1049h\x1b[?25l')
        top = 0
        try:
            while True:
                try:
                    sz = os.get_terminal_size(sys.__stdout__.fileno())
                    cols, rows = max(40, sz.columns), max(8, sz.lines)
                except OSError:
                    cols, rows = 100, 30
                avail = max(3, rows - 2)
                top = max(0, min(top, max(0, len(lines) - avail)))
                end = min(len(lines), top + avail)
                head = ' %s ' % title
                where = ' %d-%d of %d ' % (top + 1, end, len(lines)) if len(lines) > avail \
                    else ' %d lines ' % len(lines)
                bar = (head + ' ' * max(0, cols - len(head) - len(where)) + where)[:cols]
                foot = (' Up/Down PgUp/PgDn Home/End scroll   Esc, q or Enter back ')[:cols - 1]
                body = [console_slice(ln, 0, cols - 2) for ln in lines[top:end]]
                body += [''] * (avail - len(body))
                frame = ['\x1b[7m' + bar + '\x1b[0m' if p.on else bar] + body + \
                    ['\x1b[7m' + foot + ' ' * max(0, cols - 1 - len(foot)) + '\x1b[0m'
                     if p.on else foot]
                out.write('\x1b[H' + '\n'.join(ln + '\x1b[K' for ln in frame) + '\x1b[J')
                self._scrollbar(2, avail, len(lines), avail, top, cols)
                out.flush()
                size = (cols, rows)
                while True:
                    k = self.key(0.3)
                    if k is not None:
                        break
                    try:
                        sz = os.get_terminal_size(sys.__stdout__.fileno())
                        if (max(40, sz.columns), max(8, sz.lines)) != size:
                            break
                    except OSError:
                        pass
                if k in ('esc', 'q', 'enter', 'ctrl-c', 'ctrl-d'):
                    return
                if k in ('up', 'k'):
                    top -= 1
                elif k in ('down', 'j'):
                    top += 1
                elif k in ('pgup', 'b'):
                    top -= avail - 1
                elif k in ('pgdn', ' ', 'f'):
                    top += avail - 1
                elif k in ('home', 'g'):
                    top = 0
                elif k in ('end', 'G'):
                    top = len(lines)
        finally:
            out.write('\x1b[?25h\x1b[?1049l')
            out.flush()

    def _scrollbar(self, base_row, nrows, total, visible, top, cols):
        if total <= visible or nrows <= 0:
            return
        thumb = max(1, min(nrows, round(nrows * visible / total)))
        span = nrows - thumb
        tstart = max(0, min(span, round(span * (top / max(1, total - visible)))))
        on = self.pal.on
        parts = ['\x1b[?7l']
        for r in range(nrows):
            hit = tstart <= r < tstart + thumb
            g = '█' if hit else '│'
            if on:
                g = ('\x1b[36m' if hit else '\x1b[2m') + g + '\x1b[0m'
            parts.append('\x1b[%d;%dH%s' % (base_row + r, cols, g))
        parts.append('\x1b[?7h')
        sys.stdout.write(''.join(parts))

    # ---- live views: scrolled, and what is typed is a grep -------------------------
    # The log, the journal and the broker come into one screen of their own:
    # the newest at the bottom, followed while the view is at the end. Up,
    # PgUp and Home scroll back (the view then stays where it is and counts
    # what came meanwhile), End or Enter follow again; Left/Right move it
    # sideways. Whatever is typed filters the lines as `grep -i` does, the
    # hits marked; Backspace takes a character back, Ctrl+U all of them. Esc
    # clears the filter first, then goes back to the menu.
    def _mark(self, coloured, find):
        """The hits of `find` shown reversed - in the text between the colours."""
        if not find or not self.pal.on:
            return coloured
        try:
            rx = re.compile(find, re.I)
        except re.error:
            rx = re.compile(re.escape(find), re.I)
        out = []
        for part in re.split(r'(\x1b\[[0-9;?]*[A-Za-z])', coloured):
            if part.startswith('\x1b['):
                out.append(part)
            elif part:
                out.append(rx.sub(lambda m: '\x1b[7m' + m.group(0) + '\x1b[27m'
                                  if m.group(0) else '', part))
        return ''.join(out)

    def live_view(self, title, first, more, paint, find=''):
        """The live screen: `first()` the lines there are, `more()` those come
        since (asked a few times a second), `paint(line)` its colours."""
        p = self.pal
        if self._raw() is None or not sys.stdout.isatty():
            for ln in first() + more():
                print(ln)
            return
        import termios
        import tty
        fd = sys.stdin.fileno()
        was = termios.tcgetattr(fd)
        out = sys.stdout
        lines = []                       # (plain, coloured)

        def add(raw):
            for ln in raw:
                ln = ln.expandtabs(8).replace('\r', '')
                col = (paint(ln) if paint else ln) if p.on else console_plain(ln)
                lines.append((console_plain(col), col))
        add(first())
        test = console_grep(find)
        hits = [i for i, x in enumerate(lines) if test(x[0])]
        top, follow, xoff, new, dirty, size = 0, True, 0, 0, True, None
        tty.setcbreak(fd, termios.TCSANOW)
        out.write('\x1b[?1049h\x1b[?25l')
        try:
            while True:
                came = more()
                if came:
                    n0 = len(lines)
                    add(came)
                    got = [i for i in range(n0, len(lines)) if test(lines[i][0])]
                    hits += got
                    if not follow:
                        new += len(got)
                    if len(lines) > self.LIVE_KEEP * 1.25:
                        cut = len(lines) - self.LIVE_KEEP
                        gone = sum(1 for i in hits if i < cut)
                        del lines[:cut]
                        hits = [i - cut for i in hits if i >= cut]
                        top = max(0, top - gone)
                    dirty = dirty or bool(got)
                try:
                    sz = os.get_terminal_size(sys.__stdout__.fileno())
                    cols, rows = max(40, sz.columns), max(8, sz.lines)
                except OSError:
                    cols, rows = 100, 30
                if (cols, rows) != size:
                    size, dirty = (cols, rows), True
                avail = max(3, rows - 2)
                last = max(0, len(hits) - avail)
                if follow:
                    top = last
                top = max(0, min(top, last))
                if dirty:
                    end = min(len(hits), top + avail)
                    where = (' %d-%d of %d ' % (top + 1, end, len(hits))) if hits else ' 0 '
                    state = ' following ' if follow else (' PAUSED%s ' % (
                        ', %d new below' % new if new else ''))
                    head = ' %s ' % title
                    gp = '  grep -i: %s_ ' % find if find else '  type to grep '
                    right = state + where
                    bar = (head + gp)[:max(0, cols - len(right))]
                    bar = bar + ' ' * max(0, cols - len(bar) - len(right)) + right
                    foot = (' type: grep (any case)  Bksp  Ctrl+U clear   Up/Down PgUp/PgDn '
                            'Home  End: follow   Left/Right  Esc back ')[:cols - 1]
                    body = [console_slice(self._mark(lines[i][1], find), xoff, cols - 2)
                            for i in hits[top:end]]
                    if not hits:
                        body = ['', '   ' + (p.dim('nothing with "%s" yet' % find) if find
                                             else p.dim('nothing yet'))]
                    body += [''] * (avail - len(body))
                    inv = (lambda t: '\x1b[7m' + t + '\x1b[0m') if p.on else (lambda t: t)
                    tone = '\x1b[33m' if (not follow and p.on) else ''
                    frame = [tone + inv(bar[:cols])] + body[:avail] + \
                        [inv(foot + ' ' * max(0, cols - 1 - len(foot)))]
                    out.write('\x1b[H' + '\n'.join(ln + '\x1b[K' for ln in frame) + '\x1b[J')
                    self._scrollbar(2, avail, len(hits), avail, top, cols)
                    out.flush()
                    dirty = False
                k = self.key(0.25)
                if k is None:
                    continue
                dirty = True
                if k in ('esc', 'ctrl-c', 'ctrl-d'):
                    if find and k == 'esc':
                        find = ''
                    else:
                        return
                elif k == 'up':
                    follow, top = False, top - 1
                elif k == 'down':
                    top += 1
                    follow = top >= last
                elif k == 'pgup':
                    follow, top = False, top - (avail - 1)
                elif k == 'pgdn':
                    top += avail - 1
                    follow = top >= last
                elif k == 'home':
                    follow, top = False, 0
                elif k in ('end', 'enter'):
                    follow, new = True, 0
                elif k == 'left':
                    xoff = max(0, xoff - 20)
                    continue
                elif k == 'right':
                    xoff += 20
                    continue
                elif k == 'bs':
                    find = find[:-1]
                elif k == 'ctrl-u':
                    find = ''
                elif k and len(k) == 1 and k.isprintable():
                    find += k
                else:
                    continue
                if k in ('bs', 'ctrl-u', 'esc') or (k and len(k) == 1 and k.isprintable()):
                    test = console_grep(find)
                    hits = [i for i, x in enumerate(lines) if test(x[0])]
                    follow, new = True, 0
                if follow:
                    new = 0
        finally:
            out.write('\x1b[?25h\x1b[?1049l')
            out.flush()
            termios.tcsetattr(fd, termios.TCSADRAIN, was)

    def _log_text(self, ln):
        """One line of the log, coloured: the time dim, the level by how bad,
        addresses in magenta, what went well green and what did not red, a
        whole warning yellow and a whole error red."""
        p = self.pal
        m = re.match(r'^(\S+ \S+)\s+(debug|info|warn|error|crit)\s+(.*)$', ln)
        if not m or not p.on:
            return ln
        lvl, rest = m.group(2), m.group(3)
        tone = self.LOG_TONES.get(lvl, '')
        back = {'warn': '\x1b[33m', 'bad': '\x1b[1;31m'}.get(tone, '')
        rest = re.sub(r'\b(\d{1,3}(?:\.\d{1,3}){3})\b',
                      lambda x: p._c('35', x.group(1)) + back, rest)
        rest = re.sub(r'\b(online|connected|switched on|done|ok)\b',
                      lambda x: p.ok(x.group(1)) + back, rest)
        rest = re.sub(r'\b(offline|refused|failed|blocked|not answering|lost)\b',
                      lambda x: p.crit(x.group(1)) + back, rest)
        if tone == 'warn':
            rest = p.warn(rest)
        elif tone == 'bad':
            rest = p.bad(rest)
        elif tone == 'dim':
            rest = p.dim(rest)
        lv = {'warn': p.warn, 'bad': p.bad, 'dim': p.dim}.get(tone, p.info)(lvl.ljust(5))
        return '%s %s %s' % (p.dim(m.group(1)), lv, rest)

    def log_path(self):
        return str(CONFIG.get('log_file') or DEFAULTS.get('log_file') or '/var/log/zigmon/zigmon.log')

    def live_log(self, what=''):
        """The daemon's log file, followed - through a rotation too."""
        path = self.log_path()
        st = {'f': None, 'ino': None}

        def first():
            try:
                f = open(path, 'r', encoding='utf-8', errors='replace')
            except OSError as e:
                return [self.pal.crit('%s cannot be read: %s' % (path, e))]
            st['f'] = f
            st['ino'] = os.fstat(f.fileno()).st_ino
            # read from near the end only: a log can be gigabytes
            f.seek(0, 2)
            f.seek(max(0, f.tell() - 2 * 1024 * 1024))
            got = f.read().splitlines()
            return got[1:][-self.LIVE_KEEP:] if len(got) > 1 else got

        def more():
            f = st['f']
            if f is None:
                return []
            out = []
            while len(out) < 5000:
                ln = f.readline()
                if not ln:
                    break
                out.append(ln.rstrip('\n'))
            if not out:
                try:
                    if os.stat(path).st_ino != st['ino']:          # rotated
                        f.close()
                        st['f'] = open(path, 'r', encoding='utf-8', errors='replace')
                        st['ino'] = os.fstat(st['f'].fileno()).st_ino
                except OSError:
                    pass
            return out
        try:
            self.live_view('Live log  %s' % path, first, more, self._log_text, what)
        finally:
            if st['f']:
                st['f'].close()

    def live_cmd(self, title, argv, paint=None):
        """What a command keeps writing - the journal, the broker - in the
        live view; the command is stopped, by its own process, on the way out."""
        try:
            pr = subprocess.Popen(argv, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                  stdin=subprocess.DEVNULL, text=True, errors='replace')
        except OSError as e:
            self.page(title, self.pal.crit(str(e)))
            return
        q = collections.deque()

        def pump():
            for ln in pr.stdout:
                q.append(ln.rstrip('\n'))
        threading.Thread(target=pump, name='zigmon-console-pump', daemon=True).start()

        def more():
            out = []
            while q:
                out.append(q.popleft())
            return out
        try:
            self.live_view(title, lambda: [], more, paint, '')
        finally:
            pr.terminate()
            try:
                pr.wait(3)
            except Exception:                           # noqa: BLE001
                pr.kill()

    def journal(self):
        self.live_cmd('journalctl -u zigmon -f',
                      ['journalctl', '-u', 'zigmon', '-f', '-n', '400', '--no-pager'])

    def broker(self):
        self.live_cmd('zigmon --watch', self.argv('--watch', '--no-color'))

    # ---- windows on the text screen: arrows and Enter ------------------------------
    # Nothing is typed at a bare prompt: a question is a window (a form) whose
    # fields are moved between by the arrows, a choice is picked by the
    # arrows, a list is scrolled and Enter on one offers what can be done with
    # it. What is typed is checked before anything is run; Esc closes the
    # window and goes back. The screen under a window is drawn again by
    # `self.backdrop`, so a window made bigger or smaller is drawn right.
    def _getkey(self, win=None):
        """A key on the text screen, by name: 'up', 'enter', 'esc', or the character."""
        c = self.curses
        src = win or self.scr
        k = src.getch()
        if k == -1:
            # The window's size looked at too (PuTTY and others whose change
            # is not always told): drawn again to the new one.
            try:
                size = os.get_terminal_size(sys.__stdout__.fileno())
                if (size.lines, size.columns) != self.scr.getmaxyx():
                    c.resizeterm(size.lines, size.columns)
                    self.scr.clear()
                    return 'resize'
            except (OSError, ValueError, c.error):
                pass
            return None
        if k == 27:
            # An arrow some terminals send as ESC [ B rather than as the key
            # their description names: read whole here.
            src.nodelay(True)
            try:
                k2 = src.getch()
                if k2 in (ord('['), ord('O')):
                    seq = chr(k2)
                    while len(seq) < 8:
                        k3 = src.getch()
                        if k3 == -1:
                            break
                        seq += chr(k3)
                        if chr(k3).isalpha() or chr(k3) == '~':
                            break
                    got = console_key(b'\x1b' + seq.encode('latin-1', 'replace'))
                    return None if got == 'seq' else got
                if k2 != -1:
                    c.ungetch(k2)
                return 'esc'
            finally:
                src.nodelay(False)
        named = {c.KEY_UP: 'up', c.KEY_DOWN: 'down', c.KEY_LEFT: 'left', c.KEY_RIGHT: 'right',
                 c.KEY_PPAGE: 'pgup', c.KEY_NPAGE: 'pgdn', c.KEY_HOME: 'home', c.KEY_END: 'end',
                 c.KEY_ENTER: 'enter', 10: 'enter', 13: 'enter', c.KEY_BACKSPACE: 'bs',
                 127: 'bs', 8: 'bs', c.KEY_DC: 'del', c.KEY_RESIZE: 'resize', 21: 'ctrl-u',
                 9: 'tab'}
        if k in named:
            if k == c.KEY_RESIZE:
                try:
                    c.update_lines_cols()
                except Exception:                       # noqa: BLE001
                    pass
                self.scr.clear()
            return named[k]
        if 32 <= k < 0x110000:
            try:
                return chr(k)
            except ValueError:
                return None
        return None

    def _box(self, win, h, w):
        """A frame round a window, in UTF-8 lines where the terminal takes them."""
        c, A = self.curses, self.A
        if 'utf' in (sys.stdout.encoding or '').lower():
            hz, vt, tl, tr, bl, br = '─', '│', '┌', '┐', '└', '┘'
        else:
            hz, vt, tl, tr, bl, br = '-', '|', '+', '+', '+', '+'
        for y, line in ((0, tl + hz * (w - 2) + tr), (h - 1, bl + hz * (w - 2) + br)):
            try:
                win.addstr(y, 0, line, A['key'])
            except c.error:
                pass                                    # the bottom-right corner
        for y in range(1, h - 1):
            for x in (0, w - 1):
                try:
                    win.addstr(y, x, vt, A['key'])
                except c.error:
                    pass

    def _fresh(self):
        """Back from a command's own screen: the text screen drawn whole again."""
        if self.plain:
            self.curses.reset_prog_mode()
            self.scr.clear()
            self.plain = False
            self.st_now = True

    def _under(self):
        """The screen under a window, written but not yet shown."""
        self._fresh()
        if self.backdrop:
            try:
                self.backdrop()
                return
            except Exception:                           # noqa: BLE001
                pass
        self.scr.noutrefresh()

    def _window(self, want_h, want_w):
        """A framed window in the middle of the screen; (win, h, w)."""
        c = self.curses
        h, w = self.scr.getmaxyx()
        ww = max(20, min(want_w, w - 2))
        wh = max(5, min(want_h, h - 2))
        win = c.newwin(wh, ww, max(0, (h - wh) // 2), max(0, (w - ww) // 2))
        win.keypad(True)
        win.erase()
        self._box(win, wh, ww)
        return win, wh, ww

    def _wput(self, win, y, x, text, attr=0):
        try:
            wh, ww = win.getmaxyx()
            if 0 < y < wh - 1 and x < ww - 1:
                win.addnstr(y, x, str(text), max(0, ww - x - 1), attr)
        except self.curses.error:
            pass

    def _wtitle(self, win, ww, title, attr):
        try:
            win.addnstr(0, 2, ' %s ' % title, ww - 4, attr)
        except self.curses.error:
            pass

    def _wkey(self, win, wait=500):
        win.timeout(wait)
        return self._getkey(win)

    @staticmethod
    def _wrap(text, width):
        out = []
        for para in str(text or '').split('\n'):
            out += _textwrap.wrap(para, max(10, width)) or ['']
        return out

    def note(self, title, text, tone=''):
        """Words in a window; any of Enter, Esc, q or Space closes it."""
        A = self.A
        while True:
            self._under()
            h, w = self.scr.getmaxyx()
            ww = max(30, min(100, w - 4))
            lines = self._wrap(text, ww - 4)[:max(1, h - 6)]
            win, wh, ww = self._window(len(lines) + 4, max(len(title) + 8, min(
                ww, max(len(x) for x in lines + ['']) + 6)))
            self._wtitle(win, ww, title, A['title'])
            for i, ln in enumerate(lines):
                self._wput(win, 1 + i, 2, ln, A.get(tone, 0) if tone else 0)
            self._wput(win, wh - 2, 2, 'Enter or Esc - back', A['dim'])
            win.noutrefresh()
            self.curses.doupdate()
            if self._wkey(win) in ('enter', 'esc', 'q', ' '):
                return

    def working(self, words):
        """A window that says something is being done (the screen waits for it)."""
        self._under()
        win, wh, ww = self._window(3, min(100, len(words) + 6))
        self._wput(win, 1, 2, words, self.A['dim'])
        win.noutrefresh()
        self.curses.doupdate()

    def confirm(self, title, words, yes='Yes', no='No', danger=False):
        """Yes or no, chosen by the arrows (or y / n) - No unless Yes is chosen:
        Enter straight away, by habit, does nothing."""
        A = self.A
        pick = 1
        while True:
            self._under()
            h, w = self.scr.getmaxyx()
            ww = max(40, min(80, w - 4))
            lines = self._wrap(words, ww - 4)[:max(1, h - 8)]
            win, wh, ww = self._window(len(lines) + 5, ww)
            self._wtitle(win, ww, title, A['bad'] if danger else A['title'])
            for i, ln in enumerate(lines):
                self._wput(win, 1 + i, 2, ln)
            x, y = 2, wh - 2
            for i, lab in enumerate((yes, no)):
                lab = '  %s  ' % lab
                self._wput(win, y, x, lab, (A['bad'] if danger and i == 0 else A['sel'])
                           if i == pick else A['key'])
                x += len(lab) + 2
            self._wput(win, y, x + 2, 'Left/Right  Enter  Esc', A['dim'])
            win.noutrefresh()
            self.curses.doupdate()
            k = self._wkey(win)
            if k in ('esc', 'n', 'N'):
                return False
            if k in ('y', 'Y'):
                return True
            if k in ('left', 'right', 'tab', 'up', 'down'):
                pick = 1 - pick
            elif k == 'enter':
                return pick == 0

    def choose(self, title, options, words='', cur=0):
        """One of `options` ([(value, words)]), picked by the arrows; Esc None."""
        A = self.A
        if not options:
            return None
        sel = max(0, min(cur or 0, len(options) - 1))
        top = 0
        while True:
            self._under()
            h, w = self.scr.getmaxyx()
            ww = min(90, w - 4, max(36, max(len(o[1]) for o in options) + 12,
                                    len(title) + 8, len(words) + 6 if words else 0))
            head = self._wrap(words, ww - 4) if words else []
            room = max(1, min(len(options), h - 6 - len(head)))
            win, wh, ww = self._window(room + len(head) + (4 if head else 3), ww)
            self._wtitle(win, ww, title, A['title'])
            y = 1
            for ln in head:
                self._wput(win, y, 2, ln, A['dim'])
                y += 1
            if head:
                y += 1
            if sel < top:
                top = sel
            if sel >= top + room:
                top = sel - room + 1
            for n, (_val, lab) in enumerate(options[top:top + room]):
                i = top + n
                if i == sel:
                    self._wput(win, y + n, 2, (' %2d  %s' % (i + 1, lab)).ljust(ww - 5), A['sel'])
                else:
                    self._wput(win, y + n, 2, ' %2d' % (i + 1), A['key'])
                    self._wput(win, y + n, 7, lab)
            if len(options) > room:
                self._wbar(win, y, room, len(options), top, ww - 2)
            win.noutrefresh()
            self.curses.doupdate()
            k = self._wkey(win)
            if k in ('esc', 'left', 'q'):
                return None
            if k == 'up':
                sel = (sel - 1) % len(options)
            elif k in ('down', 'tab'):
                sel = (sel + 1) % len(options)
            elif k in ('home', 'pgup'):
                sel = 0
            elif k in ('end', 'pgdn'):
                sel = len(options) - 1
            elif k and len(k) == 1 and k.isdigit():
                n = int(k) - 1
                if 0 <= n < len(options):
                    return options[n][0]
            elif k in ('enter', 'right'):
                return options[sel][0]

    def _wbar(self, win, y0, rows, total, top, x):
        """The scroll bar on the right of a list in a window."""
        A = self.A
        if total <= rows:
            return
        thumb = max(1, min(rows, round(rows * rows / total)))
        tstart = max(0, min(rows - thumb, round((rows - thumb) * top / max(1, total - rows))))
        utf = 'utf' in (sys.stdout.encoding or '').lower()
        for r in range(rows):
            hit = tstart <= r < tstart + thumb
            try:
                win.addstr(y0 + r, x, ('█' if hit else '│') if utf else
                           ('#' if hit else '|'), A['key'] if hit else A['dim'])
            except self.curses.error:
                pass

    def form(self, title, fields, words='', check=None, ok='OK'):
        """Questions in one window. fields: [{'key', 'label', 'kind': 'text' |
        'secret' | 'choice' | 'number', 'value', 'options': [(value, words)],
        'need': True, 'range': (a, b), 'help', 'check': fn(value, values) ->
        an error or None}]. Up/Down (Tab) move between them, a choice is
        changed by Left/Right, Enter checks them all and gives {key: value};
        Esc gives None. A secret shows a star for each character, never the
        characters."""
        c, A = self.curses, self.A
        vals, pos = {}, {}
        for f in fields:
            f.setdefault('kind', 'text')
            if f['kind'] == 'choice':
                opts = [o[0] for o in f['options']]
                vals[f['key']] = f.get('value') if f.get('value') in opts else opts[0]
            else:
                vals[f['key']] = str(f.get('value') if f.get('value') is not None else '')
            pos[f['key']] = len(vals[f['key']]) if f['kind'] != 'choice' else 0
        at, err, err_at = 0, '', None
        try:
            while True:
                shown = fields
                at = max(0, min(at, len(shown) - 1))
                f = shown[at]
                self._under()
                h, w = self.scr.getmaxyx()
                ww = max(50, min(100, w - 4))
                head = self._wrap(words, ww - 4) if words else []
                labw = min(30, max(len(x.get('label') or x['key']) for x in shown) + 1)
                fieldw = max(8, ww - labw - 7)
                helps = (self._wrap(f.get('help') or '', ww - 4) if f.get('help') else [])[:4]
                wh = len(head) + (1 if head else 0) + len(shown) + 2 + 4 + 1
                win, wh, ww = self._window(wh, ww)
                self._wtitle(win, ww, title, A['title'])
                y = 1
                for ln in head:
                    self._wput(win, y, 2, ln, A['dim'])
                    y += 1
                if head:
                    y += 1
                cursor = None
                for i, x in enumerate(shown):
                    lab = (x.get('label') or x['key'])[:labw - 1]
                    here = i == at
                    self._wput(win, y, 2, lab.rjust(labw), A['key'] if here else 0)
                    vx = 3 + labw + 1
                    v = vals[x['key']]
                    if x['kind'] == 'choice':
                        said = dict(x['options']).get(v, v)
                        txt = ('< %s >' % said) if here else ('  %s' % said)
                        self._wput(win, y, vx, txt[:fieldw], A['sel'] if here else A['ok'])
                    else:
                        t = ('*' * len(v)) if x['kind'] == 'secret' else v
                        p = pos[x['key']] if here else len(t)
                        start = max(0, p - fieldw + 1)
                        self._wput(win, y, vx, t[start:start + fieldw].ljust(fieldw),
                                   c.A_UNDERLINE | (A['key'] if here else 0))
                        if here:
                            cursor = (y, vx + p - start)
                    if err and err_at == x['key']:
                        self._wput(win, y, ww - 3, '!', A['bad'])
                    y += 1
                y += 1
                for ln in helps:
                    self._wput(win, y, 2, ln, A['dim'])
                    y += 1
                if err:
                    self._wput(win, wh - 2, 2, err[:ww - 4], A['bad'])
                else:
                    self._wput(win, wh - 2, 2, ('Up/Down field   ' + ('Left/Right choose   '
                               if any(x['kind'] == 'choice' for x in shown) else '') +
                               'Enter %s   Esc cancel' % ok)[:ww - 4], A['dim'])
                try:
                    c.curs_set(1 if cursor else 0)
                    if cursor:
                        win.move(*cursor)
                except Exception:                       # noqa: BLE001
                    pass
                win.noutrefresh()
                c.doupdate()
                k = self._wkey(win)
                if k is None or k == 'resize':
                    continue
                key, kind = f['key'], f['kind']
                if k == 'esc':
                    return None
                if k == 'up':
                    at = (at - 1) % len(shown)
                elif k in ('down', 'tab'):
                    at = (at + 1) % len(shown)
                elif k == 'enter':
                    err, err_at = '', None
                    for i, x in enumerate(shown):
                        v = vals[x['key']]
                        if x['kind'] not in ('choice', 'secret'):
                            v = v.strip()
                            vals[x['key']] = v
                        bad = None
                        name = x.get('label') or x['key']
                        if x.get('need') and v == '':
                            bad = '%s - it is needed' % name
                        elif x['kind'] == 'number' and v != '':
                            try:
                                n = int(v)
                                lo, hi = x.get('range') or (None, None)
                                if (lo is not None and n < lo) or (hi is not None and n > hi):
                                    bad = '%s - a whole number from %s to %s' % (name, lo, hi)
                            except ValueError:
                                bad = '%s - a whole number' % name
                        if not bad and x.get('check') and v != '':
                            try:
                                bad = x['check'](v, vals)
                            except Exception as e:      # noqa: BLE001
                                bad = str(e)
                        if bad:
                            err, err_at, at = bad, x['key'], i
                            break
                    if err:
                        continue
                    got = {x['key']: vals[x['key']] for x in shown}
                    if check:
                        bad = check(got)
                        if bad:
                            err, err_at = bad, None
                            continue
                    return got
                elif kind == 'choice':
                    opts = [o[0] for o in f['options']]
                    i = opts.index(vals[key]) if vals[key] in opts else 0
                    if k == 'left':
                        vals[key] = opts[(i - 1) % len(opts)]
                    elif k in ('right', ' '):
                        vals[key] = opts[(i + 1) % len(opts)]
                    err = ''
                else:
                    t, p = vals[key], pos[key]
                    if k == 'bs' and p > 0:
                        t, p = t[:p - 1] + t[p:], p - 1
                    elif k == 'del':
                        t = t[:p] + t[p + 1:]
                    elif k == 'left':
                        p = max(0, p - 1)
                    elif k == 'right':
                        p = min(len(t), p + 1)
                    elif k == 'home':
                        p = 0
                    elif k == 'end':
                        p = len(t)
                    elif k == 'ctrl-u':
                        t, p = '', 0
                    elif k and len(k) == 1 and k.isprintable():
                        if kind == 'number' and not (k.isdigit() or (k == '-' and p == 0)):
                            continue
                        t, p = t[:p] + k + t[p:], p + 1
                    else:
                        continue
                    vals[key], pos[key] = t, p
                    if err_at == key:
                        err, err_at = '', None
        finally:
            try:
                c.curs_set(0)
            except Exception:                           # noqa: BLE001
                pass

    def ask_one(self, title, label, value='', help_='', need=True, secret=False, check=None):
        """One question in a window; its answer, or None (Esc)."""
        got = self.form(title, [{'key': 'v', 'label': label, 'value': value, 'help': help_,
                                 'need': need, 'kind': 'secret' if secret else 'text',
                                 'check': check}])
        return None if got is None else got['v']

    def pick(self, title, load, cols, act=None, empty='nothing here', words=''):
        """A list to scroll with the arrows: `load()` gives its rows (asked
        again after something was done to one), `cols` [(heading, fn(row),
        width, tone fn(row) or None)]. Enter calls `act(row)`; / finds. Esc
        back, q leaves the console."""
        c, A = self.curses, self.A
        self.working('working...  ' + title)
        rows = load() or []
        sel, top, find, said, said_bad = 0, 0, '', '', False
        while True:
            self._fresh()
            h, w = self.scr.getmaxyx()
            seen = [r for r in rows if not find or find.lower() in ' '.join(
                str(fn(r)) for _h, fn, _w, _t in cols).lower()]
            sel = max(0, min(sel, len(seen) - 1))
            avail = max(3, h - 5 - (1 if words else 0))
            if sel < top:
                top = sel
            if sel >= top + avail:
                top = sel - avail + 1
            top = max(0, min(top, max(0, len(seen) - avail)))
            # widths: as given; the last one takes what is left
            ws = [cw for _h, _f, cw, _t in cols]
            ws[-1] = max(8, min(ws[-1] or 200, w - 4 - sum(x + 2 for x in ws[:-1])))

            def paint(_seen=seen, _top=top, _sel=sel, _ws=ws, _avail=avail, _said=said,
                      _bad=said_bad, _find=find):
                self.scr.erase()
                self._put(0, 0, ' ' * w, A['head'])
                self._put(0, 0, ' zigmon %s  %s ' % (__version__, title), A['head'] | c.A_BOLD)
                right = ' %d%s ' % (len(_seen), (' of %d, with "%s"' % (len(rows), _find))
                                    if _find else '')
                self._put(0, max(0, w - len(right) - 1), right, A['head'])
                y = 1
                if words:
                    self._put(y, 1, words[:w - 2], A['dim'])
                    y += 1
                x = 2
                for (hd, _f, _w, _t), cw in zip(cols, _ws):
                    self._put(y + 1, x, hd[:cw], A['key'])
                    x += cw + 2
                y += 2
                if not _seen:
                    self._put(y + 1, 4, empty if not _find else 'nothing with "%s"' % _find,
                              A['dim'])
                for n, r in enumerate(_seen[_top:_top + _avail]):
                    i = _top + n
                    x = 2
                    if i == _sel:
                        self._put(y + n, 1, ' ' * (w - 3), A['sel'])
                    for (_hd, fn, _w, tone), cw in zip(cols, _ws):
                        try:
                            v = str(fn(r))
                        except Exception:               # noqa: BLE001
                            v = '?'
                        attr = A['sel'] if i == _sel else (A.get(tone(r) or '', 0) if tone else 0)
                        self._put(y + n, x, v[:cw], attr)
                        x += cw + 2
                if len(_seen) > _avail:
                    thumb = max(1, min(_avail, round(_avail * _avail / len(_seen))))
                    ts = max(0, min(_avail - thumb, round((_avail - thumb) * _top
                                                          / max(1, len(_seen) - _avail))))
                    utf = 'utf' in (sys.stdout.encoding or '').lower()
                    for r_ in range(_avail):
                        hit = ts <= r_ < ts + thumb
                        self._put(y + r_, w - 1, ('█' if hit else '│') if utf
                                  else ('#' if hit else '|'), A['key'] if hit else A['dim'])
                if _said:
                    self._put(h - 2, 1, _said[:w - 2], A['bad'] if _bad else A['ok'])
                help_ = ' Up/Down PgUp/PgDn Home/End move   Enter %s   / find   Esc back ' % (
                    'what to do with it' if act else 'look')
                self._put(h - 1, 0, ' ' * (w - 1), A['head'])
                self._put(h - 1, 0, help_[:w - 1], A['head'])
                self.scr.noutrefresh()
            self.backdrop = paint
            paint()
            c.doupdate()
            self.scr.timeout(500)
            k = self._getkey()
            if k is None or k == 'resize':
                continue
            said = ''
            if k == 'esc':
                if find:
                    find = ''
                    continue
                return None
            if k == 'q':
                return 'quit'
            if k in ('up', 'down', 'pgup', 'pgdn', 'home', 'end'):
                sel = {'up': sel - 1, 'down': sel + 1, 'pgup': sel - (avail - 1),
                       'pgdn': sel + (avail - 1), 'home': 0, 'end': len(seen) - 1}[k]
            elif k == '/':
                got = self.ask_one('Find', 'with the words', find, need=False,
                                   help_='Only the rows with these words in them stay; '
                                         'Esc in the list shows them all again.')
                if got is not None:
                    find, sel, top = got, 0, 0
            elif k in ('enter', 'right') and seen and act:
                r = act(seen[sel])
                if r == 'quit':
                    return 'quit'
                if isinstance(r, tuple):
                    said, said_bad = r
                self.working('working...  ' + title)
                rows = load() or []

    def live(self, fn):
        """A view of its own on the terminal (a live log, a progress)."""
        self.go_plain(fn)

    # ---- small parts the lists use --------------------------------------------------
    @staticmethod
    def _when(ts):
        if not ts:
            return '-'
        try:
            return time.strftime('%Y-%m-%d %H:%M', time.localtime(float(ts)))
        except (TypeError, ValueError):
            return str(ts)

    @staticmethod
    def _rows(got, *keys):
        if isinstance(got, dict):
            for k in keys:
                if isinstance(got.get(k), list):
                    return got[k]
            return []
        return got if isinstance(got, list) else []

    def details(self, title, row, skip=()):
        """One row's fields as words, in a window or on its own screen."""
        lines = []
        for k, v in row.items():
            if k in skip or v in (None, '', [], {}):
                continue
            if isinstance(v, (list, dict)):
                v = json.dumps(v, default=str, ensure_ascii=False)
            lines.append('%-16s %s' % (k, v))
        h, w = self.scr.getmaxyx()
        if len(lines) <= h - 8:
            self.note(title, '\n'.join(lines))
        else:
            self.go_plain(lambda: self.page(title, '\n'.join(lines)))

    # ---- 1 status and checks ------------------------------------------------------
    def m_status(self):
        def events():
            got = self.form('Events', [
                {'key': 'n', 'label': 'how many', 'kind': 'number', 'value': '50',
                 'range': (1, 5000), 'need': True,
                 'help': 'The newest first, as the dashboard\'s event log has them.'}])
            if got:
                self.act('--events', '--limit', got['n'])
        return self.sub('Status and checks', [
            ('Status (every device with its latest readings)', lambda: self.act('--status')),
            ('Checks (the daemon, the broker, the database...)', lambda: self.act('--check')),
            ('Events', events),
            ('Diagnostics (settings, API latency, database size)', lambda: self.act('--diag')),
            ('What root last did for the dashboard', lambda: self.act('--root-status')),
        ], 'status')

    # ---- 2 live log ---------------------------------------------------------------
    def m_live(self):
        return self.sub('Live log', [
            ('The log file  %s' % self.log_path(), self.live_log, 'plain'),
            ('The journal of the service (journalctl -u zigmon -f)', self.journal, 'plain'),
            ('The broker, live (zigmon --watch)', self.broker, 'plain'),
        ], 'live')

    # ---- 3 devices and sockets ----------------------------------------------------
    TONES = {'ok': 'ok', 'warn': 'warn', 'crit': 'bad'}

    def m_devices(self):
        def devices():
            return self.pick('Devices', lambda: self._rows(self.out('--devices'), 'devices'), [
                ('device', lambda d: d.get('name'), 28, None),
                ('level', lambda d: d.get('level'), 7, lambda d: self.TONES.get(d.get('level'))),
                ('kind', lambda d: d.get('kind') or '', 12, None),
                ('last', lambda d: (human_age(d['age_s']) + ' ago') if d.get('age_s') is not None
                 else 'never', 12, None),
                ('model', lambda d: ((d.get('vendor') or '') + ' ' + (d.get('model') or '')).strip(),
                 40, lambda d: 'dim')], self.device_do, 'no device yet')

        def plugs():
            return self.pick('Sockets', lambda: self._rows(self.out('--plug'), 'plugs'), [
                ('socket', lambda p: p.get('name'), 24, None),
                ('state', self._plug_state, 9,
                 lambda p: 'ok' if p.get('output') else ('bad' if not p.get('online') else 'dim')),
                ('power', lambda p: '' if p.get('power') is None else '%s W' % p['power'], 10, None),
                ('address', lambda p: p.get('host') or '', 40, lambda p: 'dim')],
                self.plug_do, 'no socket is configured')
        return self.sub('Devices and sockets', [
            ('The devices (Enter: what to do with one)', devices),
            ('The sockets (Enter: switch one)', plugs),
            ('Every socket, live from the device', lambda: self.act('--plug')),
            ('The batteries: which are sinking, and how long they have',
             lambda: self.act('--battery')),
        ], 'devices')

    @staticmethod
    def _plug_state(p):
        if not p.get('online'):
            return 'offline'
        return 'on' if p.get('output') else 'off'

    def device_do(self, d):
        name = d['name']
        what = self.choose(name, [('24h', 'Its readings, the last 24 hours'),
                                  ('7d', 'Its readings, the last 7 days'),
                                  ('show', 'Show it all')],
                           '%s, %s' % (d.get('level'), d.get('kind') or d.get('source') or ''))
        if what in ('24h', '7d'):
            self.act('--history', name, '--range', what)
        elif what == 'show':
            self.details(name, d)

    def plug_do(self, p):
        name = p['name']
        what = self.choose(name, [('on', 'Switch it on'), ('off', 'Switch it off'),
                                  ('toggle', 'Switch it to the other state'),
                                  ('why', 'Why it is not answering, step by step'),
                                  ('show', 'Show it all')],
                           'It is %s.' % self._plug_state(p), cur=1 if p.get('output') else 0)
        if what == 'on':
            self.act('--plug-on', name)
        elif what in ('off', 'toggle'):
            if self.confirm('Switch %s' % ('off' if what == 'off' else 'it over'),
                            'Whatever is plugged into %s loses its power if it was on.' % name,
                            'Switch it'):
                self.act('--plug-off' if what == 'off' else '--plug-toggle', name)
        elif what == 'why':
            self.act('--diagnose', name)
        elif what == 'show':
            self.details(name, p, skip=('values', 'counters'))

    # ---- 4 accounts of the dashboard ------------------------------------------------
    ROLES = [('viewer', 'viewer - looks'), ('operator', 'operator - switches things'),
             ('admin', 'admin - may do everything')]

    @staticmethod
    def _account_name(v, _vals):
        return None if re.match(r'^[A-Za-z0-9._@-]{1,64}$', v) else 'letters, digits and . _ - @ only'

    def m_accounts(self):
        def name_of(title):
            return self.ask_one(title, 'the account', help_=(
                'Its name, as `zigmon --accounts` shows it.'), check=self._account_name)

        def make():
            got = self.form('Make an account', [
                {'key': 'name', 'label': 'name', 'need': True, 'check': self._account_name,
                 'help': 'What it signs in with: letters, digits, . _ - @'},
                {'key': 'role', 'label': 'role', 'kind': 'choice', 'value': 'operator',
                 'options': self.ROLES},
                {'key': 'by', 'label': 'signs in by', 'kind': 'choice', 'value': 'password',
                 'options': [('password', 'a password, changed at the first sign-in'),
                             ('pin', 'a PIN only (a kitchen tablet)')],
                 'help': 'The password or the PIN is made up here and shown once.'}])
            if got:
                self.act('--account-add', got['name'], got['role'],
                         *(['--with-pin'] if got['by'] == 'pin' else []))

        def password():
            name = name_of('A new password')
            if name and self.confirm('A new password', 'The password (or the PIN) of %s is '
                                     'replaced by one made up here and shown once; the old one '
                                     'stops working.' % name, 'Replace it'):
                self.act('--account-password', name)

        def role():
            got = self.form('What an account may do', [
                {'key': 'name', 'label': 'the account', 'need': True, 'check': self._account_name},
                {'key': 'role', 'label': 'role', 'kind': 'choice', 'value': 'viewer',
                 'options': self.ROLES}])
            if got:
                self.act('--account-role', got['name'], got['role'])

        def off():
            name = name_of('Switch an account off')
            if name and self.confirm('Switch off', '%s can no longer sign in to the dashboard '
                                     'until it is switched on again.' % name, 'Switch it off'):
                self.act('--account-off', name)

        def on():
            name = name_of('Switch an account on again')
            if name:
                self.act('--account-on', name)
        return self.sub('Accounts of the dashboard', [
            ('The accounts, their roles, when each last signed in',
             lambda: self.act('--accounts')),
            ('Make one', make),
            ('A new password (or PIN) for one', password),
            ('What one may do (its role)', role),
            ('Switch one off', off),
            ('Switch one on again', on),
            ('Who is signed in now, and from where', lambda: self.act('--sessions')),
        ], 'accounts')

    # ---- 5 settings -----------------------------------------------------------------
    @staticmethod
    def _shown(v):
        if v is True:
            return 'on'
        if v is False:
            return 'off'
        return '' if v is None else str(v)

    def _settings_rows(self):
        got = self.out('--settings')
        if not isinstance(got, dict):
            return []
        return [{'key': k, 'value': v} for k, v in sorted(got.items())]

    def setting_do(self, row):
        """The window to change one setting, saved by `zigmon --settings KEY=VALUE`."""
        key = row['key']
        if secret_key(key):
            # A value typed here would stand on a command line, where every
            # process on the machine can read it: the console puts no secret there.
            self.note(key, '%s is a secret. It is changed on the dashboard (Settings), where it '
                           'never stands on a command line.' % key)
            return None
        got = self.form(key, [
            {'key': 'v', 'label': 'value', 'value': self._shown(row.get('value')),
             'help': 'Now: %s. Checked by the daemon as the dashboard checks it before it is '
                     'saved.' % (self._shown(row.get('value')) or '(empty)')}])
        if got is None:
            return None
        rc = self.act('--settings', '%s=%s' % (key, got['v']))
        return ('%s = %s - saved' % (key, got['v']), False) if rc == 0 else \
            ('%s was not changed' % key, True)

    def m_settings(self):
        def browse():
            return self.pick('Settings', self._settings_rows, [
                ('setting', lambda r: r['key'], 30, None),
                ('value', lambda r: self._shown(r.get('value')), 60, None)],
                self.setting_do, 'the daemon did not say (is it running?)')

        def by_key():
            got = self.form('Change one by its key', [
                {'key': 'key', 'label': 'the key', 'need': True,
                 'help': 'As `zigmon --settings` shows it - e.g. block_minutes.',
                 'check': lambda v, _: None if re.match(r'^[a-z][a-z0-9_]*$', v)
                 else 'small letters, digits and _'}])
            if got:
                rows = [r for r in self._settings_rows() if r['key'] == got['key']]
                if not rows:
                    self.note('Change one', 'there is no setting %s' % got['key'], 'bad')
                    return
                done = self.setting_do(rows[0])
                if done:
                    self.note('Change one', done[0], 'bad' if done[1] else 'ok')
        return self.sub('Settings', [
            ('Browse and change (Enter: change one)', browse),
            ('Change one by its key', by_key),
            ('All of them as text', lambda: self.act('--settings')),
            ('Every kind of message, and where it goes', lambda: self.act('--alerts')),
        ], 'settings')

    # ---- 6 security ---------------------------------------------------------------
    @staticmethod
    def _address(v, _vals):
        try:
            ipaddress.ip_network(v, strict=False)
            return None
        except ValueError:
            return 'an address, e.g. 89.24.5.7 or 2001:db8::1'

    def m_security(self):
        def blocked():
            return self.pick('Blocked addresses', lambda: self._rows(self.out('--blocked')), [
                ('address', lambda r: r.get('ip'), 40, None),
                ('for', lambda r: 'good' if r.get('forever') else
                 '%d min' % ((r.get('left') or 0) // 60 + 1), 8, None),
                ('by', lambda r: 'itself' if r.get('auto') else 'hand', 6, lambda r: 'dim'),
                ('turned away', lambda r: r.get('hits') or 0, 11, None),
                ('why', lambda r: r.get('why') or '', 60, lambda r: 'dim')],
                self.unblock_do, 'nobody is blocked')

        def keep_out():
            got = self.form('Keep an address out', [
                {'key': 'ip', 'label': 'the address', 'need': True, 'check': self._address},
                {'key': 'how', 'label': 'for', 'kind': 'choice', 'value': 'while',
                 'options': [('while', 'as long as blocking is set to'), ('good', 'good')]}])
            if got:
                self.act('--blocked', got['ip'], *(['--force'] if got['how'] == 'good' else []))

        def everybody():
            if self.confirm('Let everybody back in', 'Every address on the blocked list may talk '
                            'to the API again, those kept out for good too.', 'Let them in',
                            danger=True):
                self.act('--unblock', 'all')
        return self.sub('Security', [
            ('The blocked addresses (Enter: let one back in)', blocked),
            ('Keep an address out', keep_out),
            ('Let everybody back in', everybody),
            ('The list as lines a Mikrotik takes', lambda: self.act('--blocked', 'mikrotik')),
            ('The router (Mikrotik)', lambda: self.act('--mikrotik', 'show')),
            ('Whether the log of the server in front is read', lambda: self.act('--proxy')),
            ('The broker\'s access list', lambda: self.act('--acl', 'check')),
        ], 'security')

    def unblock_do(self, r):
        ip = r.get('ip')
        if ip and self.confirm('Let it back in', '%s may talk to the API again.' % ip,
                               'Let it in'):
            self.act('--unblock', ip)

    # ---- 7 backups ----------------------------------------------------------------
    @staticmethod
    def full_dir():
        return os.environ.get('ZIGMON_FULL_DIR', '/var/backups/zigmon')

    def _full_files(self):
        out = []
        try:
            for f in os.scandir(self.full_dir()):
                if f.is_file(follow_symlinks=False):
                    st = f.stat(follow_symlinks=False)
                    out.append({'path': f.path, 'name': f.name, 'at': st.st_mtime,
                                'bytes': st.st_size})
        except OSError:
            pass
        return sorted(out, key=lambda x: x['at'], reverse=True)

    def _with_passphrase(self, pw, fn):
        """`fn(extra arguments)` with the password a backup is locked with in a
        file of root's own for as long as it runs - never on a command line."""
        if not pw:
            return fn([])
        fd, path = tempfile.mkstemp(prefix='zigmon-console-')
        try:
            os.write(fd, pw.encode('utf-8'))
            os.close(fd)
            return fn(['--passphrase-file', path])
        finally:
            try:
                os.unlink(path)
            except OSError:
                pass

    def _file_check(self, v, _vals):
        return None if os.path.isfile(v) else 'there is no such file'

    PW_HELP = 'Only for a backup locked with a password; empty otherwise.'

    def full_inspect(self, path=None):
        got = self.form('What is in a backup', ([] if path else [
            {'key': 'file', 'label': 'the file', 'value': self.full_dir() + '/', 'need': True,
             'check': self._file_check}]) + [
            {'key': 'pw', 'label': 'its password', 'kind': 'secret', 'help': self.PW_HELP}])
        if got:
            self._with_passphrase(got['pw'], lambda more: self.act(
                '--full-inspect', path or got['file'], *more))

    def full_restore(self, path=None):
        got = self.form('Put the whole installation back', ([] if path else [
            {'key': 'file', 'label': 'the file', 'value': self.full_dir() + '/', 'need': True,
             'check': self._file_check}]) + [
            {'key': 'parts', 'label': 'which parts',
             'help': 'Empty: every part it holds. Or some of them, e.g. database,config,tls '
                     '(What is in it lists them).',
             'check': lambda v, _: None if re.match(r'^[a-z]+(,[a-z]+)*$', v)
             else 'words joined by commas'},
            {'key': 'pw', 'label': 'its password', 'kind': 'secret', 'help': self.PW_HELP}])
        if not got:
            return
        path = path or got['file']
        if not self.confirm('Put it back', 'What is here now is replaced by %s (%s). The service '
                            'is stopped while it is done.' % (
                                os.path.basename(path), got['parts'] or 'every part'),
                            'Put it back', danger=True):
            return
        self._with_passphrase(got['pw'], lambda more: self.act(
            '--full-restore', path, *((['--parts', got['parts']] if got['parts'] else []) +
                                      more + ['--yes'])))

    def full_do(self, f):
        what = self.choose(f['name'], [('info', 'What is in it'),
                                       ('restore', 'Put it back (replaces what is here)')])
        if what == 'info':
            self.full_inspect(f['path'])
        elif what == 'restore':
            self.full_restore(f['path'])

    def m_backups(self):
        def kept():
            return self.pick('Backups of the whole installation', self._full_files, [
                ('made', lambda f: self._when(f['at']), 16, None),
                ('size', lambda f: '%.1f MB' % (f['bytes'] / 1e6), 10, None),
                ('file', lambda f: f['name'], 60, None)], self.full_do,
                'none here yet (%s)' % self.full_dir())
        return self.sub('Backups', [
            ('The backups of the database there are', lambda: self.act('--backup')),
            ('A backup of the database now', lambda: self.act('--backup', 'now')),
            ('A backup of the whole installation now', lambda: self.act('--full-backup')),
            ('The backups of the whole installation (Enter: look in one, put it back)', kept),
            ('What is in a backup file', self.full_inspect),
            ('Put the whole installation back from a file', self.full_restore),
            # "Backups to other machines" come here, from CONSOLE_MORE['backups']
        ], 'backups')

    # ---- 8 upgrades ---------------------------------------------------------------
    def m_upgrades(self):
        def from_file():
            path = self.ask_one('Upgrade from a package file', 'the package', '/root/', help_=(
                'zigmon-X.Y.Z.tar.gz, signed. It is checked, the whole installation is backed '
                'up, and the old version is put back if the new one does not answer.'),
                check=lambda v, _: None if os.path.isfile(v) and v.endswith(('.tar.gz', '.tgz'))
                else 'not a .tar.gz file')
            if not path:
                return
            if self.confirm('Upgrade', 'This machine is upgraded with %s - the dashboard is away '
                            'for a minute.' % os.path.basename(path), 'Upgrade'):
                here = Path(self.me).parent
                helper = str(next((p for p in (here / 'zigmon_upgrade.py',
                                               here / 'deploy' / 'zigmon_upgrade.py')
                                   if p.is_file()), here / 'zigmon_upgrade.py'))
                self.live(lambda: self.show_live([sys.executable, '-I', helper, '--run', path],
                                                 '$ zigmon_upgrade.py --run %s' % self._quote(path)))
                self.st_now = True
        return self.sub('Upgrades', [
            ('How it stands (what root last did, the last upgrade)',
             lambda: self.act('--root-status')),
            ('Upgrade from a package file', from_file),
            # "Look for a new version on the web" and "Upgrade from the web"
            # come here, from CONSOLE_MORE['upgrades']
        ], 'upgrades')

    # ---- 9 the service ------------------------------------------------------------
    def m_service(self):
        def restart():
            if self.confirm('Restart the service', 'The house is not watched and nothing is '
                            'switched for a few seconds.', 'Restart'):
                self.act_argv(['systemctl', 'restart', 'zigmon'], '$ systemctl restart zigmon',
                              quiet_ok='restarted')
                self.st_now = True

        def at_login():
            on = console_at_login()
            r = self.choose('The console at login', [
                ('on', 'On - root sees this console first when signing in'),
                ('off', 'Off - root gets the ordinary shell')],
                'It is %s now.' % ('ON' if on else 'off'), cur=0 if on else 1)
            if r and (r == 'on') != on:
                self.act('--console-at-login', r)
        return self.sub('The service', [
            ('Its state', lambda: self.act_argv(
                ['systemctl', 'status', 'zigmon', '--no-pager', '-n', '60', '-l'],
                '$ systemctl status zigmon')),
            ('Restart it', restart),
            ('The pages (nginx, PHP)', lambda: self.act_argv(
                ['systemctl', 'status', 'nginx', 'php-fpm', '--no-pager', '-n', '5'],
                '$ systemctl status nginx php-fpm')),
            ('Root\'s helpers (backups, upgrades)', lambda: self.act_argv(
                ['systemctl', 'status', 'zigmon-root.path', 'zigmon-upgrade.path', '--no-pager'],
                '$ systemctl status zigmon-root.path zigmon-upgrade.path')),
            ('Its journal, live', self.journal, 'plain'),
            ('The console at login: on or off', at_login),
        ], 'service')


def console_at_login():
    """Whether root's login opens the console: the flag is a plain file
    starting with "on". Opened without following a link and without waiting
    on a pipe, as the login hook reads it."""
    try:
        fd = os.open(console_flag_path(), os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    except OSError:
        return False
    try:
        import stat as _stat
        if not _stat.S_ISREG(os.fstat(fd).st_mode):
            return False
        return os.read(fd, 8).decode('ascii', 'replace').strip() == 'on'
    finally:
        os.close(fd)


def console_at_login_set(on):
    """The switch, root's alone. Written beside the flag and put in its place,
    so a link or a pipe found there is replaced, never followed."""
    if os.geteuid() != 0:
        raise PermissionError('zigmon: only root sets that (sudo zigmon --console-at-login %s)'
                              % ('on' if on else 'off'))
    flag = console_flag_path()
    tmp = '%s.%d.tmp' % (flag, os.getpid())
    for attempt in (0, 1):
        try:
            fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o644)
            break
        except FileExistsError:
            # one left behind by a run that died: ours by its name, taken away
            if attempt:
                raise
            os.unlink(tmp)
    try:
        os.write(fd, b'on\n' if on else b'off\n')
        os.fchmod(fd, 0o644)
    finally:
        os.close(fd)
    os.rename(tmp, flag)
    return ('the zigmon console opens when root signs in at the console or over SSH (q leaves '
            'it for the shell)' if on else 'root signs in to the ordinary shell; '
            '`zigmon --console` opens the console')


# What 5.21 brought, in the console's menus: the network, the clock and
# restarting kept or put back from here - where somebody is when the new
# network does not answer on the page - backups to other machines, and a new
# version from the web. Each is the same command run on the command line.
def _console_machine(c):
    def ask(kind, act, title, words, danger):
        if c.confirm(title, words, 'Yes' if not danger else title, danger=danger):
            c.act('--change-%s' % act, kind)
    return c.sub('Network, time and power', [
        ('What waits to be kept (a new network, a firewall change)', lambda: c.act('--changes')),
        ('Keep the new network', lambda: ask('net', 'keep', 'Keep the new network',
                                             'The new network stays as it is.', False)),
        ('Put the old network back now', lambda: ask('net', 'back', 'Put the old network back',
                                                     'The machine goes back to its old network and '
                                                     'restarts.', True)),
        ('Keep the change of the firewall', lambda: ask('fw', 'keep', 'Keep the firewall',
                                                        'The firewall and who may reach the pages '
                                                        'stay as they are.', False)),
        ('Put the old firewall back now', lambda: ask('fw', 'back', 'Put the old firewall back',
                                                      'The firewall and who may reach the pages go '
                                                      'back to what they were.', True)),
        ('What root last did (and the clock, the network it saw)', lambda: c.act('--root-status')),
    ], 'machine')


def _console_upgrade_online(c):
    if c.confirm('Upgrade from the web', 'The newest zigmon at upgrade_url is fetched, its '
                 'signature checked, the whole installation backed up and this machine upgraded - '
                 'the dashboard is away for a minute.', 'Upgrade'):
        c.act('--upgrade-online', '--yes')


CONSOLE_MORE['main'].append(('Network, time and power', _console_machine))
CONSOLE_MORE['backups'].extend([
    ('Backups to other machines: how they went', lambda c: c.act('--rbackup-status')),
    ('Backups to other machines: one now', lambda c: c.act('--rbackup-now')),
])
def _console_downgrade(c):
    """Going back: the versions there are and which are safe, then one chosen
    and asked for - as zigmon --downgrade does, the database left as it is."""
    c.act('--downgrade-check')
    version = c.ask_one('Go back to an older version', 'the version', '', help_=(
        'One that --downgrade-check called safe, e.g. 5.20.0 - or the path of a package file. '
        'The database is left as it is; this version is put back if the older one does not answer.'),
        check=lambda v, _: None if re.match(r'^\d+\.\d+\.\d+$', v) or os.path.isfile(v)
        else 'a version X.Y.Z or a package file')
    if version and c.confirm('Go back', 'zigmon goes back to %s and restarts - the database stays '
                             'as it is.' % version, 'Go back', danger=True):
        c.act('--downgrade', version, '--yes')


CONSOLE_MORE['upgrades'].extend([
    ('Look for a new version on the web now', lambda c: c.act('--upgrade-check')),
    ('Upgrade from the web', _console_upgrade_online),
    ('Going back to an older version (the database stays as it is)', _console_downgrade),
])


def console_cli(arguments):
    """`zigmon --console [--no-color] [--config FILE]` and `zigmon
    --console-at-login on|off|status`."""
    global CONFIG_FILE
    pal = Palette('--no-color' not in arguments and not os.environ.get('NO_COLOR')
                  and sys.stdout.isatty())
    if '--console-at-login' in arguments:
        at = arguments.index('--console-at-login')
        word = arguments[at + 1] if at + 1 < len(arguments) else 'status'
        if word not in ('on', 'off', 'status'):
            sys.stderr.write('zigmon: --console-at-login on, off or status\n')
            return 2
        if word == 'status':
            on = console_at_login()
            print('the console at login is %s (%s)' % ('on' if on else 'off', console_flag_path()))
            return 0
        try:
            print(pal.ok(console_at_login_set(word == 'on')))
        except PermissionError as e:
            sys.stderr.write('%s\n' % e)
            return 2
        except OSError as e:
            sys.stderr.write('zigmon: %s could not be written: %s\n' % (console_flag_path(), e))
            return 1
        return 0
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        sys.stderr.write('zigmon: the console needs a terminal\n')
        return 2
    if '--config' in arguments:
        at = arguments.index('--config')
        if at + 1 < len(arguments):
            # the commands it runs are given the same file
            CONFIG_FILE = Path(arguments[at + 1])
            os.environ['ZIGMON_CONFIG'] = str(CONFIG_FILE)
    try:
        load_config()
    except Exception:                                   # noqa: BLE001 - it says so itself
        pass
    return Console(pal).run()


def main(argv=None):
    global DEBUG, CONFIG_FILE
    arguments = list(sys.argv[1:] if argv is None else argv)

    # The console and its switch (5.21): before the configuration is judged,
    # because a console is wanted most when something is wrong with it.
    if arguments and arguments[0].startswith('-') and (
            '--console' in arguments or '--console-at-login' in arguments):
        return console_cli(arguments)

    # A backup of the whole installation, and putting one back (5.18): root's
    # own helper does it, the same one the dashboard asks.
    if arguments and arguments[0] in ('--full-backup', '--full-restore', '--full-inspect'):
        helper = Daemon.helper_file('zigmon_root.py')
        if os.geteuid() != 0:
            print('the whole installation is root\'s to copy and to put back: sudo zigmon %s'
                  % ' '.join(arguments))
            return 2
        word = {'--full-backup': '--backup', '--full-restore': '--restore',
                '--full-inspect': '--inspect'}[arguments[0]]
        return subprocess.call([sys.executable, '-I', str(helper), word] + arguments[1:])
    if arguments and arguments[0] == '--root-status':
        return root_status_main()
    if arguments and arguments[0] in ('--change-keep', '--change-back', '--changes'):
        return change_main(arguments)
    if arguments and arguments[0] in ('--accounts', '--account-add', '--account-password', '--account-role',
                                      '--account-off', '--account-on'):
        load_config()
        return accounts_main(arguments)

    # "zigmon gateway ..." reads a Zigbee gateway's own HTTP API (SLZB-06 etc).
    if arguments and arguments[0] == 'gateway':
        pal = Palette('--no-color' not in arguments and sys.stdout.isatty())
        return gateway_main(arguments[1:], pal)

    # "zigmon sms ..." and "zigmon modem ...", the way "zigmon shelly" reads a
    # plug: a word for the thing, a word for what to ask it.
    if arguments and arguments[0] in ('sms', 'modem', 'wifi', 'plug', 'zigbee'):
        return _thing_main(arguments[0], arguments[1:])

    # "zigmon shelly ..." is a world of its own, with its own options.
    if arguments and arguments[0] == 'shelly':
        rest = []
        skip = False
        for index, value in enumerate(arguments[1:]):
            if skip:
                skip = False
                continue
            if value == '--config' and index + 2 < len(arguments):
                CONFIG_FILE = Path(arguments[index + 2])
                skip = True
                continue
            rest.append(value)
        load_config()
        for problem in CONFIG_FATAL:
            sys.stderr.write('CONFIG: %s\n' % problem)
        pal = Palette('--no-color' not in rest and sys.stdout.isatty())
        return shelly_main(rest, pal)

    parser = build_parser()
    if arguments and arguments[0] in ('--help', '-h') and sys.stdout.isatty():
        # the same help, with the commands picked out from the words about them
        pal = Palette('--no-color' not in arguments)
        text = parser.format_help()
        out = []
        for line in text.split('\n'):
            body = line.strip()
            if body.startswith('zigmon ') and '  ' in line:
                cut = len(line) - len(line.lstrip())
                head = line[:cut] + body.split('  ')[0]
                out.append(pal.ok(head) + pal.dim(line[len(head):]))
            elif line.startswith(' ' * 20) and body and not body.startswith('-'):
                out.append(pal.dim(line))         # a description that ran on
            elif body and not line.startswith(' ') and body.endswith(':'):
                out.append(pal.warn(line))
            else:
                out.append(line)
        sys.stdout.write('\n'.join(out) + '\n')
        return 0
    args = parser.parse_args(arguments)
    if args.config:
        CONFIG_FILE = Path(args.config)
    DEBUG = args.debug
    load_config()
    pal = Palette(not args.no_color and sys.stdout.isatty())

    if CONFIG_FATAL and not (args.check or args.diag):
        for note in CONFIG_FATAL:
            sys.stderr.write('ERROR: %s\n' % note)
        return 2

    if getattr(args, 'secret', False):
        # Before anything is dispatched. It used to be set up halfway down the
        # chain, so --status and everything above it never saw it at all.
        if not _other_work(args):
            return cmd_secret(args, pal)
        held = unmask_secrets(args, pal)
        if held is None:
            return 1
        globals()['SHOW_SECRETS'] = True
        try:
            return _dispatch(args, pal)
        finally:
            finish_secrets(held, args, pal)
    return _dispatch(args, pal)


def _dispatch(args, pal):
    """Every flag on the main command, in order."""
    if getattr(args, 'tell', None):
        return cmd_tell(args, pal)
    if getattr(args, 'taps_test', False):
        return cmd_taps_test(args, pal)
    if getattr(args, 'taps', False):
        return cmd_taps(args, pal)
    if getattr(args, 'presses', False):
        return cmd_presses(args, pal)
    if getattr(args, 'scripts', False):
        return cmd_scripts(args, pal)
    if getattr(args, 'proxy', False):
        return cmd_proxy(args, pal)
    if getattr(args, 'settings', None) is not None:
        return cmd_settings(args, pal)
    if getattr(args, 'alerts', False):
        return cmd_alerts(args, pal)
    if getattr(args, 'heating', False):
        return cmd_heating(args, pal)
    if getattr(args, 'people', False):
        return cmd_people(args, pal)
    if getattr(args, 'scenes', False):
        return cmd_scenes(args, pal)
    if getattr(args, 'sessions', False):
        return cmd_sessions(args, pal)
    if getattr(args, 'backup', None) is not None:
        return cmd_backup(args, pal)
    if getattr(args, 'upgrade_check', False):
        return cmd_upgrade_check(args, pal)
    if getattr(args, 'upgrade_online', None):
        return cmd_upgrade_online(args, pal)
    if getattr(args, 'downgrade_check', False):
        return cmd_downgrade_check(args, pal)
    if getattr(args, 'downgrade', None):
        return cmd_downgrade(args, pal)
    if getattr(args, 'rbackup_now', False) or getattr(args, 'rbackup_status', False):
        return cmd_rbackup(args, pal)
    if getattr(args, 'run_script', None):
        return cmd_run_script(args, pal)
    if getattr(args, 'unblock', None):
        args.blocked = ('clear' if str(args.unblock).lower() in ('all', '*')
                        else '-' + str(args.unblock))
        return cmd_blocked(args, pal)
    if getattr(args, 'blocked', None):
        return cmd_blocked(args, pal)
    if getattr(args, 'mikrotik', None):
        return cmd_mikrotik(args, pal)
    if args.status:
        return cmd_status(args, pal)
    if args.devices:
        return cmd_devices(args, pal)
    if args.history:
        return cmd_history(args, pal)
    if args.events:
        return cmd_events(args, pal)
    if args.watch:
        return cmd_watch(args, pal)
    if args.permit_join:
        return cmd_permit_join(args, pal)
    if args.plug:
        return cmd_plug(args, pal)
    if args.plug_on or args.plug_off or args.plug_toggle or args.plug_pulse:
        return cmd_plug_switch(args, pal)
    if args.plug_reset:
        return cmd_plug_reset(args, pal)
    if args.bindings:
        return cmd_bindings(args, pal)
    if args.rules:
        return cmd_rules(args, pal)
    if args.reset_data:
        return cmd_reset(args, pal)
    if args.sms:
        return cmd_sms(args, pal)
    if args.what_if:
        return cmd_whatif(args, pal)
    if getattr(args, 'acl', None):
        return cmd_acl(args, pal)
    if getattr(args, 'modem', None):
        return cmd_modem(args, pal)
    if getattr(args, 'check_sms', False):
        return cmd_check_sms(args, pal)
    if args.diagnose:
        return cmd_diagnose(args, pal)
    if args.battery:
        return cmd_battery(args, pal)
    if getattr(args, 'weather_now', False):
        return cmd_weather(args, pal)
    if args.switch:
        return cmd_target(args, pal)
    if args.targets:
        return cmd_targets(args, pal)
    if args.check:
        return cmd_check(args, pal)
    if args.diag:
        return cmd_diag(args, pal)
    if args.map_now:
        return cmd_map(args, pal)
    if getattr(args, 'monthly', False):
        return cmd_monthly(args, pal)
    if args.presence:
        return cmd_presence(args, pal)
    if args.wifi:
        return cmd_wifi(args, pal)
    if args.wifi_probe:
        return cmd_wifi_probe(args, pal)
    if args.wifi_order_reset or args.reset_order:
        what = args.reset_order or 'wifi'
        if not re.match(r'^[a-z]+$', what):
            print(pal.crit('%r is not one of: %s, all' % (what, ', '.join(sorted(Daemon.ARRANGEMENTS)))))
            return 2
        code, answer = api_call('/api/order/reset?what=' + what, timeout=20.0, token=read_token())
        if code != 200 or not answer.get('ok'):
            print(pal.crit('the daemon refused: %s' % (answer.get('error') or code)))
            if answer.get('choices'):
                print(pal.dim('  pick one of: %s, all' % ', '.join(answer['choices'])))
            return 2
        for name in answer.get('reset') or []:
            print(pal.ok('%s: back to the default arrangement' % name))
        return 0
    if args.aggregate:
        store = Storage()
        n = store.aggregate()
        print('rolled up %d hourly rows' % n)
        return 0

    if mqtt is None:
        sys.stderr.write('ERROR: python3-paho-mqtt is not installed (dnf install -y python3-paho-mqtt)\n')
        return 2

    # The daemon writes the database, its WAL and the token. Started as root
    # over the service's own files it leaves root-owned pieces behind that the
    # service cannot open on its next start.
    if os.geteuid() == 0 and not args.allow_root and str(db_path()).startswith(str(STATE_DIR)):
        try:
            import pwd
            pwd.getpwnam(SERVICE_USER)
            sys.stderr.write('ERROR: do not run the daemon as root over %s.\n'
                             '  installed service:   systemctl status zigmon\n'
                             '  foreground, as the service user:   sudo -u %s %s\n'
                             '  a scratch copy as root:   --config /tmp/test.json with db_file and api_port '
                             'of its own, plus --allow-root\n' % (STATE_DIR, SERVICE_USER, sys.argv[0]))
            return 2
        except KeyError:
            pass                        # no service user on this machine; a test box

    try:
        daemon = Daemon()
    except StorageError as e:
        sys.stderr.write('ERROR: %s\n' % e)
        return 2
    signal.signal(signal.SIGTERM, daemon.stop)
    signal.signal(signal.SIGINT, daemon.stop)
    signal.signal(signal.SIGHUP, daemon.reopen_log)
    return daemon.run()


if __name__ == '__main__':
    sys.exit(main())
